window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["25783654"]={"book":{"id":25783654,"title":"如何高效学习","author":"[加]斯科特·扬","translator":"程冕","publisher":"机械工业出版社","pubdate":"2013-12","isbn":"9787111444008","tags":["学习方法","学习","方法论","思维","个人管理","整体性学习方法","整体性学习","思维方法"],"memCount":18},"np":1,"pb":[50],"idx":[{"i":19429,"t":"如何进行积极阅读","l":"TF1-2","c":"沐沐2025","g":1,"p":1},{"i":19418,"t":"费曼学习技巧","l":"TF1-1","c":"沐沐2025","g":1,"p":1},{"i":17586,"t":"如何才能做到高效学习","l":"TF1-1","c":"梁嘉雯","g":1,"p":1},{"i":16349,"t":"四问学习法帮你完成学习步骤&比喻法帮你深入理解和记忆","l":"TF2-4","c":"小东","g":1,"p":1},{"i":15328,"t":"积极阅读法","l":"TF2-1","c":"[email]","g":1,"p":1},{"i":15091,"t":"费曼学习法","l":"TF1-2","c":"[email]","g":1,"p":1},{"i":15029,"t":"通过积极阅读法+笔记流的学习，使得我们的学习更高效","l":"TF2-4","c":"亦新","g":1,"p":1},{"i":14980,"t":"如何高效学习","l":"TF1-1","c":"[email]","g":1,"p":1},{"i":14178,"t":"如何识别生活中的熵增","l":"TF1-1","c":"石研","g":1,"p":1},{"i":13414,"t":"运用费曼技巧进行整体性学习","l":"TF1-1","c":"楊楊","g":1,"p":1},{"i":13189,"t":"费曼技巧","l":"TF2-3","c":"方华丽","g":1,"p":1},{"i":12736,"t":"四问学习法&比喻记忆法","l":"TF2-4","c":"小东","g":1,"p":1},{"i":12598,"t":"一个养成每日习惯的方法","l":"TF1-1","c":"严金英","g":1,"p":1},{"i":12425,"t":"TF1-2","l":"TF1-2","c":"张书豪","g":1,"p":1},{"i":11932,"t":"如何让你的笔记变得简单有趣 ","l":"TF2-4","c":"罗巧琴","g":1,"p":1},{"i":11781,"t":"拆解《超速学习》之定下学习目标之后，先“做什么？”","l":"TF1-1","c":"学姐","g":1,"p":1},{"i":11578,"t":"TF1-2过级","l":"TF1-2","c":"依哲","g":1,"p":1},{"i":11243,"t":"如何高效学习","l":"TF2-2","c":"KK607","g":1,"p":1},{"i":11237,"t":"如何让你的笔记变有趣","l":"TF2-4","c":"罗巧琴","g":1,"p":1},{"i":10628,"t":"如何应用费曼技巧高效学习","l":"TF2-2","c":"罗巧琴","g":1,"p":1},{"i":10568,"t":"如何应用比喻建立知识联系","l":"TF2-3","c":"罗巧琴","g":1,"p":1},{"i":10181,"t":"手写笔记-加深巩固知识","l":"TF2-2","c":"小鱼-","g":1,"p":1},{"i":9789,"t":"循环式作息计划","l":"TF1-1","c":"朱朱2020","g":1,"p":1},{"i":9417,"t":"整体性学习及费曼技巧","l":"TF2-4","c":"珮源","g":1,"p":1},{"i":9020,"t":"学习比喻法掌握知识","l":"TF1-1","c":"章鱼-","g":1,"p":1},{"i":8874,"t":"费曼技巧 20190915","l":"TF2-2","c":"罗巧琴","g":1,"p":1},{"i":8800,"t":"如何实现高效学习","l":"TF1-1","c":"乐之","g":1,"p":1},{"i":8476,"t":"如何在工作生活中保持源源不断的活力和热情","l":"TF1-1","c":"啸野","g":1,"p":1},{"i":8458,"t":"个人学习","l":"TF1-2","c":"斑驳阳光","g":1,"p":1},{"i":8274,"t":"提高学习效率","l":"TF3-2","c":"木木33","g":1,"p":1},{"i":7828,"t":"提升学习效率","l":"TF3-2","c":"木木33","g":1,"p":1},{"i":7819,"t":"掌握学习的屠龙术——费曼技巧","l":"TF1-1","c":"谢洪涛","g":1,"p":1},{"i":7646,"t":"积极阅读法。","l":"TF2-1","c":"刘阳","g":1,"p":1},{"i":7536,"t":"学会运用费曼技巧","l":"TF1-1","c":"栗子（Lisa)","g":1,"p":1},{"i":7483,"t":"费曼技巧，","l":"TF1-2","c":"刘阳","g":1,"p":1},{"i":7242,"t":"运用费曼技巧，你能达到过目不忘","l":"TF1-1","c":"猴哥999","g":1,"p":1},{"i":7121,"t":"费曼学习法","l":"TF1-1","c":"灿阳","g":1,"p":1},{"i":6922,"t":"费曼技巧","l":"TF1-2","c":"张晶","g":1,"p":1},{"i":6248,"t":"整体性学习方法的顺序---黄荣","l":"TF1-1","c":"嗲嗲~","g":1,"p":1},{"i":6240,"t":"绝不拖延——黄荣","l":"TF1-1","c":"嗲嗲~","g":1,"p":1},{"i":6033,"t":"联想法","l":"TF3-1","c":"曾金泉","g":1,"p":1},{"i":6007,"t":"设置学习目标","l":"TF3-3","c":"曾金泉","g":1,"p":1},{"i":5584,"t":"整体性学习技术的实际运用——费曼技巧","l":"TF2-3","c":"曾金泉","g":1,"p":1},{"i":4139,"t":"终极学习法—费曼技巧。","l":"TF1-2","c":"宝仲","g":1,"p":1},{"i":3514,"t":"终极学习法—费曼技巧","l":"TF1-2","c":"宝仲","g":1,"p":1},{"i":3239,"t":"高效学习工具之一：联想法","l":"TF1-1","c":"素颜","g":0,"p":1},{"i":2816,"t":"如何掌握高效的学习方法","l":"TF1-2","c":"小清蜓","g":1,"p":1},{"i":1183,"t":"如何学的少会的多？","l":"TF3-2","c":"Emma","g":0,"p":1},{"i":971,"t":"运用联想法记忆","l":"TF2-4","c":"七月上","g":1,"p":1},{"i":908,"t":"整体性学习将使你的课程不再枯燥乏味","l":"TF2-2","c":"七月上","g":1,"p":1}],"ms":[{"id":19429,"topic":"如何进行积极阅读","learn_goal":"","remark":"如何进行积极阅读","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"沐沐2025","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>【个人介绍】\u003c/p>\u003cp>今天我为各位带来的是分享主题是如何高效学习，按照惯例，我先做一下我的个人介绍，有三个关键词，一个是我的名字叫沐沐，就是取自如沐春风的那个沐沐，我希望给各位带来一个如沐春风的感觉。\u003c/p>\u003cp>第二关键字是5,562米，因为作为一个徒步爱好者，我在卓玛拉垭口实现了我人生的一个新高度。最后一个标签关键字是极客，我作为一个极客，很乐意为各位解答与电脑相关的问题，同时作为一个 i 人的话，我也很乐意作为大家的一个倾听者。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>那下面介绍我们本次的图书以及相应的拆页，那今天给各位带来的图书是《如何高效学习》。这本书的作者是斯科特杨，他是因超速学习而成名的一个学习的实践家。他非常厉害的一个点就是他实现了实现 10 天攻克线性代数，以及一年修完 MIT 的 4 年课程，这些看起来就是在常人看起来无法完成的一个任务。这本书的核心的内容主要有几点，一是介绍了作者整理的整体性学习这个策略，以及给出了相应的一些学习方法技术，就比如说快速阅读法、留笔记法以及比喻法，这本书最大的优势是在于它实现了真实的可以操作的一个内容，它不仅讲了整体性学习策略这么个心法，也提供了非常多的工具供各位进行相关的学习和效率的提升。\u003c/p>","ratings_count":1,"texts":[{"id":23799,"quote":"\u003cp>【R原书拆页】\u003c/p>\u003cp>进行积极阅读时你需要记下：\u003c/p>\u003cp> （1）这一节中主要观点是什么？\u003c/p>\u003cp> （2）我怎样才能记住主要观点？\u003c/p>\u003cp> （3）我要怎样将主要观点拓展开以及应用它。\u003c/p>\u003cp> 第一个问题仅仅促使你完整地获取信息；第二个问题迫使你对信息进行联系、视觉化和比喻法；第三个问题要求你将信息应用在不同的情境中。这三个问题迫使你将每个知识点都要经过整体性学习里的理解、拓展和应用三个阶段。\u003c/p>\u003cp>如果你能对教科书里的每一个知识点都进行这样完整的积极阅读，你一定会天下无敌。一旦你熟悉了这种方式，就不必对每个知识点进行完整的积极阅读，而只针对自己需要理解和记忆困难的那些内容。\u003c/p>\u003cp>现在给大家 2 分钟的时间进行阅读，完成阅读后，可以举手或者是回复个666，或者是语音提示我。\u003c/p>","explains":"\u003cp>接下来由我来为大家做一个这本书拆页的讲解。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>各位刚才看完这个拆页，相信大家也发现了，阅读致用类的书籍，最大的痛点就是有这么几个。看完就忘，抓不到重点，不会迁移。本书也讲了，根源就是没有完成理解和拓展这个三个步骤，只是简单的完成了信息获取这个环节，作者总结出来的积极阅读三问，核心点就是把阅读的内容从获取到应用进行打通，从而实现从信息获取到理解到应用拓展的一个贯穿性的流程。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>积极阅读三问把隐性加工显性化，让每次阅读都产出可回忆、可调用、可迁移的知识块，从而把书真正变成自己的能力。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>这个步骤的具体操作，我把它总结成为三步，三问法，第一问就是要抓观点，就是每次阅读完就要提醒自己这个环节到底讲了什么内容，最好用自己的一句话来总结这个观点。第二问就是问自己你是如何去记忆这个环节，就可以用比喻、图像等方式把这个观点转换成一些让大脑容易记忆的内容。第三问的话就是寻找相应的应用，将场景的观点和自己的生活相结合，找到相应的观点、应用的场景。那在这里的话，我就举了书中的一个例子，作者是这样举例的，他当时刚刚读完心理学里面的经典条件反射，其主要的知识点是经典条件反射的发现者是巴甫洛夫，经典条件的反射是刺激引起反应，那就是他通过阅读那个经典条件反射的片段提取出来的关键的支点。第二，他是怎么来记忆的呢？他就想象了一幅画面，这幅画面里面就有巴普洛夫的狗，听到铃声又流出了唾液，看，通过这个找钩子的这种图像记忆法，其实是非常直观的，就把知识点转换成一个感官记忆，非常具有画面感。那作者是怎么样去拓展这个知识点呢？他与实际的生活场景相结合？比如说他举了一个例子，他听到电视里类似的手机铃声，就会情不自禁地掏出自己的手机，也就非常契合了元素的观点，巴普洛夫的狗听到铃声就会流出唾液，人经常也是类似在相应的场景里面，比如说电视机里面有相应的手机铃声，就会联想到是不是自己的手机响了，从而情不自禁地掏出自己的手机进行查看。\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>积极阅读的适用边界\u003c/p>\u003cp>适用于\u003c/p>\u003cp>系统学习、难点突破、学术输出，需要高保真记忆时必用。\u003c/p>\u003cp>不适用于\u003c/p>\u003cp>消遣阅读如小说散文，强制三问会破坏阅读乐趣，应直接放弃。\u003c/p>","interaction":"\u003cp>接下来，给大家分享下我的失败经验：\u003cbr>\u003cstrong>【A1】（激活过去经验）\u003c/strong>\u003cbr>【时间】从去年的7月开始\u003cbr>【起因】我发现自己的阅读量不足\u003cbr>【经过】于是我开始增加自己的阅读量，有空就开始阅读致用类书籍。\u003cbr>【结果】但是依旧没有能摆脱阅读人必然会碰到的问题。看了忘的问题。\u003cbr> \u003cbr> \u003cbr>【反思】\u003c/p>\u003cp>过去在进行阅读的时候，针对一些技术性、学科类书籍的阅读，对其中的知识点没有采用过积极阅读的方法来对知识点进行有效的获取，特别是针对《如何高效学习》这本书也没有用该书的方法进行阅读。以至于在进行阅读笔记输出的时候，写不出主要观点，没有进行关联、拓展、应用。\u003cbr> \u003cbr>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>好的，在理解了今天学习的新知内容，以及了解了新知的应用场景后，和我给出的经验分享后。\u003cbr>接下来请大家回想一下，自己在学习某个概念的时候，请想想自己有没有经历过类似的情境或者相关的经验？在小组内分享。\u003cbr>为了便于各位在组内进行讨论、因为今天人不多，我们就分为一组。给大家3分钟讨论时间。结束后，我会邀请一位伙伴进行分享。\u003cbr> 提醒大家的是，分享时应有明确的时间、地点、人物、起因经过、结果，主要是真实地记录当时你的做法，大家可以参考我的A1便签！回溯的时间最好不要超过半年。\u003c/p>\u003cp>\u003cstrong>【学习者案例】现场记录——案例\u003c/strong>\u003c/p>\u003cp>曾老师：我刚才在小组讨论的时候说到之前看过了一本书，就是人生设计课的那个作者重新写的一本新书，好像叫《重新设计你的工作》，当时为了做人生设计课这个拆书课的时候，就把这个作者的一本新书也一块看了，想的就是两本书结合起来做一堂拆书课。\u003c/p>\u003cp>但是现在再回忆起来的话，对于人生设计课还能回想起来，可是那本新书的内容，我几乎已经全部忘了，现在回想起来的问题，就是刚才你说的，没有采取主动阅读的方式，所以导致对那本书彻底的遗忘。如果还有机会再重新学习一次的话，可能就会用今天学到的这个方法，先想一想这本书我想要找到的是有关于哪一些方面的观点，然后再针对这些观点去找钩子，最后再匹配一些场景进行学习，可能就能记得下来了，谢谢。\u003c/p>\u003cp>\u003cstrong>【A2】 （催化应用）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>接下来，请大家设想一下，在未来一周或一段时间内你有什么学习内容，可以实践这个方法。\u003cbr> 大家可以参照下我的行动步骤模板，在便签上写下你的应用步骤。需要提醒大家的是，你的行动计划中需要有具体的时间、可衡量可预期的目标、可执行的行动步骤。时间是2分钟，写完后把便签交给我进行监督。\u003c/p>\u003cp>【结尾】\u003c/p>\u003cp>以上就是本次我的拆书分享。感谢大家的聆听。给大家准备了便签，大家可以写上对我想说的话。帮助我更好的提升拆书技能。\u003cbr>感谢各位能来现场参加本次活动。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1763281994000,"updated_at":1764043608000,"ria":true},{"id":19418,"topic":"费曼学习技巧","learn_goal":"","remark":"费曼学习技巧","level":"TF1-1","duration":14,"status":30,"type":0,"chaishujia":{"username":"沐沐2025","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>【个人介绍】\u003c/p>\u003cp>各位伙伴，大家好。欢迎参与我的拆书家线下过级。这是我的拆书家1-1的过级，首先，介绍下自己。大家可以叫我沐沐，如沐春风的沐沐。在过去的地球生活中，我做过的，自己认为最有成就的一件事，就是在海拔5562米的卓玛拉垭口，见证了人生的新高度。作为一个I人，我喜欢倾听他人的故事，愿意为他人做一个树洞的存在。作为一个Geek，我很乐意为他人解答与电脑相关的问题。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>现场有不少新朋友，应该是第一来参加拆书活动，那我先给各位简要介绍下，拆书帮、拆书家及拆书法分别是什么：\u003c/p>\u003cp>\u003cbr>【什么是拆书帮】\u003cbr> 拆书帮是基于拆书家的\u003cstrong>学习者社群\u003c/strong>，是一个非营利性组织，表现为各地的拆书帮分舵，其\u003cstrong>使命\u003c/strong>是帮助更多学习爱好者成长为拆书家。拆书帮的\u003cstrong>创始人\u003c/strong>是赵周老师。\u003cbr>【什么是拆书家】\u003cbr>作为拆书帮的主体，拆书家在拆书帮体系中扮演着多重关键角色，其\u003cstrong>核心使命\u003c/strong>是促进\u003cstrong>学习者\u003c/strong>将书本知识转化为实际行动能力。\u003cbr>【什么是拆书法】\u003cbr>拆书法是让你读完书后能够\u003cstrong>学得会、带得走、用得上\u003c/strong>的好方法。\u003cbr>拆书法是以\u003cstrong>学习者为中心\u003c/strong>，特别适合\u003cstrong>成年人的学习方法论\u003c/strong>。\u003cbr>拆书的“拆”不是拆散的拆，是\u003cstrong>拆为己用\u003c/strong>，是内化和应用知识的过程。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>下面就正式进入我们的拆书环节，今天我选取的图书是《如何高效学习》。\u003cbr> 作者是斯科特·扬，是一位因“超速学习”成名的学习实践家。他曾用自创的方法完成“10天攻克线性代数”“\u003cstrong>一年修完MIT四年课程\u003c/strong>”等看似不可能的任务。本书系统呈现了他的核心学习体系，涵盖整体性学习策略、快速阅读法、流笔记法、比喻法、内在化等七大实用技术，并从生活安排到时间管理，提供完整的高效学习支持系统。本书最大的优势在于“真实可操作”。这本书将带你跳出碎片化学习的困境，通过系统性思维+结构化方法，让你用更少时间，掌握更深的学识。不只是学得快，更是学得明白、记得长久。认真操作，你或许也能成为别人眼中的“学霸”。\u003c/p>","ratings_count":1,"texts":[{"id":23788,"quote":"\u003cp>【R原书拆页】\u003cbr> 下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003cbr> 第一步：选择要学习的概念。\u003cbr> 首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003cbr> 第二步：设想你是老师，正在试图教会一名新生这个知识点\u003cbr> 这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清。\u003cbr> 第三步：当你感到疑惑时，返回去吧\u003cbr> 每当众多碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003cbr> 第四步：简单化和比喻\u003cbr> 如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003cbr> 例如：在学习力矩时，用简单的话解释力矩，而不是照抄书上的定义。比如，首先用俗语“扭曲”来说清楚力矩是什么意思。\u003cbr> 其次，给力矩找个恰当的比喻，我把力矩向量比喻为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>","explains":"\u003cp>各位，下面我将按照3W1H原则给分享一下我的I便签。\u003cbr>\u003cstrong>[what] 费曼技巧是什么\u003c/strong>\u003cbr>费曼技巧是一种高效学习方法，其核心在于通过\u003cstrong>模拟教学\u003c/strong>的方式，来检验和深化自己对某个知识的理解。它主张学习时设想自己需要将这个概念传授给毫无基础的人，并力求用最简单、形象的语言进行解释。\u003cbr> \u003cbr>\u003cstrong>[why]为何选择费曼技巧\u003c/strong>\u003cbr>我们常常在学习时觉得已经弄懂了一个概念，但真正尝试向别人讲解时，却会卡壳或发现逻辑漏洞。费曼技巧正是针对这一痛点，从深化理解、巩固记忆、助力应用于考试三个方面提升学习效果。\u003cbr> \u003cbr>知道了费曼技巧是什么，以及为什么学习后，该如何应用该技巧呢？\u003cbr>\u003cstrong>[how]如何实践费曼技巧\u003c/strong>\u003cbr>以下是实践费曼技巧的四个关键步骤，可以用一张白纸来辅助完成\u003cbr>\u003cstrong>第一步：确立目标\u003c/strong>：在白纸顶端写下想要深入学习的概念或知识点名称。明确目标是高效学习的第一步。\u003cbr>\u003cstrong>第二步：尝试教学（核心环节）\u003c/strong>：想象你正在向一个完全的外行（比如一个孩子）解释这个概念。用自己的话写下你的解释，尽可能避免使用任何专业术语。这一步的\u003cstrong>关键在于模拟教学输出。\u003c/strong>\u003cbr>\u003cstrong>第三步：回顾与查漏\u003c/strong>：在第二步中，你很可能会遇到讲不明白、卡壳或者解释不清的地方。这些卡顿点恰恰是你知识结构的薄弱环节，非常宝贵。标记出这些部分，然后回顾原始学习资料，或通过查阅其他资源、向人请教，专门攻克这些难点，直到你能流畅地解释。\u003cbr>\u003cstrong>第四步：简化与类比\u003c/strong>：在确保解释准确的基础上，努力简化你的语言，使其更加精炼易懂。尝试使用类比或生活中的比喻来解释抽象概念。例如，将“致用类阅读”比作“看医生”，目的是“解决问题”，这样就非常形象。\u003c/p>\u003cp>通过以上步骤，相信你对费曼技巧的操作有了一定的了解，当然不是有了锤子看什么都是钉子，费曼技巧也是有适用边界的。我进行了如下梳理（读其中的一、二条适用及不适用的场景），其中这个技巧很适合理解概念性知识、但不适合高度依赖肌肉记忆和重复练习的技能。\u003c/p>\u003cp>\u003cstrong>[where]费曼技巧的适用边界\u003c/strong>\u003cbr>费曼技巧在以下情境中能有效提升学习效果：\u003cbr>\u003cstrong>理解概念性知识：\u003c/strong>当你需要深入理解某个定义、原理或理论框架（如勾股定理、供求关系），而非仅仅记住结论时，该方法能迫使你探究其本质和来龙去脉。\u003cbr>\u003cstrong>攻克难点与查漏补缺：\u003c/strong>在复习中，通过尝试讲解，可以快速暴露知识薄弱环节（如讲解卡壳、逻辑不清之处），从而针对性巩固。\u003cbr>\u003cstrong>掌握过程性与技能性知识：\u003c/strong>对于有明确步骤的内容（如解题流程、软件操作），该方法能帮助你理解每一步的缘由和关联，而不仅是机械记忆步骤。\u003cbr>\u003cstrong>优化表达与沟通：\u003c/strong>当需要向非专业人士解释复杂内容时，该方法要求的“简化与类比”能助你剥离专业术语，使沟通更顺畅。\u003cbr>\u003cstrong>知识的内化与整合：\u003c/strong>该方法能促进新知识与已有经验的连接，助力完成从“知道”到“理解”再到“能运用”的转化。\u003cbr>不适用或需谨慎使用的场景\u003cbr>在以下情况，费曼技巧可能并非最优选择：\u003cbr>\u003cstrong>高度依赖肌肉记忆和重复练习的技能\u003c/strong>：如乐器指法、体育运动动作等，其精髓在于身体的重复练习和感觉培养，语言解释往往事倍功半。\u003cbr>\u003cstrong>高度抽象或侧重个人情感体验的内容\u003c/strong>：如某些哲学概念、诗歌意境等，这类内容常具有多义性和主观性，强求“简单解释”可能损失其丰富内涵。\u003cbr>\u003cstrong>纯粹的事实性信息记忆\u003c/strong>：如记忆大量独立单词拼写、历史日期等，这类信息通常更依赖记忆技巧或间隔重复。\u003cbr>\u003cstrong>信息量极大且结构松散的内容初期\u003c/strong>：面对庞大主题时，直接应用易无从下手，更好的策略是先整体梳理框架，拆解模块后再逐一攻克。\u003cbr>\u003cstrong>知识探索的最早期阶段\u003c/strong>：当对一个领域完全陌生时，首要任务是广泛输入以建立基本感知，而非立即追求“清晰解释”，否则易因信息不足而挫败。\u003c/p>","interaction":"\u003cp>【A1便签】\u003c/p>\u003cp>接下来，给大家分享下我的经验：\u003cbr>【经验】 \u003c/p>\u003cp>2025年10月，我加入拆书帮训练营学习拆书方面的知识。其中有一个课程内容的知识点叫“MTV法则”，这个教学法用来开展做自我介绍。我当时法则看了两遍，认为自己就理解了，记住了。\u003cbr>直到2015年10月的某天，我参加了一场社群活动，当时有一个环节，我想尝试用MTV法则介绍自己，才发现自己还存在卡壳和表述不不全面的问题。\u003c/p>\u003cp>【反思】\u003cbr> 现在回想，如果当时掌握了费曼技巧，可以运用费曼技巧的四步法来学习“MTV法则”。\u003cbr>\u003cstrong>第一步：选择概念，\u003c/strong>明确目标。\u003cbr>\u003cstrong>第二步：以教代学，输出初稿\u003c/strong>。\u003cbr>\u003cstrong>第三步：查漏补缺，搞懂难点。\u003c/strong>在第二步中，我会不可避免地发现某些环节解释不清或存在卡壳。这些“卡壳点”正是我的知识薄弱环节，需要重点标记出来。\u003cbr>\u003cstrong>第四步：简化表达，形象类比\u003c/strong>。将复杂的MTV法则用直白的语言重新表述，可以创造生活中的类比或比喻。\u003c/p>\u003cp>以上是我的经验和反思，那接下来我展示下，如何运用今天这个拆页片段。首先是按照SMART原则设定目标。\u003c/p>\u003cp>【A2便签】\u003c/p>\u003cp> 【设定目标】（Smart原则）\u003c/p>\u003cp> 计划2025年12月30日前，用费曼技巧学习拆书法二级技能点，至少完成2-1和2-2的7个技能点的学习。确保自己通过学习后顺利过级。\u003c/p>\u003cp>【详细措施】\u003cbr> 为了完成以上目标，结合费曼技巧拟定措施如下：\u003cbr> \u003cstrong>第一步：设计模板框架\u003c/strong>（计划2025年11月15日前完成）\u003cbr> 核心是为每个技能点准备一个电子文档，并规划好固定的记录区域。例如，可以划分为“技能名称”、“核心解释”、“常见误区/卡壳点”、“生活化比喻/案例”以及“我的应用计划”等板块。使用统一的模板能系统化地记录学习过程，方便日后回顾与迭代。\u003cbr> \u003cbr> \u003cstrong>第二步：以教代学，输出初稿\u003c/strong>（计划2025年11月24日前完成）\u003cbr> 针对选定的技能点，想象你需要向一位毫无该领域背景的朋友（或像“小白”一样的学习者）讲解。在这一步，完全使用自己的语言来书写技能的核心内容，刻意避免直接抄录手册中的专业术语。关键在于模拟“教学”场景，迫使自己组织思路、消化知识，而不仅仅是复述。\u003cbr> \u003cbr> \u003cstrong>第三步：识别卡点，针对性攻克\u003c/strong>（计划2025年11月31日前完成）\u003cbr> 在第二步书写“教案”时，必然会遇到解释不清、逻辑跳跃或概念模糊的“卡壳”处。这正是费曼技巧的价值所在——精准暴露知识盲区。标记这些难点，然后带着问题回头精读手册、查阅优秀实录案例，或向导师、同伴请教，直至能用简洁的语言清晰地解释通顺。\u003cbr> \u003cbr> \u003cstrong>第四步：精炼与类比，实现内化\u003c/strong>（计划2025年12月15日前完成）\u003cbr> 在理解无误的基础上，对技能点的描述进行极致简化，尝试用一句话概括其精髓。更进一步，为它寻找一个贴切的生活化比喻或类比。例如，将“积极倾听”比作“像Wi-Fi信号放大器一样，先全盘接收信息再予以增强反馈”。这个从抽象到具象的转换过程，能极大加深理解并促进记忆。\u003c/p>\u003cp>【结尾】\u003c/p>\u003cp>以上就是本次我的拆书分享。感谢大家的聆听。给大家准备了便签，大家可以写上对我想说的话。帮助我更好的提升拆书技能。\u003cbr>感谢各位能来现场参加本次活动。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1762863944000,"updated_at":1764043596000,"ria":true},{"id":17586,"topic":"如何才能做到高效学习","learn_goal":"","remark":"解决养成新习惯的痛点，让你享受习惯，享受这个坚持的过程，当你享受其中，快乐的情绪给到你更多正面的反馈，源源不断的自驱力应运而生，培养新习惯，替代旧习惯不再是难事。","level":"TF1-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"梁嘉雯","city":"佛山市"},"club":{"name":"佛山有为筹备分舵","city":"佛山"},"prologue":"\u003cp>【拆解图书】《如何高效学习》\u003c/p>\u003cp>【拆解主题】如何养成每日习惯\u003c/p>\u003cp>【拆解级别】TF1-1\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是嘉雯，是今天的拆书分享者。欢迎大家今天来参加拆书活动。\u003c/p>\u003cp>按照拆书帮的传统，我先用三个标签来简单介绍一下我自己：\u003c/p>\u003cp>第一个标签是爱成长，我是终身成长的践行者，活到老学到老，保持学习的状态，心态年轻烦恼少。\u003c/p>\u003cp>第二个标签是爱经营，我喜欢看心理学相关的书籍，也喜欢看育儿和亲密关系领域的书籍，去思考如何经营身边的亲密关系和与自己的关系；\u003c/p>\u003cp>第三个标签是爱美食，喜欢搜罗各种美食，和喜欢自己动手制作美食。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>在阅读上面，你是否有这样的困惑：看了很多书，看完就忘了，做了很多笔记，也就留在了文件夹里吃灰。那怎么样才能做到高效阅读，让知识真正地为我所用呢？拆书法帮到你！\u003cbr> \u003cbr> 所谓拆书，就是以学习者为中心，把书上的原文片段联系实际经验，去帮助我们提升能力和解决问题。拆书法有扎实地成人学习理论基础。成人的学习不再是只追求懂多少，而是能用多少，真正做到学以致用。\u003cbr> \u003cbr> 拆书法分为个人学习和组织学习\u003c/p>\u003cp>个人学习指以学习者为中心，用RIA便签学习法来拆书，R指的是阅读原文，I意思是用自己语言重述原文，A意思是联系经验，催化应用。写3张便签，拆完一本书就能够达到参加同主题培训的效果。\u003c/p>\u003cp>而组织学习是通过RIA现场学习，更多集中在拆书家引导现场学习者把知识拆为己用。\u003c/p>\u003cp>众多的拆书学习爱好者汇聚一堂，组成了拆书帮，目前全球一共有70多个拆书帮正式分舵，这些都是由非盈利性青年自行组织，致力于让更多的学习爱好者成长拆书家，陪伴赋能，拆为己用，反求诸己，深度学习，共同成长。如果感兴趣的朋友，欢迎你们的加入。\u003c/p>","ratings_count":1,"texts":[{"id":21779,"quote":"\u003cp>\u003cstrong>片段来源：\u003c/strong>《如何高效学习》P158\u003c/p>\u003cp>\u003cstrong>【R：阅读原文片段】\u003c/strong> 如何养成每日习惯\u003c/p>\u003cp>习惯的养成是另外一个课题，足以写一本书。我专门为此写过一本电子书。改变习惯并不像想象的那么困难，我在下面列举了一些养成正确习惯的方法，供大家参考。\u003c/p>\u003cp>(1)坚持某个习惯30天。比如每天阅读40页坚持一个月，每天练习网页设计一小时。为你接下来的30天设定一个每天都要坚持的学习目标吧，30天的坚持会形成一种习惯。\u003c/p>\u003cp>(2)坚持下去。每天以同样的方式完成同样的习惯，今天阅读，明天听讲，后天练习的方式对于养成习惯来说太脱节了。\u003c/p>\u003cp>(3)享受这个习惯。假如你不能享受这个习惯，这个习惯就不牢固。用头脑风暴法列举出各种各样可以养成的习惯吧，我想在一大堆想法中找出一个让你享受的习惯（阅读、练习和目标设置）应该不难。\u003c/p>\u003cp>(4)寻找特殊时段。我喜欢晨读，因为这对于我来说是一段不受打扰、可以专心思考的安静时段。找到属于你的每天特殊时段有助于强化你的习惯。 \u003c/p>","explains":"\u003cp>【What】：拆页的内容是和习惯养成相关的内容。《如何高效学习》的作者斯科特.杨提出了一个养成正确习惯的方法，如果你有这方面的需求，说不定就能帮到你！选定一个想要培养的习惯作为目标，每天同样的时间，以同样的方式，坚持30天并享受这个习惯，习惯就在不知不觉中养成了。\u003c/p>\u003cp>【Why】：你有没有过这样的经历，培养习惯起初雄心壮志“我一定要把这个习惯培养下来”苦哈哈的坚持了一个星期，两个星期，后面动力不足就放弃了，有的人还会给自己贴上“三天打鱼两天晒网”的标签。其实大可不必。不能培养新习惯不是自己不能坚持，而是方法上出问题了。\u003c/p>\u003cp>斯科特.杨提出的方法正好解决养成新习惯的痛点，让你享受习惯，享受这个坚持的过程，当你享受其中，快乐的情绪给到你更多正面的反馈，源源不断的自驱力应运而生，培养新习惯，替代旧习惯不再是难事。\u003c/p>\u003cp>【how】：养成正确习惯的方法具体分四步走：\u003c/p>\u003cp>1. 筛选习惯：写出你想养成的各种各样的习惯，并从中挑选你最享受的习惯作为你的目标。\u003c/p>\u003cp>2. 寻找时段：找到对你来说特殊的时间段，可以让你不受干扰地完成习惯。\u003c/p>\u003cp>3. 固定方式：每天以同样的方式完成同样的习惯。\u003c/p>\u003cp>4. 坚持30天：接下来的30天设定一个习惯养成的目标，每天完成。\u003c/p>\u003cp>【Where】 : 这个方法适用在工作，生活，学习中想要培养新习惯的场合。不适用于安于现状，不想改变的人群。\u003c/p>","interaction":"\u003cp> 【A1】\u003c/p>\u003cp>去年10月的时候立了一个flag，想要养成一个每天读书的习惯，保持一个读书的状态，我的计划是每天晚上睡前读一页书，但是坚持了2个星期就放弃了。结合斯科特.杨的养成正确习惯的方法，反思一下我这个读书习惯的养成情况：\u003c/p>\u003cp> 1. 筛选习惯：读书这个习惯我是享受的，在这个过程中我感到身心舒畅。\u003c/p>\u003cp> 2. 寻找时段：我找了晚上睡前这个时段，但其实这个时间段常常很忙碌，有时候还会被孩子打断，所以这个时间段不合适。\u003c/p>\u003cp> 3.固定方式：每天在房间看一页书，这个方式是固定的。但是内心有时候为了完成计划，就潦草应付翻一番书就算了。\u003c/p>\u003cp> 4.坚持30天：没有坚持30天，只是坚持了2个星期就没有坚持下去了\u003c/p>\u003cp>以上就是我对习惯没有培养下来的反思。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>2024年都过去了差不多一半了，我看完的书本一只手可以数过来。我的目标是“养成一个每天看半小时书的习惯”，结合上面的经验，调整了培养习惯的方法，我的计划如下：\u003c/p>\u003cp>1.筛选想读的书。想读演讲主题的书《高效演讲》\u003c/p>\u003cp>2. 寻找不受干扰的时间段。工作日午休时段比较固定12点-12点30\u003c/p>\u003cp>3. 固定的方式，调整为在办公桌上阅读这本书半个小时。\u003c/p>\u003cp>4. 坚持30天，每天阅读半个小时，直至读完，以一本书为一个习惯养成的周期，设置阶段性奖励， 每天读完了就在台历上打勾‘\u003c/p>\u003cp>以上就是我的拆书分享，谢谢大家\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1715322714000,"updated_at":1727233352000,"ria":true},{"id":16349,"topic":"四问学习法帮你完成学习步骤&比喻法帮你深入理解和记忆","learn_goal":"","remark":"每天都在看朋友圈的干货，觉得自己在学习。\n\n一周一本书，觉得自己在学习。\n\n参加培训班，觉得自己在学习。\n\n刷抖音，看视频，觉得自己在学习。\n\n那为何真正需要用的时候你忘了这些干货和知识呢？\n\n知道吗？\n\n这些动作只是在获取信息。\n\n还要完成了基本的学习步骤。\n\n来！\n\n参加我的拆书活动，\n\n两招让你搞定学习，拿到学习结果。","level":"TF2-4","duration":55,"status":30,"type":0,"chaishujia":{"username":"小东","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家晚上好，我是小东，是今天2-4拆书家，今天我拆的这本书叫《如何高效学习》。在拆书之前，先给大家分一下组，便于稍后的讨论。\u003c/p>\u003cp>F（特征，核心是书）：本书的作者是斯科特•扬（Scott Young），这是一个用1年时间修完麻省理工33门课的大神级人物，这本书主要是介绍他的整体性学习方法。\u003c/p>\u003cp>A（优势，重点是比较）：跟同类学习方法类书籍《跃迁》比较，它系统的介绍了整体性学习策略，全书围绕整体性学习方法的具体步骤来讲解，还把用到的概念和学习技术很贴心的整理汇总，非常实用。\u003c/p>\u003cp>B1（利益，强调的是学习者收获）：本书介绍了整体性学习策略，提供了具体的步骤，只要对照练习，就能掌握方法，提高自己的学习技能。\u003c/p>\u003cp>B2\u003cstrong>片段益处\u003c/strong>：今天的学习大家将掌握两个技能：\u003c/p>\u003cp>1. 在自学的时候，可以利用四问学习法引导自己完成理解，记忆，拓展和应用的学习过程。\u003c/p>\u003cp> 2.对需要深入理解和记忆的知识，能运用“比喻三步法”，找到自己过往相似的经验，达到新知与熟悉的经验进行链接的目的。\u003c/p>\u003cp>今天的学习总目标是：\u003c/p>\u003cp> 希望完成本次现场学习后，学习者能通过“四问学习法”深度的理解学习内容，通过“比喻三步法”，加强记忆，从而提升学习效率。\u003c/p>\u003cp>逻辑关系：\u003c/p>\u003cp> 两个拆页的逻辑关系是递进关系，第1个拆页是教我们深度理解学习内容，第2个拆页是理解之后怎样去加强记忆。\u003c/p>\u003cp>拆页一学习目标：\u003c/p>\u003cp> 通过拆页一的学习，学习者在自学时，能运用“四问学习法”引导自己完成理解，记忆，拓展和应用的学习过程，达到加深理解学习内容的目的。 \u003c/p>\u003cp>接下来开始我的拆书，第一个主题是：利用四问学习法完成学习步骤。请大家花１分钟时间来阅读一下这个拆页。阅读完的伙伴请举手示意我。\u003c/p>","ratings_count":2,"texts":[{"id":20461,"quote":"\u003cp>进行积极阅读时你需要记下：\u003c/p>\u003cp>（1）这一节中主要观点是什么？\u003c/p>\u003cp>（2）我怎样才能记住主要观点？\u003c/p>\u003cp>（3）我要怎样将主要观点拓展开以及应用它。\u003c/p>\u003cp>第一个问题仅仅促使你完整地获取信息；第二个问题迫使你对信息进行联系、视觉化和比喻法；第三个问题要求你将信息应用在不同的情境中。这三个问题迫使你将每个知识点都要经过整体性学习里的理解、拓展和应用三个阶段。\u003c/p>\u003cp>比如我刚刚读完心理学中的经典条件反射，其主要的知识点是：\u003c/p>\u003cp>·经典条件反射的发现者是巴甫洛夫\u003c/p>\u003cp>·经典条件反射是刺激引起反应\u003c/p>\u003cp>我会这样记忆：\u003c/p>\u003cp>·想象一副图画，画中巴甫洛夫的狗听到铃声流出了唾液。\u003c/p>\u003cp>我会这样拓展：\u003c/p>\u003cp>·我听到电视里类似的手机铃声，会不由自主地掏出自己的手机。\u003c/p>\u003cp>如果你能对教科书里的每一个知识点都进行这样完整的积极阅读，你一定会天下无敌。一旦你熟悉了这种方式，就不必对每个知识点进行完整的积极阅读，而只针对自己需要理解和记忆困难的那些内容。\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴已经阅读完了。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>或许大家会有这样的困惑：明明这个知识点自己看过，为什么到考的时候就记不起来呢？其实学习是一个有具体步骤的过程，看过一遍只是学习的第一步获取信息。\u003c/p>\u003cp>今天的拆页就帮我们解决了走完学习过程的问题。拆页的核心有三步，分别是信息的主要观点是什么？怎么记住观点，如何对观点进行拓展和应用，其中第三步拓展和应用合在一起比较难应用，我把这一步细化为两步，先对观点进行拓展，激发过去的经验或将知识变成具体的应用技能，然后再规划未来如何应用，这样就便于使用，我把这个技能叫做四问学习法。\u003c/p>\u003cp>【细化行动步骤】\u003c/p>\u003cp>那四问学习法具体怎么做呢？\u003c/p>\u003cp>第一步，我看到什么？通过这个提问让自己提炼关键信息，整理成主要观点。\u003c/p>\u003cp>第二步，我想到什么？通过这个提问，让自己能深入理解和记忆信息，我怎样用自己的话来重述原文。\u003c/p>\u003cp>第三步：我变成什么？通过这个提问，让自己能将知识变成具体的技能或应用规则。\u003c/p>\u003cp>第四步，我用在哪里？通过这个提问，引导自己规划未来把知识用在哪些地方。\u003c/p>\u003cp>【强调不这么做的坏处】\u003c/p>\u003cp>\u003cstrong>（一般做法）\u003c/strong>我们大部分人在学习的时候以为看了，学习就完了。其实这才做到了学习过程的第一步获取信息。\u003c/p>\u003cp>\u003cstrong>（这种做法的坏处）\u003c/strong>这个信息没有经过自己的理解，拓展和应用，当时是以为自己学到了，但实际上没有深刻理解，导致看了就忘。同时也很浪费时间，以为自己学习了，其实没有拿到学习结果。\u003c/p>\u003cp>\u003cstrong>（反例）\u003c/strong>我在《瞎吃》这本书上看到这样一段信息“研究人员普遍认为，至少要花20分钟，我们的身体和大脑才能传递饱足的信息，信息传达之后，我们才会觉得自己吃饱了。”然后就完了，我还觉得这本书很无聊，这个信息对我也没什么用。\u003c/p>\u003cp>\u003cstrong>（回顾how,反例变正）\u003c/strong>当我学了四问学习法这个技能后再看着段信息的时候，我会问自己：\u003c/p>\u003cp>我看到什么？这段信息的主要观点是大脑比胃的感觉要慢20分钟。\u003c/p>\u003cp>我想到什么？胃饱的信息传递给大脑要花20分钟时间，大脑再让嘴停下来不进食时，已经多吃了20分钟的食物，这样每次都多吃，不胖才怪。\u003c/p>\u003cp>我变成什么？吃饭的时候少吃20分钟？不现实，应该是少吃20%的食物比较合适。\u003c/p>\u003cp>我用在哪里？吃饭要提前决定，比自己想吃的量少打20%的饭菜，防止自己吃的过多。\u003c/p>\u003cp>这样经过这四步，我把这个信息变成了一个可以触发自己管理自己饮食的技能，真正做到了学以致用。\u003c/p>","interaction":"\u003cp>【A1】【显像提问】\u003c/p>\u003cp>好，现在大家想一想，（构建情境）我们有没有觉得知识点很好，随手在手机里点了收藏，但自己后来又没去看这篇文章，也没有去应用的经历？有，好，我们找出一个来（激活经验）时间1分钟，我请小伙伴分享。\u003c/p>\u003cp>诗奇：看了一个很好的微信文章，只要加一步就能让人思维混乱，逻辑混乱，当时觉得很好，随手点收藏，结果到现在还没有用起来。\u003c/p>\u003cp>刚才诗奇给我们分享了一个没有用四问学习法引导自己走完学习过程的例子谢谢诗奇的分享。\u003c/p>\u003cp>刚才大家分享了一些没有走完学习过程的案例，那大家如果再去看书学习时，尝试用今天学到的四问学习法引导自己完成学习步骤，你会怎么做呢？请大家讨论一下，1分钟后我请一位代表分享。\u003c/p>\u003cp>拆书家：你上次没走完学习过程那篇文章是什么？\u003c/p>\u003cp>诗奇：我上次看了觉得好的，但没有走完学习过程的那篇文章是学会提问。\u003c/p>\u003cp>拆书家：那你拿起手机，用四问学习法走完全过程，应该怎么做呢？\u003c/p>\u003cp>诗奇：我看到了篇文章写的是情景，问题，行为，求助四个框架来提问。\u003c/p>\u003cp>诗奇：我想到什么，我只要提问的时候，都可以把我想提的问题信息先整理成情景，问题，行为，求助的框架，然后讲出来。\u003c/p>\u003cp>诗奇：我变成了什么，我把这情景，问题，行为，求助变成四个提问步骤，先描述情景，再讲出我的问题，然后描述行为，最后提出诉求。\u003c/p>\u003cp>诗奇：我用在哪里，我用在我的求助上。我家孩子特别爱蹦蹦跳跳（背景），我很担心他摔倒，注意力不集中(问题），我给他报了一个乐高课（行为），想让他通过上这个课改善一下注意力集中问题，我想问一下还有哪些方法能改善和提高孩子注意力（求助）\u003c/p>\u003cp> 非常感谢诗奇的分享，大家给她一点掌声。\u003c/p>\u003cp>用四问学习法引导自己完成学习步骤就算学会知识了吗？不一定，四问学习法中的第二步记忆就很让人头痛，那大家都是怎么记忆的呢？\u003c/p>\u003cp>拆页二学习目标：\u003c/p>\u003cp> 通过拆页二的学习，学习者在遇到需要记忆的学习内容时，能利用比喻三步法， 找到新知识与自己过往相似的经验，达到新知与熟悉的经验进行联系，强化记忆的目的。\u003c/p>\u003cp> 这本书介绍了一个加深理解和记忆的方法，“比喻三步法”，将新学的知识与熟悉的知识进行链接，它们就会被自己理解得越好，记得越牢。请大家用两分钟时间阅读一下拆页二，看完后抬头示意我。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":20462,"quote":"\u003cp> 比喻法在整体性学习中扮演的角色是类似的，比喻就是在不熟悉的知识和熟悉的知识之间架起一座沟通的桥梁。比喻在文学中主要提供视觉上的相似，而在整体性学习中联系的是类似的过程：事件或者信息的顺序。（其实比喻法不必拘泥于二者有多么相似，只要有一点相似，不管是视觉、听觉、触觉还是直觉，也不管是原理、目的还是过程，都可以拿来比喻，比喻法也就是建立模型的方法。──译者注）\u003c/p>\u003cp>举例来说，\u003cstrong>我们在心理学课上学到了条件反射，\u003c/strong>经典的条件反射讲的是一个刺激经过强化，与一个反应建立联系的现象，这个现象由巴甫洛夫观察狗的行为而发现。巴甫洛夫注意到如果每次给狗送食物之前先按铃的话，以后一按铃，即使不给食物，狗也会分泌唾液。\u003c/p>\u003cp> 怎样应用比喻法学习条件反射？\u003cstrong>比喻法的第一步是在你的个人经验中寻找能够模拟条件反射的东西，\u003c/strong>我个人生长在加拿大的冰天雪地里，所以想到的第一个比喻就是在雪地里行走。你第一次在雪地里行走时，因为雪地茫茫一片，走哪条路都有可能。但是几次行走以后，你会选择一开始走的路，因为开始的行走在雪地上形成了一条隐约可见的小路，走这条路显然比随便走更容易。\u003c/p>\u003cp> 我将雪中走路与条件反射联系在一起，一开始，铃声可能或不引起狗分泌唾液（这代表一开始雪地茫茫一片，无路可寻）。\u003cstrong>但是在将铃声和食物关联在一起后，从铃声到食物的路就在雪地上（狗的大脑里）形成了，最终狗一听见铃声就分泌唾液，因为这条路已经很明显了。\u003c/strong>像许多比喻一样，这个比喻也不完美，但是它很有用。\u003c/p>","explains":"\u003cp>【what】原文讲用“比喻法”来理解和记忆“条件反射”的例子，通过整理“条件反射”的本意“刺激经过强化形成一个反应联系”，然后在自己过往的经验找到一个跟“条件反射”信息特征，顺序很相似例子（雪中多次走路形成路），然后将本意和自己熟悉的经验联起来，让自己快速理解和记住了知识。为了方便大家更容易理解比喻法是如何做到的，我举个我自己的案例。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>比如我看了积极阅读法，用比喻法来记忆积极阅读法。我先整理积极阅读法的意思“”阅读后要及时用三个提问来引导自己将知识点完成理解，拓展和应用三个过程顺序”，核心是3个过程顺序，我只要在自己的过往经验里找相似的过程就可以了。\u003c/p>\u003cp>然后我在自己的个人经验里找出与积极阅读法比较相似的过程。这个过程与我到餐馆点菜吃饭的过程比较相似，到餐馆后我先看菜单获取信息，接着我点菜理解菜单，然后等上菜我在想着个菜是怎么做的，好吃在哪里，最后吃饭吃饱。\u003c/p>\u003cp>我把在餐馆点菜吃饭的过程和积极阅读法过程联系起来，看菜单是获取信息，点菜是理解知识点，等上菜是进行拓展知识点，吃饭把肚子吃饱是把知识应用起来。这个比喻和旧经验不同的地方是等上菜跟拓展差异比较大，但整体过程和积极阅读法过程很相似，能让我快速理解和记住这个积极阅读法，达到了我把“积极阅读法”和点菜吃饭链接一起，迅速理解和记住了的目的。\u003c/p>\u003cp>【细化步骤】\u003c/p>\u003cp>结合案例，这个比喻法有很清晰的三个步骤，我将其称为“比喻三步法”。\u003c/p>\u003cp>第一步，理本意。整理出信息的本意，整理出信息的特征，顺序等。\u003c/p>\u003cp>第二步，找相似。在个人经验和熟悉的知识和经验中找到与信息本意相似的特征，顺序部分。\u003c/p>\u003cp>第三步，联知识。把相似的部分联起来，检查比喻中不同的地方，从而建立对新知识更丰富的心理表征。\u003c/p>\u003cp>【案例】我看了“著名的心理和经济学家丹尼尔.卡尼曼提出的峰终定律，它指出人们会更多地受到事件的高峰和结束时刻的影响，而不是事件整个过程中的平均值。” 我用比喻三步法来理解和记忆这个峰终定律。\u003c/p>\u003cp> 第一步：理本意。峰终定律讲人的过程体验受两个时刻影响最大，一个是事件的高峰时刻，一个是事件的结束时刻，定律的特征是2个时刻对人的体验影响最大。\u003c/p>\u003cp>第二步，找相似。在自己的脑海里想“跟2个时刻对人体验影响最大”的经历，我想起自己小时家比较穷，妈妈每次在家请客人吃饭，在几个素菜和凉菜后上一道鱼，然后在快要吃完的时候，上一道甜蛋花汤，家里亲戚都夸我妈能干。\u003c/p>\u003cp>第三步，联知识。请吃饭就是体验过程，上鱼就是体验高峰时刻，最后上甜蛋花汤就是吃饭结束时刻，这样利用有限的资源也让客人觉招待的很周到，这就是峰终定律，不同的是峰终定律主要运用在体验设计上，还有在有限资源下如何将投入产出比最大化的意思。\u003c/p>\u003cp>【where】比喻三步法一般用在对抽象的概念的理解和记忆上，对一些杂乱信息比如一系列日期，专业术语，复杂的规章制度等就不太适合。\u003c/p>\u003cp>【预防异议】可能有小伙伴说，比喻法第二步找相似好困难，其实我们先要做好整理知识点原本带有的特征，顺序，然后利用信息的特征和顺序，从自己熟悉的知识和经验中找到相似性，只要有一点相似就可以拿来比喻。\u003c/p>\u003cp>【回应或反馈】\u003c/p>\u003cp>把比喻法介绍了这么多，请问有没有哪位小伙伴有什么不太明白的地方？\u003c/p>\u003cp>星民：联知识怎么联比较好？\u003c/p>\u003cp>拆书家：星民提了一个非常好的问题，让我们先给他一点掌声。联知识，首先把新知和检验相似的部分联起来，然后再找到两者的不同。我们都是男的，不同是你比我帅。我这样的回答能解决你的困惑吗？\u003c/p>\u003cp>星民: 就是区分的意思。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>教就是最好的学习，大家今天学习了“比喻三步法”，接下来做一个场景演练。\u003c/p>\u003cp>【场景】\u003c/p>\u003cp>李老师是一个善于用比喻法讲解物理概念的老师。\u003c/p>\u003cp>老王正在给儿子讲解压强的概念，物体所受\u003ca href=\"https://baike.baidu.com/item/%E5%8E%8B%E5%8A%9B/5798497\">压力的大小与受力面积之比叫做压强,公式P=F/S，讲了半天，因为老王自己也不太懂压强，所以儿子也没听明白，这让老王急的直冒汗，老王拿起手机打给了李老师，想请李老师用比喻法给自己指点一下，压强怎么用比喻三步法来理解和记忆。\u003c/p>\u003cp>【清晰指令】\u003c/p>\u003cp>压强本意的特征或顺序是什么？我们生活中有哪些跟压强相关的经验？打针；鞋里有颗小石子，硌的脚疼，这个经验跟压强的相似性是什么？如果你是李老师，你怎么用比喻三步法引导老王？请一人扮演老王，一人扮演李老师，组内先讨论1-2分钟，然后再角色演练4分钟，最后请一组小伙伴分享。\u003c/p>\u003cp>学习者演练:\u003c/p>\u003cp>茂林和小帅哥，茂林扮演李老师，小帅哥扮演老王.\u003c/p>\u003cp>小帅哥：我向你请教一下怎么记压强比较好。\u003c/p>\u003cp>茂林：压强的本意是压力和面积的关系，再你的生活经验里有哪些和力，面积相关的事情啊？\u003c/p>\u003cp>小帅哥：掐肉，手指用力，指甲尖接触肉的面积，轻轻一点力就掐的手很疼，如果用指头面捏肉就不疼。\u003c/p>\u003cp>茂林：对啊，这个掐肉有力，有面积，跟着个压强就很相似。\u003c/p>\u003cp>小帅哥：是啊！是啊！\u003c/p>\u003cp>茂林：压强是力和面积的关系，掐肉也是力和受力面积的关系，不同的是压强的单位是帕，牛顿每平方，掐肉就是很疼。\u003c/p>\u003cp>拆书家：太棒了！他俩完美的演绎了比喻法记忆压强的方法，给我们的老王和李老师一点掌声！\u003c/p>\u003cp>大家的手机里都收藏了哪些值得分享的知识？比如元知识，互惠原理等等。现在要选出一个知识下周做部门分享，这个知识是什么？请大家花1分钟写在便签上，并在小组内讨论2分钟，然后我请1~2位朋友出来分享。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>拆书家：你下周你要分享的知识是什么？\u003c/p>\u003cp>诗奇：我打算记忆峰终定律这个概念。\u003c/p>\u003cp>今天晚上你拿起了手机，准备好好记一下这个知识点。我们小组内讨论一下这个知识点的本意是什么，然后再运用“比喻三步法”一起完成理解记忆，最后请小伙伴上台分享你的具体步骤，时间5分钟。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>拆书家：你要记忆的知识点是什么？\u003c/p>\u003cp>诗奇：我要记忆峰终定律这个概念。\u003c/p>\u003cp>拆书家：峰终定律的本意是什么？\u003c/p>\u003cp>诗奇：记忆峰终定律的本意是两个关键时间点特别影响体验。\u003c/p>\u003cp>诗奇：我有个相似的体验，就是去爬山，爬的时候很累，爬上山顶，看山顶风景，心旷神怡，感觉很好，下山后一起吃个饭，也感觉特别香。\u003c/p>\u003cp>诗奇：爬山的这两个时间点跟峰终定律很像，不同的点是峰终定律是心理学的一个概念，而爬山却是我个人具体的体验。\u003c/p>\u003cp>拆书家：太棒了！诗奇完美的演绎了用比喻法记忆峰终定律。大家给她来点掌声。\u003c/p>\u003cp>今天的小伙伴都非常给力！接下来给大家做个总结：通过今天的分享，希望大家在学习中能运用两个技能：\u003c/p>\u003cp>1. 用四问学习法引导自己完成理解，记忆和拓展应用的学习过程。\u003c/p>\u003cp>2. 在对要深入理解和记忆的知识能运用比喻三步法，理本意，找相似，联知识来找到自己熟悉的经验，达到新知与熟悉的经验进行链接的目的。\u003c/p>\u003cp>最后，借用米南德的一句话来结束我的分享，学会学习的人，是非常幸福的人。祝愿今天听我分享的人都生活幸福！\u003c/p>\u003cp> 我是小东，感谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1690972115000,"updated_at":1696325252000,"ria":true},{"id":15328,"topic":"积极阅读法","learn_goal":"","remark":"通过学习积极阅读法，提升自己的学习力！","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"[email]","city":"银川"},"club":{"name":"银川拉拉缨分舵","city":"银川"},"prologue":"\u003cp>大家好，我是银川筹备分舵的李永忠。欢迎参加我今天的TF2-1拆书晋级活动，我今天拆书主题是“积极阅读”。 \u003c/p>\u003cp>\u003cstrong>一、 【自我介绍】（1分钟（134字）\u003c/strong>\u003c/p>\u003cp>首先介绍一下我自己，我是来自银川筹备分舵的李永忠，木子李，永远的永，忠诚的忠，永远忠于内心就是我。\u003c/p>\u003cp>我用三个标签介绍一下自己：\u003c/p>\u003cp>第一个标签是[网络安全]，这是我的本职工作。\u003c/p>\u003cp> 第二个标签是[一级拆书家]，希望未来能够成为三级拆书家。\u003c/p>\u003cp> 第三个标签是[终身学习践行者]，我学习，我快乐。\u003c/p>\u003cp>\u003cstrong>二、 【图书介绍】（1.5分钟360字）\u003c/strong>\u003c/p>\u003cp>【F特征】今天我要拆解的书是《如何高效学习》，作者是斯科特·扬，这是一本教会你如何学习，而且不仅仅是学会学懂，不仅仅是理解知晓，而且还能让你记住。记住，是成年人读书学习难以逾越的一座大山，这本书能帮你解决记不住的问题。\u003c/p>\u003cp>【A优势】作者亲自实践并总结提炼方法，不仅提供了高效学习的理论，还提供了实操技术。比其他书更好的是，提供的方法切实可行，而且还为学习者提供了生活和时间管理的整体方案。\u003c/p>\u003cp>【B利益】\u003c/p>\u003cp>你读书的时候有没有眼睛盯在书上，思绪已经到了天边？\u003c/p>\u003cp>你学习的时候有没有这种情况：一看全会，一背全忘？\u003c/p>\u003cp>你有没有发现，明明是很熟悉的内容，可就是死活想不起来？\u003c/p>\u003cp>这本书能让你读书时集中精力，深入理解，深刻记忆。\u003c/p>\u003cp>【过渡】作者的方法到底如何呢？我们能不能学的到呢？\u003c/p>\u003cp>我们今天就一起来学习书中介绍的一个方法：积极阅读。\u003c/p>\u003cp>\u003cstrong> 三 【学习目标】（0.5分钟，56字）\u003c/strong>\u003c/p>\u003cp>我们今天通过本次RIA现场学习后，能够实现的目标：\u003c/p>\u003cp>能够使用积极阅读的方法去读书学习；\u003c/p>","ratings_count":1,"texts":[{"id":19371,"quote":"\u003cp>积极阅读不仅仅是简单地在书上画各种颜色的记号和在空白处写一写心得体会，还是将知识点真正地整合在一起。\u003c/p>\u003cp>开始积极阅读时，准备好要读的书和笔记本，在笔记本上写下每章的标题和亚标题，每读完一小部分时（指读法），在笔记本上记一些笔记。\u003c/p>\u003cp>进行积极阅读时你需要记下：\u003c/p>\u003cp>（1）这一节中主要观点是什么？\u003c/p>\u003cp>（2）我怎样才能记住主要观点？\u003c/p>\u003cp>（3）我要怎样将主要观点拓展开以及应用它。\u003c/p>\u003cp>第一个问题仅仅促使你完整地获取信息；第二个问题迫使你对信息进行联系、视觉化和比喻法；第三个问题要求你将信息应用在不同的情境中。\u003c/p>","explains":"\u003cp>【I的技能要求：强调不这么做的坏处。】\u003c/p>\u003cp>[What]这个片段介绍的是一种读书学习的方法：积极阅读法。\u003c/p>\u003cp>[Why] 如果不使用积极阅读法，读的时候可能会走神，对内容理解不够深刻，对读过的内容也记不住。\u003c/p>\u003cp>【过渡语：大家知道了积极阅读的好处，不知道大家平常都是这么阅读的呢？现在，就让我们一起来学习一下积极阅读法。】\u003c/p>\u003cp>[How] 如何积极阅读呢？有三点：\u003c/p>\u003cp>第一，明确主题，在纸上写下要阅读的主题，一般是章节的标题或者副标题。不写下来的话，读完之后可能就如过眼云烟，了无痕迹了；\u003c/p>\u003cp>第二，使用指读，就是用手指指着书上的文字来阅读。这样可以集中注意力。你有没有在阅读的时候，突发发现只是眼睛盯着书，脑子早也不知道想到哪里去了。用手指着就不会出现这种情况了。\u003c/p>\u003cp>第三，回顾思考，思考3个问题：1.这个片段的主要内容是什么？2.如何记住这些内容？3.如何拓展并应用这些内容？\u003c/p>\u003cp>[Where]积极阅读用在哪里合适呢？\u003c/p>\u003cp>第一，适合致用类和理论类书籍，以及小说的阅读；\u003c/p>\u003cp>第二，不太适合诗歌、散文之类的内容。\u003c/p>\u003cp>\u003cstrong>【我的故事】[反面案例]（2分钟，460字）\u003c/strong>\u003c/p>\u003cp>下面给大家分享一个我阅读《遥远的救世主》的事。\u003c/p>\u003cp>[起因]很多人都推荐《遥远的救世主》，里面的不少内容很精彩。\u003c/p>\u003cp>[经过]读的时候我也有这样感觉，确实有不少内容很精彩，也会在书上写写划划勾出来。读久了，时不时的也会走神，发现之后就拉回思绪继续读。感觉读得累了就结束。\u003c/p>\u003cp>[结果]整本书读完之后才发现，只记得一些大的事件，很多细节根本记不清楚。想要给别人讲，才发现有点儿困难。\u003c/p>\u003cp>[反思]\u003c/p>\u003cp>[回顾目标] 我的目标就是读完这本书，能把精彩的部分讲给别人听。[评估结果] 等读完书后才发现，只记得那些精彩故事的轮廓，一句话就能说完，连情节都没有，更谈不上精彩。\u003c/p>\u003cp>[分析原因] 讲不出来的原因就是读书方法有问题。结合积极阅读法来分析的话，原因如下：\u003c/p>\u003cp>第一，阅读主题不明确。没有在笔记本上写下阅读主题，读的多少取决于自己的感受，缺乏明确的阅读目标。\u003c/p>\u003cp>第二，没有使用指读法，注意力不够集中。读不了多久就容易走神，读书效率太低。\u003c/p>\u003cp>第三，没有回顾思考。读完一个精彩故事或章节没有停下来回顾思考，没有总结精彩内容，没有特别关注精彩之处的细节，更没有想过记住这些精彩之处。\u003c/p>\u003cp>[总结经验] 以前的阅读的方法不好，发现了就得想办法改变。现在学习了积极阅读法，就要用起来：阅读的时候要明确主题，使用指读法，读完一个章节要回顾思考，尤其是精彩的部分。\u003c/p>","interaction":"\u003cp>【A1激活经验】 【显像提问的A1】 \u003c/p>\u003cp>好的，现在请你回忆一下你曾经读书的情景：\u003c/p>\u003cp>你可能舒服地躺在沙发上，也可能坐在书房的桌子前，屋里的灯光非常柔和，你翻开了一本书。刚开始你还能集中精力阅读，偶尔你还会用比勾画出你认为的重点。没过多久，你发现自己有点儿走神，然后你拉回思绪继续读。就这样不知过了多久，你感觉有点儿累了，准备结束。你合上书的那一刹那，有没有发现：读了那么多，感觉脑子空空的，就算是划过的重点，竟然也没有多少印象。\u003c/p>\u003cp>你读书的时候，有过这样的失败经历吗？\u003c/p>\u003cp>\u003cstrong>[分享]\u003c/strong>：\u003c/p>\u003cp>好的，请分享一下类似这样读书的失败经历。思考时间2分钟。可以把类似的失败经历打在公屏上。也可以用2分钟时间直接语音分享。\u003c/p>\u003cp> \u003cstrong>分享一：\u003c/strong>我平常读书的时候会放一些音乐，有时随着音乐的节奏什么的，也会打乱自己的思路，会想着去看一下手机。又莫名的打开了手机。当我发现要去读书的时候，时间又过了5分钟10分钟了。在读书的时候也没有明确的目标，可能就是为了消遣，为了达成读书这个目标而完成。比如我现在读的《富爸爸和穷爸爸》，在和别人聊天的时候，如果提到这本书的话，我也会说我看过这本书，但是具体让我去表述这本书的内容、观点、带给自己的认知提升，其实都表达不出来。看了就相当于没看一样。\u003c/p>\u003cp> \u003cstrong>分享二\u003c/strong>：我读书的时候，读着读着，手机响一下，我可能就会去看手机了。等我回来再看的时候，这个片段已经记不清了。我又会翻到前面再去看，就会造成读的时间特别长。\u003c/p>\u003cp>【A1+反思加工经验】\u003c/p>\u003cp>我们每个人都有些失败的读书经历，刚才也有小伙伴做了分享。\u003c/p>\u003cp>\u003cstrong>[思考]\u003c/strong>请大家想一想，我们读书的时候，各种问题层出不穷。为什么会这样呢？有人可能觉得读书原本就是如此，或者归因于身体、习惯、年龄等原因。现在，请把你的读书方法和积极阅读法对比，看看有什么不同？其实积极阅读法就是解决这些问题的。如果现在让你读一本书的话，你如何运用积极阅读法？\u003c/p>\u003cp>思考时间为3分钟。\u003c/p>\u003cp>\u003cstrong>【分享自己读书方法的变化，用以提醒小伙伴思考的内容】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[我的过去]\u003c/strong>读《遥远的救世主》时，对书中精彩的部分也勾勾画画。只是为了了解故事而读这本书。没有针对精彩部分做专项主题阅读，阅读过程会走神，缺乏回顾思考的环节。\u003c/p>\u003cp>\u003cstrong>[我的现在]\u003c/strong>如果重读《遥远的救世主》，就使用积极阅读法:先明确内容，写在纸上；然后使用指读，集中注意力阅读内容；最后回顾思考，围绕这三个问题：这个片段的主要内容是什么？怎么记住？怎么拓展应用？\u003c/p>\u003cp>【时间到后如果没有小伙伴分享的话，直接点名分享，分享时间共计5分钟。】\u003c/p>\u003cp>\u003cstrong>[分享]\u003c/strong>如果考虑好的话，请直接语音分享：\u003c/p>\u003cp>1.你以往的阅读方法和积极阅读法的不同之处？\u003c/p>\u003cp>2.如果现在去读书的话，你怎么使用积极阅读法：明确主题，使用指读，回顾思考？\u003c/p>\u003cp> \u003cstrong> 分享一\u003c/strong>：以往的和积极阅读的不同，我感觉我的阅读方法，主题也不明确，是随心所欲的，翻到哪本书就读哪本书。阅读的时候也不够专注，在阅读的时候还在做其他一些事情，比如听音乐，听音乐的时候可能又耍手机去了。也没有形成系统的一些思考、回顾，也没有去总结，看过了就看过了。按积极阅读法的话，它的内容也比较明确，在过程中使用的是指读，这样子就能够让注意力更加集中，第三就是回顾思考、复盘，帮助我们进行很好的一个梳理。\u003c/p>\u003cp> 如果我现在去读书用积极阅读法的话，明确主题，我会估计书的目录去看我感兴趣的主题，并在本子上记录下来这个章节这个主题是什么，在过程中用笔指着书，一排一排的去读。第三步回顾思考，我会根据每一个章节进行梳理，这一章节写了什么内容，用自己的话去总结一下。如果有好的金句，也把它梳理一下。读完这本书之后再进行回顾，包括和他人的分享。这样子的话，比我之前的读书方法要有效，要好很多。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>最后我来总结一下，今天我们学习了《如何高效学习》一书中的“积极阅读”，可以概括为三步：第一，明确主题；第二，使用指读；第三，回顾思考。今天，我们的学习目标是能够使用积极阅读的方法去读书学习。从刚才的情况看，大部分人都能够达成今天的学习目标。\u003c/p>\u003cp> [行动呼吁]如果你要读书的话，请一定尝试一下积极阅读法，我以过来人的经验告诉你，这是最好的读书方法之一。\u003c/p>\u003cp>好的，非常感谢大家参加我的TF2-1晋级活动，感谢积极分享的小伙伴，我非常开心。今天的拆书活动就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1678689456000,"updated_at":1679627962000,"ria":true},{"id":15091,"topic":"费曼学习法","learn_goal":"","remark":"通过学习费曼学习法\"选择、讲解、返回、简化\"的学习步骤，提升学习效果。","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"[email]","city":"银川"},"club":{"name":"银川拉拉缨分舵","city":"银川"},"prologue":"\u003cp>大家好，我是银川筹备分舵的李永忠。欢迎参加我今天的TF1-2拆书晋级活动，我今天拆书主题是“费曼技巧”。\u003c/p>\u003cp>今天我们有个小组分享的环节，可以开麦参加分享的小伙伴请在聊天区扣1。由于参与人员不多，我们就分成一个大组分享。 \u003c/p>\u003cp>首先我介绍一下我自己，我是来自银川筹备分舵的李永忠，永远忠于内心。\u003c/p>\u003cp>我用三个标签介绍一下我自己：\u003c/p>\u003cp>第一个标签是[网络安全]，这是我的主业。网络安全事关国计民生，在这个行业工作多年，我也有幸成为省级专家库的一员。\u003c/p>\u003cp>第二个标签是[职业生涯规划咨询]，这是我的副业。工作生活一脸懵，微信电话找永忠，所有问题全扫空！\u003c/p>\u003cp>第三个标签是[终身学习践行者]，这是一直在持续做的事情。读书、写作、运动每日三件事，日更1400多天。未来还要继续。\u003c/p>\u003cp>今天我要拆解的书是《如何高效学习》，作者是斯科特·扬，我们先看一下作者的学霸历程。上高中的时候课下基本不学习，以全班第二名的成绩毕业。在MIT期间，1年学完了4年的课程，而且GPA均在A到A+之间。用的就是他发明的整体性学习策略。\u003c/p>\u003cp>这本书对此进行了详细介绍。书的优势在于不仅提供高效学习的理论和方法，还为高效学习提供了生活和时间管理的整体方案。\u003c/p>\u003cp>作者的方法到底如何呢？能不能让我们也成为学霸呢？\u003c/p>\u003cp>我们今天就一起来学习书中介绍的一个方法：费曼技巧。\u003c/p>","ratings_count":1,"texts":[{"id":19098,"quote":"\u003cp>【R】费曼技巧（第二部分 整体性学习的实际运用——费曼技巧）\u003c/p>\u003cp>下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>第一步：选择要学习的概念\u003c/p>\u003cp>首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp>第二步：设想你是老师，正在试图教会一名新生这个知识点\u003c/p>\u003cp>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清。\u003c/p>\u003cp>第三步：当你感到疑惑时，返回去吧\u003c/p>\u003cp>每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>第四步：简单化和比喻\u003c/p>\u003cp>如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003c/p>","explains":"\u003cp>[What]这个片段介绍的费曼技巧，是一种深入理解和深刻记忆知识的方法，它是一种以教促学，不断在教与学中循环，让你彻底学懂学会的方法。\u003c/p>\u003cp>[Why]为什么要使用费曼技巧呢？它有两大好处，第一，通过输出倒逼输入，通过讲解倒逼学习。第二，就是解决了我们不知道自己不知道的问题，它是查缺补漏的利器。\u003c/p>\u003cp>[How]使用费曼技巧有四步：\u003c/p>\u003cp>第一步，选择。选择你想要深入理解、深刻记忆的概念。把它写在一张纸的上面，就是为了明确学习目标，有的放矢。\u003c/p>\u003cp>第二步，讲解。把自己想象成老师，要把这个概念讲给对此一无所知的小白听。你得思考怎么讲才能让对方听得明白，这是帮助你加工信息，理清思路、理解概念的过程。\u003c/p>\u003cp>第三步，返回。当你讲不下去的时候，不管是讲不出来还是组织不了语言，都返回去重新学习，并把学到的内容写在纸上。这让你明确再次学习的目标，加深理解和记忆，查缺补漏的环节。\u003c/p>\u003cp>第四步：简化。前面讲解的过程中，你可能使用了专业术语。现在你要用简单直白的语言，重新组织语言，加上一些比喻再讲一遍。这是加深理理解、强化记忆的过程。\u003c/p>\u003cp>为什么要写在纸上呢？直接讲可以吗？不建议。俗话说好记性不如烂笔头，写在纸上可以帮助我们明确内容、整理思路，加深理解和记忆。让你学完就真理解真记住。\u003c/p>\u003cp>下面给大家分享一个我自己的故事。\u003c/p>\u003cp>[起因]去年11月中旬的时候，和用户沟通了一个软件开发的项目。想把数字孪生技术引入进去，于是开始学习数字孪生的概念和应用。\u003c/p>\u003cp>[经过]还是和以前一样，选书、开读：划重点、做笔记，一样都没有少。还在网上查阅了不少资料。感觉自己已经学懂了。\u003c/p>\u003cp>随后就和研发同事去讨论，结果发现简单的概念可以说说，稍微复杂一些的具体应用，就有点儿说不清了。\u003c/p>\u003cp>[结果]这次沟通交流就很失败，至少有两点：第一，对概念没有深刻理解；第二，不知道自己哪些内容没学懂，学习效果无从检验。\u003c/p>\u003cp>\u003cstrong>【我的反思】\u003c/strong>\u003c/p>\u003cp>事后我也反思了一下，【回顾目标】我的学习目标就是搞清楚数字孪生的概念和应用，去和研发沟通。【评估结果】结果发现对部分内容没有理解透彻，导致沟通失败。【分析原因】如果对标费曼技巧的话，主要原因有3点：\u003c/p>\u003cp>1.讲解环节缺失，没有通过讲解来加深对知识的理解，本来就是要做沟通，练习讲解的同时还能加深自己对概念的理解。最关键的是可以检查自己的学习效果。有助于查漏补缺。\u003c/p>\u003cp>2.返回环节目标不明，虽然有些内容反复阅读过，由于不知道自己哪里不知道，重学的目标和重点也不明确，效果自然不好。\u003c/p>\u003cp>3.简化环节缺失，没有对概念用简单直白的语言来表达，有些生涩的名词还是死记硬背，没有用比喻，对概念理解不够深刻。\u003c/p>\u003cp>【总结经验】如果使用了费曼技巧的话，我认为学习效果会好很多。以后学习的时候，尤其是需要和别人交流的时候，一定要使用费曼技巧，让自己真正成为知识的主人。\u003c/p>\u003cp>【适用场景】\u003c/p>\u003cp>费曼技巧的适用场景主要有两点：\u003c/p>\u003cp>1.适合自学重要概念的场景，当然也可以检查自己对概念理解和掌握的程度。\u003c/p>\u003cp>2.适合与别人交流分享某个概念的场景；比如你学习一个新概念，然后分享给同事。\u003c/p>","interaction":"\u003cp>通过这个拆页，我们学习了费曼技巧，我也分享了自己没使用费曼技巧的尴尬故事。\u003c/p>\u003cp>请大家想一下自己过往有没有这样的经历：把自己读书学到的东西，要讲的时候才发现说不清楚或者说的特别啰嗦。\u003c/p>\u003cp>比如类似这样的失败故事：\u003c/p>\u003cp>1.学习了一个概念，比如拆书片段选择方法，感觉自己明白了，结果说的时候，发现太啰嗦，不太容易说清楚。\u003c/p>\u003cp>2.学习了《高效能人士的七个习惯》中的积极主动，却讲不清楚什么是积极主动。\u003c/p>\u003cp>3.第一次写I便签的时候，看片段的时候自己都明白，写【输出】的时候无从下手。\u003c/p>\u003cp>好的，请你把这样的失败故事，在组内和其他小伙伴分享一下，也可以把你的故事打在公屏上。组内分享结束后，我们请1-2位小伙伴给大家分享一下。时间为\u003cstrong>3分钟\u003c/strong>。\u003c/p>\u003cp> 好的，我们现在请小伙伴先给大家分享一下。\u003c/p>\u003cp> 分享一：以前大学学计算机C语言的时候，但讲给别人里面的概念的时候，讲不清楚，比如说指针*，面向对象 ，函数\u003c/p>\u003cp> 分享二：《思考快与慢》里系统1系统2的理论很有意思，但要跟别人讲，说不清楚\u003c/p>\u003cp> 刚才大家都分享了自己过去的失败经历。如果我们使用费曼技巧再学习一下刚才的主题，给别人分享的时候，还会出现说不清楚的事情吗？我相信不会。\u003c/p>\u003cp>拆为己用是我们拆书帮的价值观，学了就要用起来。下面请大家用4分钟时间，在电脑上写一个便签：为自己使用费曼技巧制定目标和行动方案。\u003c/p>\u003cp>制定目标，大家可以这样写：在什么时候，用什么方法，做什么事，做到何种程度。行动方案就是为了实现这个目标，你要怎么去做。\u003c/p>\u003cp>比如：未来一周之内，我使用费曼技巧学习《如何高效学习》这本书中的1个概念，并分享给一个同事。\u003c/p>\u003cp>具体行动方案如下：\u003c/p>\u003cp>第一，阅读《这样读书就够了》，找到想要学习的一个概念；\u003c/p>\u003cp>第二，使用费曼技巧学习这个概念；\u003c/p>\u003cp> a.选择，找1个自己感兴趣的概念，写在纸上；\u003c/p>\u003cp> b.讲解，把这个概念讲给别人听；\u003c/p>\u003cp> c.返回，如果讲不清，或语言啰嗦的时候返回再学；\u003c/p>\u003cp> d.简化，试着用简单直白的语言以及比喻来讲。\u003c/p>\u003cp>第三，把这个概念分享给一个同事听。\u003c/p>\u003cp>写好之后请大家把自己的目标和行动方案打在公屏上。如果时间允许的话，我们也请1-2位小伙伴给大家分享一下他的目标和行动方案。\u003c/p>\u003cp> 分享一：我刚好下周要做《天赋驱动》的拆书，可以用这个方法。下周二上午9点到11点，我会抽出书中共拆的片段，自己先梳理一般，然后和其他伙伴进行分享。把里面的逻辑和概念做个拆解和分享，如果发现中间有问题的地方，我会再重新把书的内容进行学习深化。\u003c/p>\u003cp> 由于时间原因，先暂停分享。我把今天的片段总结一下，之后您再给小伙伴们分享。\u003c/p>\u003cp>最后我来总结一下，今天我们学习了《如何高效学习》一书中的“费曼技巧”，可以概括为四步：第一，选择；第二，讲解；第三，返回；第四，简化。[行动呼吁]在这里，希望大家按照自己制定的行动计划，把费曼技巧用起来，提升自己的学习能力、强化自己的沟通表达能力。\u003c/p>\u003cp>好的，非常感谢大家参加我的TF1-2晋级活动，今天的拆书活动就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1674036264000,"updated_at":1674090460000,"ria":true},{"id":15029,"topic":"通过积极阅读法+笔记流的学习，使得我们的学习更高效","learn_goal":"","remark":"《如何高效学习》，本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法，流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。跟随作者，你也将成为高效学习的超级学霸。","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"亦新","city":"杭州市"},"club":{"name":"杭州雷峰塔筹备分舵","city":"杭州"},"prologue":"\u003cp>\u003cstrong>Step1：把事先准备好的两个复印原书拆页发给现场学习者\u003c/strong>\u003c/p>\u003cp>我已经把2个拆页的内容发至聊天框内，同时，我在拆页的过程中也会把拆页内容进行屏幕共享。\u003c/p>\u003cp>\u003cstrong>Step2\u003c/strong> \u003cstrong>：站到大家面前，跟大家打个招呼，分好组\u003c/strong>\u003c/p>\u003cp>大家好，我是亦新。我的三个标签是：一位新手拆书家、HR从业者、创业赋能师。欢迎大家来到今天的拆书活动现场，今天是我的2-4晋级，我的分享主题是如何运用笔记让学习更高效。今天的课程将分成2个部分。第一个部分是《积极阅读法》拆页的学习，第二个部分是《笔记流》拆页的学习。这两个拆页内容是递进关系。为了接下来方便讨论，首先我们先来分一下组，因为今天是一场线上活动，人员不是很多，我们就分为一组。\u003c/p>\u003cp>\u003cstrong>学习目标：包含学习者可被观察到/ 被测量到的行为或动作，现场学习者设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>大家是否还对学生时代自己的笔记记忆犹新，在学生时代，老师在讲授的过程当中，经常叫我们把某一些要点记录下来，告诉我们这个是重点，要考的哦；在教学过程中要求我们做好学习笔记。同时你也会发现一些优秀的学生，他在复习的时候翻看的不是书籍，而是他平时记录的学习笔记；其实我们也会羡慕那些把学习笔记做得特别优秀的学生，哇你的笔记为什么做的这么漂亮，这么的清晰，这么的有创意，而且会把学习的这个知识完全转化成自己的要点。你的这个笔记让我一看就能明白，对我太有帮助了。自己怎么就没有办法去完成这么漂亮又简洁、逻辑性强的笔记呢？笔记对我的学习帮助太关键了。\u003c/p>\u003cp>我记得去年全国联合RIA集训营，有一位学习者的学习笔记就把我们惊艳到了，清晰、美观、实用，同时也能看到她对知识的领悟能力超强。\u003c/p>\u003cp>今天我们学习的目标有两个：\u003c/p>\u003cp>1. 通过第一个拆页《积极阅读法》的学习，运用RIA便签法，能够掌握高效阅读的方法，便于我们更好的掌握书中的知识。在你下一次阅读学习中，就可以运用积极阅读三步法，理解知识、掌握知识、运用知识，让书中的知识为己所用。\u003c/p>\u003cp>2. 在第二个拆页《笔记流》的学习，运用RIA便签法，能够掌握笔记记录的要点和绘制方法，让自己的笔记更简洁。更明了，提升笔记的作用。不妨我们用笔记流的方法绘制我们下一次的读书笔记，你会发现，原先没有理解的知识点，现在有了新的突破与诠释。\u003c/p>\u003cp>\u003cstrong>Step3 （用FAB法介绍图书，1-2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F特征，核心是&quot;书“，用于满足好奇心\u003c/strong>\u003c/p>\u003cp>《如何高效学习  Learn More Study Less》本书的作者斯科特·扬是一位因为快速学习而成名的神奇小子，他应用自己发明的学习方法，完成了10天搞定线性代数，一年学习4年MIT课程的“不可能任务”。本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法，流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。跟随作者，你也将成为高效学习的超级学霸。\u003c/p>\u003cp>\u003cstrong>A优势，重点是”比较“，用于建立安全感\u003c/strong>\u003c/p>\u003cp>《如何高效学习》一书和其他同类书籍相比，介绍的整体性学习策略很具有操作性，可以避免学生在学习中陷入只见树木，不见森林的误区。本书从一位“学习大师”的亲身体验出发，总结出“整体性学习”的策略及方法，同时，配合作者实际运用的各类学习工具，切实帮助读者逐步练就高效的“学习方法与学习习惯”。\u003c/p>\u003cp>\u003cstrong>B利益，强调的是”你“，用于引发兴趣\u003c/strong>\u003c/p>\u003cp>大部分人的学习习惯是：阅读无数，但无法掌握书中要点，更别说学以致用了，这其实是一种碎片化知识点学习，如何摆脱学习困境，让有限的时间学习到更多知识。特别是在当今信息爆炸的时代，如何高效的处理信息，有机的整合知识，充分的运用所学，成为学习的关键。那我们就来读读这本书吧，本书整体性学习方法，掌握系统思考的模式，神奇的笔记法，让你可以花费更少时间学到更多。\u003c/p>","ratings_count":1,"texts":[{"id":19036,"quote":"\u003cp>\u003cstrong>第一个拆页：RIA【10-15分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Step4 【R】（环节，让大家阅读你复印好的原书拆页）\u003c/strong>\u003c/p>\u003cp>学习目标1：通过第一个拆页的学习，运用RIA便签法，能够掌握高效阅读的方法，便于我们更好的掌握书中的知识。在你下一次阅读学习中，就可以运用积极阅读三步法，理解知识、掌握知识、运用知识，让书中的知识为己所用。\u003c/p>\u003cp>今天我选取了书中积极阅读法主题片段。我已经把原文片段进行屏幕共享，下面请大家花1分钟时间阅读原文片段。阅读完的小伙伴请扣“1”。\u003c/p>\u003cp>R原文 图书：《如何高效学习》 \u003c/p>\u003cp>拆页1：积极阅读法\u003c/p>\u003cp>尽管我将积极阅读放在了快速阅读之中，实际上积极阅读与快速阅读是对立的。积极阅读强调深入的理解材料，所以自然降低了阅读速度。积极阅读不仅仅是简单的在书上画各种颜色的记号和在空白处写心得体会，还是将知识点真正的整合在一起。\u003c/p>\u003cp>开始积极阅读时，准备好要读的书和笔记本，在笔记本上写下每章的标题和标题，每读完一小部分时（指读法），在笔记本上记一些笔记。\u003c/p>\u003cp>进行积极阅读时你需要记下：\u003c/p>\u003cp>(1)节中主要观点是什么？\u003c/p>\u003cp>(2)你怎样才能记住主要观点?\u003c/p>\u003cp>(3)我要怎样将主要观点拓展开以及应用它?\u003c/p>\u003cp>第一个问题仅仅促使你完整的获取信息；第二个问题迫使你对信息进行联系、视觉化和比喻法，第三个问题要求你将信息应用在不同的环境中，这三个问题迫使你将每个知识点都要经过整体性学习的理解、拓展和应用三个阶段。\u003c/p>\u003cp>比如我刚刚读完心理学中的经典条件反射，其主要的知识点是。\u003c/p>\u003cp>· 经典条件反射的发现者是巴普洛夫\u003c/p>\u003cp>· 经典条件反射是刺激引起反应\u003c/p>\u003cp>我会这样记忆：\u003c/p>\u003cp>· 想象一幅图画，画中巴普洛夫的狗听到铃声流出了唾液。\u003c/p>\u003cp>我会这样拓展：\u003c/p>\u003cp>进行积极阅读时你需要记下\u003c/p>\u003cp>· 我听到电视里类似的手机铃声，会不由自主的掏出自己的手机。\u003c/p>\u003cp>如果你能对教科书里的每一个知识点都进行这样完整的积极阅读，你一定会天下无敌。一旦你熟悉了这种方式，就不必对每个知识点进行完整的阅读，而只针对自己需要理解和记忆困难的那些内容。\u003c/p>","explains":"\u003cp>\u003cstrong>拆书家讲解引导：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Step5 【拆书技能】：【I】环节，涵盖了二级的 4 种讲解引导技巧：1）强调不那么做的坏处，2）给出了学习者可能异议的预防性讲解，3）细化了原文行动建议的步骤，4）根据原书中案例脉络，给出了更贴近实际的例子。\u003c/strong>\u003c/p>\u003cp>我看大家都已经阅读完毕，那接下来，我们来看一下，这段文字主要讲述了什么？\u003c/p>\u003cp>【what】\u003c/p>\u003cp>积极阅读法就是在读完每一个章节都能够记录下这一章节中最重要的观点，并能够记忆，同时能够想象出运用此观点场景及能够解决的问题。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>一般做法：大家在阅读一本书的时候，可能只是会在书本上做一点的记录或者是画一些重要的词句，或者在内容的边上批注一下，这是大部分阅读者和学习者的习惯。很少会把阅读和笔记配合起来，成为真正的学习。\u003c/p>\u003cp>运用积极阅读法，我们不仅能够理解书中的观点、要点，还能够形成我们脑海中的记忆。同时能够描绘出它的应用场景，这其实就是一个学以致用的过程。它不仅大大的加快了我们的学习效率，还可以帮助我们在未来要去查找相关资料的时候，在复习的时候也加快了我们的速度。\u003c/p>\u003cp>不那么做的坏处：如果我们不使用积极阅读法，我们可能就看过就忘了，学习完了以后我们就不会再去运用它。无法成为我们自己的知识。\u003c/p>\u003cp>举例说明：\u003c/p>\u003cp>11月底公司计划组织员工阅读《营销管理》这本书，并进行读书分享。为了防止员工敷衍了事，对读书分享做了较细致的安排：\u003c/p>\u003cp>1. 制定读书分享计划表，明确每位员工的分享时间及时长\u003c/p>\u003cp>2. 同步清晰罗列的分享的要求，即完成读书笔记，格式不限。只有完成读书笔记的才能够和大家分享阅读心得，计划如下图\u003c/p>\u003cp>但是12月5日的分享不是太理想，有的同事就在书本上做了标记与内容，写一些自己的理解与心得，显得杂乱无章，分享者自己都没有理解书中的知识要点，无法形成连贯的知识内容进行分享，而学习者更是听得一头雾水，不明所以。分享的效果极差，没有实现分享的目标，通过阅读、分享让大家进行二次知识的学习，提升大家的营销能力。\u003c/p>\u003cp>通过积极阅读法的学习，我们应该提前让读书分享者学习积极阅读法，通过三步法即，提炼章节中的精华、要点、重点，体会作者所要表达的意图，并记录，然后将这些观点转化成自己的语言，就如我们R便签中的what，这是一个真正理解的、转化成自己知识的过程，并记录在笔记本上，最后我们试想一下这个知识的应用场景以及能够帮助我们解决工作中及生活中的哪些问题，这才是有效阅读。\u003c/p>\u003cp>接下来我会在12月12日先对分享员工进行积极阅读法的培训与学习，让员工运用积极阅读三步法，即提炼-他人知识、转化-自我知识、致用-应用知识，完成他们的阅读，形成自己的分享笔记，让他们学习领悟到积极阅读法的功效，让他们运用积极阅读法完成读书笔记，这才是真正的阅读，才能实现读书分享的初衷，分享也变得更有意义。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>积极阅读三步法：\u003c/p>\u003cp>1. 提炼-他人知识：你在阅读学习的这个过程当中，能够找到阅读章节内容当中最关键的部分，最重要的部分，也是作者重点想要表达给读者的，并且能够把它识别出来，记录下来。\u003c/p>\u003cp>2. 转化-自我知识：我们会发现，其实在很多书籍当中的观点会用到很多专业术语，这些专业术语其实是不利于我们的理解的，我们需要把它转化成自己能够通俗易懂好记的词汇，同时把它做语言的转换记录下来。\u003c/p>\u003cp>3. 致用-应用知识：学习了这么多的知识和内容，我们如何让它在我们的生活和学习中帮助我们呢？我们可以写下我们的使用场景，我该如何运用所需知识，帮助我解决实际问题。这才是真正的学习，即学+习=学习。\u003c/p>\u003cp>预防可能的异议：\u003c/p>\u003cp>我之前经常听到这样的声音，老师我也读了很多书，但感觉都用不上呀，这是为什么？也有学习者说，老师，我能看懂书中的内容，但是到要用它的时候就不知道怎么用了？\u003c/p>\u003cp>老师，我读书也做笔记，但是做完笔记我发现对我的学习帮助不大，这是为什么呢？笔记到底长什么样呢？我该如何做读书笔记？\u003c/p>\u003cp>今天我们分享的积极阅读法中，最为关键的是第二条，也是最难的，转化成自己的知识，这是承上启下的作用，只有把作者的知识真正转化成自己的知识，我们才有可能把他运用到生活和工作当中。如果没有第2个步骤，其实就是还没有真正去理解这个知识点的内容。仅仅还是在于已阅的浅层面。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>适应边界：积极阅读法适用于阅读书籍、查找资料，公文学习、工作交接、文件学习、公司规则制度学习，功课学习，还适用于下属聆听上司工作指导，适用于开会的总结发言。\u003c/p>\u003cp>不适应边界：快速阅读时就不适用此方法，还有在短时间完成一个系列书籍的框架浏览，此方法也不适应。\u003c/p>","interaction":"\u003cp>\u003cstrong>Step6 【A1】环节\u003c/strong> \u003cstrong>（提出一个显像问题，让学习者更容易联想到特定情境，从而激活经验，10分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1】技能点的环节提问和指令清晰，学习者能根据提问中的场景联系自己过往的具体经验，且加工出如果以后遇到同等情况，可以如何做。\u003c/strong>\u003c/p>\u003cp>学习永无止境，我们在不断找寻适用于自己的学习方法。刚刚我们学习了积极阅读法3步法，接下来请大家回想一下，在最近的一个月内，大家是否有过比较失败的学习案例？比如：一本书看了一年还没看完；比如书已经看完了，但已经不记得他的主要内容了；比如每一本书都只看了第一章。。。。等等。请大家花3分钟时间写下你的故事，因为我们今天进行的是线上学习，大家把自己写好的案例发到对话框里，我们选一位伙伴进行分享，分享时间为2分钟。\u003c/p>\u003cp>接下来我们请峰哥用2分钟时间给我们分享一下他经历的故事：\u003c/p>\u003cp>峰哥的分享：我喜欢中医养生，皇帝内径在中医里面是比较基础的一本书，很多理论都是这边书做指引的，这边书非常棒。我很多时候都想看，但是看了看了，看到后面就忘记前面所讲的内容，特别是定义，造成后面就看不懂，看不下去了，所以到现在为止都没有完完整整的看完，大概只看了1/5，主要还是因为没有方法。\u003c/p>\u003cp>韩大哥分享：我自己有一段时间比较负向，就找了一本书，这本书叫《正向力》，这个书的方向是对的，但是内容还是相当复杂的，我只看了开头部分，里面的观点知道，但是不会应用，也记不住，最终造成自己也不愿意去看了，所以只看了一个开头，就结束了。\u003c/p>\u003cp>□【技能点】：拆书家至少有一次给出了关联到原文知识点的回应或反馈。\u003c/p>\u003cp>非常感觉小伙伴的分享，如果我们重新回到过去的场景，尝试用我们今天学习到的积极阅读3步法；即提炼--他人知识、转化--自我知识；致用-应用知识，你会怎么做，来提升自己的学习效率？请大家花2分钟时间写下行动步骤，然后我们请一位小伙伴分享一下他的行动，分享时间为3分钟。\u003c/p>\u003cp>我看已经有学员已经完成了他的改善行动步骤，接下来我们用3分钟时间请1位小伙伴给我们做一个分享交流；\u003c/p>\u003cp>韩大哥：峰哥，你写的这个案例还是很符合今天学习的三个步骤，提炼、转换、致用。我觉得峰哥写的不错，让峰哥分享一下。\u003c/p>\u003cp>峰哥：\u003c/p>\u003cp>第一步：把一些概念性的话圈出来，简单进行内容的记忆，提炼内容概要、重要思想，形成自己的记忆。\u003c/p>\u003cp>第二步：把相关的知识对应到自己的生活当中，看看哪些是有问题的，转化成自己的知识。\u003c/p>\u003cp>第三步：把这些问题进行改善和提升，最终解决问题，学以致用，实现学习成效。\u003c/p>\u003cp>阶段性总结：刚刚和大家一起学习了积极阅读法三步法：即提炼--他人知识、转化--自我知识；致用-应用知识，形成自己有效的读书笔记，让阅读更高效，让学习更致用。那大家是否会很好奇，老师，我们该如何把笔记做的更美观，更简洁呢，不要着急，接下来我们学习的拆页就是《笔记流》，带领大家走进美妙的笔记世界。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":19037,"quote":"\u003cp>\u003cstrong>第二个拆页：RIA【30-45分钟】\u003c/strong>\u003c/p>\u003cp>学习目标：笔记是一个可以联系到学习的平台，用简单的文字和箭头呈现出最浓缩的信息\u003c/p>\u003cp>今天第二个拆页，我选取了书中笔记流主题片段。我已经把原文片段进行屏幕共享，下面请大家花1分钟时间阅读原文片段。阅读完的小伙伴请扣“1”。\u003c/p>\u003cp>R原文 图书：《如何高效学习》 \u003c/p>\u003cp>拆页2：笔记流\u003c/p>\u003cp>我在课堂上曾经使用一种记笔记的方法，对信息量较大的课程效果不错，我把这种记笔记的方法称为笔记流技术。笔记流技术的目标是提供一个平台以联系学到的东西。大多数人采用的画线、画圈等传统记笔记的方式被很多“流”（虽然有些杂乱）替代。\u003c/p>\u003cp>使用笔记流时，首先写下最主要的观点，尽量用很短的单词来替换完整的句子，这可能会降低可读性，但是提高了上课时的学习效率。事实、日期、细节和描写要尽量减少单词量，不要写冗长的段落。\u003c/p>\u003cp>一旦你写下了一个观点，下一步就是在这个观点和其他观点之间画上一些箭头，观点不是建立成金字塔式的结构，而是呈现出相互关联的关系，这个过程与实际的整体性学习策略类似，观点连在一张网中。\u003c/p>","explains":"\u003cp>\u003cstrong>拆书家讲解引导：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书技能】：【I】环节，涵盖了二级的 4 种讲解引导技巧：1）强调不那么做的坏处，2）给出了学习者可能异议的预防性讲解，3）细化了原文行动建议的步骤，4）根据原书中案例脉络，给出了更贴近实际的例子。\u003c/strong>\u003c/p>\u003cp>我看大家都已经阅读完毕，那接下来，我们来看一下，这段文字主要讲述了什么？\u003c/p>\u003cp>【what】\u003c/p>\u003cp>笔记流技术：就是用关键词提炼出主要观点，并用箭头画出关联关系，帮助我们压缩信息，呈现知识图谱。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>一般情况下下：大多数人采用划线、画圈等传统记笔记的方式，只记录了内容，没有呈现出相关关系，即缺了“流”，笔记没有帮助我们更好的提炼知识。或者笔记记录的非常详细且复杂，笔记会分为多次去完成。\u003c/p>\u003cp>这么做的好处：“一次学会”。在学习过程中帮助我们提炼关键知识，并画出相关关系，浓缩所学知识，建立有序知识信息。一看就明白，一看即能联系到所学知识，一看就能帮助我们回忆知识点。\u003c/p>\u003cp>不这么做的坏处：我们无法通过笔记联想到过往学习的知识。笔迹呈现出来的也是杂乱无章，没有办法体现出知识点的要素、逻辑，以及内在关系。事后我们再去看自己的笔记是一头雾水。无法跟知识点相关联，无法帮助我们去更好的理解、恢复所学内容。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>1．筛信息：在学习过程中，我们需要筛选出关键知识和信息。\u003c/p>\u003cp>2．精简词：在记录关键信息时找到最简单的词，替代最主要的观点\u003c/p>\u003cp>3．画关系：用简洁明了的箭头画出各知识点、观点之间的联系\u003c/p>\u003cp>4．呈现网：一张知识族谱网呈现了知识的浓缩信息。帮助我们“一次学会”。\u003c/p>\u003cp>举例说明：\u003c/p>\u003cp>反面案例：\u003c/p>\u003cp>这是我之前的阅读笔记，那时在看《薪酬管理》这一本书，笔记记录的非常详细和复杂，我之前的笔记习惯是一边在阅读，一边详细记录，这个过程更像是在复杂黏贴，摘抄书本上的内容。更不要说有自己的思考和理解，这样的阅读习惯效率太慢，距离“一次学会”差距巨大。阅读完就忘记了书中所讲的知识，应用从何而来。\u003c/p>\u003cp>反面案例——正面案例\u003c/p>\u003cp>这份阅读笔记虽然已经筛选了信息，但是从密密麻麻的内容、信息看出她没有对关键信息进行精简提炼出关键词，同时虽然有些结构层次在，但是不明显，也没有看到明确的关联关系，更不要说形成一个知识网。所记录的信息显得无序不够清晰和简洁。\u003c/p>\u003cp>如何让我重新来一次，我会按照拆页中所讲的步骤进行记录：\u003c/p>\u003cp>1．筛信息：筛选出书中的关键信息\u003c/p>\u003cp>2．精简词：把关键信息，用最简洁的词进行记录\u003c/p>\u003cp>3．画关系：用线或者箭头画出各信息直接的关系\u003c/p>\u003cp>4．呈现网：用一张图完整的呈现这个章节的知识。\u003c/p>\u003cp>预防可能的异议：\u003c/p>\u003cp>大家会觉得这个步骤是蛮简单的，一共就只有4步，也很简洁。但是到了自己操作的时候，就会发现，没有想象当中的这么容易。特别是第一步和第二步，也就是你在阅读学习时，如何筛选出有效信息并把它提炼出来，这两部分是会比较难的。\u003c/p>\u003cp>其实每个人对于所学的信息筛选都会所不同，我们只要抓取到对自己有用的那些信息就可以了，然后把它转换成自己当时能够想到的最简洁的词语就可以了，这么一说是不是也没有这么难了。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>适应边界：\u003c/p>\u003cp>我们平时在阅读书籍、参加课程学习、列席会议等场景都适用。\u003c/p>\u003cp>不适应边界：\u003c/p>\u003cp>采访、访谈、一对一沟通时、会议记录等需要详尽记录时，则不适应。\u003c/p>","interaction":"\u003cp>【A3】学习者拆为己用：学习者拆为己用：\u003c/p>\u003cp>□【技能点】：使用【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。\u003c/p>\u003cp>&lt;设定案例场景，应用知识点进行组内角色扮演&gt;\u003c/p>\u003cp>刚刚我们学习了笔记流技术，大家是不是很想去练习一下呀？然后看看它的实际操作到底是什么样的，那接下来我们就一起进入到模拟演练的过程。\u003c/p>\u003cp>场景设计：\u003c/p>\u003cp>沟通的勇气\u003c/p>\u003cp>“勇气不仅仅是一种美德，而且是每一种美德在接受考验时的表现形式。”C.S.刘易斯写道，内心的力量是我们在生活和艰难的谈话中都需要的一种品质.\u003c/p>\u003cp>我们很多人都觉得鼓起勇气交谈很难.国际绩效教练组织2008年的研究证实了这个问题的普遍程度.在一项对750名公共、私人和志愿部门经理的调查中，70%的人表示他们无法或不愿就员工表现不佳的问题进行“勇敢的对话”。\u003c/p>\u003cp>经理们给出了两个主要原因。首先，潜在的恐惧使他们害怕进行这样的对话。其次，他们不知道应该如何去做。\u003c/p>\u003cp>掌握一些技巧会带来很大的变化。当我们能够鼓起勇气进行对话时，我们就能解决问题、创造改变、继续前行。它也让我们感觉良好。“快乐是勇敢者的情感表达”。神学家和哲学家保罗·蒂利希在他1952年出版的经典著作《活出勇气》中写道。\u003c/p>\u003cp>指令：请大家结合今天所学的笔记流技术四步法，即筛信息、精简词、画关系、呈现网，把沟通的勇气内容在白纸上画出来，请大家花6分钟时间完成，完成的小伙伴请扣“1”。\u003c/p>\u003cp>小组演练完后，我们请一组小伙伴给我们分享，分享时间为4分钟，看看他们的场景模拟。\u003c/p>\u003cp>韩大哥的练习成果：\u003c/p>\u003cp>第一步：筛信息：片段主题是沟通的勇气，\u003c/p>\u003cp>第二步：精简词：作用、现象、原因、技巧\u003c/p>\u003cp>第三步：画关系：个主题为准，现象、原因和技巧是一个基准函，然后形成了一个效果和作用，就是解决问题，创造改变和继续前行。\u003c/p>\u003cp>第四步：呈现网：他是个网状，像是一柄剑，沟通勇气是作为他的剑柄，那么下面三个穗子，很形象。\u003c/p>\u003cp>峰哥的练习成果：\u003c/p>\u003cp>沟通的勇气分三个层面来说：\u003c/p>\u003cp>第一步：含义：沟通勇气是什么？它是美德的表现。内心力量的品质。\u003c/p>\u003cp>第二步：现象：70%的人无法勇敢对话；原因：不知道怎么去做，很慌乱\u003c/p>\u003cp>第三步：改变：鼓足勇气对话\u003c/p>\u003cp>大家分享的都分成棒，思维导图不等同笔记流的技法，思维导图是层层关系，而笔记流是形成的知识网状，峰哥讲的非常棒，把文中的信息提炼出来了，如果这张图中能有一些箭头，看到关键词直接的关联关系，那就更完美了。\u003c/p>\u003cp>下面进入到模拟演练的环节\u003c/p>\u003cp>人力资源领导：小张，这次绩效面谈做的不是太理想，怎么回事呢？\u003c/p>\u003cp>事业部主管：领导，绩效面谈我感觉好难呢，特别是那些绩效不理想的，我都不知道和他们谈什么，没谈的底气呢？\u003c/p>\u003cp>人力资源领导：这咋还没底气呢？绩效分都是事实就是的，哪里做的不好，需要提升的和员工沟通一下，这也是帮助他们成长呀。\u003c/p>\u003cp>事业部主管：问题是，他们都觉得做的很好呀，我是真没在这勇气和他们沟通。\u003c/p>\u003cp>人力资源领导：小张，你这是怕得罪人呢，还是没底气和他们做绩效面谈？\u003c/p>\u003cp>事业部主管：领导，都有吧，主要还是底气不足，如果我有沟通的勇气和技巧，我也会主动找员工沟通绩效事宜\u003c/p>\u003cp>人力资源领导：这样吧，我这刚好有一篇文章讲《沟通的勇气》，你去看一下，并做个读书笔记给我。\u003c/p>\u003cp>事业部主管：好的，我学习学习。\u003c/p>\u003cp>第二天：\u003c/p>\u003cp>人力资源领导：小张，昨天我发你的文章看完了吗？\u003c/p>\u003cp>事业部主管：领导，我看完了，还按照你的要求做了读书笔记，你看\u003c/p>\u003cp>人力资源领导：天那，小张，这是你做的读书笔记，秘密麻麻的写了啥呀？\u003c/p>\u003cp>事业部主管：读书笔记呀\u003c/p>\u003cp>人力资源领导：不行不行，这是读书笔记一点都比清晰。我给你培训一下笔记流技术法，帮助你提升一下读书笔记的技巧\u003c/p>\u003cp>人力资源领导：接下来，对小张进行笔记流技术法的培训，小张，你按照刚刚的方法，重新整理这段文字的笔记\u003c/p>\u003cp>事业部主管：好的，5分钟后小张重新提交了笔记\u003c/p>\u003cp>人力资源领导：这次的笔记像样多了，你自己的感受呢？\u003c/p>\u003cp>事业部主管：经过培训我自己也觉得，这次的笔记对文章的理解更深了，笔记简单明了，我绩效面谈的时候，就把这笔记放边上，我相信对我的绩效面谈帮助会很大，谢谢领导的关心和支持\u003c/p>\u003cp>人力资源领导：期待你下次出彩的绩效面谈。\u003c/p>\u003cp>\u003cstrong>\u003cu>请大家对案例进行角色扮演，一个扮演人力资源领导，一个扮演事业部主管，大家讨论一下，2分钟后，我们邀请一对伙伴进行现场角色扮演分享\u003c/u>\u003c/strong>\u003c/p>\u003cp>人力资源领导扮演者：韩大哥\u003c/p>\u003cp>事业部主管扮演者：峰哥\u003c/p>\u003cp>人力资源领导：小张，这次绩效面谈做的不是很理想，怎么回事呢？\u003c/p>\u003cp>事业部主管：领导，绩效面谈我感觉好难呢，特别是那些绩效不理想的，我都不知道和他们谈什么，没谈的底气呢？\u003c/p>\u003cp>人力资源领导：这咋还没底气呢？绩效分都是事实，哪里做的不好，需要提升的和员工沟通一下，这也是帮助他们成长呀。\u003c/p>\u003cp>事业部主管：问题是，他们都觉得做的很好呀，我是真没在这勇气和他们沟通。\u003c/p>\u003cp>人力资源领导：小张，你这是怕得罪人呢，还是没底气和他们做绩效面谈呢？\u003c/p>\u003cp>事业部主管：领导，都有吧，主要还是底气不足，如果我有沟通的勇气和技巧，我也会主动找员工沟通绩效事宜\u003c/p>\u003cp>人力资源领导：这样吧，小张啊，我这刚好有一篇文章讲《沟通的勇气》，你去看一下，然后呢做个读书笔记给我，好吧？\u003c/p>\u003cp>事业部主管：好的，我学习学习。\u003c/p>\u003cp>第二天：\u003c/p>\u003cp>人力资源领导：小张，昨天我发你的文章看完了吗？\u003c/p>\u003cp>事业部主管：领导，我看完了，还按照你的要求做了读书笔记，你看\u003c/p>\u003cp>人力资源领导：天那，小张，这是你做的读书笔记，秘密麻麻的写了啥呀？\u003c/p>\u003cp>事业部主管：读书笔记呀\u003c/p>\u003cp>人力资源领导：不行不行，这是读书笔记一点都比清晰。我给你培训一下笔记流技术法，帮助你提升一下读书笔记的技巧\u003c/p>\u003cp>人力资源领导：接下来，对小张进行笔记流技术法的培训，小张这个笔记流它其实分为四个步骤：筛信息（把最主要的信息筛选出来，把主要问题罗列出来）、精简词（就是把文字中的关键信息用最简单的词语把它选出来，标记清晰）、画关系（递进还是并列，把内容直接的关系画出来）、形成网（最终形成知识网），通过这四个步骤，你会发现，沟通的勇气告诉我们怎么达到沟通的勇气，这是今天我们培训的内容。小张，你按照刚刚的方法，重新整理这个文字的笔记\u003c/p>\u003cp>事业部主管：好的，5分钟后小张重新提交了笔记。领导，我把关键词摘出来，并对他们之间的关系进行呈现。\u003c/p>\u003cp>人力资源领导：这次的笔记像样多了，你自己的感受呢？\u003c/p>\u003cp>事业部主管：经过培训我自己也觉得，这次的笔记对文章的理解更深了，笔记简单明了，我绩效面谈的时候，就把这笔记放边上，我相信对我的绩效面谈帮助会很大，谢谢领导的关心和支持\u003c/p>\u003cp>人力资源领导：好，期待你下次出彩的绩效面谈。\u003c/p>\u003cp>韩大哥感受：对下属的引导，当引导正确的时候很有成就感。同事对笔记流的影响更深了。\u003c/p>\u003cp>峰哥感受：新的任务拿到会很慌张，经过领导的指导就可以落地，做的很好。感受都了笔记流方法的优势。\u003c/p>\u003cp>□拆书家至少有一次给出了关联到原文知识点的回应或反馈。\u003c/p>\u003cp>&lt;对学习者案例给出和知识点相关的反馈&gt;\u003c/p>\u003cp>欢迎分享者：韩大哥和峰哥的分享，感受到了他们对笔记流的方法掌握的更流畅了。\u003c/p>\u003cp>技能点：回应与反馈\u003c/p>\u003cp>\u003cstrong>【A2】环节\u003c/strong> \u003cstrong>（使用分步催化的方法，让学习者更容易联想到特定情境，从而加工和规划出自己的具体运用，并请大家在小组内分享\u003c/strong> \u003cstrong>7-9分钟）\u003c/strong>\u003c/p>\u003cp>刚刚我们学习并演练的笔记流技术法，我们可以在更多的学习、工作、生活场景中运用此技法，现在大家可以想一下，未来的一周，你会在哪个场景运用笔记流技术四步法，比如：\u003c/p>\u003cp>你刚好需要阅读一本书籍，同时完成读书笔记；\u003c/p>\u003cp>你正在去往某场培训学习的路上，在课上需要记录知识点；\u003c/p>\u003cp>你正好需要学习某个文件，并完成笔记；\u003c/p>\u003cp>你刚好在下周有会议参加，需要做一些记录；\u003c/p>\u003cp>你即将和客户进行沟通，需要记录客户反馈的事项；\u003c/p>\u003cp>你恰好参加孩子的家长会，需要记录孩子在校情况；\u003c/p>\u003cp>请大家花2分钟时间思考一下，我们请一位小伙伴花2分钟时间给我们分享一下，她即将遇到的类似场景：\u003c/p>\u003cp>有请峰哥给我们分享：最近我在学习中医，从中医的角度讲内脏关系和定义，我会用这次学习的笔记流方法，提炼关键词，画出他们之间的关系，形成没有的中医知识网，这样对我的学习有很大的帮助\u003c/p>\u003cp>感谢峰哥的分享，中医学中内脏之间的关系，它有非常多的专业术语，这些专业术语对我们来说是比较难以理解的，我们通过笔记流的方法，包括第一个片段积极阅读法，把书本知识转换成自己的知识，两者结合，我相信，你在阅读后会有非常大的收获。期待你下次和我们分享中医和内脏的关系。\u003c/p>\u003cp>\u003cstrong>【拆书技能】：结尾时给出了强有力的结语。\u003c/strong>\u003c/p>\u003cp>结束语：今天和大家一起学习了积极阅读法（三步）：即提炼--他人知识、转化--自我知识；致用-应用知识和笔记流技法（四步）：筛信息、精简词、画关系、呈现网，2个板块知识，两者循序渐进，精即简、学致用，学习（积极阅读）+笔记（笔记流）=高效学习，让我们“学得少”，这个少是时间花得跟少，最终实现“一次学会”让我们自己成为一个高效的学习者。今天我的分享就到这里，感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1673352044000,"updated_at":1675153178000,"ria":true},{"id":14980,"topic":"如何高效学习","learn_goal":"","remark":"通过比喻学习法来高效学习！","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"[email]","city":"银川"},"club":{"name":"银川拉拉缨分舵","city":"银川"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp> 各位小伙伴们大家好，欢迎参加我的TF1-1晋级拆书，今天的拆书主题是“怎样用比喻学习”\u003c/p>\u003cp>首先做一下自我介绍，我叫——李永忠，永远忠于内心，就是我。我用三个标签介绍一下我自己：\u003c/p>\u003cp>第一个标签是[网络安全]，这是我的主业。网络安全事关国家安全、社会稳定和每个人的切身利益，我很高兴能在这个行业服务社会。\u003c/p>\u003cp>第二个标签是[职业生涯规划咨询]，这是我的副业。工作生活一脸懵，微信电话找永忠，所有问题全扫空！\u003c/p>\u003cp>第三个标签是[赋能拆书家]，这是未来想做的，不仅自己要成为拆书家，不断精进，还要赋能更多人拆书，让他们也持续精进。\u003c/p>\u003cp>\u003cstrong>【对拆书法的理解】\u003c/strong>\u003c/p>\u003cp>你读书的时候有没有觉得很多书基本上“白读”了？一年前、半年前、一月前甚至一周前读过的书，你还记得多少呢？你想不想读完一本书之后就像参加一场培训一样，印象深刻，而且还能用在工作和生活当中？如果想的话就来拆书吧，你想要的都有！\u003cbr>【去哪里呢？怎么拆呢？当然是来拆书帮，学习拆书法了。】拆书帮是基于拆书家的学习者社群，是一个非营利性组织，表现为各地的拆书帮分舵，其使命是帮助更多学习爱好者成长为拆书家。拆书帮的创始人是赵周老师。\u003cbr>拆书法是让你读完书后能够学得会、带得走、用得上的好方法。\u003cbr>拆书法是以学习者为中心，特别适合成年人的学习方法论。\u003cbr>拆书的“拆”不是拆散的拆，是拆为己用，是内化和应用知识的过程。\u003cbr>拆书法是由个人学习的拆书法和组织学习的拆书法两种，个人学习使用便签法，以阅读书中片段，书写便签，结合自身经验，内化和应用知识的方法。让人读一本书就能达到参加同主题培训的效果；组织学习的应用是拆书家用一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从效果上来说，拆书家创造的价值不亚于一位培训师。\u003c/p>","ratings_count":1,"texts":[{"id":18982,"quote":"\u003cp> 今天就由我来和大家一起拆解一下《如何高效学习》中的一个片段， “怎样用比喻学习”。这本书的作者斯科特·扬，用一年学完了MIT 4年的课程，而且GPA在A和A+之间。作者的方法到底怎么样，就让我们今天一起来验证一下。片段已经放到了屏幕上，给大家2分钟时间，请大家阅读一下原文片段，看完后请大家在聊天区敲1。\u003c/p>\u003cp>\u003cbr>片段来源：《如何高效学习》（电子书）\u003c/p>\u003cp>\u003cbr> 怎样用比喻学习？（第二部分 整体性学习技术 比喻）\u003cbr> 怎样应用比喻法学习条件反射？比喻法的第一步是在你的个人经验中寻找能够模拟条件反射的东西，我个人生长在加拿大的冰天雪地里，所以想到的第一个比喻就是在雪地里行走。你第一次在雪地里行走时，因为雪地茫茫一片，走哪条路都有可能。但是几次行走以后，你会选择一开始走的路，因为开始的行走在雪地上形成了一条隐约可见的小路，走这条路显然比随便走更容易。\u003cbr>我将雪中走路与条件反射联系在一起，一开始，铃声可能或不引起狗分泌唾液（这代表一开始雪地茫茫一片，无路可寻）。但是在将铃声和食物关联在一起后，从铃声到食物的路就在雪地上（狗的大脑里）形成了，最终狗一听见铃声就分泌唾液，因为这条路已经很明显了。像许多比喻一样，这个比喻也不完美，但是它很有用。\u003cbr>可以按照下面三个简单步骤找出一个比喻。\u003cbr> （1）确定你要深入理解和记忆的信息，在上面例子中就是经典条件反射。\u003cbr> （2）在你的个人经验中寻找与信息部分相似的东西，要达到完全符合不太可能，所以与其寻找一个完全符合的东西，不如稍作让步，找到十几个部分符合的“不完美比喻”，在上面的例子里我想到的是雪中行走。\u003cbr> （3）重复上述过程，检查比喻不恰当的地方。例如，雪中行走是线性的痕迹，而脑神经却是错综复杂的网络。\u003c/p>","explains":"\u003cp> 好的，我看到大家在聊天区都打出了1。下面我来分享一下我是如何学习这个片段的。\u003c/p>\u003cp>\u003cbr>[What]\u003c/p>\u003cp> 首先呢， 我们得知道比喻是什么。这个片段给我们提供了一种理解和记忆信息的方法，就是比喻，就是把两个事物联系到一起，找到它们的共同之处，促进理解和记忆。在使用比喻的时候，要联系自己过去的经验来比喻，比喻有多么完美不重要，通过比喻做到对知识的理解和记忆才是最重要的。\u003c/p>\u003cp>\u003cbr>[Why]\u003c/p>\u003cp> 为什么要使用比喻呢？因为使用比喻是把新知识和已有经验进行关联，让知识和自己发生关系，是对知识内化的过程，可以避免理解不透彻的情况。有了形象的、与自己相关的比喻，可以让我们加深对新知识的理解和记忆。\u003c/p>\u003cp>\u003cbr>[How]\u003c/p>\u003cp> 如何用比喻呢？有三个步骤：\u003c/p>\u003cp> 第一，确定内容。确定要深入理解和记忆的内容，可以将这些内容提炼精简为一句话或者几个关键字，便于抓住重点来理解和记忆；\u003c/p>\u003cp> 第二，找到比喻。在生活经验中寻找与学习内容相似的东西，找不到完全符合的也没关系，多找几个部分符合的也可以。可以将一个知识点和我们的衣食住行联系起来，或者是和自己喜欢的一项运动联系起来。这是寻找比喻的一个好方法；\u003c/p>\u003cp> 第三，修正比喻。重复上述过程，检查比喻当中不恰当的地方，适当进行修正。如果把云比作棉花，恰当的地方是它们的形状和颜色相似，不恰当的地方是它们的大小和构成不同。\u003c/p>\u003cp>\u003cbr>[where]\u003c/p>\u003cp> 比喻法是将新知识和已有经验联系在一起的方法，它的适用的场合有2点：\u003cbr> 1.对于相对复杂知识点的理解可以使用比喻法，加深理解；\u003c/p>\u003cp> 2.比较随意的知识点的记忆，可以使用比喻法把这些知识点串联起来，便于记忆。\u003c/p>\u003cp> \u003cbr> 不适用比喻的场合也有2点：\u003c/p>\u003cp> 1.易于理解的知识点，不必再用比喻法去理解；\u003c/p>\u003cp> 2.规律性比较强的知识点的记忆，没有必要用比喻法去记。\u003c/p>","interaction":"\u003cp> 下面我给大家分享一下我自己使用比喻来学习的一个小故事：\u003c/p>\u003cp>\u003cbr>[故事/经验]\u003c/p>\u003cp> 上周三12月21日在办公室看完如何使用比喻学习之后，我就特别想用到39786国标的管理制度部分的记忆上。这个管理制度我之前看过，也背过，但就是记得不熟练，时间一长总会忘掉几个，而且怎么想也想不起来。于是我开始整理每款制度的关键词，然后把最熟悉的用车场合和管理制度做比喻。\u003c/p>\u003cp>\u003cbr> 我是这样比喻的：\u003c/p>\u003cp> 1.要有密码应用安全管理制度，就像我们有辆车；\u003c/p>\u003cp> 2.建立密钥管理规则，密钥（英文是key，也有钥匙的意思）相当于车钥匙，车钥匙要重点管理；\u003c/p>\u003cp> 3.制度中得建立操作规范，开车也有操作规范：点火、打转向灯、给油起步；\u003c/p>\u003cp> 4.制度的执行过程得记录，和车上的行车记录仪功能一样；\u003c/p>\u003cp> 5.制度要定期修订，车要定期保养维护；\u003c/p>\u003cp> 6.要明确管理制度发布流程，4S店的保养流程一般会贴在墙上发布。\u003cbr> 这样就根据用车保养的生活经验比喻管理制度的六个要点，只要想想车的事情，就不会忘掉制度。虽然制度定期修订和车辆定期保养的比喻牵强有点，但它们的共同点是“定期”，有助于记忆这条制度。24号周六在家回顾了一下，记住了。这两天办公室又回顾了一下，真的太开心了，以前记不住的东西，现在根本忘不掉。\u003cbr>[反思/复盘]\u003c/p>\u003cp> 在学习39786标准的过程中，记住标准条款是非常重要的一个学习目标。我发现，这次使用比喻来记忆管理制度，效果完全超出预期。总共用了不到1小时时间，几天后回顾，也没有忘掉任何一条。记住的原因当然就是比喻法的功劳了。总结一下这次的学习，我觉得最大的特点是使用比喻法记忆这种规律性不强的内容，把这些内容和生活经验联系到了一起，最后达到了想忘也忘不掉的神奇效果。\u003c/p>\u003cp> 你是不是也有使用比喻学习的冲动了？或者是已经在使用比喻法尝试最近学过的一个知识点了？我和你一样，有了这次使用比喻学习的神奇经历，我想继续用这种方法把整个39786国标学习一遍。\u003c/p>\u003cp> 为此，我制定了这么一个目标：\u003c/p>\u003cp>\u003cbr>[目标]\u003c/p>\u003cp> 2023年1月20日前使用比喻法，把39786中关于技术和管理部分全部梳理一遍，每个部分至少用三种比喻方式，学习结束后可以默写这些条款的关键点。\u003cbr> 当然，仅有目标还是不够的，行动才是达成目标的手段。我的行动计划是：\u003cbr>[行动]\u003c/p>\u003cp> 1.梳理39786各个部分条款，将这些条款提炼为简短的关键字；\u003c/p>\u003cp> 2.使用比喻法将关键字和生活经验关联起来，至少用三种方式进行比喻；\u003c/p>\u003cp> 3.将比喻写成文档记录下来；\u003c/p>\u003cp> 4.找出比喻中不贴切的部分并修订；\u003c/p>\u003cp> 5.从今天开始，每周一、三、五晚上8点在书房完成39786中的一部分，第二天下午下班的时候回顾复习。\u003cbr>[保障措施]\u003c/p>\u003cp> 如果晚上没有完成的话，第二天早起利用早上时间完成。\u003cbr>[奖惩措施]\u003c/p>\u003cp> 1月20日前可以完成的话就奖励自己吃一顿火锅，如果不能完成的话就处罚自己做一个月家务。\u003cbr>[反思复盘]\u003c/p>\u003cp> 在1月20日对整个行动计划进行复盘，并总结经验教训，以便更好的使用比喻来学习。\u003c/p>\u003cp> 现在我来总结一下今天的拆书，我们学习了《如何高效学习》当中的“怎样用比喻学习”，就是把新知识和已有经验联系起来，加深理解和记忆。期待大家能把这个方法用到今后学习中，让我们一起持续精进。\u003c/p>\u003cp> 最后，谢谢大家参与我TF1-1拆书家晋级活动。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1672727166000,"updated_at":1673227173000,"ria":true},{"id":14178,"topic":"如何识别生活中的熵增","learn_goal":"","remark":"一位因为快速学习而成名的神奇小子，他应用自己发明的学习方法，完成了10天搞定线性代数，1年学习4年MIT课程的“不可能任务”。本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。跟随作者，你也将成为高效学习的超级学霸。","level":"TF1-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"石研","city":"石家庄市"},"club":{"name":"石家庄冀城分舵","city":"石家庄"},"prologue":"\u003cp>自我介绍： \u003c/p>\u003cp>大家好，我是凡事都爱琢磨研究的石研，精诚所至，金石为开，可以很好的记住我的名字！\u003c/p>\u003cp>我的三个标签是：\u003c/p>\u003cp>��� 1.个人成长教练\u003c/p>\u003cp>经历了丢失自己，找到自己，探索自己，活出超能自我，我踏上了不断精进修行的教练学习之路，开启了付费教练，也一直有做企业的公益教练活动的支持参与，如果你也想要活出超能自我，探寻自我潜力的，欢迎联系我！\u003c/p>\u003cp>��� 2.在线课程运营官\u003c/p>\u003cp>因为疫情，接触了在线课程，从此一发不可收拾，加入了一个美育教师专业师训平台，销售，运营，管理，都做过，独自运营管理过140多人的新课，做海报，写文章，制作小视频，咱都会。喜欢与人沟通，分享和联结，期待遇见有缘的你！\u003c/p>\u003cp>��� 3.终身学习者\u003c/p>\u003cp>2020年疫情期间开启了疯狂学习输入输出的模式，竟然量变成质变，有了融会贯通的感觉，真正体验到了学习的乐趣！从此开始不断学习提升，阅读，听课，参加活动，喜欢大脑思考和心灵感受的过程，喜欢在学习中获得滋养和赋能！\u003c/p>\u003cp>一句话总结：我是石研，一个专职在线课程运营官，也是一个终身学习不断精进中的个人成长教练！\u003c/p>\u003cp>拆书法和拆书帮介绍：\u003c/p>\u003cp>接下来在介绍拆书帮之前我先给大家介绍一下拆书和拆书法。\u003c/p>\u003cp>��� 拆书——系统方法论\u003c/p>\u003cp>“拆书”是一种更高效的成人阅读学习法，也有一套系统方法论，拆书就是把书中的致用片段用RIA便签法，R是阅读原文拆页，I便签用自己的话重述原文知识，A1便签指向过去，联想和激活学习者自身经验，A2便签指向未来，规划自己未来的目标和行动，最后拆为己用，指导运用于实践行动中。\u003c/p>\u003cp>��� 拆书法——两种学习形式\u003c/p>\u003cp>拆书法有两种学习形式，一种是个人学习的应用，用RIA便签拆书法读书更高效致用；一种是组织学习应用，由拆书家带领将一本书扩展加工成一场培训一个课程，促进一群人的学习成长！\u003c/p>\u003cp> 拆书帮——拆书法学习者社群\u003c/p>\u003cp>“拆书帮”是一个拆书学习爱好者的社群，致力于“释放学习促进者的能量”，带领和促进更多的人运用RIA拆书便签法把知识拆为己用，在全国各地都有拆书帮分舵（拆书爱好者俱乐部），是公益性自组织，培养热爱学习的人成长为拆书家，并影响更多的人高效学习成长！\u003c/p>","ratings_count":1,"texts":[{"id":18191,"quote":"\u003cp>主题【页码】P88-89\u003c/p>\u003cp>怎样应用比喻法学习条件反射？比喻法的第一步是在你的个人经验中寻找能够模拟条件反射的东西，我个人生长在加拿大的冰天雪地里，所以想到的第一个比喻就是在雪地里行走。你第一次在雪地里行走时，因为雪地茫茫一片，走哪条路都有可能。但是几次行走以后，你会选择一开始走的路，因为开始的行走在雪地上形成了一条隐约可见的小路，走这条路显然比随便走更容易。\u003c/p>\u003cp>我将雪中走路与条件反射联系在一起，一开始，铃声可能或不引起狗分泌唾液（这代表一开始雪地茫茫一片，无路可寻）。但是在将铃声和食物关联在一起后，从铃声到食物的路就在雪地上（狗的大脑里）形成了，最终狗一听见铃声就分泌唾液，因为这条路已经很明显了。像很多比喻一样，这个比喻也不完美，但是它很有用。\u003c/p>\u003cp>可以按照下面三个简单步骤找出一个比喻：\u003c/p>\u003cp>1）确定你要深入理解和记忆的信息，在上面例子中就是经典条件反射。\u003c/p>\u003cp>2）在你的个人经验中寻找与信息部分相似的东西，要达到完全符合不太可能，所以与其寻找一个完全符合的东西，不如稍作让步，找到十几个部分符合的“不完美比喻”，在上面例子里我想到的时雪中行走。\u003c/p>\u003cp>3）重复上述过程，检查比喻不恰当的地方。例如，雪中行走时线性的痕迹，而脑神经却是错综复杂的网络。\u003c/p>","explains":"\u003cp>我也简单地讲述一下《如何高效学习》这本书，这本书主要讲了整体性学习的策略和技术，整体性学习的基础就是将知识关联起来以达到记忆和应用知识地目的，开始学习的最佳技术是比喻、内在化、基于流程的记事和画图表法，这些方法构成了整体性学习的基础。而本次拆页就是其中的一个技术：比喻。\u003c/p>\u003cp>what:\u003c/p>\u003cp> 比喻是文学上的工具，用来将某个物体与其他物体联系在一起，比喻在学习理解难点知识中扮演的角色也是一样的，可以在新知识和已有知识之间形成桥梁作用。这两页片段讲了一个用比喻法学习条件反射这个概念，作者将雪中走路与条件反射联系在一起，比喻不完美，但是很有用，最后给出了找出比喻的三个简单步骤，非常有效实用。\u003c/p>\u003cp>why:\u003c/p>\u003cp> 知识的记忆和理解是需要方法策略的，死记硬背显然只是其中一种记忆理解的方法，还不见得有效。知识也是可以迁移运用的，文学中的比喻法也可以用在知识的理解记忆中，形成新旧知识有效的联结，让难点知识变得通俗易懂、更加生动形象，便于记忆和理解。\u003c/p>\u003cp>how:\u003c/p>\u003cp>找出比喻的三个简单步骤是：\u003c/p>\u003cp>1.确定理解记忆的信息——确定你要深入理解和记忆的信息，比如一个新知识点，一个定律或模型。\u003c/p>\u003cp>2.找到“相似比喻”——在你的个人经验中寻找与信息部分相似的东西，找到部分符合的相似比喻就可以。\u003c/p>\u003cp>3.检查完善比喻——重复上述过程，检查比喻不恰当的地方。\u003c/p>\u003cp>where:\u003c/p>\u003cp>这个方法适用于想要深入理解和记忆的难点知识和信息，简单实用有效。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>【故事】\u003c/p>\u003cp> 2019年我通过学习听课，总听到一个热力学熵增定律，当时就不是很理解，查阅搜索了百度，看看它的定义：一个系统的熵等于该系统一定过程中所吸收（或耗散）的热量除以它的绝对温度，只要热量从高温物体流向低温物体，系统熵就会增加，是不可逆的。太复杂了，看不懂啊！我就想怎么就能简单记忆理解，运用到生活中，这时我头脑中马上联想到的一个场景就是家里收拾好了会慢慢变乱，那从高温流向低温，就可以比喻成家里的环境由有序变得无序，这样一想就很好理解了。而这个比喻也会在我一听到和想到熵增定律时马上联想到。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>现在想想我当时就是无意中使用了找出比喻的三个简单步骤，先确定要理解的信息知识点，再进一步抓住头脑中第一时间闪现的比喻场景，并进行重复记忆运用，检查完善比喻。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>【目标】\u003c/p>\u003cp>这个月我计划阅读《洞见》这本书，在遇到像“洞见”、“正念”、“辨识”等概念理解时会运用比喻法进行理解和记忆，经常进行比喻法的刻意思考和练习，锻炼比喻联想的创造性思维，进行知识的深度理解和内化。\u003c/p>\u003cp>【行动】\u003c/p>\u003cp>1.确定想要记忆理解的知识和信息，提炼主要观点：坚持至少两周内每天一次好好阅读学习的内容，阅读完后，写下至少3个主要观点。\u003c/p>\u003cp>2.找出解释观点的相似比喻：针对每个观点，写一个可以解释观点的比喻，比喻要简单形象好理解，如果比喻不能完全解释观点，可以尝试找到更多可以解释观点的比喻。\u003c/p>\u003cp>3.检查完善比喻，直到确定自己真正理解。重复刻意练习，随手记录“奇思妙想”，将自己的所见所闻所想以及印象深刻的场景和事例进行比喻联想思考，随时记录下来，形成素材库备用。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>最后总结一下今天的拆书，今天主要是学习了如何找出一个比喻解释观点的三个简单步骤，其实就是将文学中的比喻迁移到了难点知识的学习中进行运用，比喻起到了一个新旧知识联结的桥梁作用，可以更好地促进难点知识的深入理解和记忆。我今天的分享就到此结束了，希望这个片段会对各位伙伴有帮助启发。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1663152998000,"updated_at":1663155421000,"ria":true},{"id":13414,"topic":"运用费曼技巧进行整体性学习","learn_goal":"","remark":"费曼技巧","level":"TF1-1","duration":13,"status":30,"type":0,"chaishujia":{"username":"楊楊","city":"重庆市"},"club":{"name":"重庆拱辰分舵","city":"重庆市"},"prologue":"\u003cp>不破不能立，不拆不成器！拆书帮把知识拆成你的能力！欢迎大家参加拆书帮重庆筹备分舵线下拆书练级活动。\u003c/p>\u003cp>我是今天的领拆人杨秦，微信名“楊楊好运来”，大家可以叫我楊楊。简单用三个标签介绍我自己，1.知识产权从业者；2.拥有六岁女宝的斜杠妈妈；3.业余中医养生爱好者\u003c/p>\u003cp>相信大家也遇到过这样的困惑，刚看完了一本书却不记得书里讲了什么，或者是没有多少时间去读书，又或者准备学一项新技能想去报培训班觉得贵，自己看书学习呢又觉得学不到精髓。那我也就是基于以上的困惑才学习了拆书法并参加了拆书帮继续深造。\u003c/p>\u003cp>那接下来我们就聊聊什么是拆书帮和拆书法。\u003c/p>\u003cp>什么是“拆书”呢？\u003c/p>\u003cp>其实就是一种学习方法，它非常适用于成人的学习，因为成人的学习基本上都是以提升能力和解决问题为主的。\u003c/p>\u003cp>拆书法具体有两种实践形式，分别如下：\u003c/p>\u003cp>第一种是供个人学习的便签学习法，也就是我们现场的大部分朋友参加过的RIA便签学习法，整体思路就是通过自己对于书中原文的理解，结合自己过往经验，深入思考从而指导我们下一步的行动，使得我们读完一本书的效用等同于参加同主题培训的效果。\u003c/p>\u003cp>第二种实践形式是由拆书家带领的RIA现场的学习， 就是由一位拆书家拿一本书加工出一场现场的学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>那拆书帮又是什么呢？\u003c/p>\u003cp>拆书帮是基于拆书法的学习爱好者社群，它是一个公益性的青年学习组织，它的使命是帮助更多的学习爱好者成长为拆书家。目前，拆书帮分布在我国47个城市，全国有56家正式分舵，12家筹备分舵。我们所在筹备分舵叫重庆扣我分舵，是由我们现场拆书家中唯一的3级拆书家、拆书帮全国的资深教育长老、且是我亲爱的师父山佳老师感召了这么一群积极向上且同频小伙伴而组成。接下来，希望更多的、爱学习的小伙伴们一起加入进来，共同学习，共同成长。\u003c/p>\u003cp>今天呢我给大家带来的R是出自《如何高效学习》中的片段，请大家用2分钟时间看一下我给大家准备的手稿内容，阅读完毕后举手示意我，我们接着进行后面的内容。\u003c/p>","ratings_count":1,"texts":[{"id":17426,"quote":"\u003cp>《如何高效学习》219页\u003c/p>\u003cp>整体性学习技术的实际运用——费曼技巧\u003c/p>\u003cp>很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只需花上20分钟就能深入理解知识点，而且记忆深刻，难以遗忘。下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>第一步：选择要学习的概念\u003c/p>\u003cp>首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp> 第二步：设想你是老师，正在试图教会一名新生这个知识点\u003c/p>\u003cp>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清。\u003c/p>\u003cp>第三步：当你感到疑惑时，返回去吧\u003c/p>\u003cp>每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>第四步：简单化和比喻\u003c/p>\u003cp>如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003c/p>\u003cp>例如：在学习力矩时，用简单的话解释力矩，而不是照抄书上的定义。比如，首先用俗语“扭曲”来说清楚力矩是什么意思。\u003c/p>\u003cp>其次，给力矩找个恰当的比喻，我把力矩向量比喻为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>","explains":"\u003cp>我们一起来看一下原文片段向我们传递了哪些信息：\u003c/p>\u003cp>What:\u003c/p>\u003cp>原文片段告诉我们费曼技巧是一种可以把想要学习的知识点通过自己整理，最终可以达到以简洁明了的方式教会别人的一种学习技巧。\u003c/p>\u003cp>Why：\u003c/p>\u003cp>在接收知识类学习时，同样的老师，不同的学生掌握的知识点却高低不同，甚至有人花别人几倍的时间也达不到想要的成绩或效果，归根结底就是没有掌握好的学习技巧。\u003c/p>\u003cp>大多数人在学习时候基本上是左耳进右耳出，也有的人学习时笔记也做的挺多，看起来很用功，但后面检测时候却发现知识点还给了老师，根本没学到任何东西，也没到达到自己想要学习的目标，最终也是浪费时间、浪费精力。\u003c/p>\u003cp>使用费曼技巧，以教代学，可以在短时间内深入理解知识点，而且记忆深刻，难以遗忘。\u003c/p>\u003cp>How：怎么运用费曼技巧\u003c/p>\u003cp>（1）选定概念:在白纸顶上写下我们选定的，将要深入理解学习的概念。\u003c/p>\u003cp>（2）假设教学场景：假设自己是一名为正在为新生备课的老师，在纸上用自己的语言的解释那个需要讲解的概念。\u003c/p>\u003cp>（3）解决疑惑：当遇到疑虑时候，参考各种渠道直到搞懂，然后把新掌握的知识继续写在纸上。\u003c/p>\u003cp>（4）生动描述：最后将纸上所有解释通过比喻、联想等方式简单明了、生动形象表述出来。\u003c/p>\u003cp>where：\u003c/p>\u003cp>（1）适用场景：费曼技巧适合爱学习、需要学习的人在学习学科类、技术类等需要大量记忆的知识时候运用。\u003c/p>\u003cp>（2）不适合场景：费曼技巧不适合用于看小说、新闻信息等娱乐休闲性质的阅读。\u003c/p>","interaction":"\u003cp>为了帮助大家更好的理解，我分享一个我自己的亲身经历\u003c/p>\u003cp>故事：2020年7月，我报考了人事局中级经济师的考试，因时间比较赶，所以给自己制定了分次突破的考试计划，计划当年只学习其中的一个比较难考试项目——经济基础，并制定了严格的学习计划和学习目标，经过3个月的努力，终于如愿以偿，顺利通过这门课程的考试。但是在2021年10月份考试的时候却把另外一门简单的考试考砸了，以致于2020年成功通过的经济基础分数也失效，弄得全盘皆输。去年底当我准备重头开始备考时候，却发现之前学习的专业内容基本都还给书本了，公示、理论都忘得干干净净，瞬间觉得再次考试通过的机会也很渺茫了！\u003c/p>\u003cp>反思：通过记忆强行记下来的书本内容，如果没有转换成自己的并且能复述出来内容，就不是自己所掌握的知识，在大脑中保存得时间也不会长久。\u003c/p>\u003cp>学习了费曼技巧之后我计划设定一个这样的目标：5月30号前，用费曼技巧学习抖音铺货并教会妈妈用抖音账号在自己的店铺里上卤鹅。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>（1）选定概念:确定学习抖音铺货后，在网上找相关课程并建立电子档案；\u003c/p>\u003cp>（2）假设教学场景：假设自己是正在为妈妈的抖音教学进行备课，并在world文档中用自己的语言介绍怎样进行抖音铺货；\u003c/p>\u003cp>（3）解决疑惑：当遇到困惑时候，找抖音客服了解情况并实操直至彻底搞懂；\u003c/p>\u003cp>（4）生动描述：最后把抖音铺货的相关步骤和相关注意事项简单明了地表述出来，直到教会妈妈在抖音里上卤鹅。\u003c/p>\u003cp>奖惩：5月30号前，如果把妈妈教会了，奖励自己一个周边一日游。如不能罚自己连续一个月不间断站桩30分钟。\u003c/p>\u003cp>以上就是我对便签学习法得一组展示，希望大家能够学有所获。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1652705331000,"updated_at":1652790253000,"ria":true},{"id":13189,"topic":"费曼技巧","learn_goal":"","remark":"费曼技巧作为一种人人都可以掌握的学习方法，让你成为学霸不再困难","level":"TF2-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"方华丽","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>\u003cstrong>【开场】\u003c/strong>\u003c/p>\u003cp> 大家好，我叫华丽。三个标签的自我介绍：1、长沙麓山分舵新任组织长老 2、终身学习的信奉者   3、爱读书、运动和吃喝玩乐。欢迎大家参加今天长沙麓山分舵第379期线上活动，谢谢大家在此陪伴我的成长。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>今天我们按照两人一组，方便一会儿小组角色扮演和讨论。\u003c/p>\u003cp>【学习目标】今天的目标是：希望在跟随我完成本次RIA现场学习之后，当学习者在自学或者感到学习低效时，能够按照“费曼技巧“给出的四步法，构建一个清晰、明确的学习步骤。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F 特征（核心是“书”，用于满足好奇心）\u003c/strong>\u003c/p>\u003cp>今天我要拆的书籍是《如何高效学习》，本书的作者斯科特•扬是一位因为快速学习而成名的神奇小子。他认为任何一门知识都不会单独存在，它总是与方方面面的知识联系在一起，要从学科内部跳出来，站在外面看学科。本书是对他学习方法的全面介绍，书中阐述的整体性学习策略的核心思想和具体技术，为高效学习者提供了从生活到时间管理的整体解决方案。\u003c/p>\u003cp>\u003cstrong>A 优势（重点是“比较”，用于建立安全感）：\u003c/strong> \u003c/p>\u003cp>这本书比同类书籍更加通俗易懂，行文生动有趣，条理清晰。书中没有深奥难懂的理论，介绍的学习方法的可操作强，读起来轻松有趣，引人入胜，是一本适合大众阅读的成功致用类书籍。\u003c/p>\u003cp>\u003cstrong>B 利益\u003c/strong>（强调的是“学习者”的利益，用于引发兴趣）\u003c/p>\u003cp>\u003cstrong>B1：（本书有什么好处？）\u003c/strong>\u003c/p>\u003cp>如果你觉得自己是学习困难户，学习起来又苦又累，还效率不高，又或者想用最短的时间，达到最快的学习效果的话，来看看这本书，跟随作者，你也将成为学习路上的超级学霸。\u003c/p>\u003cp>\u003cstrong>B2：（本片段有什么好处？）\u003c/strong>\u003c/p>\u003cp> 今天我们的学习主题是聚焦书中提到的费曼技巧片段，在学习中，我们自以为学会了某些知识，却无法验证，直到上考场或运用时才发现还有盲区，今天片段里告诉我们如何使用这种人人都能掌握的“以教为学”的学习方式，使得学习更加有趣有效，这种方法也是谷歌创始人推崇的超级学习法。\u003c/p>\u003cp>接下来，请大家花1分钟的时间，阅读屏幕上的片段。阅读完，请在对话框敲1。\u003c/p>","ratings_count":2,"texts":[{"id":17175,"quote":"\u003cp>【主题】如何高效学习\u003c/p>\u003cp>【片断来源】整体性学习技术的实际运用-费曼技巧\u003c/p>\u003cp>【原文片段】\u003c/p>\u003cp> 运用费曼技巧，你能达到过目不忘。现实中，这个技巧人人都能掌握，接下来，我就告诉大家具体如何去做。\u003c/p>\u003cp> 费曼技巧的具体措施\u003c/p>\u003cp>(1)理解那些你没有真正掌握的知识点。\u003c/p>\u003cp>(2)记住那些你能理解，却可能在考试中遗忘的知识点。\u003c/p>\u003cp>(3)作为一个考前学习的高效率方法。很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只需花上20分钟就能深入理解知识点，而且记深刻，难以遗忘。\u003c/p>\u003cp> 下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp> \u003cstrong>第一步:选择要学习的概念\u003c/strong>\u003c/p>\u003cp> 首先选好你打算深人理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp>\u003cstrong>第二步:设想你是老师，正在试图教会一名新生这个知识点\u003c/strong>\u003c/p>\u003cp> 这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清。\u003c/p>\u003cp>\u003cstrong>第三步:当你感到疑惑时，返回去吧\u003c/strong>\u003c/p>\u003cp> 每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>\u003cstrong>第四步:简单化和比喻\u003c/strong>\u003c/p>\u003cp> 如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003c/p>","explains":"\u003cp> 好，小伙伴们已经看完了。我带领大家拆解一下这个片段。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>这个片段告诉我们这种人人都能掌握的费曼技巧是如何用四步法以教促学，使得我们在学习中能够深刻理解和记忆知识点。\u003c/p>\u003cp>\u003cstrong>【Why】【人们常规的做法】\u003c/strong>\u003c/p>\u003cp>不管我们的身份是学生还是上班族，总要学习很多东西，但有时候不是想学就能学成的，很多人在书海中以苦做舟，付出很多心血，以为都学会了，却往往更多的是走马观花式学习，无法真正理解所学，所以看上去一直很努力，却始终学习效果不佳，长期以往，容易丧失学习信心，人生难以有更大的突破。今天拆页分享的费曼技巧这种神奇的方法，其核心是以教的方式让你自觉、甚至是开心的、有意识的主动学习，不断内化吸收理解知识点之后，用简单形象的方式再呈现，验证你是否真正掌握所学，是否学有遗漏，从而轻松高效完成学习任务。\u003c/p>\u003cp>\u003cstrong>【how】【拆页行动建议】\u003c/strong>\u003c/p>\u003cp> 接下来让我们看看如何具体运用费曼技巧，一共分为以下四步骤。\u003c/p>\u003cp>\u003cstrong>第一步：选择知识点\u003c/strong>：把想学、想记住的知识点或概念名称写在白纸上方醒目位置，如垃圾分类、异次元、黑茶有益健康等。\u003c/p>\u003cp>\u003cstrong>第二步：尝试当老师\u003c/strong>：这一步非常关键。需要细分为两个小步骤和一个方法。\u003c/p>\u003cp>小步骤1：想象自己是一名老师，要努力回答对面的新生提问。\u003c/p>\u003cp>小步骤2：老师在对新知识点、概念进行解读时，在纸上记下能让学生完全明白的点。\u003c/p>\u003cp>在这里我推荐一个关于提问的方法，提出一个好问题，意味着问题解决了一半，大家可以按照3W1H 法进行提问，即三个以W开头的英语单词和一个以H开头的英语单词进行设问：\u003c/p>\u003cp>（1）\u003ca href=\"https://baike.baidu.com/item/WHAT/61780\">WHAT——本质是什么？ \u003c/p>\u003cp>（2）WHY——为什么？ \u003c/p>\u003cp>（3）\u003ca href=\"https://baike.baidu.com/item/WHO/74453\">WHO——何人？ （4）\u003ca href=\"https://baike.baidu.com/item/HOW/2286245\">HOW ——怎么做？ 方法是什么？\u003c/p>\u003cp>在这个问答的过程中对一个问题刨根问底，有可能发现新的知识和新的疑问，能够促使你更好理解和产生灵感。\u003c/p>\u003cp>\u003cstrong>第三步：不懂找外援\u003c/strong>：对知识点不明白没关系，停下来，可以求助外援，如上网查询或者咨询更专业的人，把答案写在纸上，有需要的话，又可以回到第二步当老师继续做讲解，循环往复，直到弄懂为止。\u003c/p>\u003cp>\u003cstrong>第四步：简单做比喻：\u003c/strong>用直白浅显、简单的语言重新定义或用恰当的比喻来形容这个知识点的核心内容，这样可以帮助我们用生动形象的方式记住它，不容易遗忘。比如我理解的土建专业学的就是像搭积木一样把房子盖起来的技术。 \u003c/p>\u003cp>举个例子:我如何理解“ 拆书”是什么意思并记住它，下面是费曼技巧的四步法应用：\u003c/p>\u003cp>\u003cstrong>第一步：选择知识点：\u003c/strong>我在白纸上写上“拆书”两个字\u003c/p>\u003cp>\u003cstrong>第二步：尝试当老师：\u003c/strong>想象或者找一个朋友当我的学生，我跟她解释什么是“拆书”，以下是我们的对话：\u003c/p>\u003cp>我：亲爱的朋友，今天我给你解释一下“拆书”是什么意思吧!\u003c/p>\u003cp>朋友: 我只听说过拆家，拆书是什么意思呢？\u003c/p>\u003cp>我：我们在看书的时候，会不会遇到当时觉得书中方法很赞，有机会要用用，可是过一段时间就忘了的情况？\u003c/p>\u003cp>朋友：是的，上次我还看了如何与伴侣良好沟通的方法，结果昨天上午又因为鸡毛蒜皮的事跟老公吵了一架。 \u003c/p>\u003cp>我：你可以把书中如何沟通的方法自己重新整理一下，然后想想昨天和老公发生争吵过程，再试试今天回家后如何用这个沟通方法和老公解决那些鸡毛蒜皮的事。通过学习书中节选的精华内容，结合自身经验进行反思，改变自己的行动，做到知识的“拆为己用”，这就是拆书。这就是回答\u003cu>（what的提问）\u003c/u>\u003c/p>\u003cp>接下来我跟她继续解释拆书的更多内容,比如回答\u003cu>（why的提问）\u003c/u>为什么要拆书，拆书是为了解决学习没时间、没精力、看不懂、记不住等问题,回答\u003cu>（who的提问）\u003c/u>这个方法的创始人是赵周老师，回答\u003cu>（how的提问）\u003c/u>拆书学习的核心方法是“RIA现场学习法”即是“阅读拆页Reading+讲解引导Interpretation+拆为已用Appropriation”的综合应用。\u003c/p>\u003cp>然后记录下以上3W1H内容。\u003c/p>\u003cp>\u003cstrong>第三步：不懂找外援：\u003c/strong>\u003c/p>\u003cp>对于拆书how里面重要的环节选择拆页，我还不明白，因此我会请教海带师父正确选择拆页的方法，如选择拆致用类图书、有步骤的拆页等，逐一记下。\u003c/p>\u003cp>\u003cstrong>第四步：简单做比喻：\u003c/strong>\u003c/p>\u003cp>最后对于拆书，我理解是书就如同一只鸡,拆书就是把鸡拆成鸡块,这样方便吃、更好吸收。\u003c/p>\u003cp> 经过以上四步，我对拆书的理解更清楚，每次吃鸡都会想起拆书。\u003c/p>\u003cp>【预防疑义】\u003c/p>\u003cp> 有没有人觉得按这个费曼技巧“四步法”是不是太麻烦了，之前碰到知识点就看看例子听听解释，再背一背，应该就能记住了，何必这么大费周章，事实上，类似这种情况无法验证你是否真正掌握了知识，短期也许有效，长期必然低效甚至无效，增加的时间和精力成本会更高。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp> 这个方法适合愿意尝试打开专业壁垒，希望创造性解决问题的职场和学习人，尤其适合自学的时候，如果认为学习是有边界的人或者只想单纯知道问题答案的场景，不适合这个方法。 \u003c/p>","interaction":"\u003cp> 我们刚刚学习了费曼技巧的“四步法”(选择学习点、当老师、找外援、做比喻），现在来做一个演练。请大家认真听一下要演练的场景：\u003c/p>\u003cp>\u003cstrong>【设定场景】\u003c/strong>\u003c/p>\u003cp>人物：大一新生和同学\u003c/p>\u003cp>场景：某节课结束后，一名大一新生对于课上老师教的一个新知识点感到很懵，发愁要怎样才能弄明白呢？ 如果按以前的做法，只能再去问老师或者自己翻资料，但是效果可能不佳、时间也比较长，这时你想起之前学到过的费曼技巧的“四步法”(选择学习点、当老师、找外援、做比喻），于是你约了一位同班同学一起去学校图书馆自习室，按这个学习步骤做个学习讨论。\u003c/p>\u003cp>\u003cstrong>【指令】\u003c/strong>\u003c/p>\u003cp> 请大家在两人分组中一位扮演大一新生，一位扮演同班同学，此时，你们会如何用费曼技巧“四步法”做学习讨论呢？\u003c/p>\u003cp>大家先在小组内讨论并预演，接下来我会邀请一个小组两名成员来为大家分享他们的角色对话。这个环节有10分钟的时间。其中讨论时间是6-7分钟，分享时间是3-4分钟。如果有不清楚的地方，大家可以随时问我。如果都清楚了，就请开始讨论和预演吧。\u003c/p>\u003cp> 好的，时间到，我们请第一组的赵丹和summer来做个分享吧。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>赵丹：第一步我们选择今天学的“费曼技巧“进行讨论，首先我会在纸上写上概念“费曼学习法是一种事半功倍的学习方法”。\u003c/p>\u003cp>赵丹： 第二步，我是一名老师，summer你来当学生，关于这个概念你有什么不清楚的吗？\u003c/p>\u003cp>summer：请问什么是费曼学习法？（what）为什么会事半功倍？(why)谁提出的？(who)要怎样做呢？（how）\u003c/p>\u003cp>赵丹： 首先关于 what： 学习的本质是理解后的熟练运用； 关于 why 以教代学的方法就是用输出的方式去实践，学以致用。常言道，要给别人一杯水自己先要有一桶水。 带着目的去找结论； 关于who：是费曼教授发明的方法 ；关于how: 用别人可以轻松理解的方式去表达沟通。需要简单、通俗的、生动、甚至是比喻--用大家都很熟悉的方式，有代入感的方式去共情。\u003c/p>\u003cp>summer:原来如此，明白了。\u003c/p>\u003cp>赵丹： 第三步：刚在网上查了一下，费曼技巧是世界五大学习法之一，与西蒙学习法、番茄工作法、思维导图学习法和跨界学习法并列，非常值得尝试。\u003c/p>\u003cp>summer：我还感觉这个方法是不是跟拆书帮有点像？\u003c/p>\u003cp>赵丹： 是的，你说得对。接下来咱们用个简单词语形容一下费曼学习法吧！\u003c/p>\u003cp>summer：我觉得这个方法就用“以教促学”四个字表达可以吗？\u003c/p>\u003cp>赵丹：很好。\u003c/p>\u003cp>【点评与总结】\u003c/p>\u003cp>非常感谢两位小伙伴精彩的表演。来，掌声送给他们。\u003c/p>\u003cp>点评： 大家有没有发现用费曼技巧四步法以后，对知识的理解是不是更深了，同时也发现了其实还是有盲区？相信今天的学习会给大家带来更深的体会。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>今天我们学习了费曼技巧的“四步法”，看到大家都有收获，我很开心。今天的分享就到这里，感谢大家的陪伴成长！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1648019398000,"updated_at":1649908836000,"ria":true},{"id":12736,"topic":"四问学习法&比喻记忆法","learn_goal":"","remark":"你每天都在看朋友圈的干货，你觉得自己在学习。\n你一周一本书，你觉得自己在学习。\n你参加培训班，你觉得自己在学习。\n你刷抖音，看视频，觉得自己在学习。\n你以为自己在学习。\n那为何你还是没有改变呢？\n那为何真正需要用的时候你忘了这些干货和知识呢？\n你知道吗？\n你只是在获取信息。\n你完成了学习步骤没有？\n什么？\n学习还有步骤？\n是的，来参加我的拆书活动吧，\n两招让你搞定学习。","level":"TF2-4","duration":55,"status":29,"type":0,"chaishujia":{"username":"小东","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家晚上好，我是小东，是今天2-4拆书家，今天我拆的这本书叫《如何高效学习》。在拆书之前，先给大家分一下组，便于稍后的讨论。\u003c/p>\u003cp>学习目标1：学习者完成现场学习后，在自学的时候，不再只浏览信息就认为学完了，而是能运用“四问学习法”技能，引导自己完成获取，理解记忆，拓展和应用的四个学习步骤。\u003c/p>\u003cp>学习目标2：对需要深入理解和记忆的知识，能运用比喻记忆法，找到自己的经验和熟悉的知识进行链接记忆，达到加深理解和记忆的目的。\u003c/p>\u003cp>F（特征，核心是书）：本书的作者是斯科特•扬（Scott Young），这是一个用1年时间修完麻省理工33门课的大神级人物，这本书主要是介绍他的整体性学习方法。\u003c/p>\u003cp>A（优势，重点是比较）：跟同类学习方法类书籍比较，他特别强调了比喻和类比在学习中的重要性，把知识互相联系起来才是记得更多，学的更好的秘密。\u003c/p>\u003cp> B1（利益，强调的是学习者收获）：本书介绍了整体性学习策略，提供了如何学得更好的模型和具体的学习技术，只要对照练习，就能掌握方法，提高自己学习的学习技能。\u003c/p>\u003cp> B2\u003cstrong>片段益处\u003c/strong>：今天的学习大家将掌握两个技能：\u003c/p>\u003cp>1. 在自学的时候，不再只浏览信息就认为学完了，而是可以利用四问学习法引导自己完成理解，记忆和应用的学习过程。\u003c/p>\u003cp>在对要深入理解和记忆的知识能运用比喻记忆法，找到自己熟悉的经验和知识进行链接记忆，达到加深理解和记忆的目的。\u003c/p>","ratings_count":1,"texts":[{"id":16674,"quote":"\u003cp>【R】\u003cstrong>拆页1：\u003c/strong>\u003c/p>\u003cp>进行积极阅读时你需要记下：\u003c/p>\u003cp>\u003cstrong>（1）这一节中主要观点是什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（2）我怎样才能记住主要观点？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（3）我要怎样将主要观点拓展开以及应用它。\u003c/strong>\u003c/p>\u003cp>第一个问题仅仅促使你完整地获取信息；第二个问题迫使你对信息进行联系、视觉化和比喻法；第三个问题要求你将信息应用在不同的情境中。这三个问题迫使你将每个知识点都要经过整体性学习里的理解、拓展和应用三个阶段。\u003c/p>\u003cp>比如我刚刚读完心理学中的经典条件反射，其主要的知识点是：\u003c/p>\u003cp>·经典条件反射的发现者是巴甫洛夫\u003c/p>\u003cp>·经典条件反射是刺激引起反应\u003c/p>\u003cp>我会这样记忆：\u003c/p>\u003cp>·想象一副图画，画中巴甫洛夫的狗听到铃声流出了唾液。\u003c/p>\u003cp>我会这样拓展：\u003c/p>\u003cp>·我听到电视里类似的手机铃声，会不由自主地掏出自己的手机。\u003c/p>\u003cp>如果你能对教科书里的每一个知识点都进行这样完整的积极阅读，你一定会天下无敌。一旦你熟悉了这种方式，就不必对每个知识点进行完整的积极阅读，而只针对自己需要理解和记忆困难的那些内容。\u003c/p>","explains":"\u003cp>请大家花1分钟阅读原文拆页，看完抬头示意我。\u003c/p>\u003cp>大家都看完了吧！\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>或许大家会有这样的困惑：明明这个知识点自己看过，为什么到考的时候就记不起来呢？其实学习是一个有具体步骤的过程，看过一遍只是学习的第一步获取信息。\u003c/p>\u003cp>今天的拆页就帮我们解决了走完学习过程的问题。拆页的核心有三步，分别是信息的主要观点是什么？怎么记住观点，如何对观点进行拓展和应用，其中第三步拓展和应用合在一起比较难应用，我把这一步细化为两步，先对观点进行拓展，激发过去的经验或将知识变成具体的应用技能，然后再规划未来如何应用，这样就便于使用，我把这个技能叫做四问学习法。\u003c/p>\u003cp>【细化行动步骤】\u003c/p>\u003cp>那四问学习法具体怎么做呢？\u003c/p>\u003cp>第一步，我看到什么？通过这个提问让自己提炼关键信息，整理成主要观点。\u003c/p>\u003cp>第二步，我想到什么？通过这个提问，让自己能深入理解和记忆信息，我怎样用自己的话来重述原文。\u003c/p>\u003cp>第三步：我变成什么？通过这个提问，让自己能激发过去的经验或将知识变成具体的技能\u003c/p>\u003cp>第四步，我用在哪里？通过这个提问，引导自己规划未来把知识用在哪些地方。\u003c/p>\u003cp>【强调不这么做的坏处】\u003c/p>\u003cp>\u003cstrong>（一般做法）\u003c/strong>我们大部分人在学习的时候以为听了，看了，学习就完了。其实这才做到了学习过程的第一步获取信息。\u003c/p>\u003cp>\u003cstrong>（这种做法的坏处）\u003c/strong>这个信息没有经过自己的理解，拓展和应用，当时是以为自己学到了，但实际上没有深刻理解，也没有进行拓展，导致一看就忘，记住了也不会用，用的时候又忘了具体该如何下手。\u003c/p>\u003cp>\u003cstrong>（反例）\u003c/strong>我在《瞎吃》这本书上看到这样一段信息“研究人员普遍认为，至少要花20分钟，我们的身体和大脑才能传递饱足的信息，信息传达之后，我们才会觉得自己吃饱了。”然后就完了，我还觉得这本书很无聊，这个信息对我也没什么用。\u003c/p>\u003cp>\u003cstrong>（回顾how,反例变正）\u003c/strong>当我学了四问学习法这个技能后再看着段信息的时候，我会问自己：\u003c/p>\u003cp>我看到什么？这段信息的将的主要观点是大脑比胃的感觉要慢20分钟。\u003c/p>\u003cp>我想到什么？想象自己的胃饱了，派了一慢吞吞的树懒传消息给大脑说胃饱了要花20分钟时间。大脑再让嘴停下来不进食时，已经多吃了20分钟的食物，这样每次都多吃，不胖才怪。\u003c/p>\u003cp>我变成什么？吃饭的时候少吃20分钟？不现实，应该是少吃20%的食物比较合适。\u003c/p>\u003cp>我用在哪里？以后吃饭要提前决定，要比自己想吃的量少打20%的饭菜，防止自己吃的过多。\u003c/p>\u003cp> 这样经过这四步，我把这个信息变成了一个可以触发自己管理自己饮食的技能，真正做到了学以致用。\u003c/p>","interaction":"\u003cp>【A1】【显像提问】\u003c/p>\u003cp>好，听完我对拆页的分享，现在请大家回忆一下，过去一个月，你肯定看了一些书或者好看的微信文章，闭上眼睛想一想，你当时是怎样阅读的？（构建情境），有没有看的时候直拍大腿说这一招好使，我怎么就没想到呢，但看完后就忘记怎么用的情况？（激活经验）请把关键词写在拆页上，稍后请小伙伴分享。\u003c/p>\u003cp>学习者老彭：看了李诞的《脱口秀手册》，看的时候写的蛮好，合上书发现自己啥都没学会，脱口秀具体怎么做呢？\u003c/p>\u003cp>刚才给我们分享了一个没有用四问学习法引导自己走完学习过程的例子，谢谢老彭的分享。\u003c/p>\u003cp>学习恩群：看书觉得联想法很好，但看其它书的时候又忘记了联想法怎么用。\u003c/p>\u003cp>刚才大家分享了一些没有走完学习过程的案例，那大家如果再去看书学习时，尝试用今天学到的四问学习法引导自己完成学习步骤，你会怎么做呢？请大家讨论一下，一分钟后我请一位代表分享。\u003c/p>\u003cp>学习者恩群：如果再看联想法，我会先问自己我看到了什么是联想法，我想到什么是用自己的话重述原文，我变成什么是把联想法变成一个记忆技能，第四步是用在学习看书中。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":16675,"quote":"\u003cp>比喻法在整体性学习中扮演的角色是类似的，\u003cstrong>比喻就是在不熟悉的知识和熟悉的知识之间架起一座沟通的桥梁。\u003c/strong>比喻在文学中主要提供视觉上的相似，而在整体性学习中联系的是类似的过程：事件或者信息的顺序。（其实比喻法不必拘泥于二者有多么相似，只要有一点相似，不管是视觉、听觉、触觉还是直觉，也不管是原理、目的还是过程，都可以拿来比喻，比喻法也就是建立模型的方法。──译者注）\u003c/p>\u003cp>举例来说，\u003cstrong>我们在心理学课上学到了条件反射，\u003c/strong>经典的条件反射讲的是一个刺激经过强化，与一个反应建立联系的现象，这个现象由巴甫洛夫观察狗的行为而发现。巴甫洛夫注意到如果每次给狗送食物之前先按铃的话，以后一按铃，即使不给食物，狗也会分泌唾液。\u003c/p>\u003cp>怎样应用比喻法学习条件反射？\u003cstrong>比喻法的第一步是在你的个人经验中寻找能够模拟条件反射的东西，\u003c/strong>我个人生长在加拿大的冰天雪地里，所以想到的第一个比喻就是在雪地里行走。你第一次在雪地里行走时，因为雪地茫茫一片，走哪条路都有可能。但是几次行走以后，你会选择一开始走的路，因为开始的行走在雪地上形成了一条隐约可见的小路，走这条路显然比随便走更容易。\u003c/p>\u003cp>我将雪中走路与条件反射联系在一起，一开始，铃声可能或不引起狗分泌唾液（这代表一开始雪地茫茫一片，无路可寻）。\u003cstrong>但是在将铃声和食物关联在一起后，从铃声到食物的路就在雪地上（狗的大脑里）形成了，最终狗一听见铃声就分泌唾液，因为这条路已经很明显了。\u003c/strong>像许多比喻一样，这个比喻也不完美，但是它很有用。\u003c/p>","explains":"\u003cp>用四问学习法引导自己完成学习步骤就算学会知识了吗？不一定，四问学习法中的第二步记忆就很让人头痛，那大家都是怎么记忆的呢？\u003c/p>\u003cp>这本书介绍了一个加深理解和记忆的方法，“比喻记忆法”，将知识创造的关联越多，它们就会被自己记得越牢、理解得越好。\u003c/p>\u003cp> 请大家用2分钟的时间阅读一下拆页二，看完后抬头示意我。\u003c/p>\u003cp>【what】大家都看完拆页了吗？这个拆页的关键词是什么？比喻。\u003c/p>\u003cp>今天分享的比喻记忆法就是利用知识和经验的相似性进行关联记忆的方法。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>比如我看了拆页一的积极阅读法，我打算记下来做分享，我可以用比喻来这样记忆，我先把拆页一的内容关键词找出来，用三个提问引导自己完成理解，记忆，拓展和应用的学习过程；然后列出这个拆页的本意是学习有理解，记忆，拓展和应用这些学习过程，需要用问题来引导大脑完成，重点是过程；引导完成过程；接着我在自己过去的经验里找一找有没有与过程相似的经验，我想到安装电脑软件的过程中有很多确认键来进行引导安装，而且不确认就装不进去电脑，就像学习不走完过程就不能把知识变成自己的一样；然后我把新知和旧知联系起来，检查这个比喻有哪些不同的地方，相同的是都有一个过程，不同的是电脑确认过程完成了自己就运行了，人脑还要不停的引导自己去思考，记忆。\u003c/p>\u003cp>【细化步骤】\u003c/p>\u003cp>整理一下，比喻记忆法具体怎么用呢？\u003c/p>\u003cp> 第一步，定信息。确定要深入理解和记忆的信息。\u003c/p>\u003cp>第二步，理本意。整理出信息的本意，整理出信息的特征，顺序，原理，逻辑等。\u003c/p>\u003cp>第三步，找相似。在个人经验和熟悉的知识中找到与信息本意相似的部分。\u003c/p>\u003cp>第四步，联知识。重复上述过程，检查比喻不恰当的地方。\u003c/p>\u003cp>【案例】比如我看了“究人员普遍认为，至少要花20分钟，我们的身体和大脑才能传递饱足的信息，信息传达之后，我们才会觉得自己吃饱了。”用比喻记忆法来理解和记忆。\u003c/p>\u003cp>第一步：定信息。整理关键词为“胃饱的信息传达到大脑要花20分钟。”。  \u003c/p>\u003cp>第二步：理本意。这个信息里有信息传递，大脑延迟20分钟接受胃的信息，延迟时间等意思。\u003c/p>\u003cp>第三步，找相似。我洗澡调水温，感觉到水有一点冷，然后调热一点，但因为热水与冷水有一个混合的过程，我要得到的水温会有一个延迟时间，在这个时间段有可能会被烫着或冷着。\u003c/p>\u003cp>第四步，联知识。胃的信息传递到大脑会延迟，洗澡调到合适的水温也会有延迟，不同的地方是延迟的时间不一样。虽然这个比喻不完美，但我用这个比喻将新知识与我熟悉的经验进行了连接，能让我马上记住。\u003c/p>\u003cp>【where】比喻记忆法一般用在抽象的概念的理解和记忆上，对一些杂乱信息比如一系列日期，专业术语，复杂的规章制度，公式等就不太适合。\u003c/p>\u003cp>【预防异议】可能有小伙伴说，用比喻法理解记忆概念知识找相似好困难，这里其实是有个思维定式要打破，因为我们之前都是用特征相似性来比喻，造成我们没有想过利用事件或信息的顺序相似性也可以拿来比喻。打破这个思维定式，只要坚持对信息进行梳理就越能深入理解，也就越能从自己熟悉得知识中找到相似性。\u003c/p>\u003cp>【回应或反馈】\u003c/p>\u003cp>把比喻法介绍了这么多，请问有没有哪位小伙伴有什么不太明白的地方？\u003c/p>\u003cp>学习者提问：理本意还不够理解。\u003c/p>\u003cp>回应：理本意就是整理这个信息本来的意思。那个饱的信息传递到大脑要20分钟，是不是有个延迟的意思在里面，把信息里涵盖的深层意思抓取出来，就是理本意的意思。\u003c/p>\u003cp>学习者提问：定信息是什么意思。\u003c/p>\u003cp>回应：定信息就像我们找拆页一样，找到一个有HOW的技能点就是定信息。\u003c/p>","interaction":"\u003cp>教就是最好的学习，大家今天学习了“比喻记忆法”，接下来做一个场景演练。\u003c/p>\u003cp>【场景】\u003c/p>\u003cp>李老师是一个善于用比喻法讲解物理概念的老师。\u003c/p>\u003cp>李老师的朋友老王正在给儿子讲解压强的概念，物体所受\u003ca href=\"https://baike.baidu.com/item/%E5%8E%8B%E5%8A%9B/5798497\">压力的大小与受力面积之比叫做压强,公式P=F/S，讲了半天，因为老王自己也不太懂压强，所以儿子也没听明白，这让老王急的直冒汗，老王拿起手机打给了李老师，吐槽了现在的情况，想请李老师用比喻法给自己指点一下，压强怎么用比喻法来理解和记忆。\u003c/p>\u003cp>【清晰指令】\u003c/p>\u003cp>我们生活中有哪些跟压强相关的经验？打针；鞋里有颗小石子，硌的脚疼，让一个人干两个人的活很有压力算不算？如果你是李老师，你怎么用比喻记忆法引导老王？请一人扮演老王，一人扮演李老师，组内先讨论1-2分钟，然后再角色演练4分钟，最后请一组小伙伴分享。\u003c/p>\u003cp>学习者演练\u003c/p>\u003cp>学习者老彭：李老师，我是老彭，我在给儿子讲压强的概念，讲了半天讲不清楚，你有什么好招可以把这个压强概念讲清楚？\u003c/p>\u003cp>学习者冠华：哦，这个概念挺抽象的是吧，这个压强的本质意思是什么呢？\u003c/p>\u003cp>学习者老彭：压强等于压力除以面积，受力面积越小压力越大，受力面积不变，压力越大，压强越大。\u003c/p>\u003cp>学习者冠华：你看这个是分子与分母的关系，分子越大，分母不变，压强越大。这个有点抽象，你看我们生活中有哪些是分子不变，分母变化了，之就发生变化的事呢？\u003c/p>\u003cp>学习者老彭：比如说钉钉子，钉子越尖受力面积越小，就很容易钉下去。\u003c/p>\u003cp>学习者冠华：对，你要告诉他，这个钉子的受力面积不变，用的力越大，钉子越容易钉进墙里去。这就是压强大的作用。你看只要找到压强的本质意思是啥，然后再抽象一下，再在生活中找一个相似的例子告诉他，这样把知识连起来就可以了。\u003c/p>\u003cp>学习者老彭：嗯，这个方法真管用。\u003c/p>\u003cp>好，感谢两位的精彩演绎，太棒了。\u003c/p>\u003cp>大家最近有没有新看到一些值得分享的概念知识？比如元宇宙，互惠原理等等。选出一个来下周做部门分享，这个知识是什么？请大家花1分钟写在便签上，并在小组内讨论2分钟，然后我请1~2位朋友出来分享。 \u003c/p>\u003cp>学习者回应：第二曲线，单点突破，战略杠杆，\u003c/p>\u003cp>我们下周要分享这个知识了，今天晚上你拿起了书，准备好好记一下这个知识点，刚才有的小伙伴已分享，有的还没来得及分享，没关系，接下来结合今天的拆页，一起体验下“比喻记忆法”的魅力。\u003c/p>\u003cp>我们采用私董会的方式，先小组内讨论1分钟，确定记忆的一个知识点，再运用“比喻记忆法”一起帮忙完成理解记忆，最后请小伙伴台上分享你的步骤，时间5分钟。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>第一步,定信息，战略杠杆。\u003c/p>\u003cp>第二步，理本意，战略杠杆就是四两拨千斤的方式让企业十倍速成长。找到增长的关键支点。\u003c/p>\u003cp>第三步，找相似，像打蛇打七寸，把企业所以的资源压在增长的关键支点上。\u003c/p>\u003cp>第四步，联知识，战略杠杆就像是打蛇打七寸。\u003c/p>\u003cp>今天的小伙伴都非常给力！接下来给大家做个总结：通过今天的分享，希望大家在学习中能运用两个技能：\u003c/p>\u003cp>1. 用四问学习法引导自己完成理解，记忆和拓展应用的学习过程。\u003c/p>\u003cp>2. 在对要深入理解和记忆的知识能运用比喻记忆法，定信息，理本意，找相似，联知识来比喻记忆。\u003c/p>\u003cp>最后，借用米南德的一句话来结束我的分享，学会学习的人，是非常幸福的人。祝愿今天听我分享的人都是幸福的人。\u003c/p>\u003cp>我是小东，感谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1638362607000,"updated_at":1641727875000,"ria":true},{"id":12598,"topic":"一个养成每日习惯的方法","learn_goal":"","remark":"不知很多时候我们为自己设定的一个习惯，刚开始几天能坚持，但是过了几天之后就放弃了，或者不能从内心享受做这件事情的习惯，所以习惯不牢固很容易找理由放弃，所以书上的这个片段教会我们一个养成每日习惯的正确方法，为我们改变旧习惯，养成新习惯提供了思路。","level":"TF1-1","duration":13,"status":30,"type":0,"chaishujia":{"username":"严金英","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":null,"ratings_count":1,"texts":[{"id":16520,"quote":"\u003cp>习惯的养成时另外一个课题，足以写一本书。我专门为此写过一本电子书。改变习惯并不像想象的那么困难，我在下面列举了一些养成正确习惯的方法，供大家参考。\u003c/p>\u003cp>(1)坚持某个习惯30天。比如每天阅读40页坚持一个月，每天练习网页设计一小时。为你接下来的30天设定一个每天都要坚持的学习目标吧，30天的坚持会形成一种习惯。\u003c/p>\u003cp>(2)坚持下去。每天以同样的方式完成同样的习惯，今天阅读，明天听讲，后天练习的方式对于养成习惯来说太脱节了。\u003c/p>\u003cp>(3)享受这个习惯。假如你不能享受这个习惯，这个习惯就不牢固。用头脑风暴法列举出各种各样可以养成的习惯吧，我想在一大堆想法中找出一个让你享受的习惯（阅读、练习和目标设置）应该不难。\u003c/p>\u003cp>(4)寻找特殊时段。我喜欢晨读，因为这对于我来说是一段不受打扰、可以专心思考的安静时段。找到属于你的每天特殊时段有助于强化你的习惯。\u003c/p>","explains":"\u003cp>很多时候，我们为自己设定的一个习惯，刚开始几天能坚持，但是过了几天之后就放弃了，或者不能从内心享受做这件事情的习惯，内心是不愉快的，所以习惯不牢固，就很容易找理由放弃。\u003c/p>\u003cp>所以，书上的这个片段教会我们一个养成每日习惯的正确方法，为我们改变旧习惯养成新习惯提供了思路。\u003c/p>\u003cp>怎么做呢？\u003c/p>\u003cp>01.列出自己想要养成的习惯，选定1-2个让自己享受的习惯（做这个事情的时候内心的愉悦的）\u003c/p>\u003cp>02.为这个习惯设置一个每天的特殊时间段，例如：每天早上5.30——6.30晨读时间\u003c/p>\u003cp>03.每天以同样的方式去完成这个习惯\u003c/p>\u003cp>04.把这个习惯和很喜欢的事情（感觉很愉悦的事情）联系到一起，让自己做这件事的时候是愉悦的，真正去享受这个习惯，坚持30天这样做\u003c/p>\u003cp>这个方法适用于：\u003c/p>\u003cp>01.养成某些学习习惯——晨读，学英语，考试学习\u003c/p>\u003cp>02.修炼某项技能——写作，演讲，声音训练\u003c/p>\u003cp>03.工作上，某些每天固定流程的事项\u003c/p>\u003cp>04.亲子教育上，每天早上起床和晚上睡觉，亲子阅读时光\u003c/p>\u003cp>05.生活中每天都需要做的事情，例如：早上起床刷牙洗脸喝水\u003c/p>\u003cp>当我们坚持这个习惯的时间足够长，脑神经形成了记忆，会比较容易自动坚持下去，并能够真正的享受这个习惯。\u003c/p>","interaction":"\u003cp>之前，我一直想养成每天早上冥想10min的习惯，所以，早上起来，有时第一时间想起来呢，就醒来就开始放着音乐冥想，有时是洗漱完成后冥想，有时是看完书再冥想；方式上也是，一会儿用这个系列的音乐，一会儿又找到另外课程上的音乐，就感觉每次都很混乱，坚持了10天之后，我就越来越容易忘记冥想了，然后就真的很久都没有去冥想了。\u003c/p>\u003cp>回过头来反思：\u003c/p>\u003cp>发现自己冥想的时间和方式每次都不固定，所以，没有形成肌肉记忆，所以很容易忘了做这件事情，并且，心态上也是很焦虑这件事情有没有做，而没有真正从内心去享受这个事情，所以这个习惯一直都没有养成，内心感到很沮丧和焦虑。\u003c/p>\u003cp>目标：\u003c/p>\u003cp>养成每天早上冥想20min的习惯。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>01.选择每日冥想的固定音乐和课程，不随意变换。\u003c/p>\u003cp>02.设定好每日冥想的固定时间段——每天早上5:10——5:30\u003c/p>\u003cp>03.固定方式——洗漱完成后，坐到书桌前面的第一件事情：盘腿坐在椅子上，打开手机音乐，开始冥想。\u003c/p>\u003cp>04.冥想20min完成后，把冥想状态写入成功日志中，感受到自己的蜕变。\u003c/p>\u003cp>05.坚持30天，不间断，完成30天，给自己一份大餐奖励/一件衣服！\u003c/p>\u003cp>这就是我对自己养成这个习惯所设立的目标。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1635770232000,"updated_at":1635841343000,"ria":true},{"id":12425,"topic":"TF1-2","learn_goal":"","remark":"TF1-2","level":"TF1-2","duration":14,"status":30,"type":0,"chaishujia":{"username":"张书豪","city":"昆明市"},"club":{"name":"昆明春城分舵","city":"昆明"},"prologue":"\u003cp>\u003cstrong>【分组】0.5分钟\u003c/strong>\u003c/p>\u003cp>今天我们是线上活动，人数也比较少，所有人就自成一组。\u003c/p>\u003cp>今天我要拆解的片段来自《如何高效学习》这本书。这本书讲了什么呢？\u003c/p>\u003cp>\u003cstrong>【图书介绍】 1分钟\u003c/strong>\u003c/p>\u003cp> 了解这本书之前，我们先看看这本书的作者斯科特杨，斯科特是典型的“别人家的孩子”， 从高中开始斯科特几乎课下不学习，尽管如此，他还是以全班第2名的成绩毕业。读大学时，大考之前一般每天学习不过两个小时，但他是麻省理工大学历史上最快毕业的人。本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。作者写这本书希望人人都可以成为高效学习者。\u003c/p>","ratings_count":1,"texts":[{"id":16375,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页 2分钟\u003c/strong>\u003c/p>\u003cp>[主题]：如何克服拖延\u003c/p>\u003cp>[片段来源]：拆解片段来自《如何高效学习》P.150\u003c/p>\u003cp>周/日目标体系 周/日目标体系是我知道的最好的对抗延迟的方法，办法很简单：\u003c/p>\u003cp> 1. 每周周末，列一个清单，包括所有的任务、作业以及你想在下周完成的读书和学习 活动。 除非在一周内出现意想不到的事情，否则你就有责任完成这个清单，不过也不必超过清单所规定的任务。这样做就把无限的工作分割成在一周内可以完成的子任务。如果这一 周特别忙碌，你可能会推迟完成任务。如果这一周很清闲，你可能会提前完成任务。\u003c/p>\u003cp> 2. 每天晚上，检查周计划，列出每日目标清单。\u003c/p>\u003cp>下一步是将每周的工作分配到每一天，你要确保完成每日的工作清单，但是不必超过它。\u003c/p>","explains":"\u003cp>\u003cstrong>【分享I便签】 4分钟\u003c/strong>\u003c/p>\u003cp>【What】(这是一个什么概念)\u003c/p>\u003cp>拆页向我们介绍了一个对抗拖延症的方法。\u003c/p>\u003cp>【Why】(为什么要这么做，这么做有什么好处，不这么做有什么坏处)\u003c/p>\u003cp>许多人深受拖延症的折磨，每次都在临近截止日期时，熬夜加班完成任务，导致任务完成质量低下，生活压力巨大。自己不是生活的主人，而成了截止日期的奴隶。\u003c/p>\u003cp>一个有效的对抗拖延症的方法能让我们更科学地规划生活，更高效地践行自己的规划。它让我们不再把压力积攒到最后，也不用强迫自己赢在起跑线上，只需完成自己每天跟自己的约定即可。\u003c/p>\u003cp>【How】(具体怎么做呢)\u003c/p>\u003cp>1. 列出周计划。每周末，在一张纸上列出下一周要完成的所有任务，包括工作、爱好、学习、社交等所有你能预想到的任务。比如我可以列出工作类，要召开项目说明会，要写月度报告，比如社交类的，要跟朋友一起共进一次晚餐，等等。学习类的，拆书帮要过级等等。注意不要把时间安排满，因为可能有紧急的任务突然出现，占用一定的时间。\u003c/p>\u003cp>2. 列出日计划。每天晚上，查看周计划表，列出第二天要完成的任务。注意这里的任务安排要具体到详细步骤，比如不可以是准备拆书过级，而要详细说明写好预备稿、做好PPT，预约过级时间等等。同样的原因，不要把一天的时间排满。\u003c/p>\u003cp>3. 不超额，可顺延。不管是日计划，还是周计划，如果你提前完成了，不要去做额外的任务，好好享受自己挣来的休息时间。如果某一天或某一周确实突然有大量的不可抗拒的新任务，无法完成自己的计划，往下顺延计划即可，也不必自责，因为这不是你的拖延所致。\u003c/p>\u003cp>【Where】用于管理十分重要但不紧急的任务，不紧急意味着没有截止日期，十分重要意味着你真的十分渴望去完成这个任务。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】（激活过去经验） 4-5分钟\u003c/strong>\u003c/p>\u003cp>我们已经学过这个拆页，并了解了如果通过以周为单位，以日为单位，拆解自己的目标，克服拖延症。现在请大家会想一下，自己以前有没有拖延的行为。比如健身，读书计划，工作，写论文等。回忆当时为什么会拖延？当时自己是否做了计划？当时的计划跟我们今天学的计划方式有什么不同？当然如果实在是太优秀了，没有拖延案例，也可以总结一下自己不拖延经历。\u003c/p>\u003cp>给大家30秒时间回顾。之后我会请1-2位朋友为我们分享。\u003c/p>\u003cp>那我们请XX朋友为我们分享一下\u003c/p>\u003cp>【学习者案例】\u003cstrong>现场记录——案例\u003c/strong>\u003c/p>\u003cp>Amber-做拆书过级的PPT，一直拖延到过级当天的中午12点才开始做，结果让自己十分的焦虑地勉强完成了任务。\u003c/p>\u003cp>小舅妈-计划学习视频剪辑，其实已经拆分了步骤，但是没有明确的时间计划，导致迟迟没有开始。\u003c/p>\u003cp>\u003cstrong>【A2】 （催化应用）1.5分钟\u003c/strong>\u003c/p>\u003cp>现在请大家计划下周要完成的目标，列出来。建议大家可以从工作、自我提升、和社交三个方面来写，不要贪多，每个类别写1-2个任务即可。写出A2便签。\u003c/p>\u003cp>给大家2分钟的时间。\u003c/p>\u003cp>结尾：因为今天时间有限，我们只写到了周目标，希望大家今天晚上回去，把自己的目标细分成详细的步骤，并计划好明天要完成哪几个步骤。如果你对这本书、这个拆页有新的思考，页欢迎来链接我，我们多多交流。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1633248109000,"updated_at":1634006819000,"ria":true},{"id":11932,"topic":"如何让你的笔记变得简单有趣 ","learn_goal":"","remark":"过级活动","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"罗巧琴","city":"东莞市"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>【总目标】在跟随我完成这次RIA现场学习后，学习者能在简化记录时，用重点+联系的图文组合法输出笔记。\u003c/p>\u003cp>---------------------------------1 \u003c/p>\u003cp>大家好！我是拆书家龙珠，今天分享的主题是：如何让你的笔记变得简单有趣。\u003c/p>\u003cp>先用三个标签简单介绍一下我自己：\u003c/p>\u003cp>一枚酷爱学习的终身学习者\u003c/p>\u003cp>一对双胞胎的妈妈\u003c/p>\u003cp>一个有近20年理财经验的金融人\u003c/p>\u003cp>为便于一会的讨论和练习，我们先来分一下组，三人为一组，共分为三组。\u003c/p>\u003cp>----------------------------------2 \u003c/p>\u003cp>人们通常会拿别人家的孩子来发出感叹，那么，下面有些别人家的笔记。\u003c/p>\u003cp>这里有我们熟悉的RIA学习法内容的笔记、也有平常的阅读笔记。\u003c/p>\u003cp>大家觉得这样的笔记怎么样？喜欢看吗？\u003c/p>\u003cp>它吸引你的，除了看起来漂亮，是不是内容精简，表达清晰，更容易理解呢？\u003c/p>\u003cp>---------------------------------3 \u003c/p>\u003cp>\u003cstrong>技能点：设定目标，包含可以被观测到/被测量到的行为或动作。\u003c/strong>\u003c/p>\u003cp>因此，我们今天的学习目标是，在完成这次RIA现场学习后，你能在简化记录时，用重点+联系的图文组合法输出笔记。\u003c/p>\u003cp>接下来的学习大约1小时，学习两个片段。\u003c/p>\u003cp>\u003cstrong>技能点：FAB法介绍图书（F特征，A优势，B利益）\u003c/strong>\u003c/p>\u003cp>【图书介绍】（2分钟）\u003c/p>\u003cp>\u003cstrong>F（特征，核心是书）:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段来自于\u003cu>《如何高效学习》，作者是斯科特•扬\u003c/u>（Scott Young），因快速学习而成名，他\u003cu>用自己的方法，1年就修完麻省理工33门课+4门外语\u003c/u>。这本书就是对他学习方法的全面介绍，讲了高效学习的七大方法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A（优势，重点是比较）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cu>对比同类的书籍，这本书强调的不是死记硬背，反复记忆知识点，而是整体性学习，用巧妙的方法让知识关联起来。\u003c/u>因此，书本非常畅销，在它出版的6年间，被重印20多次。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B（利益，强调的是学习者收获）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1本书益处：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不知道你有没有过一路不停步的学习，却总有只见树木不见森林的情况？书中提供的学习策略，能帮你找出学习上的缺陷，修正你的学习方法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B2片段益处：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>笔记是学习的工具之一，你有没有过一段时间后打开自己的笔记看，发现信息太乱看不懂、信息太多看下去的经历呢？今天学习的片段能让你的笔记变得简单明了，同时增强你的信息处理能力。\u003c/strong>\u003c/p>","ratings_count":2,"texts":[{"id":15893,"quote":"\u003cp>\u003cstrong>学习目标1：当需要简化记录时，从全部用文字做笔记转换为使用关键词和箭头，简化信息。\u003c/strong>\u003c/p>\u003cp>下面请大家花1分钟时间阅读第一个片段：笔记流\u003c/p>\u003cp>\u003cstrong>【R】阅读原文拆页一（1分钟）\u003c/strong>\u003c/p>\u003cp>《如何高效学习》P77\u003c/p>\u003cp>我在课堂上曾经使用一种记笔记的方法，对信息量较大的课程效果不错，我把这种记笔记的方法称为笔记流技术。笔记流技术的目标是提供一个平台以联系学到的东西。大多数人采用的画线、画圈等传统记笔记的方式被很多“流”（虽然有些杂乱）替代。\u003c/p>\u003cp>使用笔记流时，首先写下最主要的观点，尽量用很短的单词来替换完整的句子，这可能会降低可读性，但是提高了上课时的学习效率。事实、日期、细节和描写要尽量减少单词量，不要写冗长的段落。\u003c/p>\u003cp>一旦你写下了一个观点，下一步就是在这个观点和其他观点之间画上一些箭头，观点不是建立成金字塔式的结构，而是呈现出相互关联的关系，这个过程与实际的整体性学习策略类似，观点连在一张网中。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong> \u003c/p>\u003cp>好，我看到大家都看完了。\u003c/p>\u003cp>\u003cstrong>What： \u003c/strong>\u003c/p>\u003cp>原文告诉我们，用记下主要观点和画线的方法，能帮助我们简化信息，增加信息秩序\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>why：\u003c/strong>\u003c/p>\u003cp>笔记流用箭头的方式创建有序的信息，在帮助理解学习内容上，效果比纯文字的信息组合更易读取和思考。\u003c/p>\u003cp>\u003cstrong>技能点：意译原文案例、细化行动步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003c/p>\u003cp>具体是怎么做呢？以下是笔记流三步法\u003c/p>\u003cp>\u003cstrong>\u003cu>1.抓重点\u003c/u>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cu>2.词代句\u003c/u>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cu>3.点线连\u003c/u>\u003c/strong>\u003c/p>\u003cp>---------------------------------5 \u003c/p>\u003cp>刚才，从原文中我们可以看到一幅英文的笔记图，那是作者的笔记流示例图。\u003c/p>\u003cp>下面，请大家看看这个图，这是泉水老师在全国共拆《底气》时侯，张华做的笔记，这张图可以说很好的示范了笔记流的三个步骤：\u003c/p>\u003cp>\u003cstrong>记下主要观点、用短句代替完整的句子、再加上箭头联系。\u003c/strong>\u003c/p>\u003cp>通过这张图是不是让我们很快的看到《底气》的主要内容呢？\u003c/p>\u003cp>----------------------6 \u003c/p>\u003cp>\u003cstrong>技能点：不这么做的坏处\u003c/strong>\u003c/p>\u003cp>事实上，现在低年级学生还会用大段的文字来记笔记外，一般人通常的做法是记些关键词或短句。\u003c/p>\u003cp>这就如同你去市场买了堆食材回来，随意放着，时间一长，再回看这些没被整理的东西会让你感觉很乱，甚至想不起原来是干啥用的，因为它们之间没被串联起来、没有标出它们的关系。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>比如下面一份笔记，这是我在一次培训上的记录，当时一边听着内容，一边随意写下大脑漂出的内容，信息看起来有些散。\u003c/p>\u003cp>【把反例变成正例】\u003c/p>\u003cp>对照这份笔记，第一有抓重点、第二也有部分用词代句的，之所以看起来散乱是信息之间无序。拆页中建议是：在这个观点和其他观点之间画上一些箭头，呈现出相互关联的关系。\u003c/p>\u003cp>如果再来一份，我会通过以下步骤，让我的笔记尽管过段时间也能看起来简单易懂。\u003c/p>\u003cp>\u003cstrong>\u003cu>1.抓重点\u003c/u>\u003c/strong>\u003c/p>\u003cp>记下主要的观点，这培训主要是讲如何通过保险来规划退休生活，那么它就会有一条主线，比如幸福是什么？如何通过规划，得想要的幸福?退休的幸福生活画像是什么等。\u003c/p>\u003cp>\u003cstrong>\u003cu>2.词代句\u003c/u>\u003c/strong>\u003c/p>\u003cp>用简短的词组代替完整的句子，比如“符合你想要的生活方式是什么？”用“生活方式”旁边画个圈写上“想”代替。\u003c/p>\u003cp>\u003cstrong>\u003cu>3.点线连\u003c/u>\u003c/strong>\u003c/p>\u003cp>在主要观点之间加上箭头，来表达它们的关联/顺序。\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>：\u003c/p>\u003cp>这时侯，可能会有伙伴觉得笔记流和思维导图有点相似，那它与思维导图的区别在哪呢？\u003c/p>\u003cp>思维导图更多用于发散思维，而笔记流更像是笔记整理的一种，不用你二次整理就能把你当时的思考更有逻辑地呈现。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（技能点：\u003c/strong> \u003cstrong>显像提问）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>下面，我想请大家回忆一下，你有没试过记了笔记却没用的经历呢？\u003c/p>\u003cp>比如，你去上某一位老师的课，认认真真的记了厚厚的笔记，回看时发现信息量太大，想看的欲望都没了…；\u003c/p>\u003cp>又比如，你看到书中某段内容特别的好，如此摘抄着一堆，想着以后能用，可时间长了，这些被堆放的笔记就像“腐烂”的信息，找不出原来的价值…；\u003c/p>\u003cp>又或是单位组织培训，你记了很多的笔记，感觉收获满满，一周后老大让你转培训时才发现，散乱的笔记内容，却没办法让你回想起哪些是当时感觉很有用的…；等等\u003c/p>\u003cp>下面请把你回想到的场景，比如时间、地点、事件，最好把当时的感受也写下来，然后在小组分享。1分钟后邀请一位小伙伴来分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>香香：上周学习，我准备红蓝两个颜色的笔，蓝色记一般的内容，红色用于标记重点，这是为了方便我回看时能知道哪些是重点，其实很多时侯都是没有时间回看笔记的。\u003c/p>\u003cp>好的，感谢香香的分享，香香的习惯挺好的。\u003c/p>\u003cp>\u003cstrong>【A1+】（反思加工）（3分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（技能点：请学习者反思加工经验）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>刚才大家都有回想到相似的场景，现在你学习了笔记流三步法，那如果把你送回当时的场境，你会如何运用笔记流三步法呢？\u003c/p>\u003cp>请在小组里继续分享你的应用步骤并进行优化，2分钟后再请一位伙伴来分享下。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>张华：我想到刚才听第一位拆书家山山拆解时记的笔记，就是用重点罗列出来的，现在学了笔记流三步法，第一记重点点和第二步词代句，我基本已经能做出来的，重点在于第三步点线边，我把刚学的几个知识点进行连线，也形成了一个循环，这样回看起来简单明了。\u003c/p>\u003cp>\u003cstrong>回应：\u003c/strong>感谢张华的分享，张华的分享中应用了笔记流三步法，1记重点、2短句代替长内容、3进行连线。这点做得非常好。\u003c/p>\u003cp>---------------------------------\u003cstrong>8 \u003c/strong>\u003c/p>\u003cp>通过刚才的应用，一份简短有序的笔记是不是就出来了？\u003c/p>\u003cp>用“→”连起来的笔记，因为把阅读顺序和理论形象地整理出来，所以读起来更容易。\u003c/p>\u003cp>那么，现在我们让这种思路的整理进一步提升，通过加入符号和绘图，让各种联系组合起来，形成图文笔记。\u003c/p>\u003cp>下面，我们来看看，这种图文组合笔记是怎么做的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":15894,"quote":"\u003cp>\u003cstrong>学习目标2：当遇到量大的信息时，用图文组合的方式输出，让信息更简单的传达。\u003c/strong>\u003c/p>\u003cp>-------------------------------9片段二\u003c/p>\u003cp>请大家花1分钟时间阅读第二个片段：概念图\u003c/p>\u003cp>\u003cstrong>【R】阅读原文拆页二（1分钟）\u003c/strong>\u003c/p>\u003cp>《如何高效学习》P100\u003c/p>\u003cp>概念图将观点联系在一起，与笔记流密切相关。概念图里的关系并不是某个顺序中的不同步骤或是按日期顺序排列的观点，而是观点之间的内在关系。在不同观点之间画上箭头，箭头上还需要加上一些简单的话语，说明二者是什么样的关系。\u003c/p>\u003cp>假如我想画出不同财务会计原理的简图，首先我要写下四个基本的清单：资产负债表、收入、留存收益以及现金流，然后我可以在它们之间建立各种联系，最后形成知识网。\u003c/p>\u003cp>假如我想画出小说中的角色关系，我会先把主角放在图的中间，然后其他人物以他为中心按照与主角的关系分别画在旁边。这种方法有助于我们理顺思路，将庞大的知识组织得条理分明。\u003c/p>\u003cp>从最重要的观点出发，不断发出分支细化知识及分解观点。\u003c/p>","explains":"\u003cp>-------------------------10 \u003c/p>\u003cp>\u003cstrong>【I】拆书家讲解引导（10分钟）\u003c/strong>\u003c/p>\u003cp>好，我看到大家已经读完了。\u003c/p>\u003cp>平常大家阅读一页材料并达到90%的理解，需要花费多长时间呢？刚才我们花了1分钟的时间阅读，能理解这段内容的90%吗？\u003c/p>\u003cp>假如把刚才的片段画成这么一幅图，大家觉得阅读上有什么变化吗？\u003c/p>\u003cp>（why）每个人处理各种形式的信息的能力，或高或低（阅读或听讲都可以获取信息，但是信息的形式不同），这直接造成学习能力的高低。在信息获取阶段，我们的主要目标是简化，另外是能获取的信息量和接收的速度。\u003c/p>\u003cp>（what）原文说要在不同观点之间画箭头，那首先我们要提取出观点，观点间画上箭头说明关系，用绘图的方式能把主要观点关系理清，让我们的思路理顺，从而形成知识网。\u003c/p>\u003cp>图文组合的方式方便理解，易于记忆和传递，同时锻炼我们的思维方式。\u003c/p>\u003cp>\u003cstrong>技能点：细化步骤\u003c/strong>\u003c/p>\u003cp>（how）那具体怎么做呢？以下是图文组合四步法\u003c/p>\u003cp>\u003cstrong>\u003cu>1、提取 \u003c/u>\u003c/strong> \u003c/p>\u003cp>归纳总结，提取主要信息，比如找出关键词、转折词、重要概念等。\u003c/p>\u003cp>\u003cstrong>\u003cu>2、连线\u003c/u>\u003c/strong>\u003c/p>\u003cp>在主要信息间连线说明关系。\u003c/p>\u003cp>\u003cstrong>\u003cu>3、织网\u003c/u>\u003c/strong>\u003c/p>\u003cp>从主到次，在已有的连线上细化知识或分解重点，添加绘文字等，调整表达形式，形成关系网或结构图。\u003c/p>\u003cp>\u003cstrong>\u003cu>4、检查 \u003c/u>\u003c/strong>\u003c/p>\u003cp>检查信息是否已全部连线，再看一遍原文，确认关系是否正确，比如是否符合逻辑关系。\u003c/p>\u003cp>它可以结合笔记流来使用也可以单独使用。\u003c/p>\u003cp>------------------------------------11 \u003c/p>\u003cp>下面我们来看个例子\u003c/p>\u003cp>电影《赤壁》大家看过吧，回顾内容它的主要人物关系大概是这样的：\u003c/p>\u003cp>《赤壁》讲述的是曹操、孙权、刘备这三方军队的争斗。\u003c/p>\u003cp>曹操要夺天下，向其他两队发起攻击。\u003c/p>\u003cp>孙权继承兄位，刘备信仰仁爱第一，但不善作战。\u003c/p>\u003cp>孙权与刘备两队结盟，共同对抗曹军。\u003c/p>\u003cp>首先，从这段人物关系中提取关键人物：曹操、孙权、刘备。\u003c/p>\u003cp>第二，根据它们的关系，连线标示，比如下图。\u003c/p>\u003cp>第三，织网，根据内容补充细节，比如曹操要夺天下、刘备仁爱第一等，完善更完整的关系网。\u003c/p>\u003cp>第四，检查连线和关系，为了清晰好看我加上了方框，最后形成如下图。\u003c/p>\u003cp>------------------------------12 \u003c/p>\u003cp>\u003cstrong>技能点：预防异议\u003c/strong>\u003c/p>\u003cp>有木有小伙伴觉得第1步提取，实施起来比较难，不知道怎么提取的？\u003c/p>\u003cp>提取是笔记的第1步，也是关键的一步，前面提到，我们可以找出关键词、转折词、重要概念等等，这对于文字版的阅读实施起来并不困难，而听课的时候可能会难些，那么，这时我们可以回归本源，从提问着手，比如主题线是什么？你希望从中获得什么？与它相关的信息就是你要提取的，如果你觉得不需要掌握的信息，就大胆地跳过它。\u003c/p>\u003cp>\u003cstrong>技能点：这么做的好处\u003c/strong>\u003c/p>\u003cp>绘图能帮助你在阅读时提取关键思想，把你的理解变成图形，在事后容易展开，而且能够被立即用在PPT或报告资料里。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3 】促动参与 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：促动学习者现场演练—场景设计、小组讨论、角色扮演\u003c/strong>\u003c/p>\u003cp>好啦！为了你能实操起来，现在需要大家一起来做笔记输出的演练。\u003c/p>\u003cp>\u003cstrong>（场景设计）\u003c/strong>\u003c/p>\u003cp>请大家仔细听好下面的内容：\u003c/p>\u003cp>你是财务部员工\u003c/p>\u003cp>今天例会的主题：财务部今年工作目标的完成情况\u003c/p>\u003cp>\u003cstrong>财务部今年工作目标的达成进度如下：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“今年的销售目标是30亿，利润目标是3亿。现在一年时间正好过半，销售额为12亿，利润是1亿，完成了当期目标的80％。从销售构成来看，委托开发为3亿，会计软件是4亿，技术派遣为5亿，主力的会计软件业务比目标低3亿，正如大家听到的那样，这个业务有必要尽快做出调整。作为支持销售的政策，我们正在推进和X销售公司的合作计划。X销售公司有非常强大的法人销售渠道，目前正在寻找类似我们的会计软件业务的产品。另外，X销售公司能够将总代理点的广告管理软件介绍给我们的现有客户。这次的商业合作目的是利用对方的销售渠道交叉销售双方的产品。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（小组讨论）\u003c/strong>\u003c/p>\u003cp>好，现在请各小组应用今天学习的图文组合四步法，把财务部年度目标进度情况呈现出来\u003c/p>\u003cp>一是将小组讨论成果写在大白纸上\u003c/p>\u003cp>二是选出一名代表出来展示小组的成果，说出你们组是怎么用图文组合四步法一步一步呈现的。\u003c/p>\u003cp>10分钟后，我将邀请一组小伙伴为我们展示。\u003c/p>\u003cp>\u003cstrong>留意现场学习情况，过程提示（5分钟后）：\u003c/strong>\u003c/p>\u003cp>大家有困难不？我这有个图大家可参考一下\u003c/p>\u003cp>\u003cstrong>（讨论方案展示）\u003c/strong>\u003c/p>\u003cp>好，时间到，下面我们请一组小伙伴上来给大家展示。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>山山组：\u003c/p>\u003cp>\u003cstrong>技能点：回应与反馈\u003c/strong>\u003c/p>\u003cp>好的，刚才山山组应用图文组合四步法，第一提取观点，把销售额、利润、年度目标、半年等这些关键词提取出来，第二根据它们的关联情况用竖形条、箭头、画线等说明之间的关联，第三通过补充细节来完善它们的关系网，最后对照原内容确认各种信息及关系是否正确。很好的为我们展示了如何把一段内容以图文组合四步法展示出来的。\u003c/p>\u003cp>感谢山山的分享。\u003c/p>\u003cp>------------------------------14 \u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>（12分钟）\u003c/p>\u003cp>\u003cstrong>分步催化一 技能点：分步催化 激活应用场景\u003c/strong>\u003c/p>\u003cp>但我们并不止步于此，学习的关键是更多的应用到日常生活中，下面请大家再想想，未来的一周或一个月，还可能会出现哪些场景，让你可以运用图文四步法的呢？\u003c/p>\u003cp>比如你在阅读书桌上放着的那本书；\u003c/p>\u003cp>比如你在公开课上的行动学习；\u003c/p>\u003cp>比如你在与部门人员在项目讨论会上；\u003c/p>\u003cp>比如你在向客户介绍你公司零售业务的运营模式；\u003c/p>\u003cp>等等\u003c/p>\u003cp>请你把想到的场景写在学员手册上。1分钟后我请一位小伙伴分享。\u003c/p>\u003cp>好，下面我们请一位小伙伴来分享一下。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>艳娜：在下次与同事讨论事项或是沟通的时侯，可以运用到图文组合四步法。\u003c/p>\u003cp>\u003cstrong>分步催化二 技能点：分步催化 规划行动步骤\u003c/strong>\u003c/p>\u003cp>好的，现在大家都有自己将要应用的场景，那请你回顾今天学习的图文组合四步法，写下应用步骤。\u003c/p>\u003cp>改变已有习惯并不容易，所以，请同步规划你的练习计划，把你怎么做的写到学员手册上，写完后在小组里讨论分享你的行动步骤。\u003c/p>\u003cp>3分钟后，我请一位小伙伴来分享。\u003c/p>\u003cp>好，下面我们请小伙伴来分享一下\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>张华：我准备应用到8月份的两堂少儿创意字课堂与机构沟通主题与流程的时侯。之前是想着用文字表达，现在我打算用图文的方法来，第一提取，提取出主要内容的关键词，比如说工具准备、招生人数、设备、课程效果等，第二连线，以这些关键词的准备/沟通的流程来连线，这能帮助和提示我，第三织网，用从主到次的网状结构，让双方一同补充细节，比如我的一些想法、他的一些想法，让他知道我们是一个共同体，第四检查，我和他一起核对，比如我有没有忘了哪些关键词的，课程的准备啊，工具的准备啊等等。\u003c/p>\u003cp>从张华的分享中，我们可以看到图文组合四步应用得很具体，从第一的提取关键词、第二的连线流程、第三的织网构建共同体，到第四的检查，都很详细，感谢张华为我们做了这么好的示范（鼓掌）。\u003c/p>\u003cp>-----------------------------15 \u003c/p>\u003cp>\u003cstrong>结束语\u003c/strong>（0.5分钟）\u003c/p>\u003cp>\u003cstrong>（技能点：强有力的结语）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>好的笔记法是一生受用的技能，用笔记流与图文结合来形成化繁为简的思考习惯，相信以后你一定可以做出更多更有趣有用的笔记。\u003c/strong>\u003c/p>\u003cp> 我今天的分享到此结束，感谢大家的参与，感谢每一位小伙伴的积极回应与反馈。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1626664192000,"updated_at":1627536319000,"ria":true},{"id":11781,"topic":"拆解《超速学习》之定下学习目标之后，先“做什么？”","learn_goal":"","remark":"当设定好了学习目标后，我们有什么可行的方法能有效地办到？我们先做些什么呢？","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"学姐","city":"潍坊市"},"club":{"name":"潍坊飞鸢分舵","city":"潍坊"},"prologue":"\u003cp>大家好，我是蒲国华，我用三个标签先介绍自己：\u003c/p>\u003cp>\u003cstrong>标签一：\u003c/strong>我是一个资深的媒体人，26年传统媒体的编辑记者，曾获过国家晚报最高奖赵超构新闻三等奖，目前依然在单位新媒体的岗位做着审稿工作。\u003c/p>\u003cp>\u003cstrong>标签二：\u003c/strong>我是一个艾杨格瑜伽的习练者，目前已经练了3年了，因为职业长期伏案工作，身体状态不佳，医生推荐瑜伽后，慢慢爱上了这项运动，疲劳的时候练一会能让身体恢复一些能量。\u003c/p>\u003cp>\u003cstrong>标签三：\u003c/strong>我是潍坊第三书房的创始人之一，希望能把自己在媒体的工作经验提炼出来，教给孩子们写作文的能力，也想用第三书房这个平台，把好的知识分享传播，能和家长们一起学习成长，助人达已。\u003c/p>\u003cp>接下来跟大家介绍一下拆书帮：\u003c/p>\u003cp>首先，拆书法是我读致用类书的目前接触到的最好的解读方法，主要是以帮助我们成人解决问题提高自身能力为目标，它通过RIA三张不同颜色便签的规范方法，从阅读一个片段后，用自己的话引导促进，把一本书拆解，形成明确的应用步骤，给予书本第二次重生。RIA=阅读拆页R+讲解引导I+拆为己用A\u003c/p>\u003cp>应用到写拆书稿就是RIA=阅读原文+重述原文+联系经验、规划运用。\u003c/p>\u003cp>拆书帮是一个非盈利性的公益自组织，有一群热爱拆书法和升级打怪的拆书家在这个社群里，他们热爱分享、互相促进、一起成长，他们会把一本书用拆书法加工成一套培训课程，用来引导和带动一群人来学习，解决的是我们通常书太厚读不完，不能集中注意力到书上等一系列的问题。目前全国拆书帮已经有51家正式分舵，16家筹备分舵。\u003c/p>\u003cp>拆书帮的价值就是陪伴赋能，拆为己用，持续精进和共同成长。这一点也是我个人比较认可的一种理念，在这里，我们一起体验、反思、分享、行动，尽力给予接纳和支持；在这里，我们创造学习促进者的价值，历练成为拆书家，帮助我们爱的人一起学习。并希望在我们的潍坊的小伙伴的共同努力下，潍坊云门筹备分舵能顺利建舵。\u003c/p>","ratings_count":1,"texts":[{"id":15722,"quote":"\u003cp>【主题】定下学习目标之后，先“做什么？”\u003c/p>\u003cp>【片段来源】《超速学习》\u003c/p>\u003cp>\u003cstrong>【片段】\u003c/strong>\u003c/p>\u003cp>回答”做什么？”\u003c/p>\u003cp>一旦掌握了學习的理由，就可以開始看看你學习主题中的知识是如何建构起來的。最好的方法就是在一張纸上画出三個栏位，分别写下「概念」「事實」舆「程序」三個标题，然後進行脑力激荡，想出所有你需要學习的事項。在此阶段，這份列表是否完整或正确并不重要，以後都可以一再修正。你的目标是有一大略的初步了解，等到開始學习之後，若發現先前的分类不太對，随時可以调整表格。\u003c/p>\u003cp>\u003cstrong>1.概念：\u003c/strong>在第一栏，写下所有需要了解的事。概念是你需要用灵活的方式去了解、好让其变得有用的想法，例如數學舆物理，两者都是强烈概念倾向的科目。有些科目则跨立於概念舆事实的分水岭，像是法律，有需要理解的法律原则，同時也有需要記忆的细则。一般而言，若某事需要被理解，而不只是记忆，我就會放到這一栏，而非放在第二栏的「事實」。\u003c/p>\u003cp>\u003cstrong>2.事实：\u003c/strong>在第二栏，写下所有需要記忆的事。事實就是任何只要你能完全記住就足够的事。不需要太深入去理解，只要你能在對的情况下記起來即可。例如语言，就是充满了关于单字、發音，以及基本文法的事实。即使著重概念的科目，通常也包含一些事实——如果你在學微积分，會需要深入了解如何求导数，但或许只要記得一些三角恒等式也就够了。\u003c/p>\u003cp>\u003cstrong>3.程序：\u003c/strong>在第三栏，写下一切需要练习的事。程序是需要执行的行動，有時根本不必做太多有意识的思考。例如學骑脚踏車，几乎完全是程序性的，基本上不涉及事实或概念。有些技能大部分是程序性的，有些则是含有某個程序性的要素，但仍有要記亿的事實舆要理解的概念。學习一種语言的新单字需要記住事實，但發音则需要练习，因此属於這一栏。\u003c/p>","explains":"\u003cp>\u003cstrong>I便签\u003c/strong>\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这个片段是说，当设定好了学习目标后，我们有什么可行的方法能有效地办到？我们先做些什么呢？\u003c/p>\u003cp>最好的办法是我们把想做的目标拆解成概念、事实与程序做目标分类，先搭框架，标出我们将要面对的问题，然后去一一解决和克服。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>原文中回答做什么的时候，是为了设定的那个目标能成功，你需要掌握的所有的知识与能力。如果我们没有搭这个框架，不分概念、事实与程序，就不知道有多少事项是我们需要重点学习的和熟能生巧的。很有可能花了大把的时间，真正重要的事上学的不够多。\u003c/p>\u003cp>如果按按照目标拆解后，先做研究，在学习和操练的过程里可以随时调整修正，达到事半功倍的结果。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>\u003cstrong>1、理解概念：\u003c/strong>找出需要事项里所有需要理解的不需要记忆的概念，放在这一栏里。比如说，汉字的偏旁部首，你认识了火这个字，理解了火这个偏旁，以后看到带火旁的字，不认识也知道这个字大概和火有关。\u003c/p>\u003cp>\u003cstrong>2、记忆事实：\u003c/strong>找出需要记忆的部分，记住就足够，不用太深入理解。比如说学英语，字母的音标，单词的读法，以及语法那是基本事实，记下来就行了。\u003c/p>\u003cp>\u003cstrong>3、练习程序：\u003c/strong>需要执行反复操作的一些程序，是刻意训练的部分。比如说学开车上路，第一步系安全带，然后打火、挂档、起步等等这就是一整套的程序要素，是需要反复练习才能熟练的。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>想要快速学习一门学科、一项新技能的时候，都可以先用这个办法拆解事项，标出学科的障碍。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>3月初，我在拆书帮训练营里头接触到了李小曼老师的思维导图后，觉得那真的是和我画的思维导图有很大的偏差的，为了学习画好思维导图，能把新书快速的用思维导图的方法，把目录先画得更简洁、更形象、更美观一些，我就买了《画出你的答案》这本教程书，很快的把书里的内容都过了一遍。但是到现在，水平也没有多大提高。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>通过对这个片段的思考，我对学习思维导图的这个事儿也进行了反思。我拿到《画出你的答案》这本书的时候，没有分出概念、事实和程序这些事项。这本书的概念、事实、程序分类后：\u003c/p>\u003cp>概念：什么是主题、关键词、各级主题相互隶属关系、色彩\u003c/p>\u003cp>事实：基本组成元素（主题、层级、放射线）是记忆事实；\u003c/p>\u003cp>程序：拿到不同的书，以及遇到不同的场景，定时间定数量按要求，反复不停地画思维导图。\u003c/p>\u003cp>现在拆解发现没有那么复杂，并且也清楚的知道我就是程序部分练的少了。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>为了提高我应对很多面对面时的沟通能力弱的问题，通过用35天的时间学习黄执中的《超级说服力》这门课程，我要在8月初之前，能在学习完这门课程，并在教练的案例指导下，提高自己的沟通说服能力。\u003c/p>\u003cp>行动计划：\u003c/p>\u003cp>\u003cstrong>1、理解概念：\u003c/strong>可能遇到的情绪问题、更好的说法（别人发生的案例是需要理解的）。\u003c/p>\u003cp>\u003cstrong>2、记忆事实：\u003c/strong>《超级说服力》书中六种状态——改变、化解、提升、维护、拉近、理解。\u003c/p>\u003cp>\u003cstrong> 3、练习程序：\u003c/strong>根据自己的目前和过去遇到的情绪问题，由教练指导下，按照要素反复操练。\u003c/p>\u003cp> 在课程开始一周后，再对行动计划边上课边进行调整，然后重新对接下来的课程有一个指导作用。\u003c/p>\u003cp>奖励: 如果能做到，就奖励自己去大连听黄执中的线下课。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1624353208000,"updated_at":1624363939000,"ria":true},{"id":11578,"topic":"TF1-2过级","learn_goal":"","remark":"TF1-2过级","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"依哲","city":"洛阳市"},"club":{"name":"昆明春城分舵","city":"昆明"},"prologue":"\u003cp>因在线上，而且人员不多，我们自成一组。\u003c/p>\u003cp>大家好，我是依哲，很高兴参加本次拆书训练，我的三个标签是：优势教养推广者、家庭教育传播者、积极学习践行者。\u003c/p>\u003cp>今天跟各位分享《如何高效学习》一书中的拆页内容。\u003c/p>\u003cp>这本书将颠覆你以前对学习的认知，让你从中找到学习的快乐，找到自己高效学习的心灵密码。能够花最少的时间收获最大的学习效果，相信这是任何一种学习方法都追求的最高境界，也是每一个学习者的最终梦想，期待这本书能让你找到属于自己的捷径。\u003c/p>\u003cp>作者是加拿大大学生，叫斯科特.扬，他绝对是个超级学霸，大学的专业是商业学，业余时间自学了编程，参加各种演讲，开设自己的博客，还写了几本颇具影响力的电子书。当然，这还没完，他还完成了一项学习壮举，10天拿下线性代数（天呐，我好像两个学期还没学会），12个月内自学完成4年麻省理工学院计算机科学的33 门课程。这简直就是开挂了的人生啊，他究竟有什么秘诀呢？他很坦诚地将他的全部经验写成了这本《如何高效学习》。\u003c/p>\u003cp>今天我们一起来看看这个超级学霸是怎样进行能量管理，让他有充足的体力和精力完成那些惊人成就的。\u003c/p>","ratings_count":1,"texts":[{"id":15505,"quote":"\u003cp>【主题】 ：能量管理\u003c/p>\u003cp>【片段来源】：《如何高效学习》p144\u003c/p>\u003cp>高效率秘籍1 能量管理\u003c/p>\u003cp>我见过很多能量管理不佳的学生，他们因为过重的任务而将自己搞得精疲力竭，甚至需要借助咖啡因才能勉强工作。要完美地平衡学业和生活不是件容易的事，特别是在你的日程表安排得满满的时候。\u003c/p>\u003cp>我们的身体里都有燃烧细胞，不管是物质上的还是精神上的，你不可能驾着空油箱上路，假如今天透支身体数小时，下周你可能要为此偿还更多的时间，如果你现在常常感到疲劳、压力直至精疲力竭，说明你的能量管理做得不好。\u003c/p>\u003cp>良好的能量管理有两步：\u003c/p>\u003cp>（1）增加你的能量储备。\u003c/p>\u003cp>（2）将你的日程表由线性的改为循环式的。\u003c/p>\u003cp>增加能量储备\u003c/p>\u003cp>能量并非天生的，有很多办法可以帮助我们提高能量值，按照下面的去做吧：\u003c/p>\u003cp>（1）每周有3～5次运动吗？如果你的回答为否，你正在削弱你的潜在能量水平，除非你的医生不让你参加运动，否则最少每天要抽出40分钟来锻炼身体，每天运动一点点，学习效果更明显。\u003c/p>\u003cp>（2）每晚有七八个小时的睡眠吗？有些人睡四五个小时就够了，学习工作劲头十足，不过我想你我又不是这种神人，那么还是老老实实睡到自然醒吧，别想着玩游戏、喝酒、跳舞、玩通宵，熬夜对学习来说有百害而无一利，我看一年中除了过年可以守岁，平时绝不要熬夜。睡得好，脑袋才清醒。\u003c/p>\u003cp>（3）你吃的是什么？你的食谱是高糖、高脂肪、高蛋白质的吗？请放弃它吧，我建议你吃粗纤维和粗加工的食物，这样的食物可以让你一天的血糖水平保持平稳，避免忽高忽低。\u003c/p>\u003cp>（4）一天之内，你喝几杯水？你知道吗？你的身体有2/3都是水分，最快让你丧失能量的办法就是脱水。\u003c/p>\u003cp>（5）一天你吃几餐？如果你的回答是中餐、晚餐以及时不时吃点早餐，那么你的能量有可能不足。理想的饮食应该是少吃多餐，一天吃四五餐，每次吃七分饱，这样可以保证你一天内的营养供应持续稳定，睡前吃一点能让你第二天早上精力充沛。\u003c/p>\u003cp>循环式作息计划\u003c/p>\u003cp>线性的计划是平均安排时间执行工作，而循环式作息计划则先集中小部分时间做大部分工作。这种计划安排能让你做到有张有弛，而不是死气沉沉，像个机器人。下面是一些建议。\u003c/p>\u003cp>（1）一周休息一天。我总是抽出一周中的一天，什么事也不做，将7天的活放在6天里完成，一开始很难，但是放松一天能防止你筋疲力尽。\u003c/p>\u003cp>（2）晚上不干活儿。将一天的工作放在早上集中完成，早早完成工作，晚上你就有几小时的空闲了。\u003c/p>\u003cp>（3）设定90分钟。给定自己90分钟，集中精力完成某个学习任务，一旦90分钟结束，停止工作。90分钟的时间设定能让你学习时注意力更集中。\u003c/p>","explains":"\u003cp>【what】保持高效率的秘籍之一——进行能量管理。通过增加能量储备和更改日程表模式，让你保持足够的能量，去完美地平衡学业、工作和生活。\u003c/p>\u003cp>【why】我们经常因为过重的任务把自己搞得精疲力尽，甚至需要咖啡因来勉强工作，以至于造成咖啡成瘾等不良习惯，这往往是我们对自己的能量管理不佳的结果。\u003c/p>\u003cp>当感到能量不足时，就想办法增加自己的能量储备，让自己在需要拼搏时有劲儿可使，建立科学健康的生活习惯——适量运动、保证睡眠、健康饮食、少食多餐多喝水，而不是陷入亚健康中无法自拔；\u003c/p>\u003cp>我们还可以去关注一下自己的日程表，用循环式作息计划让自己集中黄金时间完成大部分工作，使自己的计划安排有张有弛，而不是像个机器人一样平均安排时间从事低效率的死气沉沉的工作；\u003c/p>\u003cp>长期的过载工作或学习，除了会对身体带来伤害，还会造自我效能感下降、幸福感缺少、抑郁等心理问题，适时调整自己的状态、节奏至关重要。\u003c/p>\u003cp>【how】可以从两个方面来进行能量管理\u003c/p>\u003cp>1、增加能量储备：适量运动（每天运动40分钟，强度适中）、保证睡眠（每晚七八个小时）、健康饮食（放弃高脂高糖高蛋白）、少食多餐（每天四五餐、每次七分饱）、多喝水（每天八杯水）\u003c/p>\u003cp>2、采用循环式作息计划，这样可以做到张弛有度：一周休息一天、晚上不干活、设定90分钟专注时间，集中精力完成某项任务。\u003c/p>\u003cp>另外，找到适合自己的生活作息，从吃喝、睡觉、工作等各方面掌握自己的最佳状态，比如每天哪个时间段运动，几点睡几点起，一天中哪个时间段自己效率最高、那就集中精力来完成重要任务，每天哪个时间需要提醒自己喝水等等。对自己越了解，越能顺势而为，工作效率会越高，更能事半功倍。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>在自己的工作、学习、生活中都可以使用，当经常感到自己很疲惫时，就需要回顾一下自己是不是能量储备不足了，是不是时间表排的太满超出自己的负荷了，或者看一下自己是不是没有合理安排自己的计划，没能集中精力办大事，造成重要工作时时像巨石一样压在肩头负重难行。\u003c/p>","interaction":"\u003cp>【A1】\u003cstrong>激活过去经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>1.请各位回想下自己最近的学习、工作状态，最近的身体状况是不是良好?你平时是怎样安排你的工作和学习的，尤其是在任务比较重、压力比较大的时候？\u003c/p>\u003cp>2.给大家1分钟的时间思考下，一会儿我们用1-2分钟的时间来分享下。\u003c/p>\u003cp>3.时间到，下面依次分享下自己或见过的经历，每位分享时间1-2分钟。（抽取线上1-2位伙伴，请大家主动发言）\u003c/p>\u003cp>\u003cstrong>学习者案例记录：现场记录——范范姐案例\u003c/strong>\u003c/p>\u003cp>最近工作很忙，白天晚上都需要上课，持续了将近10天，因为工作压缩了自己的学习时间，感觉身体很疲惫，状态很不好 ，工作疲于应付。\u003c/p>\u003cp>如果运用今天推荐的能量管理的方法，可以更好的有张有弛的安排自己的工作、生活和学习，同时也能让身体更舒服，把自己照顾的更好。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：现场记录——噜啦嘞案例\u003c/strong>\u003c/p>\u003cp>在最近的一个学习营中，能够很好的掌握自己的学习、工作、生活节奏，虽然学习压力很大，早上需要5点多就起床，仍然感觉自己每天都充满精力，状态很不错。\u003c/p>\u003cp>感觉自己是在这个学习营找到了适合自己的规律的作息，在有张有弛的安排自己，让自己每天除了工作外还有学习时间、锻炼时间，并且生活起居也更科学，每天都是满血状态。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>（规划未来应用）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>假如未来的三个月，你想要完成一个学习计划，你会怎样来安排你的时间和作息呢？请写出你具体的行动目标和行动步骤。大家可以参考下面的方式：\u003c/p>\u003cp>1.时间：2.地点：3.人物：4.内容：5.可衡量的结果：6.奖惩。\u003c/p>\u003cp>因为时间原因，在线上就不要求大家分享自己的目标和行动计划了，大家可以之后私聊发给我哦。\u003c/p>\u003cp>今天的分享到此结束，希望能量管理的拆页能给你的生活带来指导和帮助，也期待各位的作业哦，相信我们运用科学地方法去管理自己的生活，能达到事半功倍的效果！感谢大家的聆听和陪伴。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>时时记录——雅琪\u003c/p>\u003cp>【目标】用本方法，制定自己的时间表，安排好五月到八月的作息计划、成长目标\u003c/p>\u003cp>【行为】\u003c/p>\u003cp>1、罗列学习内容的目标，并根据强度、难度，将其分解到每天；\u003c/p>\u003cp>2、根据每天所需时长，合理安排时间，详细列出从早到晚，每项事务的时间表；\u003c/p>\u003cp>3、注意刻意留白，一周一到两天给自己放假；\u003c/p>\u003cp>4、找到黄金时间，就是自己效率最高的时候，完成每天的重点工作；\u003c/p>\u003cp>5、每日目标完成，在周末、月末给自己一个奖励，买衣服或休闲娱乐项目。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1621691071000,"updated_at":1621828443000,"ria":true},{"id":11243,"topic":"如何高效学习","learn_goal":"","remark":"如何应用费曼技巧学习陌生知识点","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"KK607","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>\u003cstrong>【技能点：学习目标】学习目标包含了学习者可被观察到／被测量到的行为或动作。\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者遇到陌生知识点时，能通过费曼学习法学习这个知识点。\u003c/p>\u003cp>\u003cstrong>【技能点：FAB图书介绍法】能够清晰辨别出F、A、B\u003c/strong>\u003c/p>\u003cp>大家好，我是今天的拆书家，天空。\u003c/p>\u003cp>\u003cstrong>F：\u003c/strong>这是一本介绍高效学习方法论的图书，作者斯科特杨，一位因为快速学习而成名的学霸，他应用自己发明的学习方法，完成了10天搞定线性代数。本书从一位“学习大师”的亲身体验出发，总结出“整体性学习”的策略及方法，同时，配合作者实际运用的各类学习工具，切实帮助读者逐步练就高效的“学习方法与学习习惯”\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>对比同类书籍，这本书强调的不是死记硬背，反复记忆知识点,而是整体性学习，用巧妙的方法让知识关联起来，从而形成自己的高效学习方法。\u003c/p>\u003cp>\u003cstrong>B1：这本书对于想摆脱离传统死记硬背机械学习方法，教你“一口吃成一个大胖子”方法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B2：\u003c/strong> 今天选取的拆页片段，在遇到我们必须掌握的知识点时，运用费曼学习技巧轻松快速掌握，从此很难遗忘学到的知识点。\u003c/p>\u003cp>\u003cstrong>R\u003c/strong>\u003c/p>\u003cp>\u003cstrong>目标：实用类图书、HOW片段（有明显的建议）；内容不超过2页纸，不能直接打印照片，需要编辑成文字档，在Word打印\u003c/strong>\u003c/p>\u003cp> \u003cstrong> 整体性学习技术的实际运用——费曼技巧\u003c/strong>\u003c/p>\u003cp>很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只需花上20分钟就能深入理解知识点，而且记忆深刻，难以遗忘。下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>第一步：选择要学习的概念首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp>第二步：设想你是老师，正在试图教会一名新生这个知识点这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清\u003c/p>\u003cp>第三步：当你感到疑惑时，返回去吧每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>第四步：简单化和比喻如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003c/p>\u003cp>例如：在学习力矩时，用简单的话解释力矩，而不是照抄书上的定义。比如，首先用俗语“扭曲”来说清楚力矩是什么意思。\u003c/p>\u003cp>其次，给力矩找个恰当的比喻，我把力矩向量比喻为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>\u003cp>I\u003c/p>\u003cp>3\u003c/p>\u003cp>\u003cstrong>【技能点：举例，预防性讲解】用自己的话重述了原文的知识点，清晰易懂。讲解中有举例子说明，有提到学习者可能产生异议，并给予了预防性讲解。\u003c/strong>\u003c/p>\u003cp>好的，我看到大部分小伙伴已经阅读完了。\u003c/p>\u003cp>（场景S）小伙伴们，我想问一下大家，在你学习、工作和生活中，有没有过这样的经历？\u003c/p>\u003cp>你学某种课程，有些概念或知识点，你已经反复看了很多遍了，但却还是不理解；反复背了很多次了，但就是记不住？\u003c/p>\u003cp>你需要开展某项工作，这个工作涉及很多专业知识，你发自已理解起来很费劲，感觉很难上手？\u003c/p>\u003cp>再有...\u003c/p>\u003cp>（冲突C）于是这个时候，你就会觉得，这个考试太难了，这个工作太难了，产生放弃的想法。\u003c/p>\u003cp>（问题Q）哪怎么办法呢？有没有解决的方法呢？\u003c/p>\u003cp>（解答A）有，就是我今天晚上要给大家推荐的重磅学习方法，号称是“史上最牛的学习方法”---费曼学习法。\u003c/p>\u003cp>哪什么是费曼学习法呢？用一句来概括的话，\u003cstrong>就是学任何东西，如果你能用简单的话，用自己的话，不带行话术语，说给八十岁的老太太听，说给八岁的小孩听。当这些人都听懂了，你就把这个概念或知识点搞明白了。\u003c/strong>\u003c/p>\u003cp>那“费曼学习法”如何做呢？具体分为四个步骤：\u003c/p>\u003cp>\u003cstrong>第一步：选择要学习的概念\u003c/strong>。\u003cstrong>把你想学习的难懂概念或知识点，写在一张白纸的顶部。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>第二步: 以教代学；想象成一个老师，正在向一个完全不懂的小白讲解这个概念。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步:碰到没理解地方，又是关键地方，重新学习；当你开始用自己的话语描述却遇到难题和不解的点，马上找原文，找权威专家的表述，直到你自己弄懂为止，把弄懂的知识点写下来。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>第四步：简化，并用“比喻”让概念变得更好理解。\u003c/strong>\u003c/p>\u003cp> 简化大家可能好理解一些，即是简洁，避免啰嗦；但如何理解这个“比喻”呢？\u003c/p>\u003cp>\u003cstrong>我给大家举一个例子\u003c/strong>： 有人问爱因斯坦什么是相对论。\u003c/p>\u003cp>爱因斯坦说：你和一个美女在一块，一小时像一分钟；和一个讨厌的人在一块，一分钟像一小时，这就是相对论。\u003c/p>\u003cp>\u003cstrong>&lt;举例&gt;\u003c/strong>\u003c/p>\u003cp>我给大家分享一个我失败的例子。我看罗胖2018跨年演讲，有一个名词“小趋势”，这是我从字面上看不到任何延伸信息的词，我是想知道罗胖说这个“小趋势”什么意思，能不能对我工作或者其他方面有什么帮助，后来我果然忘记了。直到现在还没有知道什么是“小趋势”，如果回到当时我会应用今天学到的方法，\u003c/p>\u003cp>第一，A4纸顶部写下“小趋势”。\u003c/p>\u003cp>第二，找个不知道“小趋势”的同事分享，小趋势不是大趋势的小时候，它本身也不能长成大趋势，它的威力是能启动连锁反应。下一个相对准确的定义是：\u003c/p>\u003cp>小趋势是影响趋势的趋势，带来改变的改变。\u003c/p>\u003cp>第三步，我了解了，等到真的不懂再来翻查资料，\u003c/p>\u003cp>第四步如果用比喻来形容，就像多米诺骨牌，只要一个小小的颤动，哪怕一个蚂蚁，一个极小的趋势推动一个大一点的趋势，再推动一个更大的趋势。\u003c/p>\u003cp>\u003cstrong>&lt;预防异议&gt;，\u003c/strong>\u003c/p>\u003cp>有些小伙伴会说，不对呀，我不用这个费曼学习法，我自己重复多遍了，我生活中应用的多了，我自己也能掌握啊，也可以消化啊，如果你有那么多时间去重复，有那么多机会去实践，而且不急于一会半刻，可以不这么做，这个方法是适用于你想快速掌握一个陌生的知识点，并且让自己不容易遗忘，那么这个方法很适合你.还有小伙伴会问第三步查资料能不能放第一步，第三步是让你在教授过程中遇到障碍回顾的作用，是必不可少的。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点：分步催化】提问中包含情境或场景，有学习者受启发联系到自已的具体应用场景\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&lt;分步催化&gt;\u003c/strong>\u003c/p>\u003cp>接下来未来一个月时间里，你看书的时候遇到陌生的知识点，工作场合遇到陌生专业术语，听一场讲座老师讲到某个没听过的名词等等，你准备怎么做？小伙伴可以拿个便签纸写下那个场景。\u003c/p>\u003cp>\u003cstrong>&lt;分组安排&gt;\u003c/strong>\u003c/p>\u003cp>我先来分一下组。请在小组内分享，二分钟后，我邀请一位伙伴上台分享一下。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者：DORIS\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我前阵子看了《刻意练习》这本书，遇到一个陌生词叫“心理表征”，我就想如何才能掌握这个词。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点：分步催化】分步催化中指令清晰，有学习者根据指令，规划出了以后可以如何做的具体计划。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&lt;分步催化&gt;\u003c/strong>\u003c/p>\u003cp>好，谢谢DORIS的分享。情景已经有了，现在请各位小伙伴在小组再讨论一下，如何再运用这个“费曼学习法”来做一下行动规划。请大家拿出便签纸，写下你的行动计划。第一：你打算在什么时候用上这个方法，第二：你的行动步骤是怎么样的？然后我再请一位小伙伴来分享一下。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp> 刚才DORIS提到的这个案例非常有价值，我看你这个小组也讨论的很热烈，哪再你来分享一下你的行动计划好吗？\u003c/p>\u003cp>\u003cstrong>分享者：DORIS\u003c/strong>\u003c/p>\u003cp>我计划下次这么来实施这个“费曼学习法”：\u003c/p>\u003cp>第一步：写下“心理表征”\u003c/p>\u003cp>第二步假设自己是个老师，讲给别人听\u003c/p>\u003cp>第三步：上网查一下大家理解的“心理表征”\u003c/p>\u003cp>第四： 用简化的语言讲出来，打个比喻，“心理表征”就像你打字，别人问你“A在哪里？B在哪里”，你不清楚。但是你把手放在键盘上，你自然而然就知道A在哪里，这就是“心理表征”。\u003c/p>\u003cp>好，非常感谢DORIS的分享。\u003c/p>\u003cp>一句话总结\u003c/p>\u003cp>“费曼学习法”是一个高效学习方法，这个方法最重要的关键点是通过教授别人，越贴切的比喻，掌握概率就越大。希望我的享对大家有所帮助。我的分享到这里，谢谢大家。\u003c/p>","ratings_count":1,"texts":[{"id":15158,"quote":"\u003cp>整体性学习技术的实际运用——费曼技巧\u003c/p>\u003cp>很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只需花上20分钟就能深入理解知识点，而且记忆深刻，难以遗忘。下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>第一步：选择要学习的概念首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp>第二步：设想你是老师，正在试图教会一名新生这个知识点这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清\u003c/p>\u003cp>第三步：当你感到疑惑时，返回去吧每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>第四步：简单化和比喻如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003c/p>\u003cp>例如：在学习力矩时，用简单的话解释力矩，而不是照抄书上的定义。比如，首先用俗语“扭曲”来说清楚力矩是什么意思。\u003c/p>\u003cp>其次，给力矩找个恰当的比喻，我把力矩向量比喻为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴已经阅读完了。\u003c/p>\u003cp>（场景S）小伙伴们，我想问一下大家，在你学习、工作和生活中，有没有过这样的经历？\u003c/p>\u003cp>你学习某个课程时，有些知识点，你已经反复看了很多遍了，但却还是不理解；反复背了很多次了，但就是记不住？\u003c/p>\u003cp>你需要开展某项工作，这个工作涉及很多专业知识，你发自已理解起来很费劲，感觉很难上手？\u003c/p>\u003cp>再有...\u003c/p>\u003cp>（冲突C）于是这个时候，你就会觉得，这个考试太难了，这个工作太难了，产生放弃的想法。\u003c/p>\u003cp>（问题Q）哪怎么办法呢？有没有解决的方法呢？\u003c/p>\u003cp>（解答A）有，就是我今天晚上要给大家推荐的重磅学习方法，号称是“史上最牛的学习方法”---费曼学习法。\u003c/p>\u003cp>哪什么是费曼学习法呢？用一句来概括的话，\u003cstrong>就是学任何东西，如果你能用简单的话，用自己的话，不带行话术语，说给八十岁的老太太听，说给八岁的小孩听。当这些人都听懂了，你就把这个概念或知识点搞明白了。\u003c/strong>\u003c/p>\u003cp>那“费曼学习法”如何做呢？具体分为四个步骤：\u003c/p>\u003cp>\u003cstrong> \u003c/strong>\u003cstrong> 第一步：选择要学习的概念\u003c/strong>。\u003cstrong>把你想学习的难懂概念或知识点，写在一张白纸的顶部。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>第二步: 以教代学；想象成一个老师，正在向一个完全不懂的小白讲解这个概念。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 第三步:碰到没理解地方，又是关键地方，重新学习；当你开始用自己的话语描述却遇到难题和不解的点，马上找原文，找权威专家的表述，直到你自己弄懂为止，把弄懂的知识点写下来。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>第四步：简化，并用“比喻”让概念变得更好理解。\u003c/strong>\u003c/p>\u003cp>简化大家可能好理解一些，即是简洁，避免啰嗦；但如何理解这个“比喻”呢？\u003c/p>\u003cp>\u003cstrong>我给大家举一个例子\u003c/strong>： 有人问爱因斯坦什么是相对论。\u003c/p>\u003cp>爱因斯坦说：你和一个美女在一块，一小时像一分钟；和一个讨厌的人在一块，一分钟像一小时，这就是相对论。\u003c/p>\u003cp>\u003cstrong>&lt;举例&gt;\u003c/strong>\u003c/p>\u003cp>我给大家分享一个我失败的例子。我看罗胖2018跨年演讲，有一个名词“小趋势”，这是我从字面上看不到任何延伸信息的词，我是想知道罗胖说这个“小趋势”什么意思，能不能对我工作或者其他方面有什么帮助，后来我果然忘记了。直到现在还没有知道什么是“小趋势”，如果回到当时我会应用今天学到的方法，\u003c/p>\u003cp>第一，A4纸顶部写下“小趋势”。\u003c/p>\u003cp>第二，找个不知道“小趋势”的同事分享，小趋势不是大趋势的小时候，它本身也不能长成大趋势，它的威力是能启动连锁反应。下一个相对准确的定义是：\u003c/p>\u003cp>小趋势是影响趋势的趋势，带来改变的改变。\u003c/p>\u003cp>第三步，我了解了，等到真的不懂再来翻查资料，\u003c/p>\u003cp>第四步如果用比喻来形容，就像多米诺骨牌，只要一个小小的颤动，哪怕一个蚂蚁，一个极小的趋势推动一个大一点的趋势，再推动一个更大的趋势。\u003c/p>\u003cp>\u003cstrong>&lt;预防异议&gt;，\u003c/strong>\u003c/p>\u003cp>有些小伙伴会说，不对呀，我不用这个费曼学习法，我自己重复多遍了，我生活中应用的多了，我自己也能掌握啊，也可以消化啊，如果你有那么多时间去重复，有那么多机会去实践，而且不急于一会半刻，可以不这么做，这个方法是适用于你想快速掌握一个陌生的知识点，并且让自己不容易遗忘，那么这个方法很适合你.还有小伙伴会问第三步查资料能不能放第一步，第三步是让你在教授过程中遇到障碍回顾的作用，是必不可少的。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;分步催化&gt;\u003c/strong>\u003c/p>\u003cp>接下来未来一个月时间里，你看书的时候遇到陌生的知识点，工作场合遇到陌生专业术语，听一场讲座老师讲到某个没听过的名词等等，你准备怎么做？小伙伴可以拿个便签纸写下那个场景。\u003c/p>\u003cp>\u003cstrong>&lt;分组安排&gt;\u003c/strong>\u003c/p>\u003cp>我先来分一下组。请在小组内分享，二分钟后，我邀请一位伙伴上台分享一下。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者：DORIS\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我前阵子看了《刻意练习》这本书，遇到一个陌生词叫“心理表征”，我就想如何才能掌握这个词。\u003c/strong>\u003c/p>\u003cp> \u003cstrong>&lt;分步催化&gt;\u003c/strong>\u003c/p>\u003cp>好，谢谢DORIS的分享。情景已经有了，现在请各位小伙伴在小组再讨论一下，如何再运用这个“费曼学习法”来做一下行动规划。请大家拿出便签纸，写下你的行动计划。第一：你打算在什么时候用上这个方法，第二：你的行动步骤是怎么样的？然后我再请一位小伙伴来分享一下。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp> 刚才DORIS提到的这个案例非常有价值，我看你这个小组也讨论的很热烈，哪再你来分享一下你的行动计划好吗？\u003c/p>\u003cp>\u003cstrong>分享者：DORIS\u003c/strong>\u003c/p>\u003cp>我计划下次这么来实施这个“费曼学习法”：\u003c/p>\u003cp>第一步：写下“心理表征”\u003c/p>\u003cp>第二步假设自己是个老师，讲给别人听\u003c/p>\u003cp>第三步：上网查一下大家理解的“心理表征”\u003c/p>\u003cp>第四： 用简化的语言讲出来，打个比喻，“心理表征”就像你打字，别人问你“A在哪里？B在哪里”，你不清楚。但是你把手放在键盘上，你自然而然就知道A在哪里，这就是“心理表征”。\u003c/p>\u003cp>好，非常感谢DORIS的分享。\u003c/p>\u003cp> “费曼学习法”是一个高效学习方法，这个方法最重要的关键点是通过教授别人，越贴切的比喻，掌握概率就越大。希望我的享对大家有所帮助。我的分享到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1616753304000,"updated_at":1617000753000,"ria":true},{"id":11237,"topic":"如何让你的笔记变有趣","learn_goal":"","remark":"过级活动","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"罗巧琴","city":"东莞市"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>\u003cstrong>技能点：设定目标，包含可以被观测到/被测量到的行为或动作。\u003c/strong>\u003c/p>\u003cp>本次学习目标，在完成这次RIA现场学习后，学习者能在简化笔记记录时，不是以全文字内容，而是用重点+联系的图文组合法输出笔记。\u003c/p>\u003cp>大家好！我是拆书家龙珠，以下用三个标签介绍我自己：一枚酷爱学习的终身学习者、一对双胞胎的妈妈、一个有近20年理财经验的金融人。为便于一会的讨论和练习，我们先来分一下组，三人为一组，共分为三组。\u003c/p>\u003cp>在开始之前，我想让大家先来看看这些图片：\u003c/p>\u003cp>\u003cbr>大家觉得这样的学习笔记怎么样？喜欢看吗？会愿意分享吗？这样的笔记除了漂亮，更多吸引我们的，是一下子就能看到内容的重点。\u003c/p>\u003cp>\u003cstrong>技能点：FAB法介绍图书（F特征，A优势，B利益）\u003c/strong>\u003c/p>\u003cp>【图书介绍】（2分钟）\u003c/p>\u003cp>\u003cstrong>F（特征，核心是书）:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天我们学习的这本书\u003cu>《如何高效学习》，\u003c/u>它非常畅销，出版后的6年间，被重印20多次。\u003cu>作者斯科特•扬\u003c/u>（Scott Young），\u003cu>用1年时间修完麻省理工33门课+4门外语\u003c/u>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A（优势，重点是比较）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cu>对比同类书籍，这本书强调的不是死记硬背，反复记忆知识点,而是整体性学习，用巧妙的方法让知识关联起来，从而形成自己的高效学习方法。\u003c/u>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B（利益，强调的是学习者收获）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1本书益处：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>全书围绕整体性学习策略，为读者提供一个如何学得更好的模型，通过对照策略，你能找出学习上的缺陷，修正学习方法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B2片段益处：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>通过今天学习的两个片段，“笔记流三步法”能帮助你简化信息，提高即时思考能力和笔记速度，结合“图文四步法”，进一步增强你的理解能力，更形象的表达你的思考结果。\u003c/strong>\u003c/p>","ratings_count":2,"texts":[{"id":15150,"quote":"\u003cp>\u003cstrong>学习目标1：当需要快速记录时，从全部用文字做笔记转换为使用关键词和箭头，简化信息。\u003c/strong>\u003c/p>\u003cp>下面请大家花1分钟时间阅读第一个原文片段笔记流\u003c/p>\u003cp>\u003cstrong>【R】阅读原文拆页（1分钟）\u003c/strong>\u003c/p>\u003cp>片段一《如何高效学习》P77\u003c/p>\u003cp>我在课堂上曾经使用一种记笔记的方法，对信息量较大的课程效果不错，我把这种记笔记的方法称为笔记流技术。笔记流技术的目标是提供一个平台以联系学到的东西。大多数人采用的画线、画圈等传统记笔记的方式被很多“流”（虽然有些杂乱）替代。\u003c/p>\u003cp>使用笔记流时，首先写下最主要的观点，尽量用很短的单词来替换完整的句子，这可能会降低可读性，但是提高了上课时的学习效率。事实、日期、细节和描写要尽量减少单词量，不要写冗长的段落。\u003c/p>\u003cp>一旦你写下了一个观点，下一步就是在这个观点和其他观点之间画上一些箭头，观点不是建立成金字塔式的结构，而是呈现出相互关联的关系，这个过程与实际的整体性学习策略类似，观点连在一张网中。\u003c/p>","explains":"\u003cp>\u003cstrong>片段一\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>（5分钟）\u003c/p>\u003cp>好，我看到大家都看完了。\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>\u003c/p>\u003cp>原文告诉我们，用记下主要观点和画线将观点挂钩的方法，能帮我们快速记录，方便回顾。\u003c/p>\u003cp>\u003cstrong>why：\u003c/strong>\u003c/p>\u003cp>传统的笔记形式耗时费力，不仅没有减轻学习压力，反而增加阅读量，经常记了也很少回头看，即便回头看，也难以快速找到知识重点。笔记流的方式看起来简单、易记，在帮助理解学习内容上效果比大段的文字更有效率，真正的让笔记从厚变薄。\u003c/p>\u003cp>\u003cstrong>技能点：意译原文案例、细化行动步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003c/p>\u003cp>那具体怎么做呢？以下是笔记流三步法\u003c/p>\u003cp>\u003cstrong>\u003cu>1.抓重点\u003c/u>\u003c/strong>\u003c/p>\u003cp>记笔记的时候只记下主要的观点\u003c/p>\u003cp>\u003cstrong>\u003cu>2.词代句\u003c/u>\u003c/strong>\u003c/p>\u003cp>用简短的词组代替完整的句子\u003c/p>\u003cp>\u003cstrong>\u003cu>3.点线连\u003c/u>\u003c/strong>\u003c/p>\u003cp>在主要词组之间加上箭头，用箭头表示观点之间的挂钩关系。\u003c/p>\u003cp>刚才从原文中大家可以看到一幅英文的笔记图，那是作者的笔记流示例图。\u003c/p>\u003cp>下面，请大家看看这个图，有觉得熟面的吗？有一下子就记起来的吗？\u003c/p>\u003cp>对的，这是泉水老师在全国共拆《底气》时侯，张华做的笔记，这张图可以说很好的示范了笔记流的三个步骤：\u003c/p>\u003cp> \u003cstrong>只记下主要观点、用短句代替完整的句子、再加上箭头联系。\u003c/strong>\u003c/p>\u003cp>这张图能让来过或是没来的人很容易看到那次共拆《底气》的主要内容。\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>：\u003c/p>\u003cp>当然，如果你没有做笔记的习惯，或对笔记术没兴趣的，这方法或许对你并不管用，它更适用于喜欢记笔记，希望提高笔记效率的人。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（技能点：\u003c/strong> \u003cstrong>显像提问）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>接下来，我想请大家坐上时光机，去回想一下，你有没试过记了笔记又没回看的经历？\u003c/p>\u003cp>比如，你去上某位老师的课，认认真真的记了一大堆的笔记，回看时发现还得重新整理出重点，想想又放下了…；\u003c/p>\u003cp>又比如，你看到书中某段内容特别的好，摘抄了，想着方便以后看，可然后就没有然后了…；\u003c/p>\u003cp>又比如，单位组织培训了几天，笔记记了一大本，可它跟你回单位后，你就没搭理过它了…等等\u003c/p>\u003cp>请你回想一下，遇到类似的经历，你当时是怎么记笔记的？记的笔记是打算作何用的？结果怎样？\u003c/p>\u003cp>请把你回想到的场景，比如时间、地点、事件，最好把当时的感受也写在便签纸上，在小组里分享一下，限时1分钟。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>刘婷：上周六上的时间管理课，课堂提供了以左右分的课程内容与笔记区域的课件，老师在课上讲了很多金句，我希望把那些金句都记下来。两天下来，回顾时发现笔记都是只记录了一句话，没有信息背景，有点回想不起来，而当时想着还挺累的，笔记以后再整理吧，可然后就真的没有然后啦。\u003c/p>\u003cp>感谢小伙伴的分享。\u003c/p>\u003cp>\u003cstrong>【A1+】（反思加工）（3分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（技能点：请学习者反思加工经验）\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>好，现时光穿梭把你送回当时的场境，你会如何运用今天学习的笔记流三步法呢？\u003c/p>\u003cp>请大家在小组里分享你的应用步骤并讨论优化，限时2分钟。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>张华：疫情期间，参加孩子的家长会，当时记了很多的内容，想着回来向老公转述，但由于没有记清重点，结果转述时有些说不清了。如果应用今天学的笔记流三步法，我会先记下家长会老师说的主要观点，然后关于老师分享的在疫情期间如何调整心态的好几个案例，我会用短句代替大段的案例内容，然后把记录的内容与家长会老师说的顺序和逻辑结合进行连线。\u003c/p>\u003cp>\u003cstrong>回应：\u003c/strong>好，谢谢张华的分享，张华刚才的分享把笔记流的三步很清晰的展示出来了。\u003c/p>\u003cp>\u003cstrong>过渡页：\u003c/strong>\u003c/p>\u003cp>笔记是帮助我们回顾学习的工具，人的惯性思维是取易避难，看着越简单越能快速读取的东西引起我们的兴趣就越大，除了笔记流以外，大家觉得，增加什么能让你的笔记更能引起兴趣呢？\u003c/p>\u003cp>其实笔记流的运用，减少笔记内容可能会牺牲一些可读性，但通过箭头增加各种联系，再结合画图，可以让学习回顾变得更有趣更具整体性。\u003c/p>\u003cp>下面，我们来看看，图文组合是怎么做的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":15151,"quote":"\u003cp>\u003cstrong>学习目标2：当需要精练表达时，从单一的观点罗列转为用图文结合的方式输出信息，迅速传达要点。\u003c/strong>\u003c/p>\u003cp>请大家花1分钟时间阅读第二个片段概念图\u003c/p>\u003cp>\u003cstrong>【R】阅读原文拆页（1分钟）\u003c/strong>\u003c/p>\u003cp>片段二《如何高效学习》P100\u003c/p>\u003cp>概念图将观点联系在一起，与笔记流密切相关。概念图里的关系并不是某个顺序中的不同步骤或是按日期顺序排列的观点，而是观点之间的内在关系。在不同观点之间画上箭头，箭头上还需要加上一些简单的话语，说明二者是什么样的关系。\u003c/p>\u003cp>假如我想画出不同财务会计原理的简图，首先我要写下四个基本的清单：资产负债表、收入、留存收益以及现金流，然后我可以在它们之间建立各种联系，最后形成知识网。\u003c/p>\u003cp>假如我想画出小说中的角色关系，我会先把主角放在图的中间，然后其他人物以他为中心按照与主角的关系分别画在旁边。这种方法有助于我们理顺思路，将庞大的知识组织得条理分明。\u003c/p>\u003cp>从最重要的观点出发，不断发出分支细化知识及分解观点\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导（10分钟）\u003c/strong>\u003c/p>\u003cp>好，我看到大家已经读完了。\u003c/p>\u003cp>平常大家阅读一页材料并达到90%的理解，需要花费多长时间呢？刚才我们花了1分钟的时间阅读，能理解这段内容的90%吗？\u003c/p>\u003cp>假如把刚才的片段画成这么一幅图，大家觉得阅读上有什么变化吗？\u003c/p>\u003cp>（why）每个人处理各种形式的信息的能力或高或低（阅读或听讲都可以获取信息，但是信息的形式不同），这直接造成学习能力的高低。在信息获取阶段，我们的主要目标是简化，另外是能获取的信息量和接收的速度。\u003c/p>\u003cp>（what）原文说要在不同观点之间画箭头，那首先我们要提取出观点，观点间用箭头说明关系，用画图的方式能把主要观点关系理清，让我们的思路理顺，从而形成知识网。图文组合的方式方便理解，易于记忆和传递，在锻炼我们的思维方式的同时，真正发挥了笔记的作用。\u003c/p>\u003cp>\u003cstrong>技能点：细化步骤\u003c/strong>\u003c/p>\u003cp>（how）那具体怎么做呢？以下是图文组合四步法\u003c/p>\u003cp>\u003cstrong>\u003cu>1、提取 \u003c/u>\u003c/strong> \u003c/p>\u003cp>归纳总结，提取主要信息，比如找出关键词、转折词、重要概念等。\u003c/p>\u003cp>\u003cstrong>\u003cu>2、连线\u003c/u>\u003c/strong>\u003c/p>\u003cp>在主要信息间连线说明关系。\u003c/p>\u003cp>\u003cstrong>\u003cu>3、细化\u003c/u>\u003c/strong>\u003c/p>\u003cp>从主到次，在已有的连线上细化知识或分解重点，添加绘文字等，调整表达形式，形成关系网或结构图。\u003c/p>\u003cp>\u003cstrong>\u003cu>4、检查 \u003c/u>\u003c/strong>\u003c/p>\u003cp>检查信息是否已全部连线，再看一遍原文，确认关系是否正确，比如是否符合逻辑关系。\u003c/p>\u003cp>它可以结合笔记流来使用也可以单独使用。\u003c/p>\u003cp>下面我们来看个例子\u003c/p>\u003cp>电影《赤壁》大家看过吧，回顾内容它的主要人物关系大概是这样：\u003c/p>\u003cp>《赤壁》以《三国演义》为蓝本，讲述的是曹操的军队、孙权的军队、刘备的军队这三股势力的斗争。\u003c/p>\u003cp>曹操想要夺取天下，主动向孙权军队、刘备军队发起攻击。\u003c/p>\u003cp>孙权继承兄位统帅军队，刘备信仰仁爱第一，但不善作战。\u003c/p>\u003cp>孙权军队与刘备军队结成同盟，共同对抗曹操军队。\u003c/p>\u003cp>首先，从这段人物关系中提取关键人物\u003c/p>\u003cp>然后根据它们的关系进行连线，比如下图。\u003c/p>\u003cp>第3是细化，根据内容补充细节，比如曹军想夺取天下、孙权继承了兄位等。\u003c/p>\u003cp>最后再检查它们之间的关系，为了清晰好看我加上了方框，最后形成如下图。\u003c/p>\u003cp>\u003cstrong>技能点：预防疑义\u003c/strong>\u003c/p>\u003cp>有木有小伙伴觉得第1步提取，实施起来比较难，不知道怎么提取的？\u003c/p>\u003cp>提取是笔记的第1步，也是关键的一步，前面提到，我们可以找出关键词、转折词、重要概念等等，这对于文字版的阅读实施起来并不困难，而听课的时候可能会难些，那么这时我们可以回归本源，从提问着手，比如你希望从课中获得什么？与它相关的信息就是你要提取的，如果你觉得不需要掌握的信息，就大胆地跳过它。\u003c/p>\u003cp>\u003cstrong>技能点：不这么做的坏处\u003c/strong>\u003c/p>\u003cp>在传统的笔记里，我们习惯了一行一行地把文字记录下来，然后又一行一行地去看，关键词被埋在一大堆词汇中，这种标准的线性表达阻碍大脑作出联想，没法有效刺激大脑，更不利于记忆。所以很多人在记完笔记之后，是没有再翻阅的欲望的，因为觉得很麻烦不方便。这样，笔记最终变成了摆设，和一次性东西无异。\u003c/p>\u003cp>\u003cstrong>技能点：这么做的好处\u003c/strong>\u003c/p>\u003cp>画图能帮助你在阅读时提取关键思想，把你的理解变成图形，在事后容易展开，而且能够被立即用在PPT或报告资料里。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3 】促动参与（10分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点：促动学习者现场演练—场景设计、小组讨论、角色扮演\u003c/strong>\u003c/p>\u003cp>好啦！为了你能实操起来，现在需要大家一起来做一下笔记输出的演练。\u003c/p>\u003cp>\u003cstrong>（场景设计）\u003c/strong>\u003c/p>\u003cp>请大家仔细听好下面的内容：\u003c/p>\u003cp>你是财务部员工，财务部今年工作目标的达成进度情况如下：\u003c/p>\u003cp>\u003cstrong>财务部今年工作目标的达成进度：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“今年的销售目标是30亿，利润目标是3亿。现在一年时间正好过半，销售额为12亿，利润是1亿，完成了当期目标的80％。从销售构成来看，委托开发为3亿，会计软件是4亿，技术派遣为5亿，主力的会计软件业务比目标低3亿，正如大家听到的那样，这个业务有必要尽快做出调整。作为支持销售的政策，我们正在推进和X销售公司的合作计划。X销售公司有非常强大的法人销售渠道，目前正在寻找类似我们的会计软件业务的产品。另外，X销售公司能够将总代理点的广告管理软件介绍给我们的现有客户。这次的商业合作目的是利用对方的销售渠道交叉销售双方的产品。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（小组讨论）\u003c/strong>\u003c/p>\u003cp>好，现在请各小组进行讨论，应用今天学习的图文组合四步法，让财务部年度目标进度情况更容易看，并将笔记写在A4纸上，选出一个代表待会来展示你们的成果，说出你们是怎么用图文组合四步法一步一步做成的。\u003c/p>\u003cp>10分钟后，我会请一组小伙伴为我们展示。\u003c/p>\u003cp>\u003cstrong>留意现场学习情况，过程提示（5-7分钟后）：\u003c/strong>大家有困难不？我这给大家一个图参考一下\u003c/p>\u003cp>\u003cstrong>（讨论方案展示）\u003c/strong>\u003c/p>\u003cp>好，时间到，下面我们请一组小伙伴上来给大家展示。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp> 第二组派出嘉荣来展示\u003c/p>\u003cp>首先我们组以解决半年时间没达到销售目标的点，画出公司的销售与利润数据，数据组成与及其中没达到销售的缺口，是会计软件销量少了3亿嘛，而解决来源可以是与X销售公司进行交叉销售产品，向X销售公司的客户销售。\u003c/p>\u003cp>再对以上内容的关系进行划线说明。\u003c/p>\u003cp>\u003cstrong>技能点：回应与反馈\u003c/strong>\u003c/p>\u003cp>大家刚才的成果非常精彩，很高兴能看到大家积极投入到练习中，顺利地把一段内容以图文组合四步法展示出来。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>（12分钟）\u003c/p>\u003cp>\u003cstrong>分步催化一 技能点：分步催化 激活应用场景\u003c/strong>\u003c/p>\u003cp>但我们并不止步于此，学习的关键是更多的应用到日常生活中，下面请大家再想想，未来的一周或一个月，还可能会出现哪些场景，让你可以用图文四步法的呢？\u003c/p>\u003cp>比如你在阅读书桌上放着的那本书；\u003c/p>\u003cp>比如你在公开课上的行动学习；\u003c/p>\u003cp>比如你在回顾泉水老师的销售大课；\u003c/p>\u003cp>比如你在参加业务培训；\u003c/p>\u003cp>比如你与部门人员的项目讨论会议上；\u003c/p>\u003cp>比如你要向客户介绍公司零售业务的运营模式；\u003c/p>\u003cp>又比如你某天打开电脑，看着满桌面的文件想归类整理时等等。\u003c/p>\u003cp>请大家花1分钟时间，把想到的场景写在便签上。\u003c/p>\u003cp>好，下面我们请一位小伙伴来分享一下\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>1、小华：下次的全国共拆可以用四步法来做知识地图\u003c/p>\u003cp>2、瑞云：工作盘点\u003c/p>\u003cp>\u003cstrong>分步催化二 技能点：分步催化 规划行动步骤\u003c/strong>\u003c/p>\u003cp>大家都有自己将要应用的场景了，现在请大家回顾今天学习的图文组合四步法，写下步骤。\u003c/p>\u003cp>改变已有习惯并不容易，所以，请同步规划你的练习计划，并把你怎么做的写到我给大家准备好的便签纸上，写完后在小组里分享并讨论优化行动步骤。\u003c/p>\u003cp>限时3分钟，时间到后，我会请一位小伙伴来给我们分享。\u003c/p>\u003cp>好，下面我们请小伙伴来分享一下\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>小华：下周的全国共拆，我想把每一节的关键点提取出来，梳理节点的关系然后连线，我在试讲的时侯再看看有什么需要补充的，最后检查这些逻辑线到底是对不对的。\u003c/p>\u003cp>\u003cstrong>结束语\u003c/strong>（0.5分钟）\u003c/p>\u003cp>\u003cstrong>（技能点：强有力的结语）\u003c/strong>\u003c/p>\u003cp>好的笔记法是一生受用的技能，用笔记流与图文结合的方法形成化繁为简的思考习惯，相信一定可以使你的笔记更有趣有用。\u003c/p>\u003cp> 我今天的分享到此结束，感谢大家的参与，感谢每一位小伙伴刚才的回应与反馈。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1616655039000,"updated_at":1619492938000,"ria":true},{"id":10628,"topic":"如何应用费曼技巧高效学习","learn_goal":"","remark":"过级活动","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"罗巧琴","city":"东莞市"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>大家好！我是拆书家龙珠，以下用三个标签简单介绍一下我自己：一枚酷爱学习的终身学习者、一对双胞胎的妈妈、一个有接近20年理财经验的金融人。为方便一会的学习和讨论，我们先来分组，以桌为组，共分为2组。\u003c/p>\u003cp>我今天分享的主题：如何运用费曼技巧提高学习效果，它来自于书本《如何高效学习》。\u003c/p>\u003cp>\u003cstrong>F（特征，核心是书）:\u003c/strong>\u003c/p>\u003cp>这本书非常畅销，在它出版后的6年间，被重印了20多次。作者斯科特•扬（Scott Young），用1年时间修完麻省理工33门课、同步还拿下了4门外语。这本书就是对他学习方法的全面介绍，通过这些方法，让你也能掌握高效学习的技能，成为超级学霸。\u003c/p>\u003cp>\u003cstrong>A（优势，重点是比较）：\u003c/strong>\u003c/p>\u003cp>对比同类书籍，这本书强调的不是死记硬背，反复记忆知识点,而是整体性学习，用巧妙的方法让知识关联起来，从而形成自己的高效学习方法。\u003c/p>\u003cp>\u003cstrong>B（利益，强调的是学习者收获）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1本书益处：\u003c/strong>\u003c/p>\u003cp>全书围绕整体性学习策略，通过对照策略，你能找出学习上的缺陷，改善学习方法。\u003c/p>\u003cp>\u003cstrong>B2这个片段益处：\u003c/strong>\u003c/p>\u003cp>今天学习的片段“费曼技巧”选自书本P134，通过今天的学习，你将学会一项 “过目不忘”的技能，在学习时能记住那些容易遗忘的知识，能用自己的话把它讲明白，从而达到真正掌握所学知识的目的。 \u003c/p>","ratings_count":2,"texts":[{"id":14490,"quote":"\u003cp>下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>第一步:选择要学习的概念\u003c/p>\u003cp>首先选好你打算深入理解的概念,拿一张空白纸,在最上方写下概念的名称。\u003c/p>\u003cp>第二步:设想你是老师,正在试图教会一名新生这个知识点\u003c/p>\u003cp>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂,并把你的解释记录下来。这一步至关重要,因为在自我解释那些你理解或不理解的知识过程中,你会理解得更好,而原先不明白的地方也得以理清。\u003c/p>\u003cp>第三步:当你感到疑惑时,返回去吧\u003c/p>\u003cp>每当你碰到难题感到疑惑时,别急着往下走,学习不是单行道,回过头来,重新阅读参考材料、听讲座或找老师解答,直到你觉得搞懂了为止,然后把解释记到纸上。\u003c/p>\u003cp>第四步:简单化和比喻\u003c/p>\u003cp>如果你的解释很啰唆或者艰涩,尽量用简单直白的语言重新表述它,或者找到一个恰当的比喻以来更好地理解它。例如:在学习力矩时,用简单的话解释力矩,而不是照抄书上的定义。比如,首先用俗语“扭曲”来说清楚力矩是什么意思。其次，给力矩找个恰当的比喻，我把力矩向量比喻为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>","explains":"\u003cp>【逐字稿】\u003c/p>\u003cp>好了，我看大多数小伙伴都阅读完了。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这片段告诉我们一个提升学习效果的方法“费曼技巧”，通过它能理清对知识点的疑惑，解决一些学得浅、记不牢的问题。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>不知道大家有没过这样的经历，有时候对于某些知识点，读一遍不明白，读两遍也不完全明白，这时候如果我们使用“费曼技巧”的方法，可以帮助我们在短时间内更深入的去理解它。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那具体怎么做呢？以下是“费曼四步法”：\u003c/p>\u003cp>\u003cstrong>第一步“动动手”\u003c/strong>，把你要记住或存在疑惑的知识点写下来。\u003c/p>\u003cp>\u003cstrong>第二步“动动口”\u003c/strong>，对着镜子或听众来讲解，通过自己的语言表达来加深对知识的理解，过程中把思路和难点都记下来。\u003c/p>\u003cp>\u003cstrong>第三步“动动脑”\u003c/strong>，当出现讲不下去时，先停下，重新查找参考资料或向他人咨询，直到弄懂为止。记下解决过程。\u003c/p>\u003cp>\u003cstrong>第四步“不复杂”\u003c/strong>，删除不必要信息，用简洁的语言来总结；不用专业术语，用形象的比喻，比如“构建知识体系”，形象的比喻我会用像是搭建乐高模型的过程。\u003c/p>\u003cp> 【预防异议】\u003c/p>\u003cp>听完后，也许有些小伙伴会觉得第二步“动动口”没必要，我不做也能理解这个知识。你有过这样的经历吗？有时候你看的和理解的以为是一致的，但最后表达出来的却并非原来理解的。当你真的去讲时，会发现从看到这些内容到理解，再到跟他人讲解的过程，事实是一个对自己思路整理、检查和确认的过程。\u003c/p>\u003cp>【这样做的好处】\u003c/p>\u003cp>如果你能这么做，不但大脑会因为经常加工整理信息，转速变快、表达更流畅；而且在加工过程中可能会挖掘到一些之前忽略的信息，对知识理解更为全面、透彻了。\u003c/p>\u003cp>【不这样做的坏处】\u003c/p>\u003cp>如果你不这么做，可能你会一直停在“我看过了就以为自己理解了，我听明白了就以为自己懂了”，当需要用到时，却发现自己对知识的记忆比较模糊，也没法向别人讲明白。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>因此，当你是以记忆或深入学习知识点为目的时，便可应用“费曼四步法”。\u003c/p>\u003cp>【A1】\u003c/p>\u003cp>我想跟大家分享一个例子！去年我在广州参加一个单位的业务培训，老师课上讲了很多业务开拓的技巧，其中提到一个叫“一户6开”的知识点，第二周回单位，我跟同事分享这次培训，当分享到“一户6开”时，有同事问起“是哪6开啊？为什么是6开呢？”记得在老师讲课时，顺着老师思路，不止6开啊，我还能想到9开的，可同事问的时候我却怎么也想不全，好尴尬。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>结合今天所学，我发现凑巧用了不完整的“费曼四步法”，完整的可以这么做：\u003c/p>\u003cp>1. 在培训学习的当天，写下“一户6开”。\u003c/p>\u003cp>2. 晚上回去跟我的同房讨论如何营销“一户6开”，顺便把我想到的9开也一并说说。\u003c/p>\u003cp>3. 假如讲的时候有不记得的，回看笔记或问老师，比如问清楚为什么要做这6开呢？它的好处在哪里？\u003c/p>\u003cp>4. 用大白话简单总结，和找个形象比喻，好理解的同时好记住。比如先说“一户6开”或9开有哪些（手银、网银、公众号绑定、灵活息、风评、第三方存管、第三方支付、信用卡、信用卡自扣），再找个比喻说明这么做的好处，我想到用京东APP作比喻，京东APP为客户提供除了京东超市、唯品会、沃尔玛，开通会员还能看电影等等功能，目的除了消费你，也是为了增加客户粘性，不让你轻易的把它卸掉，这跟银行“一户6开”是同类似的。\u003c/p>","interaction":"\u003cp>【拆书家提问设计】\u003c/p>\u003cp>好了，我的故事分享完了，经过刚才的学习，相信你已知道如何运用“费曼四步法”了，现在我想请你想一下，在未来一周，你可能会遇到哪些情景可以使用“费曼四步法”的呢？比如：你在单位学习了一个新的产品，要转培训时；或者你想跨行转业，了解到一些行业知识，你要掌握它时；又或在复习以前学过但不熟悉的学习方法时…。\u003c/p>\u003cp>注意啦，是想一个适用场景和要学习的知识点，场景和知识点，只要场景和知识点，然后把它写下来。时间1分种，待会我邀请2位小伙伴来分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>学习者春霞分享：适用的场景挺多的，比如我下周的备课，讲解一些概念\u003c/p>\u003cp>学习者周琴分享：适用场景是下周的3-1的准备，还有下周公司年会要用到的PPT准备\u003c/p>\u003cp> 【拆书家提问设计】\u003cbr> 感谢两位小伙伴的分享。现在大家都有一个需要深入学习的场景和内容啦。那么，请你使用今天所学的“费曼四步法”制定一个详细的学习计划，然后在小组里讨论分享，时间4分钟，一会我邀请1位小伙伴出来分享。\u003c/p>\u003cp>\u003cbr> 【学习者案例记录】\u003cbr> 学习者分享：\u003cbr> 宇强的学习计划：\u003cbr> 1、 我最近找到了一个新的运营推广方式A，想看看它行不行。\u003cbr> 2、 下周回去跟我的同事分享并讲解这个方式的模型和做法，一起评估它的可行性。\u003cbr> 3、 过程中，如果发现有表达不足或讨论发现它有不可行的地方，回去再找资料或咨询同行是否还有其他可补充的。\u003cbr> 4、 简单总结它的做法，然后去做做看效果怎么样。\u003c/p>\u003cp>\u003cbr> 非常感谢宇强的分享。\u003cstrong>看来大家已经能够使用“费曼四步法”来学习了，\u003c/strong>希望大家都能应用\u003cstrong>“费曼四步法”\u003c/strong>帮助自己获得更好的学习成果。我今天的分享到此结束，谢谢大家。\u003cbr> \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1605483406000,"updated_at":1606788498000,"ria":true},{"id":10568,"topic":"如何应用比喻建立知识联系","learn_goal":"","remark":"过级活动","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"罗巧琴","city":"东莞市"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>学习目标\u003c/strong>】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能记住“定、理、寻、建”比喻四步法，在接触新知识时，使用比喻四步法让新知识与原有知识建立联系，加深印象、强化记忆。\u003c/p>\u003cp>【\u003cstrong>自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好！我是拆书家龙珠，以下用三个标签介绍我自己：一枚酷爱学习的终身学习者、一对双胞胎的妈妈、一个有接近20年理财经验的金融人。为便于一会的讨论和练习，我们先来分一下组，两人为一组，共分为四组。\u003c/p>\u003cp>【\u003cstrong>图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F（特征，核心是书）:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天我们学习的这本书非常畅销，它出版后的6年间，被重印20多次。\u003cu>作者斯科特•扬\u003c/u>（Scott Young），\u003cu>用1年时间修完麻省理工33门课、同步拿下了4门外语\u003c/u>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A（优势，重点是比较）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cu>对比同类书籍，这本书《如何高效学习》强调的不是死记硬背，反复记忆知识点,而是整体性学习，用巧妙的方法让知识关联起来，从而形成自己的高效学习方法。\u003c/u>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B（利益，强调的是学习者收获）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1本书益处：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>全书围绕整体性学习策略，能为你提供一个如何学得更好的模型，通过对照策略，你能找出学习上的缺陷，改正学习方法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B2这个片段益处：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天学习的片段，比喻法，选自书本P87页，通过今天的学习，你将学会在接触新知识时，不是直接记忆，而是使用比喻法让新知识与原有知识建立联系。\u003c/strong>\u003c/p>","ratings_count":2,"texts":[{"id":14424,"quote":"\u003cp>比喻法在整体性学习中扮演的角色是类似的，\u003cstrong>比喻就是在不熟悉的知识和熟悉的知识之间架起一座沟通的桥梁。\u003c/strong>比喻在文学中主要提供视觉上的相似，而在整体性学习中联系的是类似的过程：事件或者信息的顺序。\u003c/p>\u003cp>\u003cu>举例来说，我们在心理学课上学到了条件反射，经典的条件反射讲的是一个刺激经过强化，与一个反应建立联系的现象，这个现象由巴甫洛夫观察狗的行为而发现。巴甫洛夫注意到如果每次给狗送食物之前先按铃的话，以后一按铃，即使不给食物，狗也会分泌唾液。\u003c/u>\u003c/p>\u003cp>怎样应用比喻法学习条件反射？\u003cstrong>比喻法的第一步是在你的个人经验中寻找能够模拟条件反射的东西，\u003c/strong>我个人生长在加拿大的冰天雪地里，所以想到的第一个比喻就是在雪地里行走。你第一次在雪地里行走时，因为雪地茫茫一片，走哪条路都有可能。\u003cstrong>但是几次行走以后，你会选择一开始走的路，因为开始的行走在雪地上形成了一条隐约可见的小路，走这条路显然比随便走更容易。\u003c/strong>\u003c/p>\u003cp>我将雪中走路与条件反射联系在一起，一开始，铃声可能或不引起狗分泌唾液（这代表一开始雪地茫茫一片，无路可寻）。但是在将铃声和食物关联在一起后，从铃声到食物的路就在雪地上（狗的大脑里）形成了，最终狗一听见铃声就分泌唾液，因为这条路已经很明显了。像许多比喻一样，这个比喻也不完美，但是它很有用。\u003c/p>","explains":"\u003cp>好了，我看大多数小伙伴都阅读完了\u003c/p>\u003cp>【what】\u003c/p>\u003cp>比喻是一种文学上的工具，多用来将陌生的事物与其他熟悉的事物联系在一起，也就是以一种事物去认知另一种事物。而在整体性学习中，比喻所联系的是信息演化过程中的某种类似。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>应用比喻，可以建立知识与知识之间的连接，帮助理解和加强印象，以达到记忆和应用的目的。\u003c/p>\u003cp>【how】【细化行动步骤】\u003c/p>\u003cp>那如何应用比喻法呢，以下四步可以帮助大家：\u003c/p>\u003cp>\u003cstrong>第一步“定”，确定你要深入理解或记忆的内容。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步“理”，梳理它的基本信息。如它的定义、组成或特性等。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步“寻”，根据梳理的信息，搜寻你个人经验或熟悉领域中，与之类似的信息或事物。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四步“建”，连接类似的各个关联点，建立桥梁。\u003c/strong>\u003c/p>\u003cp>下面举个我的例子：\u003c/p>\u003cp>\u003cstrong>1、“定”，确定内容。\u003c/strong>\u003c/p>\u003cp>我单位想运用“区块链”共享仓库数据，于是我需要学习“区块链”这个知识点。\u003c/p>\u003cp>\u003cstrong>2、“理”，梳理信息。\u003c/strong>\u003c/p>\u003cp>根据定义，“区块链”是分布式数据存储、点对点传输、共识机制、加密算法等计算机技术的新型应用模式。本质上就是一种记账的方法，数据在不同的设备上运行，彼此独立工作，而又彼此互联，保持数据一致。最大的特点是不能篡改，不受任何人或实体控制。\u003c/p>\u003cp>\u003cstrong>3、“寻”，搜寻类似。\u003c/strong>\u003c/p>\u003cp>我喜欢学习，群体学习是常态，“区块链”的形成让我联想到某一学习领域中大家共同学习的打卡圈的形成。\u003c/p>\u003cp>\u003cstrong>4、“建”，建立连接\u003c/strong>。\u003c/p>\u003cp>“共同学习打卡圈”与“区块链”的联系，首先“区块链”是由各个区块形成一个体系（一群人形成一个圈子）；这些区块是相互独立工作而又互联互通的（如同圈子中每个人都是独立的，但圈子让这群人产生了共同的信息）；如A发出一个flag，每个人都会收到并有记录；要是第二天A后悔了，在自己手机上删了，但其他人手机上仍存在这条记录的，这就是区块链最大的特点，数据保持一致、不受他人控制（圈子中共有信息不因个人删除而失去）。像许多比喻一样，这比喻或许并不完美，但它对我有用。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>也许有小伙伴会觉得，我都“理”出它的定义和特性了，还要去找个比喻多麻烦啊！是啊，假如这是一个简单的新信息，容易理解、简单易记，实在是没有必要找比喻，但如果像我的例子“区块链”那样的一个不好理解也不好记忆的新信息，通过找到与之类似的比喻，能帮助我日后更容易的想起它是怎么一回事啊。当然，要“寻”到恰当的比喻也是不简单的，在找到一个恰当的比喻之前，你可能需要尝试好几个不太恰当的比喻，因为思维方式是需要一个过程的。\u003c/p>\u003cp>【这样做的好处】\u003c/p>\u003cp>如果你经常使用这种比喻法，大脑会逐渐习惯在记忆内存中搜索比对，寻到比喻的速度和准确度也会越来越提升。\u003c/p>\u003cp>【不这样做的坏处】\u003c/p>\u003cp>但如果你总是说自己找不到好的比喻而不去想、不去用，可能你的创造力就会一直让你压抑着、或是当要说明一个事物时，想半天也想不出一个让人更容易明白的说法。\u003c/p>\u003cp>所以不要害怕，把你能想到的都先写下来吧。\u003c/p>","interaction":"\u003cp>【拆书家指令】\u003c/p>\u003cp>我们刚刚学习了可以用“定、理、寻、建”比喻四步法向他人解释一个不太容易理解的新事物，现在一起来做一个演练吧，请大家来听听以下要演练的场景： \u003c/p>\u003cp>【场景描述】【应用知识点并形成解决方案】\u003c/p>\u003cp>读书爱好者东东参加过几期拆书活动，非常喜欢这种学习方法，但他不知道如何向他人解释什么是拆书，于向拆书家小华请教，小华通过应用 “定、理、寻、建”比喻四步法，向东东解说清楚什么是拆书，成功帮助东东更好的理解了拆书和加深了对拆书的印象。\u003c/p>\u003cp>现在，请每两人为一组进行演练，一人扮演小华，当东东来请教时，如何运用刚才学到的“定、理、寻、建”比喻四步法解释清楚什么是拆书。\u003c/p>\u003cp>另一人扮演东东，在听完小华的解释后，尝试用“定、理、寻、建”比喻四步法反馈自己的理解，什么是拆书。\u003c/p>\u003cp>现在，请每两人为一组进行演练，一人扮演小华，当东东来请教时，如何运用刚才学到的“定、寻、选、建”比喻四步法解释清楚什么是拆书。\u003c/p>\u003cp>另一人扮演东东，在听完小华的解释后，尝试用“定、理、寻、建”比喻四步法反馈自己的理解，什么是拆书。\u003c/p>\u003cp>演练时间5分钟，现在开始。5分钟后，我会选一位小华和一位东东，大家一起来听听他们的“定、理、寻、建”比喻四步法是怎么说的。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>学习爱好者文英和承景的分享：我们通过刚才的讨论，用“定、理、寻、建”比喻四步法先确定了需要了解什么是拆书，然后理出了拆书是一种学习方法论，以解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，用学习改变行为，把图书知识转化为自己的能力。\u003c/p>\u003cp>承景（东东）：那你解释一下拆书像什么？\u003c/p>\u003cp>文英（小华）：拆书嘛，你可以这么想，像我们看医生，你哪里有不舒服当然是找那方面的医生，以你的问题为中心，医生给出你问题的特定解决方案，拆书跟类似，以学习者为中心，以解决问题为目标。\u003c/p>\u003cp>承景（东东）：嗯，我明白了，看医生不是为了看医生而看医生，而是为了解决我的问题，拆书也是为了解决我的问题而去学习，而不是为了看书而看书。两个都是围绕我自己为中心。所以拆书与看医生类似。\u003c/p>\u003cp>非常感谢刚才小伙伴们的分享。\u003cstrong>看来大家已经能够使用比喻四步法学习了，在结束之前，请大家再回顾一下，比喻四步法是哪4步呢？（\u003c/strong>“定、理、寻、建”\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>好了，我今天的分享到此结束，谢谢大家参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1603473642000,"updated_at":1605413953000,"ria":true},{"id":10181,"topic":"手写笔记-加深巩固知识","learn_goal":"","remark":"哪种记笔记的方法可以加深和巩固记忆呢？可以尝试手写笔记的方法。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"小鱼-","city":"沈阳市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>开场：&lt;2分钟\u003c/strong>\u003c/p>\u003cp>学习主题：手写笔记-加深巩固需要记忆的知识。\u003c/p>\u003cp>自我介绍+分组：大家好，我是今天的拆书家：小鱼。为了我们能够充分的讨论和应用今天所学的内容，我们分成两组。今天的拆页主题是：手写笔记-加深巩固需要记忆的知识。\u003c/p>\u003cp>图书介绍：（1分钟）用FAB法介绍图书\u003c/p>\u003cp>\u003cstrong>F\u003c/strong>特征：拆页选自《学会如何学习》这本书。书中用生动有趣的方式描绘大脑运作的一般规律和特殊规律，帮助学习者找到适合自己的学习方法，从而提高学习效率。\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>优势：与同类关于学习方法的书籍相较，是由三位作者共同完成。他们都有深厚的神经科学根基，立足于有据可查的科学研究和发现，提供简单有效的学习策略。\u003c/p>\u003cp>\u003cstrong>B1\u003c/strong>利益：这是一本为青少年写的书，可以帮助孩子的学习，于我们成年人，充满新颖而实用的理念，读者可以提前使用高效学习方法，提高学习效率。\u003c/p>\u003cp>B2：比如怎么记笔记才能加深巩固记忆？书中给了我们一个实用的方法。\u003c/p>\u003cp>学习目标：\u003c/p>\u003cp>我们今天的学习目标是跟随我完成本场拆书，当你为想记忆的知识做笔记的时候，会用手写笔记的方法，记录并记忆知识。\u003c/p>","ratings_count":1,"texts":[{"id":14014,"quote":"\u003cp>这里我们用两分钟的时间来阅读原文拆页。\u003c/p>\u003cp>\u003cstrong>R阅读原书拆页：2分钟\u003c/strong>\u003c/p>\u003cp>选自《学会如何学习》P299\u003c/p>\u003cp>这里还有一个关于学习的惊喜。人们通常认为记笔记的最佳方式是把它们打出来。毕竟，打字可能比手写更快，而且笔记会更整洁。但是不对。手写笔记效果更好，哪怕你的字写得很烂。记住，你需要为重要知识建立一个大脑链接组。令人惊讶的是，如果你只是键入你所听到的信息，那么在这些词语被打到页面上的同时你不会创建链接组。信息进入耳朵，再从手中输出，这中间没有发生深层次的脑力工作。如果你手写的话，就必须对写在纸上的内容做一些思考，这有助于大脑链接组的形成。这时你的树突棘将开始生长，如果你在睡前最后复习一次笔记的话，还可以让树突棘在你睡觉时长得更好！\u003c/p>\u003cp>记笔记的一个好方法是在页面的一边画一条线，距离页边大约纸张宽度的三分之一。把最初的笔记写在比较宽的一侧，然后，当你复习它们的时候，在比较窄的一侧写出更简洁的要点。接着，不要看笔记，试着回忆那些要点，自测一下，练习调取那些链接！\u003c/p>\u003cp>记笔记并没有神奇的准则。它的主旨是提炼要点，这样你就可以复习它们，巩固你的大脑链接。\u003c/p>","explains":"\u003cp>\u003cstrong>I拆书家讲解引导（2分钟）\u003c/strong>\u003cbr>What：从神经性科学的角度谈学习方法，手写笔记的方法可以加深和巩固记忆。\u003c/p>\u003cp>Why：\u003c/p>\u003cp>一般做法：为想要记忆的知识记笔记，我们会更倾向整理成文档然，这样看起来更高效。\u003c/p>\u003cp>一般做法的坏处：通过电脑整理文档，不符合大脑的工作规律，没有发生深层次的脑力工作，很难记住，也很难快速的从头脑中提取。\u003c/p>\u003cp>How：怎样做笔记能够加深巩固记忆，把知识从头脑中提取出来呢？手写笔记法。\u003c/p>\u003cp>1.分区。把笔记页面分成左右两侧。左侧占2/3，右侧占1/3。\u003c/p>\u003cp>2.手写。把需要记忆的知识手写在左侧2/3处。\u003c/p>\u003cp>3.提炼。把知识要点提炼出来写在右侧1/3处。\u003c/p>\u003cp>4.回忆。根据要点，回忆或复述需要记忆的内容。\u003c/p>\u003cp>Where:新概念，考试复习，备课等需要记忆的知识，都可以用这个方法。巩固一天内的学习内容，或阶段性的复习。\u003c/p>\u003cp>举个例子：\u003c/p>\u003cp>给大家举个例子，我想记住“心理舒适区”这个概念。我把概念整理成文档，读了很多遍，也理解了。当我分享的时候并不能把概念全面的讲述清楚。我可以用手写笔记来完成这个概念的记忆。1.在笔记本上做好区分。2.把心理舒适区的本质是熟悉的应对方式所带来的控制感，应对方式有行为和情绪两个层面等写在右侧。3.提炼出“应对方式”这个要点，4.根据应对方式回忆并复述全部内容。\u003c/p>\u003cp>预防学习者可能出现的异议：\u003c/p>\u003cp>大家听着会觉得步骤挺简单，但是手写和提炼费时又费脑。恰是这两部分才将我们的记忆变得深刻和牢固。\u003c/p>","interaction":"\u003cp>\u003cstrong>A拆为己用（10分钟）\u003c/strong>\u003c/p>\u003cp>A2（分步催化1）\u003c/p>\u003cp>请大家思考一下，在下周或者下个月，你有个考试？要参加演讲？要去讲课？记住一些概念？我们用3分钟的时间，写下你想到的未来的场景，在组内互相分享一下。只需要分享你想到的未来的场景即可。3分钟后我们请一位伙伴和大家分享。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>白雪：我在做沟通主题的知识体系的构建。下个星期我整理构架下的基本概念，我需要记忆关于沟通的理念。\u003c/p>\u003cp>刘阳：我在读一本书，作者的理念是“情绪是构建起来的”。下个星期我读完书要做笔记，要记忆书中作者提到的重要概念。\u003c/p>\u003cp>我：谢谢白雪和刘阳的分享。\u003c/p>\u003cp>A2（分步催化2）\u003c/p>\u003cp>请将你刚才想到的未来场景，加工成一个具体例子，如何用手写笔记的方法来加深巩固需要记忆的知识。\u003c/p>\u003cp>我们用5分钟的时间，在便签上写下来，在小组内分享。5分钟后我们请一位伙伴和大家分享。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>刘阳：下个星期用手写笔记的方法记住作者提到的重要概念。\u003c/p>\u003cp>我会先把笔记本准备好，做好区分。然后我把概念写在左侧的2/3处。之后我一天内，再把概念提炼总结一下，写在右侧的1/3处。最后我根据提炼的内容，去回忆所记录的概念，我可以简单的复述一下。\u003c/p>\u003cp>我：谢谢刘阳的分享。\u003c/p>\u003cp>结束语：\u003c/p>\u003cp>工作、学习、生活中，有哪些需要记住的重要知识？不妨选用手写笔记，让知识在用的时候，从头脑中自然提取出来。谢谢大家的聆听与支持。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1595820356000,"updated_at":1596324146000,"ria":true},{"id":9789,"topic":"循环式作息计划","learn_goal":"","remark":"以小部分时间专注工作学习。1、一周休一天。2、晚上不工作。3、设定90分钟专注时间。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"朱朱2020","city":"济南市"},"club":{"name":"济南海右分舵","city":"济南"},"prologue":"\u003cp>\u003cstrong>环节1——自我介绍\u003c/strong>\u003cbr>\u003c/p>\u003cp>各位拆书帮的小伙伴们大17家好，我是朱朱，朱德的朱，不是诸——葛亮的诸。我用三个标签来进行一下简单的自我介绍，第一个标签是平面设计师，这是我的本职工作，虽然没有很亮眼的成绩，但我对自己的专业还是很自信的，大家如果有宣传设计方面的问题，可以找我咨询。第二个标签是厨艺小能手，估计这条大家都想不到吧，我对生活的定义是：到了饭点，就可以吃上可口的饭菜，这就是幸福。小伙伴有机会可以来尝尝我的手艺，虽然不是什么大餐，但绝对可以入口。第三个标签是未来的三级拆书家，虽然我刚开始1-1，但我对此抱有强烈的信心，也对升级过程中肯定会出现很多的障碍有明确的认知，那些阻挡我前行的都是我现在所缺少的，何况我有许多拆书帮的小伙伴和我一起升级打怪……\u003c/p>\u003cp>\u003cstrong>环节2——拆书帮介绍\u003c/strong>\u003c/p>\u003cp>说到拆书帮，我是2018年就知道拆书帮的，并读了《这样读书就够了》，但没有和拆书帮进行实质性接触，直到2019年下半年，我才开始参与线下活动。参与的过程是非常愉快的，和志同道合的小伙伴们共同学习，实在是太棒了，每次活动都感觉不虚此行、收获满满。参加了几次线下活动后，又在19年年底加入拆书训练营，疫情期间也参加便签大赛，成绩还算可以。这个时候我才更多的了解了拆书帮。拆书帮是由赵周老师在2013年创建的，是一个非营利性组织，是一个学习型社群，主要是以拆书法为核心，帮助学习爱好者成为一名“学习促进者”——拆书家。目前，一共有88个分舵，分布在51个城市，小伙们在线下一起拆书，共同成长。\u003cbr>\u003c/p>\u003cp>那么，什么是拆书法呢？就是强调以学习者为中心的学习方法论，主要针对成人的学习方法，对致用类和理论类书籍可以达到深度学习的状态，具体表现在：阅读原文后，加工3个便签以达到“拆为己用”的目的。I便签：用自己的语言重新理解原文；A1便签：连接过往经验，激活所学知识；A2便签：把知识应用到具体行动上。阅读原文是R，所以拆书法又叫——RIA便签学习法。拆书法主要应用在2个方面，一是个人学习，用拆书法就可以得到参加主题培训的收获；二是组织学习，就是拆书家用一本书加工成一场现场学习，引导学习者拆为己用，所创造的价值不亚于专业培训师。\u003c/p>","ratings_count":2,"texts":[{"id":13627,"quote":"\u003cp>\u003cstrong>环节3——【R】阅读原书拆页\u003c/strong>\u003c/p>\u003cp>\u003cbr>大家花2分钟的时间，看看PPT或者微信里的原文片段：\u003cbr>\u003cbr>\u003cstrong>【R：原文片段】\u003c/strong> 斯科特·扬《如何高效学习》 （P146）\u003c/p>\u003cp>循环式作息计划\u003c/p>\u003cp>线性的计划是平均安排时间执行工作，而循环式作息计划则\u003cstrong>先集中小部分时间做大部分工作\u003c/strong>。这种计划安排能让你做到有张有弛，而不是死气沉沉，像个机器人。下面是一些建议。\u003c/p>\u003cp>\u003cstrong>(1)一周休息一天\u003c/strong>。我总是抽出一周中的一天，什么事也不做，将7天的活放在6天里完成，一开始很难，但是放松一天能防止你筋疲力尽。\u003c/p>\u003cp>\u003cstrong>(2)晚上不干活儿。\u003c/strong>将一天的工作放在早上集中完成，早早完成工作，晚上你就有几小时的空闲了。\u003c/p>\u003cp>\u003cstrong>(3)设定90分钟。\u003c/strong>给定自己90分钟，集中精力完成某个学习任务，一旦90分钟结束，停止工作。90 分钟的时间设定能让你学习时注意力更集中。\u003c/p>","explains":"\u003cp>\u003cstrong>环节4——分享I便签（3分钟）\u003c/strong>\u003cbr>\u003c/p>\u003cp>我看小伙伴们都看完了，咱们继续。\u003c/p>\u003cp>这原文片段来自于斯科特·扬《如何高效学习》，这段文字虽然不多，但却提供了一个看似简单，仔细思考却不简单的“简单方法”——循环式作息计划。\u003c/p>\u003cp>【what】循环式作息计划，是通过集中时间用来专注工作/学习，是职场人可以伸伸手就能够到的时间管理方法。\u003c/p>\u003cp>【why】有效的、高效的、有科学依据的……学习方法太多太多了，为什么很多人仍然掌握不了那些方法呢？\u003c/p>\u003cp>首先不得不承认人与人之间差异是巨大的。有的人能很快能掌握科学而复杂的方法，迅速来提高自己。有的人就因为方法太复杂了，操作起来太有难度了，就果断放弃了。虽然心中强烈的知道是科学的、有效的方法，但就是执行不下去。这时他们需要的不是科学有效的方法，而是最初级的、最简单易执行的方法，用来打开局面，迈出第一步，这个循环式作息计划就是一个非常不错的选择，既有专注工作的紧张，也有放松身体的轻松，只用一周的时间就能实现一个循环，工作、休息、学习三不误。还很容易执行下去，从而可以进入下一个循环，生生不息。\u003cbr>\u003c/p>\u003cp>【how】如何执行循环式作息计划呢，具体方法很简单，看完就能记的住，但一定要明白简单背后的逻辑。\u003c/p>\u003cp>\u003cstrong>第1步，一周休一天：\u003c/strong>是的，一周就休一天，这一天你可以做你任何想做的事，但要记住一句话：休息不等于放纵。休的多了犯懒，不休的话心理不平衡。前提是把这7天的工作都要在前6天的时间里全部做完\u003c/p>\u003cp>\u003cstrong>第2步，晚上不工作：\u003c/strong>把你所有的工作都集中在白天完成，下班后就可以做你想做的事了。给自己一个心理暗示，白天把工作做完，晚上的时间都是我自己的了，这样还会促使白天工作更专注，效率更高。晚上的时间可以用来陪伴家人，也可以用来学习充电。\u003cbr>\u003c/p>\u003cp>\u003cstrong>第3步，设定90分钟：\u003c/strong>以90分钟为一个单位时间，用来集中消灭重要工作，单位时间内尽量消除外界打扰，保持专注。其它的时间就用来处理各种乱七八糟的用时较短的事情。如果是创造类行业的话，可能得设定每天2个90分钟用来工作，可以上午一个90分钟，下午一个90分钟。具体情况也可以根据工作情况进行调整。\u003c/p>\u003cp>【where】这个循环式作息计划，我给他重新起了一个名字叫：懒人时间管理。因为这个方法适合需求简单时间管理的懒人和工作强度相对稳定的人。\u003c/p>","interaction":"\u003cp>\u003cstrong>环节5——分享A1便签\u003c/strong>\u003c/p>\u003cp>我就是一个时间管理的懒人，很多事都是没有计划的，我也做过几次关于工作时间的规划，执行以后想像的美好场景并没有出现，此起彼伏的微信声、QQ声、电话声让我烦不胜烦，能安安静静的工作半个小时都难。更加让人崩溃的是，闲的时候可能好几天没活干，忙得时候各种事情都来了，忙到没办法专注于干活了。\u003c/p>\u003cp>最混乱和最有代表性的就是这次是在疫情封闭期间，因为是在家里办公，早上有时会睡过头，白天干不完的工作，晚上接着干。有一次，周一接到了一个设计工作，工作量比较大，可能需要好几天的时间才能完成，这下子就更混乱了 ，白天干活磨磨蹭蹭，一会这事，一会那事，倒杯水，上个厕所，休息一会，总感觉还有好长时间，即便干不完也不要紧，反正还有晚上呢！这样的拖延又影响了生活，使得工作和生活完全没了界限，睁开眼就上班了，闭上眼才算下班了，感觉是真的好累好累……这时候最大的愿望就是自己唰的一下变成一个时间管理达人，把工作和生活都管理井井有条。\u003c/p>\u003cp>然而愿望只是愿望，而帮不到我，唯一能帮助自己的只有自己。想起在李笑来老师的书中看到的一句话：时间是不可管理的，你只能管理你自己。是啊，谁能管得住时间呀，时间管理的本质最终还是管理自己。\u003c/p>\u003cp>\u003cstrong>环节6——分享A2便签\u003c/strong>\u003c/p>\u003cp>想管理自己怎么办呢？先从循环式作息计划开始，简单明了能做到。\u003cbr>\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>在下周一开始执行循环式作息计划，并在5-7月份的时间内养成习惯。\u003c/p>\u003cp>\u003cstrong>行动：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第1步，一周休一天。\u003c/strong>\u003c/p>\u003cp>固定在每周日休一天，工作一定要在周一到周六全部完成。遇到不能完成的情况，转移至下周一。休息时间做做家务、逛逛公园、放空大脑、看看电影等等，反正别沾工作的事就对了。\u003c/p>\u003cp>\u003cstrong>第2步，晚上不工作。\u003c/strong>\u003c/p>\u003cp>每天一上班提醒自己：白天把工作做完，晚上的时间就都是自己的了。工作至下午5点半就给自己一个&quot;下班了”确切信号，心中念叨一遍：今天的工作已经全部完成了，剩下的明天再做。每天晚上给自己留出1-2个小时用来读书或学习专业技能。\u003c/p>\u003cp>\u003cstrong>第3步，设定90分钟。\u003c/strong>\u003c/p>\u003cp>因为设计行业特性的原因，大部分的设计工作都需要整块的时间用来工作。根据当天情况进行90分钟的设定，工作少的时候就在下午进行一个90分钟的时间进行专注工作。工作量大的时候就上午、下午各一个90分钟用来专注工作。其它时间用来处理琐碎的事情。\u003c/p>\u003cp>这个方法看似很简单，很容易执行，然而最难的部分在长期的执行，一周的执行每个人都能做到，但一年呢？把这个计划贴在办公桌上吧，给自己提个醒，让时间管理变得更有效。\u003c/p>\u003cp>以上分享的就是我这次的拆书，感谢小伙伴们的参与，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1588598110000,"updated_at":1588993949000,"ria":true},{"id":9417,"topic":"整体性学习及费曼技巧","learn_goal":"运用“整体性学习”及“费曼技巧”实现高效学习","remark":"《如何高效学习》基于作者在1年内通过自学完成4年麻省理工学院计算机科学课程的经验总结而作，为读者提供了整体性学习的原理以及操作性极强的多种学习工具。","level":"TF2-4","duration":90,"status":30,"type":0,"chaishujia":{"username":"珮源","city":""},"club":{"name":"大连知行分舵","city":"大连"},"prologue":"\u003cp>【分发材料】&nbsp;\u003c/p>\u003col>\u003cli>\u003cp> 原书拆页片段1，片段2\u003c/p>\u003c/li>\u003cli>\u003cp>How步骤总结，设计好的模拟场景，以及学习者的小组演练步骤\u003c/p>\u003c/li>\u003c/ol>\u003cp>【开场】\u003c/p>\u003cp>大家好，稍后我们会有小组讨论的内容，所以先请大家分一下组：联想和晓雯为一组，郭峰和今天的两位嘉宾朋友为一组。&nbsp;\u003c/p>\u003cp>感谢大家陪我拆书晋级，我是珮源，12月份的3级拆书家，新手RIA学习力导师，终身学习者。今天我能够为大家提供的价值是一组可以帮助我们高效学习的方法。&nbsp;\u003c/p>\u003cp>【总学习目标】\u003c/p>\u003cp>希望在跟随我完成本次现场拆书学习后，大家可以基本掌握这两种学习方法，帮助我们在工作生活中提升自己的学习效率。&nbsp;\u003c/p>\u003cp>【图书介绍】&nbsp;\u003c/p>\u003cp>【F】本次拆页来自于《如何高效学习》。这本书是基于作者在1年内通过自学完成4年麻省理工学院计算机科学课程的经验总结而作，为读者介绍了整体性学习的原理并提供了很多实用具体的学习技巧。\r\n【A】介绍学习方法的书籍有很多，但大部分以理论或学术研究结果为主，存在不易操作，缺少实证等困扰。与这些同类书籍相比，《如何高效学习》是基于作者自己在短时间内高效学习各类知识的实际经验总结，具备经过了实践验证，注重实效以及操作性强等优点。&nbsp;\u003c/p>\u003cp>【B1】读者通过本书可以获得高效学习和记忆的许多实用技巧。&nbsp;\u003c/p>\u003cp>【B2】进一步说，通过今天的2个拆书片段，大家可以学会使用整体性学习法来理解和掌握新知，以及用费曼技巧来检测和巩固对知识的掌握程度。&nbsp;\u003c/p>\u003cp>【拆页1学习目标】\u003c/p>\u003cp>首先就让我们通过对第1个片段的学习，学会用整体性学习法来加深理解，掌握新知。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":13220,"quote":"\u003cp>【R】先请大家用1分钟左右的时间阅读一下拆页片段1上关于“整体性学习法”的内容，读完的朋友请举手示意我。\u003c/p>\u003cp>（以下为原文节选）\u003c/p>\u003cp>以下是这六个步骤的简单介绍。\u003c/p>\u003cp>(1)获取：获取就是信息进入你的眼睛和耳朵,阅读、课堂上记笔记以及个人的种种经历都是获取。获取阶段的目标是获取的信息要准确,信息量要尽量压缩。\u003c/p>\u003cp>(2)理解：理解就是了解信息的基本意思,并放在上下文中联系,这是学习的最基本联系\u003c/p>\u003cp>(3)拓展：拓展阶段是整体性学习中最花力气的地方,这一步将形成模型、高速公路和广泛的联系,从而获得良好的结构。\u003c/p>\u003cp>(4)纠错：纠错阶段是在模型和高速公路中寻找错误,这个阶段要删除那些无效的联系。\u003c/p>\u003cp>(5)应用：应用把纠错带入最后的水平,通过比较(知识)信息是如何在现实中运行的来进行调整,如果理解不符合现实世界,那么再多也无用。在这一步中失败的典型例子就是书呆子,即那些读书读得很好但是出了学校大门却茫然不知所措的家伙。\u003c/p>\u003cp>(6)测试：上述阶段的每一步都需要测试,测试有助于你迅速找到学习中的问题所在,帮助你改进学习技术,克服缺点。\u003c/p>","explains":"\u003cp>我看大家基本上都读完了，那么我来做一下拆解。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>整体性学习是指将新知与学习者已有的知识经验相关联，形成一个完整的知识体系；以已知为基础来理解未知，并通过学以致用来进一步掌握知识的一种学习方式。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>大家觉得“学霸”是天生的么？我看到这边有朋友回答说“不是”的，嗯，我也是这样认为的。因为我相信能够坐在同一个教室内学习的同学，彼此间智商的差别并不会非常大。这些可以在短时间内达到更好学习效果的同学，和那些学习非常努力但往往效果差强人意的同学之间的区别，也许更多是因为他们采用了不同的学习方法。“聪明”的学生不是学得更好，而是学得不同。\u003c/p>\u003cp>整体性学习法就是这样一种“不同”的学习方法，和传统学习方式相比，它更强调对于知识的真正理解和实际应用，可以帮助我们在短时间内高效掌握知识点，做到更有效地学习。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>也许我们身边很多人的学习方式仍是机械记忆，也就是常说的“死读书”，这与整体性学习的理念相悖，也是我们不提倡的一种低效耗能的学习方式。不能够真正理解的知识是无法长时间有效记忆的，通过机械记忆来学习只会让我们浪费无数个小时一遍遍复读材料却仍然记不住知识，对于稍微晦涩一点的知识点就难以把握，即使强行记住了知识点也会在考完试的第一时间忘干净。说的残酷一点，把有限的人生贡献给了学习，却仍然无法获得理想的效果。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>那么具体怎么进行整体性学习呢？可以分为6个步骤来开展：\u003c/p>\u003cp>1.&nbsp; 获取知识：通过听讲，自学等形式将知识获取到我们的头脑中。在这一步中，保持专注，去除冗杂，以及正确梳理和选择信息的能力非常重要，因为在这一步丢失的信息将无法在后面的环节中重新获得。\u003c/p>\u003cp>比如今天的拆书学习吧。那么我们学习的第一步就是通过专注听讲以及参与小组讨论和演练，争取在本次拆书课上得到尽可能多的核心知识。\u003c/p>\u003cp>2.&nbsp; 理解含义：只获取信息而不理解没有任何意义，所以这一步我们需要结合上下文，明确掌握刚刚获取知识的基本含义。\u003c/p>\u003cp>用前面的例子说，就是结合分发的拆页，小组练习以及我们自己的经验，理解拆书家在今天讲解的这个整体性学习法说的到底是什么。\u003c/p>\u003cp>3.&nbsp; 拓展关联：在这里我们需要尝试将刚学到的新知和我们熟悉的概念相关联，理解这个新知是从哪来的，其它知识点或我们已有的经验是怎么联系的，如何用它来解决实际问题等，以搭建我们自己的知识模型和体系。\u003c/p>\u003cp>继续前面的例子，就是进一步明确为什么要用我们今天学到的整体性学习法，具体怎么用它，这个学习方法和我们可能已经知道的其它学习方法有哪些共同点，又有哪些区别等等。\u003c/p>\u003cp>4.&nbsp; 查偏纠错：在这个环节我们需要发现和纠正在前面的学习过程中可能出现的一些错误关联或认知偏差。通过阅读相反观点书籍，或者检验知识点在现实中不适用范围等方法，来查偏纠错。\u003c/p>\u003cp>比如我们在学习了整体性学习法后可以联系现实和自身经验思考这个方法在哪里是不适用的；有哪些看起来和这个学习方法完全不同，但在实践中同样有效的学习技巧；又或者我们对于整体性学习法的理解有没有什么偏差呢？\u003c/p>\u003cp>5.&nbsp; 实践应用：学习的最终目的是为了应用所学解决问题。这就需要我们把所学的知识放到现实世界中去通过实践来进行验证，并且根据从应用中得到的反馈和心得来调整我们对于知识的理解和掌握。\u003c/p>\u003cp>比如我们今天学了整体性学习法，那么希望大家可以在2周内使用这个方法来学习一个自己目前关注的一个知识点。\u003c/p>\u003cp>6.&nbsp; 测试完善：测试有助于我们了解对于知识点掌握的状态，发现哪里有遗忘和误解的问题，以及如何改进。测试的方式因人而异，可以是做相关习题，小型自测，参加认证考试等等。\u003c/p>\u003cp>那么为了测试我们今天学到的内容，稍后我也会请大家做一个现场演练。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>说到这里可能有的朋友会问，应用和测试有什么区别呢？我觉得应用就是测试呀？实践应用确实是测试的一个重要方式，但测试也可以是通过正式考试等其他方式来对学习效果进行检测。\u003c/p>\u003cp>另外，我们可以在整体性学习的每一个环节对自己的学习效果进行测试，而应用通常需要我们对所学的知识至少有了初步的理解才能有效开展。\u003c/p>\u003cp>最后，测试更侧重于检查我们对知识点的掌握程度，而应用呢，更多是看我们是否会用，以及这个方法本身是否好用等。\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>整体性学习法因为强调深入理解掌握所学的知识及在现实中应用，所以特别适合对致用类知识的学习；以及比较复杂，需要投入大量时间精力深入理解后才能正确应用的知识，比如天体物理等。\u003c/p>\u003cp>【哪里不适用】\u003c/p>\u003cp>对于一些不强求明确理解的学习内容，比如基础算数加乘法等，整体性学习法可能就不是投入产出比最高的学习方式。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>举个我自己的例子：我最开始学法语时采用的方式是在法盟上课，每天背单词语法课文，凭借机械记忆来学习虽然考试成绩也达到了要求，但到了法国就很尴尬了，因为发现学的法语很难在实际中转化应用。\u003c/p>\u003cp>【变正例】\u003c/p>\u003cp>但很幸运的是我的专业是全法语授课的，所以我必须在最短时间内提高自己的法语水平。为了达到能够使用法语学习专业课的目标，我根据整体性学习法为自己制定了一个法语提升计划：\u003c/p>\u003cp>1.&nbsp; 获取知识：我的目标是用法语学专业课，所以我决定通过听写老师课堂讲解的方式来获取知识，并在课后向法国同学借笔记进行核对，来防止丢失重要信息。\u003c/p>\u003cp>2.&nbsp; 理解含义：每节课后我会参考课程同主题的中英文书籍来尝试理解笔记中不熟悉的法语单词及语法的含义。\u003c/p>\u003cp>3.&nbsp; 拓展关联：接着我会针对性地查阅这些单词和语法的具体使用条件，有哪些我已经知道的同反义词或语法应用等。\u003c/p>\u003cp>4.&nbsp; 查偏纠错：之后我会进一步查阅这些知识点的不适用范围，并向法国同学请教我的理解是否有偏差。\u003c/p>\u003cp>5.&nbsp; 实践应用：我会在提交的作业或下节课讨论时使用新学到的法语知识。\u003c/p>\u003cp>6.&nbsp; 测试完善：每周我会针对所学的法语新知进行自测，并针对检测出的薄弱环节集中巩固。\u003c/p>\u003cp>这样我通过一个学期的学习，有效提升了法语水平，同时也获得了比较理想的专业课成绩。\u003c/p>","interaction":"\u003cp>【片段1学习者参考材料】\u003c/p>\u003cp>【A1激活经验】\u003c/p>\u003cp>【提问设计】\u003c/p>\u003cp>现在请大家回想一下最近一两个月内，在工作或生活中，自己有没有想要学习某种知识却失败了的经历呢？比如想要学习英语，却感觉单词语法太难背，因而放弃了？或者想要考管理财务认证，但发现成本逻辑很难理解结果不了了之？\u003c/p>\u003cp>请把关键字写在便签上，只写经历就好，不需要写应该怎么做，然后每人用1分钟左右的时间在小组内互相分享一下，稍后我会邀请一位代表进行现场分享。\u003c/p>\u003cp>好的大家讨论的差不多了，哪位朋友愿意分享一下？\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>晓雯：上个月我报了一个思维导图线上课，但上了两天就觉得难再没上过了。\u003c/p>\u003cp>【反馈.摘要点评】\u003c/p>\u003cp>感谢这位朋友的分享！报了课程学不完确实是一个很多人都比较困扰的问题。\u003c/p>\u003cp>【A1+反思加工】\u003c/p>\u003cp>那么现在请大家想一想，如果给你一个月光宝盒回到当时的场景，运用我们刚刚学到的整体性学习法——获取知识，理解含义，拓展关联，查偏纠错，实践应用，和测试完善——你会如何开展自己的学习呢？请把关键字写在便签上并在小组内分享。希望每个人都可以用1-2分钟的时间尽量分享一下，稍后我会请一位朋友为大家做分享。\u003c/p>\u003cp>好的，哪位朋友愿意用1分钟左右的时间为大家分享一下呢？\u003c/p>\u003cp>【学习者案例】\u003cbr>\u003c/p>\u003cp>郭峰：我在过往的学习中参加过很多各类培训，比如有一个职业生涯管理师的培训，在这个培训当中我的学习方式根据今天学到的整体性学习法6步来说，主要是集中在第1，2步，在学习知识和理解上面。\u003c/p>\u003cp>如果用今天学到的整体性学习法去学的话，除了第1步吸收知识，第2步理解之外，最主要的是还要进行后几步的学习。第3步去拓展，就是和我以往学习的其他知识有什么关联，哪些可以补充，哪些可以对比找出更好的去优化，第4步去纠错，也就是找出这些知识里面哪些是不适用于我的，可以不采用，哪些是我过去理解有错误的，能不能更新一下，第5步应用，我学了管理师是为了讲课用的，所以学了以后要拿出来讲，那么讲了以后第6步测验，我的测验环节就是讲完以后希望得到别人的反馈，看到我在讲的过程中有哪些问题，以练代学。是这样一个过程。\u003c/p>\u003cp>如果回到当初，我在当时采用这样一个学习过程的话，那么我现在对于这个生涯管理师的知识的理解和掌握，会比现在的效果更好。\u003c/p>\u003cp>【反馈.号召鼓掌】\u003c/p>\u003cp>感谢这位朋友的分享！对于整体性学习步骤的把握非常精准，而且分享非常得精彩。来我们大家是不是给他鼓掌鼓励一下（带头鼓掌）？\u003c/p>\u003cp>【有力结语】\u003c/p>\u003cp>好的，简单来说，请大家记住六个步骤——获取知识，理解含义，拓展关联，查偏纠错，实践应用，和测试完善——就完整掌握了整体性学习法。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":13221,"quote":"\u003cp>【片段过渡】\u003c/p>\u003cp>有的朋友可能会说，我能理解整体性学习法可以帮助我很好的理解和学习新知，但我常常不清楚自己是否完整掌握和真正记住了学到的知识，有什么方法可以帮助我检测呢？那么接下来我就为大家介绍一种新的方法：费曼技巧。\u003c/p>\u003cp>【拆页2学习目标】\u003c/p>\u003cp>希望大家在跟随我完成片段2的拆页学习后，可以在整体性学习过程中的任何环节需要及时检测学习效果的时候，使用费曼技巧自测，来发现遗漏偏差，从而改善和巩固自己的学习效果。\u003c/p>\u003cp>【R】\u003c/p>\u003cp>现在先请大家用1分钟左右的时间阅读一下拆页片段2上关于“费曼技巧”的内容，读完的朋友请举手示意我。\u003c/p>\u003cp>（以下为原文节选）\u003c/p>\u003cp>你该如何使用这种技术?\u003c/p>\u003cp>如果你想理解一个观点,你可以通过这种技术仔细地查明到底是什么地方你不明白,然后你可以去翻阅教材、笔记或询问老师,弄清楚到底你遗漏了哪些关键知识。\u003c/p>\u003cp>如果你想为了通过考试而记住一个观点,你可以把重点放在寻找一个好的比喻或者简化词句上,不必追求彻底的理解。\u003c/p>\u003cp>最后,如果你学习是为了通过考试,运用费曼技巧复习时,要把学习材料抛在脑后。费曼技巧对于自我测试、考察对知识点的理解程度,是个真正的好方法。因为如果你不翻阅教科书就能用自己的话把观点解释清楚,那么就意味着你真正理解了该观点。\u003c/p>","explains":"\u003cp>我看到大家都读完了，那么我们来继续学习。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>费曼技巧是指在不借助学习材料的情况下，通过自己的语言讲解学习到的知识点，用以教促学的方式，检验自己对于所学知识点的理解和掌握程度。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>教授他人是最好的学习方式。如果我们不能把一个知识点给他人解释清楚，那就说明我们自己对这个知识点的理解和掌握还不够扎实。通过为他人讲解的方式，我们可以快速查验到自己对知识点把握的薄弱环节，发现理解错误和缺失的地方，进而有针对性的高效复习，快速提升学习效果。\u003c/p>\u003cp>【不使用的坏处】\u003c/p>\u003cp>如果不使用费曼技巧等自测方式来实际验证自己的学习效果，会很容易产生“一听就懂，一学就会，一考就忘”的现象，因为这种自以为的懂得和学会，其实是由于对学习效果缺乏客观考量而产生的一种错误认知。而相对于其他检测技巧，费曼技巧的优点在于它不但更简便易操作，而且可以做到及时反馈学习效果，从而帮助我们节约时间成本。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>那么具体要如何使用费曼技巧呢？拆页片段2为我们提供了一些使用费曼技巧的情境，侧重点和好处。在这个基础之上，我为大家梳理了更细致的行动步骤：\u003c/p>\u003cp>【细化行动步骤】\u003c/p>\u003cp>1.&nbsp; 选择主题：选定一个自己尚未理解或不确定是否已经理解掌握的知识点。比如RIA拆书法。\u003c/p>\u003cp>2.&nbsp; 自主阐述：尝试使用自己的语言去讲解这个知识点，过程中不要借助外部学习资源或帮助。比如不使用《这样读书就够了》或者拆书家手册的描述，而是用自己的语言来为身边的朋友解释什么是RIA拆书法。\u003c/p>\u003cp>3.&nbsp; 查缺补漏：这一步可以进一步分为3小步——\u003c/p>\u003cp>a.&nbsp; 对比；对比原文材料，记录自己有没有讲解不清楚不准确的地方；\u003c/p>\u003cp>b.&nbsp; 查找：进一步查找讲解中遗漏的地方；\u003c/p>\u003cp>c.&nbsp; 巩固：以发现的错漏内容为重点，重新理解掌握知识点。\u003c/p>\u003cp>比如在为我们的朋友讲解完RIA拆书法以后，我们可以对照《这样读书就够了》里面关于RIA拆书法的讲解，来验证自己在哪些地方讲解的有偏差或遗漏，也可以寻求朋友的反馈来观察自己在哪些环节没有解释清楚，对这些薄弱环节进行重点学习和巩固。\u003c/p>\u003cp>4.&nbsp; 迭代完善：重新尝试不借助材料来讲解该知识点，直到可以用自己的语言将知识点的核心内容完整阐述清楚为止。继续我们的例子，就是重新讲解RIA拆书法并重复前面的3个环节，直到自己可以完整流畅的把RIA拆书法解释清楚为止。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>讲到这里有的朋友可能会说，我的时间紧任务重，这样来回麻烦朋友很耗费时间精力，而且我的朋友们也不总是对我正在学的知识感兴趣。难道我要为了使用费曼技巧专门去交个朋友吗？其实费曼技巧不仅可以用于为他人讲解知识，对于学习者本人也同样适用。如果时间紧张，或者身边没有其他人，我们可以自己为自己做讲解，上面讲述的步骤是同样适用的。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>所以费曼学习法适用于一切需要快速高效检测和巩固我们学习效果的情境。\u003c/p>\u003cp>【哪里不适用】\u003c/p>\u003cp>除了那些本身不具备更多内在含义，而只需要记忆的信息。比如英语的26个字母，或阿拉伯数字等。\u003c/p>\u003cp>【举例A1+】\u003c/p>\u003cp>为了方便大家理解，我给大家分享一个身边的例子：\u003c/p>\u003cp>几年前我和一位朋友一起准备一个项目管理认证考试。我准备的稍微早一些，而我的这位朋友，我们就叫她七七吧，七七同学年假旅行回来离考试只剩1个月了，特别着急得来找我问有没有快速高效的学习方法。我非常恨铁不成钢地说：“你去旅行前我提醒过你要学习的呀，你去问机器猫要时光穿梭机吧”，这次谈话很明显地不欢而散了，并且七七最后也是不得已推迟了自己的考试计划。\u003c/p>\u003cp>如果回到当时，我会尝试用费曼技巧来帮助七七准备她的学习：\u003c/p>\u003cp>第1步选定主题，我会为七七选择针对项目管理认证设计的学习材料。\u003c/p>\u003cp>第2步自主阐述，我会和她计划共同学习的时间，每周两次一起去图书馆学习，先由七七为我讲解她学习的知识点A。\u003c/p>\u003cp>第3步查缺补漏，然后我会\u003cstrong>对比\u003c/strong>学习材料，对她没有解释清楚的地方进行提问，并\u003cstrong>查找\u003c/strong>提醒她漏讲的内容。每次学习完毕我会让七七针对性地\u003cstrong>巩固\u003c/strong>复习我们为她检测到的薄弱知识点，并继续对新内容B进行学习。\u003c/p>\u003cp>第4步迭代完善，在下一次见面时七七会首先用费曼技巧再次讲解我们之前学习过的知识点A进行复查。如果通过了，我们会重复前面的步骤帮助七七学习新内容B，如果没通过，那么我会建议七七回去以后继续用费曼技巧对知识点A和B的薄弱环节都进行复习。\u003c/p>\u003cp>如果我当时这样采用费曼技巧来帮助七七学习，相信七七很可能不需要推迟考试时间也可以顺利通过这项认证考试的。\u003c/p>","interaction":"\u003cp>【片段2学习者参考材料】\u003c/p>\u003cp>【A3促动参与】\u003c/p>\u003cp>【场景设计】\u003cbr>\u003c/p>\u003cp>好的，刚刚我们学习了费曼技巧的4个步骤，那么接下来我们就通过一个设计好的模拟场景，来实际练习一下对于这个方法的应用。请大家设想这样一个场景：\u003c/p>\u003cp>小红和小明刚刚参加了费曼技巧培训，小红前一天晚上熬夜赶项目，所以课堂上一直瞌睡，内容听的似懂非懂。下了课以后小红就问小明：“小明，我们今天学的费曼技巧究竟讲的是什么呀？你能用我听的懂的语言给我简单解释一下么？虽然有你的笔记，但是我觉得听你解释会更清楚一些。”\u003c/p>\u003cp>【小组讨论和演练】\u003c/p>\u003cp>下面就请大家阅读一下分发页2上的这个场景，结合上面给出的练习步骤以及费曼技巧的4步总结，用7分钟左右的时间在小组内讨论一下，小明该如何用我们今天学到的费曼技巧—— 1.选择主题2.自主阐述 3.查缺补漏 4.迭代完善——使用自己的语言向小红解释费曼技巧呢？\u003c/p>\u003cp>请大家设计一段小红和小明2人间的对话，并分别演练一下。有一点需要强调的是，费曼技巧中的第3步查缺补漏，既可以自己单独完成，也可以是几个人之间通过对话互相交流，或由一方为另一方指出不足这样的方式来完成的。\u003cstrong>希望大家在演练中尽量完整体现对于费曼技巧的全部4个步骤的应用\u003c/strong>。\u003c/p>\u003cp>请问我的指令清楚了么？好的那么我们开始。\u003c/p>\u003cp>稍后我会邀请一组小伙伴扮演小红和小明2人，现场为我们分享表演。\u003c/p>\u003cp>【角色扮演】\u003c/p>\u003cp>我看大家演练的差不多了，那下面请1组朋友以角色扮演的形式，为大家分享一下你们刚才的演练内容。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>【演练内容对应费曼技巧——1.选定主题】\u003c/p>\u003cp>嘉宾1:小明，今天讲的费曼技巧是什么意思呀，我有点没听明白，你能再给我介绍一下么？\u003c/p>\u003cp>【演练内容对应费曼技巧——2.自主阐述】\u003c/p>\u003cp>嘉宾2:好的，今天我们讲的费曼技巧主要是首先选择一个主题，可以是咱们日常生活中感兴趣想要学习的一个知识；然后在这个过程中你要围绕着这个主题用自己的话来进行阐述，或讲解；之后在你自己查缺补漏的过程中，你要确保无论自己的讲解无论逻辑上还是其他方面都是没有问题的。如果在这个过程中你发现有什么问题，那么可以和老师或者同学探讨一下，或者查一查资料来补足巩固知识，都可以的。学习结束后呢，你可以尝试把这个知识分享给其他人，为他人讲解一下。\u003c/p>\u003cp>【演练内容对应费曼技巧——3.查缺补漏】\u003c/p>\u003cp>嘉宾1:哦，那你说第3步查缺补漏的步骤里有个对比，具体要怎么对比呀？拿什么对比呀？\u003c/p>\u003cp>【演练内容对应费曼技巧——4.迭代完善】\u003c/p>\u003cp>嘉宾2:对比就是说我们可以使用老师讲解的内容呀，或者向同学借笔记呀都可以，然后参照这些材料做对比。\u003c/p>\u003cp>嘉宾1:哦，好的，那我回头再把老师讲的理顺一下，再看看书。谢谢你！\u003c/p>\u003cp>【反馈.摘要点评】\u003c/p>\u003cp>我们给他们鼓鼓掌好不好？这两位朋友表演的太棒了！现学现用而且对于费曼技巧这4个步骤的掌握非常的精准，尤其是第3步查缺补漏时，通过小红提出问题的设计，做到了帮助小明通过对比来查缺补漏，从而进行了迭代完善。非常非常棒！\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>【分步催化1:提问设计】\u003c/p>\u003cp>好，那么接下来到了大家发挥想象力的时候了。请大家设想一下，未来两周内有什么知识是你非常想要高效学习，却不清楚自己的掌握程度，或者很难做到深刻理解和记忆的，比如想要提升财会知识，却总是记不住专业概念和术语？或者想要改善自己的时间管理技巧，却不太能理解不同待办分类之间的区别？\u003cbr>\u003c/p>\u003cp>请将这个场景写在标签上。只需要写出场景，不需要写如何解决。然后每人用1分钟左右的时间在小组内进行讨论分享。完成的朋友请举手示意我。稍后我会邀请一位代表进行现场分享。\u003c/p>\u003cp>我看大家讨论的差不多了，哪位朋友愿意分享一下？\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>嘉宾1:我今天参加了拆书活动，觉得拆书法确实是我非常需要的，所以接下来我想要去深入了解拆书法。\u003c/p>\u003cp>【反馈】\u003c/p>\u003cp>太棒了！我们又多了一位拆书爱好者，感谢这位朋友的分享。\u003c/p>\u003cp>【分步催化2:规划应用】\u003c/p>\u003cp>那么现在就请大家结合自己刚刚提出的场景，规划一下你会在未来两周内，如何运用我们今天学到的费曼技巧，也就是——1.选择主题2.自主阐述 3.查缺补漏 4.迭代完善——的方法，来提高自己对这些知识的掌握和记忆呢？\u003c/p>\u003cp>请把目标和行动步骤的关键字写在便签上并在小组内分享你的应用计划。希望每人都用1-2分钟的时间尽量表达一下，稍后我会邀请一位朋友为大家做分享。\u003c/p>\u003cp>好的大家讨论的差不多了，哪位朋友愿意为大家做一下分享呢？\u003c/p>\u003cp>【学习者案例记录1】\u003c/p>\u003cp>【对应费曼技巧——1.选定主题】\u003c/p>\u003cp>郭峰：因为我负责会员发展，所以需要经常给人讲什么是拆书法。我觉得拆书法要经常学，深入的理解，所以我会以费曼技巧为基础，讲解拆书法和拆书帮，就像刚才给嘉宾1讲的一样。\u003c/p>\u003cp>【对应费曼技巧——2.自主阐述】\u003c/p>\u003cp>讲的过程中尽量用自己最简单的语言去把拆书法和拆书帮讲解清楚。\u003c/p>\u003cp>【对应费曼技巧——3.查缺补漏】\u003c/p>\u003cp>【对比】过程中可能还会有讲的不清楚或者不够简洁不够明确的地方，或者对方提问有疑问的地方，那我就回头再去问拆书帮的大咖，还有看拆书家手册，和拆书帮官网。\u003c/p>\u003cp>【查找】现在虽然已经讲了几次，但有时候语言感觉还不够简练，并且也需要查找一些讲遗漏的地方。\u003c/p>\u003cp>【巩固】把语言的逻辑再整理好，形成一个书面的或者关键词的介绍。\u003c/p>\u003cp>【对应费曼技巧——4.迭代完善】\u003c/p>\u003cp>然后再拿出来讲，在反复讲的过程中不断迭代，不断更新，会讲的越来越好。\u003c/p>\u003cp>【反馈.号召鼓掌】\u003c/p>\u003cp>感谢郭峰为我们分享了用费曼技巧来提高自己解释“拆书法”的水平的计划。对于费曼技巧的步骤掌握非常明确，让我们大家为他鼓掌！\u003c/p>\u003cp>还有哪位朋友愿意分享一下么？\u003c/p>\u003cp>【学习者案例记录2】\u003c/p>\u003cp>【对应费曼技巧——1.选定主题】\u003c/p>\u003cp>晓雯：我分享一下我对于思维导图的学习的计划。\u003c/p>\u003cp>【对应费曼技巧——2.自主阐述】\u003c/p>\u003cp>我会先用自己的语言来解释一下我认为思维导图是什么，我认为思维导图就是串联关键词，构成整个事情主体的大纲；\u003c/p>\u003cp>【对应费曼技巧——3.查缺补漏】\u003c/p>\u003cp>【对比】然后我会查缺补漏，先进行对比，与我的课程内容和笔记进行对比；\u003c/p>\u003cp>【查找】然后查找看看有什么漏掉的地方；\u003c/p>\u003cp>【巩固】然后对查出来的漏掉的内容重新学习和巩固；\u003c/p>\u003cp>【对应费曼技巧——4.迭代完善】\u003c/p>\u003cp>最后我学完以后，会在学习者群里给大家分享我的理解，听取大家的反馈，并根据大家的反馈，进行自己对思维导图认知的完善，再继续分享迭代完善，直到把思维导图理解透彻。\u003c/p>\u003cp>【反馈.号召鼓掌】\u003c/p>\u003cp>好的，晓雯对使用费曼技巧来学习思维导图的规划非常清晰，非常棒！让我们同样鼓掌感谢晓雯的分享！\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>有力结语\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>最后我们来简单回顾一下，今天都学了哪些方法：\u003c/p>\u003cp>第一是整体性学习法，包括获取知识，理解含义，拓展关联，查偏纠错，实践应用，测试完善，这6步；第二是费曼技巧，包括选择主题，自主阐述，查缺补漏，迭代完善，这4步。\u003c/p>\u003cp>请大家在活动之后多刻意练习，争取尽早熟练掌握这两种方法，成为高效学习者。我今天的拆解结束。感谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1575701948000,"updated_at":1575702969000,"ria":true},{"id":9020,"topic":"学习比喻法掌握知识","learn_goal":"运用比喻法三步骤掌握难理解难记忆的知识","remark":"遇到难理解的知识信息怎么办？死记硬背？那会忘的很快，用比喻法可以让你牢牢记住。","level":"TF1-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"章鱼-","city":"泰安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我叫张宇，是一名高中语文老师。目前最有成就感的一件事是能突破自我走出舒适圈，比如现在非常想接受拆书帮的“魔鬼”训练成为拆书家。在我的工作中我发现学生在做阅读理解的时候很困难，而RIA便签法给了我一个思路，让我觉得可以用它帮助学生解决困难。\r\n我个人致力于提升自己的学习能力，向“终生学习”努力。并非常想把学习的到的知识内化后把学习的能量传递给学生。育人达己。在未来拆书过级的道路上能提高自己的基础能力，成为优秀的拆书家。同时把它介绍给学生以提高学生的阅读能力。\u003c/p>","ratings_count":1,"texts":[{"id":12762,"quote":"\u003cp>拆书：\u003c/p>\u003cp>拆书是一种学习方法论，适用于想提升能力、解决问题的成人。拆书强调的是以学习者为中心，是把书本当成医生“治疗”自身不足，而不是把书当成老师“膜拜”知识。通过RIA学习法把书中的知识拆为已用。\u003c/p>\u003cp>拆书法分为应用于个人学习的便签读书法和应用于组织学习的RIA现场学习法。\u003c/p>\u003cp>主要步骤是：\u003c/p>\u003cp>第一个步骤R:Reading，阅读原文拆页。\u003c/p>\u003cp>第二个步骤I：指拆书家对原文知识拆页的讲解和对现场学习者的引导。\u003c/p>\u003cp>第三个步骤A：学习者拆为已用，要把知识关联学习者的经验、规划具体的运用。它分为3个部分：A1关联学习者过往经验，A2催化学习者应用，A3促动学习者现场演练。\u003c/p>\u003ch3>\u003cp>拆书帮：\u003c/p>\u003c/h3>\u003cp>拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。拆书帮目前在全国有47家分舵，200多会员，我们是属于其中一个正在筹备的分舵，泰安筹备分舵。\u003c/p>\u003cp>今天我们要拆的是来自于《如何高效学习》的第88页，一个关于运用比喻进行学习的片段，接下来给大家2分钟阅读拆页，阅读完毕后抬头示意我一下。\u003c/p>\u003cp>怎样应用比喻法学习条件反射?比喻法的第一步是在你的个人经验中寻找能够模拟条件反射的东西。我个人生长在加拿大的冰天雪地里，所以想到的第一个比喻就是在雪地里行走。你第一次在雪地里行走时，因为雪地茫茫一片，走哪条路都有可能。但是几次行走以后，你会选择一开始走的路，因为开始的行走在雪地上形成了一条隐约可见的小路，走这条路显然比随便走更容易。\u003c/p>\u003cp>我将雪中走路与条件反射联系在一起，一开始，铃声可能或不引起狗分泌唾液(这代表一开始雪地茫茫一片，无路可寻)。但是在将铃声和食物关联在一起后，从铃声到食物的路就在雪地上(狗的大脑里)形成了，最终狗一听见铃声就分泌唾液，因为这条路已经很明显了。像许多比喻一样，这个比喻也不完美，但是它很有用。\u003c/p>\u003cp>可以按照下面三个简单步骤找出一个比喻。\u003c/p>\u003cp>(1\u003cstrong>)确定你要深入理解和记忆的信息\u003c/strong>，在上面例子中就是经典条件反射。\u003c/p>\u003cp>(2)\u003cstrong>在你的个人经验中寻找与信息部分相似的东西，\u003c/strong>要达到完全符合不太可能，所以与其寻找一个完全符合的东西，不如稍作让步，找到十几个部分符合的“不完美比喻”，在上面的例子里我想到的是雪中行走。\u003c/p>\u003cp>(3\u003cstrong>)重复上述过程，检查比喻不恰当的地方。例\u003c/strong>如，雪中行走是线性的痕迹，而脑神经却是错综复杂的网络。\u003c/p>","explains":"\u003ch2>\u003cp>I拆书家讲解引导\u003c/p>\u003c/h2>\u003cp>\u003cstrong>What：\u003c/strong>在文学上运用比喻可以帮助人们抓住不同事物的相似之处，用浅显、具体、生动的事物来代替抽象、难理解的事物，进而帮助人们进行理解记忆。原文段也说运用比喻法就是从自己的个人经验中寻找和所要学习的信息类似的东西，然后建立模型。\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>因为有些信息难理解难记忆，为了解决这一问题，我们可以运用比喻法寻找自己容易理解深有感触的一点和要学习的信息建立联系。如果不这样做就无法检测自己是否真正记住理解了该知识。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>如何找出一个比喻呢？\u003c/p>\u003cp>\u003cstrong>1、确定信息。\u003c/strong>确定你想要深入理解和记忆的信息。\u003c/p>\u003cp>\u003cstrong>2、寻找喻体。\u003c/strong>此处不需要你找到完全相似的喻体，只要是有一点相似，不管是视觉、听觉、触觉还是直觉，也不管是原理、目的还是过程，都可以拿来比喻。而且可以寻找多个比喻。\u003c/p>\u003cp>\u003cstrong>3、优化比喻\u003c/strong>。将你想出来的多个比喻和原来的信息进行联系，找出最恰当最容易帮你理解的那一个并进行优化。\u003c/p>\u003cp>\u003cstrong>Where：适用于自学某些专业性较强的知识的时候，或者需要将一些难理解难记忆的知识教授给别人的时候。\u003c/strong>\u003c/p>","interaction":"\u003ch2>\u003cp>A1便签\u003c/p>\u003c/h2>\u003cp>2019年9月24日，我在讲评作文的时候发现同学们的作文结构不是很合理，写议论文只注重了事例的使用，没有行文的内在逻辑结构，甚至还有同学作文只有三大段。为了加深同学们对作文结构重要性的理解，我把构建作文结构比喻成捏人。写作文前只准备事例就像捏人只准备了泥，泥再多也还不是人。我们要把这个人的形状捏出来，再去补充它的血肉。然后再检查这个人是不是有身子长腿短的毛病。同学们听后哈哈大笑。这个比喻应该在他们心中留下很深的印象，再写作文的时候会考虑到结构安排的问题。\u003c/p>\u003cp>&nbsp; 反思： 当我看到原文段关于比喻法掌握知识的时候，我是激动的，我认为它可以很好的将难理解的知识和自己相关经验结合，更有效的理解掌握。我自己有时也用，但都是随机的。我没有有意识的寻找比喻，没有想出多个比喻进行对比，更没有对此进行优化形成模型。这都需要练习。\u003c/p>\u003cp>\u003ch2>\u003cp>A2便签\u003c/p>\u003c/h2>\u003cp>背景：和学生聊天的时候说到了树立目标的问题，他回答那不是好高骛远吗。\u003c/p>\u003cp>目标：用比喻法解答学生关于树立目标和好高骛远的疑问。\u003c/p>\u003cp>1、确定信息。确定要理解的信息是高中生树立目标和好高骛远的区别。\u003c/p>\u003cp>2、寻找喻体。①可以用爬泰山的比喻：两个人都站在山脚下，目标都是爬到泰山顶上看日出，一个人计划用4个小时爬到山顶，但是自己现在还办不到，他想中间借助一下缆车。另一个人体弱多病却认为自己可以依靠自己4个小时上到山顶没问题。这两个人第一个是树立目标，第二个是好高骛远。\u003c/p>\u003cp>3、优化比喻。好高骛远的意思是脱离实际地追求目前不可能实现的过高、过远的目标。一个人树立目标会是远大的，知道自己目前可能实现不了，但是可以想办法解决。可以用爬山的比喻\u003c/p>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1570516400000,"updated_at":1570692219000,"ria":true},{"id":8874,"topic":"费曼技巧 20190915","learn_goal":"运用费曼技巧，提高学习效果","remark":"","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"罗巧琴","city":"东莞市"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;各位亲爱的小伙伴们，大家上午好！我是今天的拆书家龙珠，以下是我的三个标签：爬楼中的一级拆书家、一对双胞胎的妈妈、爱上语音写作的践行者。在开始之前我们来分一下组，四人为组，共分为三组。今天我分享的主题是如何运用费曼技巧提高学习效果，它来自《如何高效学习》P134页。\u003c/p>\u003cp>&nbsp;F（特征，核心是书）:《如何高效学习》的作者是斯科特•扬（Scott Young），一位因为快速学习而成名的神奇人物，他应用自己发明的学习方法，1年拿下4门外语、用12个月自学完成麻省理工4年33门课，腻害吧。这本书就是对他学习方法的全面介绍，通过这些方法，让你也能掌握高效学习的技能，成为超级学霸。&nbsp;\u003c/p>\u003cp>A（优势，重点是比较）：以前，我们听到的多是“刻苦学习”，这本书讲的是“巧妙学习”。它系统地总结出一套高效学习的方法，强调整体性学习，实用且可操作，让你花更少的时间却学到更多的知识。同时，这本书是亚马最畅销商品，当当及中国图书网的哲学类畅销榜前50，也得到如人工智能研究者马文·明斯基、吉林省总督学孙鹤娟、北京大学计算机科学与技术系教授李晓明诸多教育界人士的大力推荐。\u003c/p>\u003cp>&nbsp;B（利益，强调的是学习者收获）：\u003c/p>\u003cp>&nbsp;B1本书益处：\r\n如果你是学生，想有针对性提高各种学科的成绩，那它提供了既可以提高成绩也能对知识理解得更为透澈的方法；如果你是成人，在学习中陷入“只见树木，不见森林”的误区，那它提供了高效学习的秘诀，以及高效处理信息、有机整合知识等技能。\u003c/p>\u003cp>&nbsp;B2这个片段益处：\r\n讲了那么多，那今天我带来了什么呢？今天学习的片段“费曼技巧”，是一项能让你实现传说中“过目不忘”的技能。当下次学习新知识时，不再是学了就忘，而是帮你加深了对知识的理解，从而延长对知识的记忆时效。\u003c/p>","ratings_count":2,"texts":[{"id":12595,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【拆书家指令】那现在请大家用2分钟时间阅读片段。（最后30秒时）读完的小伙伴举手示意一下。\u003c/p>\u003cp>【原文片段】如何练习费曼技巧\u003c/p>\u003cp>下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>\u003cstrong>第一步:选择要学习的概念\u003c/strong>\u003c/p>\u003cp>首先选好你打算深入理解的概念,拿一张空白纸,在最上方写下概念的名称。\u003c/p>\u003cp>\u003cstrong>第二步:设想你是老师,正在试图教会一名新生这个知识点\u003c/strong>\u003c/p>\u003cp>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂,并把你的解释记录下来。这一步至关重要,因为在自我解释那些你理解或不理解的知识过程中,你会理解得更好,而原先不明白的地方也得以理清。\u003c/p>\u003cp>\u003cstrong>第三步:当你感到疑惑时,返回去吧\u003c/strong>\u003c/p>\u003cp>每当你碰到难题感到疑惑时,别急着往下走,学习不是单行道,回过头来,重新阅读参考材料、听讲座或找老师解答,直到你觉得搞懂了为止,然后把解释记到纸上。\u003c/p>\u003cp>\u003cstrong>第四步:简单化和比喻\u003c/strong>\u003c/p>\u003cp>如果你的解释很啰唆或者艰涩,尽量用简单直白的语言重新表述它,或者找到一个恰当的比喻以来更好地理解它。例如:在学习力矩时,用简单的话解释力矩,而不是照抄书上的定义。比如,首先用俗语“扭曲”来说清楚力矩是什么意思。其次，给力矩找个恰当的比喻，我把力矩向量比喻为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>【学习目标】在跟随我完成本次RIA现场学习后，学习者在学习新知识时，不是模糊不清就当学过了，而是使用费曼技巧对新知识进行解释，弄明白了所学知识。\u003c/p>\u003cp>【逐字稿】好了，我看大多数小伙伴都阅读完了。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>片段告诉我们一个提升对知识理解的方法：“费曼技巧”，通过它来理清对知识点理解或讲解过程中遇到的疑惑，解决一些记不住、记不牢的浅层学习问题。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>大家不知道有没试过，对于某些知识点，有时候读一遍不明白，读两遍也不能完全明白，这个时候如果我们使用“费曼技巧”的方法，可以在短时间内帮助我们更深入的去理解知识点。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那具体怎么做呢？以下是“费曼四步法”：\u003c/p>\u003cp>1️、写下知识点，把你新学的或存在疑惑的知识点写下来。\u003c/p>\u003cp>2️、讲解知识点，对着镜子或向听众讲解这个知识点，通过自己的语言表达来加深对知识的理解，把那些明白与不明白的地方都记录下来，特别是讲解的思路和难点。\u003c/p>\u003cp>3️、讲解不畅时先弄懂知识点，当讲解遇到有疑惑或不能说下去时，停下来，重新查找参考资料或向他人咨询，直到弄懂为止。记录哪些不会的地方和解决过程。\u003c/p>\u003cp>4️、重新表述，去掉啰嗦或不够直白地方，用简单化的语言总结，并给予形象的比喻来帮助理解和加深记忆，比如，什么是构建知识体系？它就如同搭建乐高模型的过程。 \u003c/p>\u003cp>&nbsp;[预防异议]\u003c/p>\u003cp>听完后，也许有些小伙伴会觉得讲解知识点这步不好操作，有点别扭。不知道大家有没过这样的经验？有时候看的和理解的以为是一致的，但最后表达出来的却并非原来理解的。\u003c/p>\u003cp>所以如果你真的操作起来，会发现从看到这些内容到理解，再到跟他人讲解的过程事实是一个对自己思路整理的过程。\u003c/p>\u003cp>【不这样做的坏处】\u003c/p>\u003cp>如果不这么做，有可能你会以为我知道呀就是自己理解了，我会啊就是自己懂了，可当需要用到或向别人讲解时，却发现自己记不清怎么用，也没法向别人讲明白。\u003c/p>\u003cp>【这样做的好处】\u003c/p>\u003cp>那如果这么做了又有什么好处呢？第一，因为经过了大脑的思考，你会把这个知识点记得更牢；第二，它往往容易让你有新的发现，挖掘到一些之前可能忽略的信息。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>不过值得注意的是，“费曼四步法”它适用于新的知识点理解或以深入学习为目标的人。一些简单、易记的知识点就不适用于它啦。\u003c/p>\u003cp>【A1】\u003c/p>\u003cp>来，我跟大家分享一个有趣的例子哈！7月我参加了一个业务培训，老师课上讲了很多业务开拓的技巧，其中提到一个叫“一户6开”，第二周回单位，我需要跟同事分享培训内容，当我提到“一户6开”的时候，有个同事提问，哪6开啊？为什么是6开？记得老师讲的当时，我顺着老师思路，还想到9开，可当同事问的时候我却怎么也想不齐全是哪6开，唉哎，好尴尬，还好有笔记，当然我也很机智，反问他平常开户都让客户开哪些业务？在他思考的空档，我拿出手机来回顾笔记，然后告诉他哪6开，原因何在，有什么好处。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>通过今天的片段学习，我知道我无意识的用了不完整的“费曼四步法”，所以，如果重来，我会这么做：\u003c/p>\u003cp>1. 在培训学习的当天，写下“一户6开”并进行复习。\u003c/p>\u003cp>2. 向我的同房讲述如何营销“一户6开”，并把我顺着这个思路想到的9开也说出来（手银、网银、公众号绑定、灵活息、风评、第三方存管、第三方支付、信用卡、信用卡自扣）。\u003c/p>\u003cp>3. 假如讲的时候不记得，回去看笔记，回想一下老师当时是怎么说的，为什么要做这6开，它的好处在哪里。\u003c/p>\u003cp>4. 简化和适当运用比喻，帮助他人理解的同时便于回忆。例如“一户6开”如同你下载了一个京东APP，它除了向你推荐它的超市、唯品会、沃尔玛，还会诱导你开通PLUS会员、支付的时候让你用白条，那么京东APP便达到目的成为你手机不可或缺的一个。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>好了，经过刚才的学习和举例，相信你已知道如何用“费曼四步法”来进行学习或强化学习效果了，现在请你想一下，在未来一周，你可能会遇到哪些情景可以使用它呢？比如，在单位学习了一个新的产品，你要转培训时；或者在课堂上老师讲了一个新的技能，你要掌握它时；又或在复习以前学过但不熟悉的学习方法时…。注意哈，只需要设想一个场景+你需学习的知识点即可，然后把它写下来。时间1分种，待会我邀请2位小伙伴来分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>学习者茉莉：下周学习素描的时候应用“费曼四步法”加深对“阴影表达”这个知识点的表现。\u003c/p>\u003cp>学习者丹妮：下周应用“费曼四步法”向老师培训“参考咨询”这个知识点。\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>感谢分享。现在大家都有一个需要深入学习的内容吧。那么，请你使用今天所学的“费曼四步法”，制定一个详细的学习计划，然后在小组里讨论分享，一会我邀请1位小伙伴来分享。时间4分钟。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>学习者红梅：运用“费曼四步法”对刚学会的一个效能类APP绘图功能应用于转培训，一是找出APP绘图功能所在，二是向小伙伴讲述如何应用绘图功能对客户进行营销，三是假如忘记了部分操作，回顾老师学习的内容后再继续演示，四是整理简化刚才的操作步骤，列出12345操作前的提示语，帮助记忆操作，就像出门要带身份证、手机、钥匙、钱包的提示语“身手钥钱”。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 非常感谢小伙伴的分享。\u003cstrong>看来大家已经能够使用“费曼四步法”的方法学习了，\u003c/strong>希望大家能主动应用今天学到的内容用来帮助自己获得更好的学习成果。我今天的分享到此结束，谢谢大家。\u003cbr>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1568560021000,"updated_at":1570602732000,"ria":true},{"id":8800,"topic":"如何实现高效学习","learn_goal":"学习运用费曼技巧高效学习","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"乐之","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>【自我介绍】\r\n大家好，我是乐之，乐是快乐喜乐的乐，之是之乎者也的之。知之者不如好之者，好之者不如乐之者，希望自己做个乐在其中的人。\r\n我用三个标签介绍下自己，第一个标签，我是一名自由职业者，之前一直是一名财务经理人，正在转型成为财务培训师。\r\n第二个标签是喜欢读书。我现在最大的爱好就是读书，工作中也需要大量的阅读。\r\n第三个标签是喜欢拆书。非常喜欢赵周帮主的这样一句话，“总是把知识化成斗志，难免在失败和空谈中黯然神伤；真正把知识拆为己用，就能从一个成功走向另一个成功。” 我把拆书思维用在国学的学习上，这两年有质的改变。学着搭建自己的知识体系，综合能力在逐步提升。\r\n【介绍拆书和拆书帮】\r\n那什么是拆书呢？\r\n“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。\r\n拆书法分为个人学习和组织学习。\r\n个人学习，简单来说有这么几个步骤，首先是选书，根据自己想要解决的具体问题，或要提升的某个方面能力，选择致用类的图书。然后是读书，先通过比较快的速度找到对自己重要的片段，然后慢速阅读。再然后，是写三个便笺。\r\n这是三个便笺，第一个便笺是自己对这段文字的理解，第二个是自己过去的相关经验，第三个是自己以后的具体应用。通过三张便笺，加深了对知识的理解，反思了自己的经验，更重要的是能学以致用。这是个人学习的拆书法，也叫做拆书帮便签学习法。\r\n组织学习，就像今天这样，一位拆书家拿一本书，加工出一场现场学习，引导和促进一群人把知识拆为己用。\r\n组织学习有RIA三个核心环节。R是阅读拆页。I是拆书家讲解引导，促进学习者理解知识并关联自己。A是拆书家促进学习者将书中内容拆为己用。\r\n个人学习和组织学习，都是基于RIA便笺法的学习。简单来说，个人学习是一个人的学习，组织学习是一群人学习。组织学习需要由拆书家引导大家学习，个人学习一个人就可以完成。\r\n那拆书帮是个什么样的组织呢？\r\n拆书帮是基于拆书法的非盈利性的学习社群，是陪伴拆书家的成长平台，是由知名学习类图书《这样读书就够了》的作者赵周创立的。拆书帮在全国设有七十多个分舵，拆书家在各个分舵里参与活动。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":12508,"quote":"\u003cp>接下来是阅读拆页的环节。\u003c/p>\u003cp>我们先来看下拆页，左上角的位置，学习主题是“高效学习”，学习目标是“学习运用费曼技巧高效学习”。\u003c/p>\u003cp>右边是记笔记的位置，请大家在读的时候，结合三个便笺写下自己的笔记。\u003c/p>\u003cp>给大家二分钟的时间，现在开始。\u003c/p>\u003cp>费曼技巧的具体措施：（1）理解那些你没有真正掌握的知识点。（2）记住那些你能理解，却可能在考试中遗忘的知识点。（3）作为一个考前学习的高效率方法。很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只需花上20分钟就能深入理解知识，而且记忆深刻，难以遗忘。\u003c/p>\u003cp>下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>第一步：选择要学习的概念。\u003c/p>\u003cp>首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp>第二步：设想你是老师，正在试图教会一名新生这个知识点\u003c/p>\u003cp>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清。\u003c/p>\u003cp>第三步：当你感到疑惑时，返回去吧\u003c/p>\u003cp>每当众多碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>第四步：简单化和比喻\u003c/p>\u003cp>如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003c/p>\u003cp>例如：在学习力矩时，用简单的话解释力矩，而不是照抄书上的定义。比如，首先用俗语“扭曲”来说清楚力矩是什么意思。\u003c/p>\u003cp>其次，给力矩找个恰当的比喻，我把力矩向量比喻为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>","explains":"\u003cp>好了，大家读的差不多了。接下来，我分享下对这个片段的理解：\u003c/p>\u003cp>[what]\u003c/p>\u003cp>费曼技巧，是在自己要深入学习某个知识点时，设想要教会没有这方面基础的人，在一张纸上写上要转述给别人的内容，并将转述内容简单化和形象化，以达到高效学习的目的。\u003c/p>\u003cp>[why]\u003c/p>\u003cp>我们很多时候的学习，根本不会去想着教会别人，所以很多时候以为自己理解了、搞懂了。试着去讲给别人听、教别人，才发现，自己还远远没有搞懂搞透。\u003c/p>\u003cp>对于一些比较难的知识点，如果我们不去复述，不加以简单化、形象化，转化成自己的语言，是很难记住，或者很难长时间记住的。\u003c/p>\u003cp>费曼技巧在三个方面可以帮助我们更高效的学习：\u003c/p>\u003cp>第一，费曼技巧可以帮助我们更好的理解知识点。\u003c/p>\u003cp>当我们讲述给别人听时，我们可能会发现自己讲不明白，也可能别人听不明白。这时需要我们回头再去学习回顾知识点，直到真正掌握并能讲述。这样的学习，可以有效的促进我们对知识点的深入理解。如果从一开始就以讲述为目的进行学习，学习会更加主动，理解也会更加深入。\u003c/p>\u003cp>第二，费曼技巧可以帮助我们更容易记住知识点。\u003c/p>\u003cp>通过对知识点的复述，通过对知识点的深入理解，通过对知识点的简单化和形象化，我们可以更容易的记住知识点。\u003c/p>\u003cp>第三，费曼技巧对通过考试也很有帮助。\u003c/p>\u003cp>运用费曼技巧高效学习，我们可以用自己的观点复述知识点，能记住知识点，对考试的帮助也是非常明显的。\u003c/p>\u003cp>[how]\u003c/p>\u003cp>那怎样运用费曼技巧学习知识点呢？总共有四个步骤：\u003c/p>\u003cp>第一步，选择知识点。选择想要深入学习的知识点，拿出一张白纸，最上方写上知识点的名称。\u003c/p>\u003cp>第二步，写内容。想象去教会别人，想象教的人是没有这个知识点储备的，想象怎么能深入浅出的让别人听懂，然后写出知识点的内容。这一步会促进自己对知识点的深入理解，特别是一些比较模糊、模棱两可的理解。\u003c/p>\u003cp>第三步，搞懂知识点。写内容可能会遇到困难，可以暂停，通过看资料、听课、请教别人，去真正搞懂搞透知识点。\u003c/p>\u003cp>第四步，简单化和形象化知识点。简单化是用生活化、简单直白的语言，形象化是用比喻的方法。\u003c/p>\u003cp>比如拆书法的致用类阅读，把书当作医生。医生是连小朋友都知道的职业，医生的主要职责是看病，致用类的阅读主要是解决问题，把书当作医生，既简单又形象。\u003c/p>","interaction":"\u003cp>【A1便签】\u003c/p>\u003cp>接下来，给大家分享下我的经验：\u003c/p>\u003cp>2016年下半年，我开始学习一些培训方面的知识。我从一本书上看到一个知识点叫“五星教学法”，这个教学法以学员以中心，重视学员的参与，符合人的认知规律，学员体验会非常好。于是，我把书看了好几遍，还有一个微课，也听了两三遍。当时以为，自己看了几遍、听了几遍应该理解了、记住了。\u003c/p>\u003cp>直到2017年6月，参加了一场“五星教学法”的现场培训，分组活动讲解“五星教学法”，才发现自己还远没有理解和搞透。\u003c/p>\u003cp>如果当时掌握了费曼技巧，可以运用费曼技巧的四步法来学习“五星教学法”：\u003c/p>\u003cp>第一步，可以找一张A4空白纸，写下“五星教学法”。\u003c/p>\u003cp>第二步，写内容。想着去教会别人，别人怎样才能听懂，写下相应的内容。\u003c/p>\u003cp>第三步，搞懂知识点。如果没写明白，说明自己还没真正搞懂，要去再学习、理解。\u003c/p>\u003cp>第四步，简单化和形象化知识点。用直白的语言，简单描述。这样，我就能更加理解这个知识点，用自己的语言输出，而且有视觉化的笔记，也能更容易的记住知识点。\u003c/p>\u003cp>运用费曼技巧学习，可以深入理解知识点，而且更容易记住。\u003c/p>\u003cp>【A2便签】\u003c/p>\u003cp>这些是我的经验和反思，那接下来我准备怎么运用今天这个拆页片段呢？\u003c/p>\u003cp>我定的目标是，2019年9月，用费曼技巧学习二级技能点，至少完成2-1和2-2的7个技能点的学习。根据拆书进度，适当学习2-3和2-4的技能点。\u003c/p>\u003cp>我的关键行动， 是运用费曼技巧的四步法来学习。\u003c/p>\u003cp>第一步，设计简单的A4纸模板，每张模板写一个技能。\u003c/p>\u003cp>第二步，写内容。根据手册技能点解释及案例，写出技能的主要内容。\u003c/p>\u003cp>第三步，搞懂知识点。写内容会遇到很多障碍，可以多学习手册、实录、请教别人、写拆页获得反馈，去真正搞懂技能点。\u003c/p>\u003cp>第四步，根据某个具体的技能点，去简单化和形象化技能点。\u003c/p>\u003cp>这是我的规划应用。\u003c/p>\u003cp>以上就是我这个片段的拆书，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1567931152000,"updated_at":1567931338000,"ria":true},{"id":8476,"topic":"如何在工作生活中保持源源不断的活力和热情","learn_goal":"-","remark":"-","level":"TF1-1","duration":12,"status":29,"type":0,"chaishujia":{"username":"啸野","city":"滨州"},"club":{"name":"济南海右分舵","city":"济南"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;大家好！我是啸野，我是一名HR，我是一名非常喜欢运动和户外的HR，各类运动项目我都比较喜欢，我曾经参加山西五台山的徒步朝拜之旅，全程徒步56公里，除了五台山我也游览过其他的像普陀山等佛道名山圣地，因为我也是一名道家修行者。我喜欢学习并且追求突破。去年有幸结识了拆书帮，刚进入拆书帮希望有一天可以实现拆书变现，但是参加过一次线下活动后，我希望我是一个分享者，希望分享自己各种游历故事以及学习中的感悟，让大家可以有所收获。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;\u003cp>&nbsp; &nbsp; &nbsp; 那下面就让我带领大家一下再次了解什么是拆书？拆书是一种学习方法论，简单说就是把书中知识拿出来，经过提炼和加工后，能够与我们的现实生活相结合，并且指导我们如何运用到现实生活的技巧和方法，它强调以学习者为中心，也是一种非常适用于以提升能力、解决问题为目标的成人学习法。那我们怎么学习拆书法呢，那就是加入拆书帮。我一直喜欢阅读，但是也常有读完就会忘记书中的内容。参加拆书帮训练营后我发现拆书便签法是一个非常实用的读书方法。什么是“RIA”，R为Reading，指阅读原书拆页，I为Interpretation，是指拆书家对原文知识拆页的讲解和对现场学习者的引导，A为Appropriation，就是拆为己用。A又分为：A1是激活学习者经验，关注的是过去经验；A2是催化学习者应用，指向的是未来。通过RIA拆书法可以帮助我们更清晰的梳理和掌握书中的内容。拆书帮在全国有许多分支机构，我去年加入济南日天分舵，感受到了拆书帮带给自己的能量。希望更多的小伙伴可以成为拆书家，也帮助我们成为更好的自己。\u003c/p>\u003c/p>","ratings_count":3,"texts":[{"id":12130,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cp>【R】阅读原书拆页 &nbsp;来源：《如何高效学习》\u003c/p>\u003cp>接下来，邀请大家一起阅读一下我为大家准备好的原文片段，时间是2分钟，请大家读完后举手示意我：\u003c/p>\u003cp>R:循环式作息计划\u003c/p>\u003cp>线性的计划是平均安排时间执行工作，而循环式作息计划则先集中小部分时间做大部分工作。这种计划安排能让你做到有张有弛，而不是死气沉沉，像个机器人。下面是一些建议\u003c/p>\u003cp>（1）一周休息一天。我总是抽出一周中的一天，什么事也不做，将7天的活放在6天里完成，一开始很难，但是放松一天能防止你筋疲力尽。\u003c/p>\u003cp>（2）晚上不干活儿。将一天的工作放在早上集中完成，早早完成工作，晚上你就有几小时的空闲了。\u003c/p>\u003cp>（3）设定90分钟。给定自己90分钟，集中精力完成某个学习任务一旦90分钟结東，停止工作。90分钟的时间设定能让你学习时注意力更集中。\u003c/p>\u003cstrong>\u003c/strong>\u003c/p>","explains":"\u003cp>好，现在小伙伴们都完成了阅读，接下来我给大家分享我的&quot;I&quot;便签：\u003c/p>\u003cp>\u003cstrong>what:\u003c/strong>该片段告诉我们在面对学习或者有紧急任务的情况下，如何安排时间从而拥有更高效且健康的生活。\u003c/p>\u003cp>\u003cstrong>why:\u003c/strong>日常生活中我们大部分人基于学习的需求或者工作中的紧急安排，往往把时间安排的让自己精力耗尽，就像机器人一样连轴转，导致工作生活毫无幸福感。而片段中的方法就提醒了我们，拥有高效而幸福的生活可以通过什么样的方式实现，让我们更好的享受生活和工作。\u003c/p>\u003cp>\u003cstrong>how\u003c/strong>:在日常的生活中，我们如何合理的安排自己的周、日计划呢？\u003cbr>\u003c/p>\u003cp>①一周至少给自己一天休息时间，用来彻底的放松。\u003c/p>\u003cp>②将一天的工作尽量安排在白天完成，晚上留出点空闲时间来休息。\u003c/p>\u003cp>③设90，工作停：给自己设定90分钟时间，到了就休息。\u003c/p>\u003cp>\u003cstrong>where：\u003c/strong>\u003c/p>\u003cp>适合：\u003c/p>\u003cp>问题：学习或者工作中时间管理复盘（反思总结）的时候使用。\u003c/p>\u003cp>使用者：有强烈改变欲望的人或有监督者的人。\u003c/p>\u003cp>不适合：\u003c/p>\u003cp>使用者：无改变欲望且无监督者的人。\u003c/p>\u003cp>问题：被迫完成且紧急的任务\u003c/p>","interaction":"\u003cp>\u003cstrong>下面分享我的A1便签\u003c/strong>\u003c/p>\u003cp>我在做半年总结时发现连续的早起晚睡的习惯，让我的工作和生活状态都不是很好。\u003c/p>\u003cp>反思：经过反思，我发现自己没有给自己安排休息时间，让身心放松休息。\u003c/p>\u003cp>结果：工作压力暂时没法完全排解，生活状态也没有得到改善。\u003c/p>\u003cp>如果用文中提到的方法进行改善的话，我会每周给自己安排休息一天，啥都不做尽情放松。工作和学习都尽量集中，晚上留几个小时的空闲时间。如果晚上学习的话，设定90分钟，时间到了就休息10分钟，让身体有休息的转换。\u003c/p>\u003cp>\u003cstrong>分享A2便签\u003c/strong>\u003c/p>\u003cp>我的应用A2便签：\u003c/p>\u003cp>目标：我7月开始了第一次拆书升级之旅，我的目标在10月前成为二级拆书家，目前的工作也十分紧凑，为了能更高效的完成学习和工作，我会连续一个月每周日晚上进行总结、复盘。\u003c/p>\u003cp>具体行动：向自己发问：这个月内我每周是否安排了一天休息？每天是否有给自己安排休息的空档，感觉怎样？学习效率是否有提升，工作状态和生活是否得到改善？\u003c/p>\u003cp>时间：一个月内\u003c/p>\u003cp> 对象：自己\u003c/p>\u003cp>\u003cstrong>奖惩：\u003c/strong>\u003c/p>\u003cp>&nbsp;完成奖励自己吃一次火锅。\u003c/p>\u003cp>&nbsp;没有就罚自己跑步三公里。\u003c/p>\u003cp>我的分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1563892374000,"updated_at":1563892735000,"ria":true},{"id":8458,"topic":"个人学习","learn_goal":"如何让自己高效学习","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"斑驳阳光","city":"上海市"},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我叫周秧秧，是一名市政专业建造师，也是一名新手拆书家。今天拆1-2级别，为了便于伙伴们在组内进行讨论、分享，我们先来分个组，后面四位伙伴分为一组，前面四位伙伴分为一组，大家用眼神链接一下组员，有不明白分组情况的告知我，我再确认下。好的，都清楚了。下面我们将正式进入拆书环节。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":12108,"quote":"\u003cp>下面我来演示费曼技巧的操作流程。\u003c/p>\u003cp>第一步:选择要学习的概念\u003c/p>\u003cp>首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp>第二步:设想你是老师，正在试图教会一名新生这个知识点\u003c/p>\u003cp>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清。\u003c/p>\u003cp>第三步:当你感到疑惑时，返回去吧\u003c/p>\u003cp>每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>第四步:简单化和比喻\u003c/p>\u003cp>如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003c/p>","explains":"\u003cp>好，看大家都阅读的差不多了，那我们一起来理解下这个拆页。\u003c/p>\u003cp>【WHAT】该片段通过四个步骤来引导读者学会用费曼技巧来实现高效学习。费曼技巧是集输入、验证、再输入、输出固化，整个过程的主动、高效的一种学习方式，它可以帮助学习者更高效、更深入、更持久地掌握知识；\u003c/p>\u003cp>【WHY】传统的学习方式比较被动，容易停留在想当然的理解上，由此也会产生很多思维和理解上的盲区。\u003c/p>\u003cp>【HOW】费曼技巧具体分为四步来实现：\u003c/p>\u003cp>［选定概念］选定一个你想要深入理解的学习概念。\u003c/p>\u003cp>［以教促学］假想一个零基础的孩子，也可以真实地教授一个零基础的孩子，通过教来促进自己更深入地理解和领会。\u003c/p>\u003cp>［重新学习］遇到讲不明白的地方，或者对方听不懂的时候，回到学习资源，或请教专业人士，直到完全弄通。\u003c/p>\u003cp>［简要重述］把整个教的过程以及解决难题的过程重新梳理和重述，固化知识。\u003c/p>\u003cp>为了便于大家更好地理解今天的新知，我给大家举个我应用费曼技巧学习快速阅读的案例吧。\u003c/p>\u003cp>【时间】&nbsp;上周五\u003c/p>\u003cp>【起因】&nbsp;我报了一个快速阅读的训练营，头两天一直没有找到快速阅读的感觉。\u003c/p>\u003cp>【经过】&nbsp;第三天接到孩子即将参加的暑期营老师的通知，需要让孩子在开营前尽可能多地了解夏商周的知识。如何在有限的时间内，让一个小孩尽可能多地了解夏商周的知识呢？我突然想到我刚刚在学的快速阅读法，我试着把学到的快速阅读内容进行简要梳理后，手把手教给孩子，在教授的过程中，遇到了不少讲不明白，孩子也听不懂的地方，我重新回到课件，还请教了教练。在我的引导下，2小时不到，孩子完成了3本儿童历史书籍。最后我还把整个教学过程及解决疑难的过程用语音写作的方式记录下来，固化了知识。\u003c/p>\u003cp>【结果】我发现我自己对于快速阅读已经有了更深的理解，阅读速度得到了质的飞跃。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1\u003c/strong>\u003cstrong>】拆书家提问设计\u003c/strong>\u003c/p>\u003cp>好的，在理解了今天学习的新知内容，以及了解了新知的应用场景后，接下来请大家回想一下，自己在学习某个概念的时候，有没有感觉学得特别费劲或者特别低效让人沮丧的时候呢？比如你怎么学习游泳的？怎么学习思维导图的？在小组内分享。时间3分钟。结束后，我会邀请一位伙伴进行分享。提醒大家的是，分享时应有明确的时间、地点、人物、起因经过、结果，主要是真实地记录当时你的做法！现在开始计时。\u003c/p>\u003cp>【学习者自力】案例分享：\u003c/p>\u003cp>我在学习蛙泳的时候，一直游不了太远，后来通过网上查询之后，才知道有个假呼吸的概念没有搞明白。导致一直以错误的方式在呼吸，错误的呼吸方式导致我一直进入不了长距离的游泳状态。\u003c/p>\u003cp>【拆书家导引】\u003c/p>\u003cp>非常感谢自力分享的案例，需要提醒的是，在分享过往案例时，最好把具体的时间匹配上去，形成一个可链接、可追溯的完整案例。自力给我们分享了一个游泳的经历，在这个案例中，有一个呼吸概念，自力一直没有搞明白，导致游不远，通过今天的学习内容，可以试着给零基础的孩子解释解释这个概念，解释不清楚的时候就可以请教下教练，把这个概念自己能表述清楚之后，再通过应用来固化知识，我相信下次游的时候肯定就比较顺畅了。好的，再次感谢自力的分享。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>接下来，请大家设想一下，在未来一周内你有什么学习内容，可以实践这个方法。大家可以参照下我的行动步骤模板，在便签上写下你的应用步骤。需要提醒大家的是，你的行动计划中需要有具体的时间、可衡量可预期的目标、可执行的行动步骤。时间是2分钟，写完后把便签交给我。现在开始。\u003c/p>\u003cp>【学习者大白】A2目标及行动计划分享：\u003c/p>\u003cp>目标：本周末，我计划在家用费曼理论学习RIA便签法，并记录。\u003cbr>\u003c/p>\u003cp>1、选定RIA的学习概念。\u003c/p>\u003cp>2、找身边的人分享。\u003c/p>\u003cp>3、教的过程中不清楚的点回顾、总结、反思，在手册中寻找答案。\u003c/p>\u003cp>4、再梳理，记录。\u003c/p>\u003cp>【结语】\u003cbr>\u003c/p>\u003cp>好的，非常感谢大家的积极参与，今天我们主要是学习了费曼理论的四个步骤，希望伙伴们在今后的工作和学习中，能够应用今天学到的内容，让我们的学习更加高效。今天的拆书分享就到这里，非常感谢大家的陪伴和聆听，谢谢！\u003c/p>\u003cp>（学习者案例根据语音分享及便签整理）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1563721181000,"updated_at":1563844519000,"ria":true},{"id":8274,"topic":"提高学习效率","learn_goal":" 通过对本拆页的学习，让学习者认识并了解整体性学习的方法，并","remark":"本书从一位“学习大师”的亲身体验出发，总结出“整体性学习”的策略及方法，同时，配合作者实际运用的各种学习工具，切实帮助学习者练就高效的“学习方法与学习习惯”。方法决定一切，你一定可以从中有所受益。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"木木33","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"【自我介绍】亲爱的小伙伴们，大家好，我是木木。三个标签介绍自己，拆书家，整理咨询师，户外爱好者。\r\n（分组）我们继续沿用刚才的分组，三位小伙伴一组，两位小伙伴一组。\r\n【学习者场景法图书介绍】\r\n（场景）不知道大家有没有这样的感受：特别想要好好学习，但是无从下手。报了很多很多这样的培训班，学的一多，就各种慌乱，懵掉了，只能记得一小部分；每天晨起打卡，社群共读，好不容易看完一本书，然后，什么都讲不出来，也不知道可以怎么用。\r\n（提问）小伙伴们有没有类似的困惑呢？秋千，你有吗？大学教师有这样的困惑吗？\r\n（学习者互动）\r\n秋千：学校里面还好。\r\n拆书家：学校里面还好，在什么时候不太好呢？\r\n秋千：在互联网上报的课程就会觉得跟不上，很难消化吸收，报的越多越焦虑。\r\n（影响）是的，这是因为欠缺了一项能力——将任何一个知识都搭建进自己的知识体系的能力。没有这种学习能力，知识永远是松散的，你需要花更大的精力来进行记忆，现在信息发展的这么快，需要学习大量的知识，就会让你不知所措。\r\n（解决）今天这本书《如何高效学习》中的片段为大家带来的“整体性学习法”可以提高我们这种学习能力，帮助你建立自己的知识体系，让知识随时可以为你所用。\r\n【学习目标】今天的学习目标是：学习者运用（行为）“整体性学习三步法”（澄清）搭建一个简单的知识结构（界定）。\r\n【A1测试题】\r\n在阅读片段前，邀请小伙伴们做个小测试。请看测试表，请大家用一分钟的时间给自己打分，（注意1分代表与你的情况完全不符合，6分代表与你的情况非常符合）打完分后请大家汇总一下，做好的小伙伴请示意我：\r\n序号 内容 得分（1分完全不相符，6分是完全相符）\r\n1 学习新知识时，我总会查找资料，通过多种方式去理解。 1 2 3 4 5 6\r\n2 学完知识后，我还知道它们是如何推导出来的。 1 2 3 4 5 6\r\n3 我会对类似的知识点进行比较和分析。 1 2 3 4 5 6\r\n4 我大脑里有很多知识点，它们联系紧密，可以随时调用。 1 2 3 4 5 6\r\n5 关于概念，我会联想到其它事物来记住它们。 1 2 3 4 5 6\r\n总分 \r\n【I测试题解释+和学习者互动】\r\n这套自测题用来检测平时学习的习惯和方法，帮助我们更好的了解自己，大家不要紧张。\r\n得分20分以上的小伙伴举手示意一下，两位，恭喜你们，已经具有很强的学习能力了，如果能掌握整体性学习，学习能力会有更大的提升。\r\n得分在10到20分的小伙伴请举手示意一下，剩下的小伙伴都在这个分数段，显然你们已经走在了通往高效学习的路上，更要特别关注合适的学习方法。今天没有10分以下的小伙伴，无论分数如何大家都不要灰心，今天我将为大家分享高效学习的方法。","ratings_count":1,"texts":[{"id":11894,"quote":"\u003cp>\u003cstrong>【R：阅读原文】\u003c/strong>\u003c/p>\u003cp>《如何高效学习》\u003c/p>\u003cp>整体性学习需要采用多种途径综合学习，而不是试图在大脑中复制一个完美的拷贝，整体性学习是运用你大脑里已有的丰富的神经元网络吸收，整合信息。整体性学习在于创造信息的网络，一个知识与另一个知识相互关联，那些互相关联的知识网络使你真正做到对知识的完全理解，从而轻松地驾驭知识。\u003c/p>\u003cp>整体性学习意味着知识的学习并不是孤立的。事实上，知识的学习从来就不是孤立的，学习任何知识（概念，定义，公式，问题，观点，理论等）都需要联系。你创造的联系越多，它们就会记得越牢，理解得越好。\u003c/p>\u003cp>机械记忆认为学习就像整理一个个大小不一的盒子。一个数学大盒子里装有代数，几何，微积分小盒子。微积分小盒子里又有更小的函数盒子和一些公式的应用盒子等。在你的微积分盒子里不可能找到生物，历史，绘画，舞蹈和科幻电影的踪迹。\u003c/p>\u003cp>但是学习并不是整理盒子，学习就像编织一张大网。\u003c/p>\u003cp>整体性学习者不会采取这样有组织的方法（整理盒子）储存信息（这可能会解释很多聪明的人组织能力却很差的现象）。整体性学习者可以将所有东西关联起来，公式并不仅仅是公式，它是一种感觉，一幅图像，你可以将它与天上飞行的超音速飞机联系在一起。\u003c/p>","explains":"\u003cp>\u003cstrong>【I:重述原文】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>我们想学好英语，晚上背了20个单词，一觉醒来，还记得几个？（学习者回应：一个/两个）看了一本书，非常想把所学的知识讲给别人，每次都会卡壳，甚至大脑一片空白，这是因为没有建立这部分的知识结构。会学习的人都是有套路的，他们将所学的知识与其它相联系，建立牢固的知识链接体系，能够随时调用这些知识为自己所用。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>整体性学习是通过观察会学习的人如何学习而得到的总结。\u003c/p>\u003cp>提问：片段中有哪些对“整体性学习”进行描述的关键词？哪位小伙伴愿意分享下？\u003c/p>\u003cp>婷英：找到关联，互相联系\u003c/p>\u003cp>拆书家：找到关联，互相联系，还有吗？\u003c/p>\u003cp>秋千：多途径的综合学习。\u003c/p>\u003cp>拆书家：多途径的综合学习，还有吗？\u003c/p>\u003cp>秋千：整合信息，联系。\u003c/p>\u003cp>拆书家：整合信息，联系。好谢谢大家。整体性学习采用各种方法将知识进行联系成为一个系统。\u003c/p>\u003cp>\u003cstrong>【概念对比+学习者互动】\u003c/strong>\u003c/p>\u003cp>为了让大家进一步的理解整体性学习，我举几个例子，请大家判断一下：\u003c/p>\u003cp>【反例一】：每天背30个单词，早中晚各复习一次，是整体性学习吗？\u003c/p>\u003cp>\u003cstrong>（学习者回应）\u003c/strong>不是。\u003c/p>\u003cp>拆书家：对，不是。整体性学习不是单一的，学习方式更加丰富多样，更加的灵活。\u003c/p>\u003cp>【反例二】：阅读《再见，拖延症》这本书的时候，想到和之前看的《战胜拖延症》中的内容有很多一样的。是整体性学习吗？\u003c/p>\u003cp>\u003cstrong>（学习者回应）\u003c/strong>不是/是。\u003c/p>\u003cp>拆书家：不是的，整体性学习强调关联所有事物，而不仅仅是同类。\u003c/p>\u003cp>【反例三】：小明成绩优异，无论是语文，数学都有方法的进行。这个是整体性学习吗？\u003c/p>\u003cp>\u003cstrong>（学习者回应）\u003c/strong>是的。\u003c/p>\u003cp>拆书家：这里有两种情况，如果小明是将所有学科作为一个系统来进行学习，就是整体性学习，如果单独语文按照语文的学习方法，数学按照数学的学习方法，它们是分开进行的话，就是零散的，不是整体性学习。\u003c/p>\u003cp>\u003cstrong>根据以上的列子，我给大家列出了“机械性记忆”和“整体性学习”的区别：\u003c/strong>&nbsp;\u003c/p>\u003cp>【重点难点总结】\u003c/p>\u003cp>可以发现整体性学习的重点是：采用各种方法，将所有知识链接成一个整体，建立系统的知识结构。难点在于给不同的知识之间搭建桥梁的时候需要熟练的使用对比，联想等各种手法。\u003c/p>\u003cp>【适用边界】整体性学习适用于逐步建立自己的知识体系，不适用于需要死记硬背的内容和应对短时间的突击考试。比如说，我用这种方法突击三个月，就可以在高考中战无不胜，这种是不适用的。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>知道了这种高效的学习方法，相信大家一定非常想了解如何进行整体性学习。它共有三步：\u003c/p>\u003cp>\u003cstrong>一、收集信息\u003c/strong>。\u003c/p>\u003cp>我们现在收集信息的渠道很多，现在大家一般第一时间收集信息会走什么渠道？（学习者回应：百度/网络搜索），网络搜索（百度），我们还可以询问他人，比如我们的导师，我们的同行给我们的一些信息，过往知识的积累，阅读.....等等新旧知识，因为信息量非常大，我们要对信息进行筛选和简化，特别注意的是提炼出对\u003cstrong>当下有用\u003c/strong>的信息。\u003c/p>\u003cp>\u003cstrong>二、关联信息。\u003c/strong>从三个方面进行联系。\u003c/p>\u003cp>1.背景。它从哪里来的？\u003c/p>\u003cp>2.同类。常用对比建立联系。比如：苹果和桔子，它们的不同点是什么呢？颜色不同，味道不同……相同点是什么呢？都是水果。\u003c/p>\u003cp>3.不同类。常用的方法是联想。比如：《这样读书就够了》这本书就好像一把钥匙开启了我的智慧之门。就把钥匙和这本书建立了一个联系。\u003c/p>\u003cp>通过以上三步不仅扩展了新知识并且和旧知识建立了联系。\u003c/p>\u003cp>在这里要特别注意：同类和不同类对于每个人有不同的标准。请大家不要执着于纠结这个点，无论是哪一类，我们的目的是建立所有事物之间的联系。让它们方便随时为我所用。\u003c/p>\u003cp>\u003cstrong>三、持续迭代。\u003c/strong>\u003c/p>\u003cp>在工作和生活的过程中，不断的在原有的结构中增加新的内容，建立更多旧知识之间的链接，使内容更加的丰富，结构更加的稳固。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>在这里给大家分享一个我自己的例子：通过《提问力》这本书籍搭建简单的知识结构。\u003c/p>\u003cp>\u003cstrong>一、收集信息\u003c/strong>。我主要是通过百度。\u003c/p>\u003cp>\u003cstrong>二、关联信息。\u003c/strong>从三个方面进行联系。\u003c/p>\u003cp>1.背景。作者：赵周老师，2018年出版……\u003c/p>\u003cp>2.同类。同类书籍：《学会提问》《如何有效的提问》……如果我看完了这两本书后，就和《提问力》一起增加了关于“提问”的一个能力。\u003c/p>\u003cp>3.不同类。除了书籍，现在我们还有很多的栏目也提供关于“提问”的一些知识讲解，比如：得到，今天我们现场有几位洋葱俱乐部的学习者，在洋葱俱乐部里也是可以学到这样的一些知识点的，可以加入这个知识体系，比如私董会里边，提问也是非常重要的一个能力。\u003c/p>\u003cp>关于同类，我在这里就和同类书籍建立了一个联系，不同类我就联想到了一些知识付费的栏目和几位小伙伴参加的洋葱俱乐部，透过这样之后，就通过《提问力》这样的一个书籍，建立了这部分的简单知识结构。因为时间的关系，在这里不做更多的延展。\u003c/p>\u003cp>\u003cstrong>三、持续迭代\u003c/strong>\u003c/p>\u003cp>后期遇到相关的知识点，我们把它填到相应的分支上，日积月累的搭建知识结构。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>有的小伙伴认为这样太慢了，这一点都不奇怪，任何新事物都有一个适应期，一旦你度过了适应期，像美国大片里面一样，我已经建立了自己的知识架构，需要什么，随时伸出手抓出来用就可以了，学习效率就会突飞猛进。在这里我们看到，它不是一个体系，只是一个知识片段啊，是的，我们今天只搭建一个简单的结构，无数的建立链接之后，我们就织成了属于我们自己的知识的大网，这个过程需要我们慢慢的日积月累来绘制。这样的话，无论是我们在学校学习的知识，还是在互联网上报的培训班，马上可以把所有的知识联系到一起，那么外面来的这些信息就不会觉得学起来非常困难了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3：促动参与】\u003c/strong>\u003c/p>\u003cp>刚才我们学习了“整体性学习三步法”，现在进入学以致用的A3环节，什么是A3呢？就是我们每个人都化身演员，化身要拿奥斯卡小金人的演员，请大家现场做一个演练。请仔细听：\u003cstrong>首先\u003c/strong>请大家运用“整体性学习三步法”搭建《这样读书就够了》的一个简单的知识结构，\u003cstrong>然后\u003c/strong>向你的朋友小王讲述你搭建的知识结构。我们以小组为单位，一个人做自己，一个人扮演小王，请大家30秒的时间先分好角色。\u003c/p>\u003cp>扮演小王的小伙伴举手示意我一下，谢谢！\u003c/p>\u003cp>现在请大家用两分钟的时间给《这样读书就够了》搭建一个简单的知识结构，可以参考我之前举例中的图示。\u003c/p>\u003cp>好，时间到，我看到大家简单的知识结构都已经搭建好了，请大家两分钟的时间向你的朋友小王介绍你搭建的知识结构。然后将有请一组小伙伴上来进行角色扮演。\u003c/p>\u003cp>\u003cstrong>（学习者案例）\u003c/strong>哪一组愿意主动来为大家表演一下？好，昌琪携手你的小伙伴来为大家表演一下。\u003c/p>\u003cp>（昌琪扮演自己，小Y扮演小王）\u003c/p>\u003cp>昌琪：小王，好久不见了，最近还好吗？\u003c/p>\u003cp>小王：最近很迷茫。\u003c/p>\u003cp>昌琪：很迷茫是吧。迷茫找我就对了，我给你推荐一本书《这样读书就够了》可以解决你的迷茫。\u003c/p>\u003cp>小王：可以给我说说这本书吗？\u003c/p>\u003cp>昌琪：好。《这样读书就够了》是阅读大咖赵周老师写的一本书，里面的RIA便签读书法，可以将知识点化为我们的行动，解决我们的问题，我觉得很赞哦，推荐你去阅读一下。然后还有其它的同类的书我也可以推荐给你比如小六老师的《洋葱阅读法》，再比如秋叶大叔的《如何阅读一本书》这些都可以结合起来阅读。\u003c/p>\u003cp>小王：光阅读这些书籍就可以吗？还有其它的途径吗？\u003c/p>\u003cp>昌琪：有啊，可以参加拆书帮的线下训练营，手把手教你。参加小六老师的线下训练营能够输出九宫格养成一个习惯。\u003c/p>\u003cp>小王：那我可以试试看，谢谢。\u003c/p>\u003cp>【回应和反馈】\u003c/p>\u003cp>谢谢两位，我们大家可以看到，通过“整体性学习三步法”我们透过一本书，如果再继续延伸，持续迭代的话就可以建立一系列的这个知识结构。通过赵周老师这样一个点我们又可以建立《提问力》和《这样读书就够了》之间的连接。通过这样的学习，就不存在外面的学习和学校的学习完全试脱节的，所有的东西都是一个体系，拿来用，就好了。再次谢谢两位。\u003c/p>\u003cp>\u003cstrong>&nbsp;[A2\u003c/strong>\u003cstrong>：催化学习者应用]（布置作业）\u003c/strong>\u003c/p>\u003cp>今天我们学习了“整体性学习三步法”，在这里给大家布置一个作业，请大家在一周的时间内，运用“整体性学习三步法”针对目前阅读的书籍或者一个概念点搭建一个简单的知识结构，并在群里进行分享。这本书是什么呢？你准备在什么时间？什么地点？分享给谁？请大家先写在便签纸上交给我。\u003c/p>\u003cp>昌琪：《洋葱读书法》/6月底之前/读书会/读书会的小伙伴\u003c/p>\u003cp>婷英：《伯恩斯新情绪疗法》/下周二/电话/父亲\u003c/p>\u003cp>小Y：《亲密关系》/明天（6月24日）/家里/男朋友\u003c/p>\u003cp>秋千：《这样读书就够了》/6月25号/洋葱训练营/训练营小伙伴\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>衷心的希望大家有方法有技巧的进行学习，并且在学习上付出的每一分努力都能有所收获。我今天的带拆到这里就结束了，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1561726431000,"updated_at":1561726431000,"ria":true},{"id":7828,"topic":"提升学习效率","learn_goal":"认识并了解整体性学习的方法，并学以致用。","remark":"学习是需要方法的，特别是在当今信息爆炸的时代，如何高效地处理信息，有机地整合知识，充分地运用所学，已经成为学习的关键。本书从一位“学习大师”的亲身体验出发，总结出“整体性学习”的策略及方法，同时，配合作者实际运用的各种学习工具，切实帮助学习者练就高效的“学习方法与学习习惯”。方法决定一切，你一定可以从中有所受益。","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"木木33","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"【自我介绍】\r\n亲爱的小伙伴们，大家下午好，我是木木。三个标签介绍自己，拆书家，整理师，户外爱好者。\r\n（分组）因为大家刚才已经分过组了，我们沿用刚才的分组，两两一组。\r\n【学习者场景法图书介绍】\r\n（场景）不知道大家有没有觉得这样的话很熟悉：“一孕傻三年。”“哎，我的记忆力太差了。”你花了一个月才看完一本书，合上书之后，什么都不知道。这些都是学习力不足的表现。\r\n（影响）身处这个信息化的时代，不进步就等于退步。单纯的依赖勤奋已经太低效，学习力不足严重影响自我提升，无法适应岗位的变化，久而久之就会被时代所淘汰。\r\n（提问）小伙伴们在面对这样状况的时候，都是怎么做的呢？结果怎么样？我有请一位小伙伴给我们分享一下：\r\n（学习者互动）\r\n木木（拆书家）：来我们的科研狗（张亚光，刚自我介绍时候自称科研狗）。妮一般面对这样的状况的时候你是怎么做的呢？学习力不足。\r\n亚光：学习力不足，就去报培训班上课。\r\n木木：报培训班上课，结果呢？\r\n亚光：结果就会去学习一些思维方式，这样来提升自己的学习力。\r\n木木：学习，提升。你觉得这种提升大吗？\r\n亚光：大的，会有很大的提升。\r\n木木：看来学习是非常重要的。\r\n亚光：需要持续不断的学习。\r\n木木：持续不断的学习，谢谢。\r\n木木：文婷小伙伴，你一般这个时候是怎么做的？\r\n文婷：一般是先想想是不是方法不对。\r\n木木：我们都会去寻找一些方法来提高我们的学习。今天来的小伙伴们都是非常优秀的爱学习的小伙伴。\r\n（解决）今天这本书《如何高效学习》中的片段为大家带来的是“整体性学习法”，通过结构化的学习，帮助大家用最少的时间学到更多的东西。\r\n【学习目标】今天的学习目标是：学习者在跟随我完成RIA现场学习后，运用（行为）“整体性学习四步法”（澄清）指导他人学习（界定）。\r\n【A1测试题】\r\n在阅读片段前，邀请小伙伴们做个小测试。请看测试表，请大家用一分钟的时间给自己打分，（注意1分代表与你的情况完全不符合，6分代表与你的情况非常符合）打完分后请大家汇总一下，做好的小伙伴请示意我：\r\n序号 内容 得分（1分完全不相符，6分是完全相符）\r\n1 对于新知识，我总会查找资料，通过多种方式去理解。 1 2 3 4 5 6\r\n2 学完的知识，我还知道它们是如何推导出来的。 1 2 3 4 5 6\r\n3 我大脑里有很多知识，通常需要什么就会很快找到。 1 2 3 4 5 6\r\n4 我制定有一套自己常用的学习方法。 1 2 3 4 5 6\r\n5 关于概念，我会联想到其它事物来记住它们。 1 2 3 4 5 6\r\n总分 \r\n【I测试题解释+和学习者互动】\r\n这套自测题用来检测平时学习的习惯和方法。并不代表权威，只是帮助我们了解自己。所以大家不要有心理压力。得分20分以上的小伙伴举手示意一下，一个都没有哦。20分以上是学霸级的选手。\r\n（学习者）：他20以上，群笑。\r\n木木：高手藏在民间，20分以上是学霸级的选手，说明你已经有很强的学习力了。得分在10分到20分以上的小伙伴举手示意我一下，大家基本上都在这个分数段。显然今天来的小伙伴们已经走在了通往高效学习的路上了。包括文婷，包括我们的亚光刚才都有说过，会去报班，会去学习，有意识的去关注学习方法。","ratings_count":1,"texts":[{"id":11346,"quote":"\u003cp>\u003cstrong>【R：阅读原文】\u003c/strong>现在进入R环节，阅读原文片段，请大家用1分钟的时间阅读片段，阅读完毕的小伙伴请微笑示意。\u003c/p>\u003cp>《如何高效学习》\u003c/p>\u003cp>整体性学习需要采用多种途径综合学习，而不是试图在大脑中复制一个完美的拷贝，整体性学习是运用你大脑里已有的丰富的神经元网络吸收，整合信息。整体性学习在于创造信息的网络，一个知识与另一个知识相互关联，那些互相关联的知识网络使你真正做到对知识的完全理解，从而轻松地驾驭知识。\u003c/p>\u003cp>整体性学习意味着知识的学习并不是孤立的。事实上，知识的学习从来就不是孤立的，学习任何知识（概念，定义，公式，问题，观点，理论等）都需要联系。你创造的联系越多，它们就会记得越牢，理解得越好。\u003c/p>\u003cp>机械记忆认为学习就像整理一个个大小不一的盒子。一个数学大盒子里装有代数，几何，微积分小盒子。微积分小盒子里又有更小的函数盒子和一些公式的应用盒子等。在你的微积分盒子里不可能找到生物，历史，绘画，舞蹈和科幻电影的踪迹。\u003c/p>\u003cp>但是学习并不是整理盒子，学习就像编织一张大网。\u003c/p>\u003cp>整体性学习者不会采取这样有组织的方法（整理盒子）储存信息（这可能会解释很多聪明的人组织能力却很差的现象）。整体性学习者可以将所有东西关联起来，公式并不仅仅是公式，它是一种感觉，一幅图像，你可以将它与天上飞行的超音速飞机联系在一起。\u003c/p>","explains":"\u003cp>\u003cstrong>【I:重述原文】【导出概念+学习者互动】\u003c/strong>\u003c/p>\u003cp>提问：刚读完了这个片段，我想问问大家机械记忆式学习是什么？单浩你可以给我们分享一下吗？学霸。\u003c/p>\u003cp>单浩（学霸）：我个人感觉就是说，比如你要去应对一门考试，肯定有一些资料，这些资料没有自己的一套方法，看到什么记忆什么，而不是说举一反三，去联想或者说怎么样的。\u003c/p>\u003cp>木木：看到什么就只学什么，没有进行关联。那整体性学习刚才我们片段怎么讲的？ \u003c/p>\u003cp>单浩（学霸）：整体性学习可能就是你要搭建一个网络，知识一定要是一个体系性的出现的。由点到面，由面到一个立体的结构。\u003c/p>\u003cp>木木：非常的好，那学霸给我们分享下，你之前都是采用什么学习方法的？\u003c/p>\u003cp>单浩（学霸）：其实我以前也有很多这种困扰，以前学到的东西会经常不记得。我怎么样才能提高自己的这种现状，所以我会去阅读一些相关的书籍和上一些培训班，讲座来触发自己。包括今天参加这个拆书活动。\u003c/p>\u003cp>木木：好的谢谢。看来今天来的小伙伴们都是学习的高手，那么我们今天来学习一种不一样的学习方法“整体性学习法”，通过刚才大家的分享我们可以了解到整体性学习看待知识的角度是多方面的，将方方面面的知识联系在一起。\u003c/p>\u003cp>\u003cstrong>【概念对比+学习者互动】\u003c/strong>\u003c/p>\u003cp>为了让大家更好的理解，我举几个例子：\u003c/p>\u003cp>【反例一】：每天背30个单词，早中晚各复习一次，是整体性学习吗？\u003c/p>\u003cp>（学习者回应）不是。\u003c/p>\u003cp>木木：对。不是，整体性学习采用多样化的学习方式。\u003c/p>\u003cp>【反例二】：今天历史课上讲的金字塔，我结合了中国的长城进行记忆。是整体性学习吗？\u003c/p>\u003cp>（学习者回应）是。\u003c/p>\u003cp>木木：NO。也不是，整体性学习强调多个维度的知识链接，而不仅仅是同类记忆。刚才我们的学霸有说。\u003c/p>\u003cp>【反例三】：小明成绩优异，无论是语文，数学都有方法的进行。这个是整体性学习吗？\u003c/p>\u003cp>（学习者回应）是吧。\u003c/p>\u003cp>木木：是…吧（群笑）这里有两种情况，如果小明是把所有学科进行有联系的学习就是整体性学习，如果单独语文按照语文的学习方法，数学按照数学的学习方法，就是零散的，不是整体性学习。\u003c/p>\u003cp>\u003cstrong>根据以上的列子，我给大家列出了“机械性记忆”和“整体性学习”的区别：\u003c/strong>\u003c/p>\u003cp>大家看我手里：这个是机械性记忆学习，这个是整体性学习。（摇一摇）大家可以听到机械性学习它是零散的，我打开之后大家可以看一下，它的学习方式是单一的，只是把所有的知识放到这个盒子里了，是单一的一种方式，并且是同类的记忆，比如说（拿出每个小球）语文，数学，物理它都是分开的。那么我们的整体性学习是什么呢？大家看这里，整体，结构化，关联所有的事物，所有关联到一起并且是丰富多样的路径学习。\u003c/p>\u003cp>【重点难点总结+适用边界】可以发现整体性学习采用多种途径综合学习，每学习一个新概念，都会自动的与其它知识相联系。它强调关联所有事物，将零散的知识链接成一个整体。适用于建立结构化学习体系，不适用于需要死记硬背的内容。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>常常我们花了九牛二虎之力去参加一个考试，然后，没过；晚上背了20个单词，一觉过去，还记得几个？大家都在笑，都在偷偷的笑，记得20个的举手我看看，没有。文婷刚才说记得一个。聪明人都是有套路的，他们将所学的知识与其它知识相联系，建立牢固的知识链接体系，从而提升学习效率。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>整体性学习是通过观察聪明的人是如何学习而得到的总结。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>既然已经知道了有这种用时又少，效率又高的学习方法，相信大家一定是非常想了解啦。让我们一起来进入“整体性学习四步法”：\u003c/p>\u003cp>\u003cstrong>一.\u003c/strong>\u003cstrong>获取信息\u003c/strong>。通过网络搜索，听，观察，问，阅读，笔记等等各种渠道来获取大量的信息，通过筛选和简化之后，提炼出对当下有用的信息，注意是当下有用。\u003c/p>\u003cp>\u003cstrong>二. \u003c/strong>\u003cstrong>准确理解。\u003c/strong>\u003c/p>\u003cp>准确指符合实际。比如说：&quot;我们要关门了。&quot;大家认为是什么意思？\u003c/p>\u003cp>&nbsp;(学习者回应)：就是赶我们走。\u003c/p>\u003cp>木木：赶我们走，还有什么意思？\u003c/p>\u003cp>（学习者回应）；把门关上，天冷了。\u003c/p>\u003cp>木木：如果放在我们家里，我们是要做关门这个动作，或者刚才有小伙伴说，我们不留客了。饭店里面我们要关门了，是我们要打烊了。中国文化博大精深，一定要放到当下的场景和上下文里理解，才能够得出准确的理解。\u003c/p>\u003cp>\u003cstrong>三.\u003c/strong>\u003cstrong>拓展链接。\u003c/strong>\u003c/p>\u003cp>拓展是什么意思呢？拓展是在原有的基础上增加新的东西。这个时候一定要问一个问题“从这个知识点还可以学到什么呢？”在拓展链接的这个环节，最重要的是提问。从三个维度进行：提问—获取信息-回答，提问-获取信息-回答。从哪三个维度呢？深度，同领域，不同领域。\u003c/p>\u003cp>1.深度（背景）。“这个知识是从哪里来的？”“为什么以这种方式存在。”进行一次一次的提问，一直往深里挖掘。\u003c/p>\u003cp>2.同领域。“类似的还有哪些？有哪些相同点，有哪些不同？”\u003c/p>\u003cp>3.不同领域（联想/比喻）。常用的方法是联想和比喻。\u003c/p>\u003cp>在这里我给大家举个例子：\u003c/p>\u003cp>这里有个苹果。\u003c/p>\u003cp>从深度：2000年前在中国就已经有了，最早是在烟台种植的。那么2000年发生了什么事情呢？为什么会种植在烟台呢？进行一步一步的提问。\u003c/p>\u003cp>从相同领域：苹果富含丰富的维生素---延伸到美白。苹果里边含有的苹果酸，可以减去下肢的脂肪，所以很多减肥套餐里都有苹果—还有哪些减肥的方法呢？哪种是健康的，哪种是不好的。\u003c/p>\u003cp>不同领域：苹果砸在牛顿的头上，万有引力。乔布斯的苹果帝国，手机，乔布斯的名言，乔布斯的故事……等等等等，因为今天时间有限，我只进行了简单的拓展。“苹果”就让看似风牛马不相及的减肥，地域，乔布斯，万有引力成为了一个整体里的部分，这些信息可以随时拿来调用。\u003c/p>\u003cp>\u003cstrong>四.\u003c/strong>\u003cstrong>综合应用。\u003c/strong>\u003c/p>\u003cp>工作生活知识它是一个整体，我们要学以致用。比如说：我最近学习了一个领导力，我要怎么管理人，我做菜的时候对应的把这些人对应成家里的菜，萝卜青菜土豆，我怎么样把这些菜炒成色香味俱全，你管理好了这些菜，就也可以将方法运用到工作中去，把这些人管理好。比如说，我们指导他人其他人运用“整体性学习四步法”也是应用。\u003c/p>\u003cp>大家要注意的是，这几个步骤可以依次进行，也可以跳跃往返。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>给大家分享一个我自己的例子，寒假的时候，儿子背诵“学而不思则罔”，怎么都背不住，就来问我，我想问下大家，想当年背论语很厉害的小伙伴有吗？看来这是一个千古难题哈，我要抓住一切彰显我母亲智慧的机会，我用“整体性学习四步法”对他进行了引导：\u003c/p>\u003cp>\u003cstrong>一.获取信息\u003c/strong>。“儿子，妈妈陪着你去百度和书本上看看这句话是什么意思。”搜索了很多的信息，筛选出5年纪小朋友年龄段的10条，罗列出来。\u003c/p>\u003cp>\u003cstrong>二.准确理解\u003c/strong>。因为这个地方就是子曰：“学而不思则罔，思而不学则殆。”联系上下文，我们把意思相近和相同的总结归纳成一句话来解释。总结出：“死记硬背而不思考不理解，就做不到活学活用，容易迷茫。”在这里当然要引导我的儿子链接更多的知识。\u003c/p>\u003cp>\u003cstrong>三.建立链接\u003c/strong>。这个时候我就说“我们一起来看看从这句话还可以学到什么呀？”我和他一起从三个维度提问获取信息回答：\u003c/p>\u003cp>1.深度。我们了解了孔子，儒家，论语---孔子他有很多的故事，弟子，朝代等等都可以。\u003c/p>\u003cp>2.同领域。因为他是讲一种学习方法，那么还有其它的学习方法吗？比如说我们的亚光，还有我们的学霸，就学习了各种学习技术。孔子其它语录等等\u003c/p>\u003cp>&nbsp;3.不同领域（联想）。我就引导我儿子，因为我儿子特别喜欢射箭。就好像你在射箭的时候，如果不提前思考对应靶心要站的位置，瞄准的角度，射箭时候的风向，就不容易射到靶心。经过这样的引导之后，我的儿子就说：“原来这句话是我射箭的时候要先想，想好之后用脑，我就不会找不到靶心了。”因为时间的关系，我今天没办法后面做深度拓展。这个图示大家也要注意是立体呈现的。\u003c/p>\u003cp>\u003cstrong>四.综合应用\u003c/strong>。 “学而不思则罔”现在他射箭就会说起这句话，提醒他先思考，也很容易就记住不会忘记了。\u003c/p>\u003cp>经过这样的学习后，透过一句话搭建了不同知识之间的桥梁，日积月累，他就会建立起自己庞大的知识库，随时活学活用。大家有时间或者等下课后我们可以玩一下这个游戏，这个游戏很嗨的，往后边一直延伸扩展。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>有的小伙伴认为这样太慢了，这不奇怪，任何新事物都有一个适应期，一旦你度过了适应期，学习效率将会突飞猛进。也有小伙伴认为，讲给别人太麻烦了，就好像我给我儿子讲，输出是最好的输入，这也是我们为什么来拆书，在引导别人的过程中，其实自己在刻意练习刻意内化，输出越多，对自己效果越快越好。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3：促动参与】\u003c/strong>\u003c/p>\u003cp>刚才我们学习了“整体性学习四步法”，现在进入学以致用的环节，请大家现场做一个演练。请看小剧本右侧的框，仔细听：你正在闺蜜家玩耍，她的孩子小花在吃桔子，请你引导小花运用“整体性学习四步法”通过“桔子”搭建部分知识结构，注意是用“整体性学习四步法”进行引导搭建部分知识结构。我们以小组为单位，一个人扮演自己，一个人扮演孩子小花，请大家先分好角色，然后小组内分享，4分钟后，有请一组小伙伴上来扮演。\u003c/p>\u003cp>木木：大家只需要给她搭建一个一层或者两层的结构就可以了，最后以对话的方式呈现，大家先确认下谁扮演自己，谁扮演小花。\u003c/p>\u003cp>木木：好，时间到。丹丹和沁水我看到你们还画出了图，来给我们大家演示一下。你们两个谁扮演小花？\u003c/p>\u003cp>沁水：阿姨我在吃桔子。\u003c/p>\u003cp>丹丹：真好，想了解关于桔子的一些事情吗？\u003c/p>\u003cp>沁水：想。\u003c/p>\u003cp>丹丹：好，我们一起百度一下好不好？\u003c/p>\u003cp>沁水：好的。\u003c/p>\u003cp>丹丹：桔子是一种水果，含有丰富的维生素，吃了可以让眼睛明亮。哎呀，你看它的原产地在中国，有几千年了呢。（深度拓展）\u003c/p>\u003cp>沁水：古人也有橙子吃呀。\u003c/p>\u003cp>丹丹：你手上拿的这个是属于水果的一种，你看它是橙色的，平时还有哪些是食物是橙色的呀？ \u003c/p>\u003cp>沁水：南瓜（同领域拓展）\u003c/p>\u003cp>丹丹： 特别的好，我们有一个节日会用南瓜来做装饰，你去年那天还穿了斗篷呢？还记得吗？\u003c/p>\u003cp>沁水：我记得，万圣节的南瓜灯。（不同领域拓展）\u003c/p>\u003cp>丹丹：来我们一起尝尝看它是什么味道。\u003c/p>\u003cp>沁水：酸的。（同领域拓展）\u003c/p>\u003cp>丹丹：酸的味道你喜不喜欢？\u003c/p>\u003cp>沁水：不是特别喜欢。\u003c/p>\u003cp>丹丹：那我们平时对待别人是不是要经常酸酸的，要给别人甜甜的味道？（不同领域拓展）\u003c/p>\u003cp>沁水：是的，阿姨。\u003c/p>\u003cp>【回应和反馈】感谢两位小伙伴带来的精彩演绎，经常性的刻意给别人分享，用输出强化输入，其实也加深了我们自己的了解，今天只是引导大家简单的运用了这个方法。回去后大家多分享几遍就会感受到其中的魅力。好，接下来要给大家布置作业了。\u003c/p>\u003cp>\u003cstrong>&nbsp;[A2\u003c/strong>\u003cstrong>：催化学习者应用]（布置作业）\u003c/strong>\u003c/p>\u003cp>今天我们学习了“整体性学习四步法”，回家之后我们不仅自己要用起来，还要分享给身边的人。在这里给大家布置一个作业，请大家在一周的时间内，运用“整体性学习四步法”对身边的人进行一个知识点的分享，然后将分享的过程发在群里。你准备找谁分享呢？在什么时间？请写在便签纸上。刚才有一份“整体性学习四步法”的流程图，大家可以拿着这个图分享。最先分享到群里的小伙伴我会送给他一本书籍。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>衷心的希望大家有方法有技巧的进行学习，在学习上付出的每一分努力都能有所收获。我今天的带拆到这里就结束了，谢谢大家。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1557066882000,"updated_at":1557066882000,"ria":true},{"id":7819,"topic":"掌握学习的屠龙术——费曼技巧","learn_goal":"读一本书之后，学会如何快速掌握知识","remark":"一位因为快速学习而成名的神奇小子，他应用自己发明的学习方法，完成了10天搞定线性代数，1年学习4年MIT课程的“不可能任务”。本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。跟随作者，你也将成为高效学习的超级学霸。","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"谢洪涛","city":"上饶"},"club":{"name":"上饶三清山分舵","city":"上饶"},"prologue":"\u003cp>各位伙伴，大家下午好。很高兴能在这里与大家共同拆书学习，今天是我的1-1拆书练级。\u003c/p>\u003cp>首先自我介绍下，我叫谢洪涛，谢谢的谢，洪水的洪，波涛的涛。别看我名字洪水波涛的，其实本人并不凶。\u003c/p>\u003cp>我给自己三个标签：\u003c/p>\u003cp>第一个标签：感恩的人，心存善良懂得感恩一直是我的人生信条。\u003c/p>\u003cp>第二个标签： 年轻的爸爸，这是我家庭生活新扮演的角色，现有萌娃两枚，虽然压力山大但痛并快乐着。\u003c/p>\u003cp>第三个标签： 家具配件供应商，这是我的职业。如果大家有整体家居上面的问题，我可以提供一些建议和帮助。\u003c/p>\u003cp>介绍完了自己后，接下来介绍下拆书帮。\u003c/p>\u003cp>那什么是拆书？就我理解，拆书是一种学习方法，用来提升我们能力，解决实际问题的。它是以我们学习者自己为中心，讲知识联系到我们自身的经验，规划之后具体行动，进而提高我们能力。即拆为己用。\u003c/p>\u003cp>因此拆书形式主要分为个人和组织学习两种。个人主要是RIA便签学习法；组织学习就是像现在，由一位拆书家就一本书与大家一同现场学习，并由他引导大家把知识拆为己用。\u003c/p>\u003cp>那什么是拆书帮呢？即是一群运用拆书法学习的学习爱好者聚集的学习型社群。在这个公益的组织中我们一起陪伴赋能、持续精进、共同成长。这就是拆书帮。\u003c/p>","ratings_count":1,"texts":[{"id":11338,"quote":"\u003cp>介绍完拆书帮以后，我们回到本次拆书的主题。《如何高效学习》\u003c/p>\u003cp>一直以来，如何快速高效学习是大家梦寐以求的技能，那学习中是否存在这样的一种“屠龙技”呢？\u003c/p>\u003cp>那接下来，请小伙伴阅读这个拆页，寻找答案。\u003c/p>\u003cp>\u003cem>原书拆页《如何高效学习》P133/134\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cbr> \u003c/em>&nbsp;&nbsp;&nbsp;&nbsp; \u003cem>理査德\u003c/em>\u003cem>D\u003c/em>\u003cem>．费曼（\u003c/em>\u003cem>&nbsp;Richard&nbsp;D&nbsp;Feynman\u003c/em>\u003cem>），美国物理学家，诺贝尔奖获得者，曾经任教于普林斯顿大学物理系。费曼挑战任何一位普林斯顿大学数学系的教授，即不管这些教授告诉费曼多么复杂难懂的数学知识，只要他们使用简单的术语（不得使用费曼觉得生僻复杂的单词或术语）去描述，费曼就定会得出同样的结果。\u003c/em>\u003cem>\u003cbr> &nbsp;&nbsp;&nbsp;&nbsp; \u003c/em>\u003cem>这则故事常常拿来证明费曼是个伟大的天オ。不过现实中，这个技巧人人都能掌握，接下来，我就告诉大家具体如何去做。\u003c/em>\u003cem>\u003cbr> &nbsp;&nbsp;&nbsp; \u003cstrong>&nbsp;\u003c/strong>\u003c/em>\u003cstrong>\u003cem>费曼技巧\u003c/em>\u003c/strong>\u003cem>的具体措施\u003c/em>\u003cem>\u003cbr> &nbsp;\u003c/em>\u003cem>（\u003c/em>\u003cem>1\u003c/em>\u003cem>）理解那些你没有真正掌握的知识点。\u003c/em>\u003cem>\u003cbr> &nbsp;\u003c/em>\u003cem>（\u003c/em>\u003cem>2\u003c/em>\u003cem>）记住那些你能理解，却可能在考试中遗忘的知识点。\u003c/em>\u003cem>\u003cbr> &nbsp;\u003c/em>\u003cem>（\u003c/em>\u003cem>3\u003c/em>\u003cem>）作为一个考前学习的高效率方法。\u003c/em>\u003c/p>\u003cp>\u003cem>很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只花上\u003c/em>\u003cem>20\u003c/em>\u003cem>分钟就能深入理解知识点，而且记忆深刻，难以遗忘。\u003c/em>\u003cem>\u003cbr> &nbsp; \u003c/em>\u003c/p>\u003cp>\u003cem>下面我来演示费曼技巧的操作流程，你可以用它大幅度提高各门学科的成绩。\u003c/em>\u003cem>\u003cbr> &nbsp;&nbsp; \u003cstrong>&nbsp;&nbsp;\u003c/strong>\u003c/em>\u003cstrong>\u003cem>第一步：选择要学习的概念\u003c/em>\u003c/strong>\u003cem>&nbsp;\u003c/em>\u003cem>首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/em>\u003cem>\u003cbr> &nbsp;&nbsp;&nbsp; \u003cstrong>&nbsp;\u003c/strong>\u003c/em>\u003cstrong>\u003cem>第二步：设想你是老师，正在试图教会一名新生这个知识点\u003c/em>\u003c/strong>\u003cstrong>\u003cem>\u003cbr> \u003c/em>\u003c/strong>\u003cem>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得好，而原先不明白的地方也得以理清。\u003c/em>\u003cem>\u003cbr> &nbsp;&nbsp;&nbsp;&nbsp; \u003c/em>\u003cstrong>\u003cem>第三步：当你感到疑惑时，别着急往下走，返回去吧\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cem>每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/em>\u003cem>\u003cbr> &nbsp;&nbsp;&nbsp; &nbsp;\u003c/em>\u003cstrong>\u003cem>第四步：简单化和比喻\u003c/em>\u003c/strong>\u003cstrong>\u003cem>\u003cbr> \u003c/em>\u003c/strong>\u003cem>如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003c/em>\u003c/p>\u003cp>\u003cem>&nbsp;\u003c/em>\u003c/p>\u003cp>&nbsp;&nbsp; 好，如果大家看完了，请举手示意一下。\u003c/p>\u003cp>&nbsp;&nbsp; 好的。\u003c/p>","explains":"\u003cp>\u003cstrong>What\u003c/strong>：这个拆页介绍了一种整体性学习技术——费曼技巧\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>：这种学习技巧有两个特别好的价值：1，在学习新知识新概念，能让你快速从陌生到理解掌握。2，在巩固旧知识，自我检测查漏补缺有奇效。\u003c/p>\u003cp>\u003cstrong>Where\u003c/strong>：那对于它的适用边界来讲：基本上适用非技术实操类的理论概念的学习与自查。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>： 那我们具体如何使用它呢？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我提取这项技巧（费曼技巧）的首字母（F、M、J、Q）来做步骤学习\u003c/p>\u003cp>第一步：F&nbsp; find （寻找）&nbsp; 确立主题&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 找到你所要学习的知识概念，把其详细内容写出来\u003c/p>\u003cp>第二步：M&nbsp; master（大师） 好为人师 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 假想自己是老师，向小白徒弟传授武艺。你该如何讲解，写下讲解的思路与过程\u003c/p>\u003cp>第三步：J&nbsp; journalist（新闻记者） 查漏补缺 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在复述讲解中，遇到卡壳疑难地方。立马返回钻研。要像新闻记者样 刨根问底直到彻底掌握为止。\u003c/p>\u003cp>第四步：Q （so Q&nbsp; ,娇小可爱）&nbsp; 巧用比喻&nbsp;&nbsp; \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 将你的讲解 用简单浅显、生动形象的语句覆盖。最好用比喻\u003c/p>\u003cp>值得一提：MJQ步骤彼此循环，直至彻底掌握为止。\u003c/p>","interaction":"\u003cp>分享一下，此前我失败的经验。虽然时间遥远，但非常深刻。\u003c/p>\u003cp>我中考是以630分的总分被县中特招班录取的。高中的知识较初中的还是深奥难懂些。尤其数学物理，理解难度非常高。但当时底子厚，学的轻松。老师当堂讲的知识都懂，小测试也OK。但到分文理科时，忽然发现数理化严重落后，很多知识点模棱两可。后面权衡 取巧选了文科。\u003c/p>\u003cp>现在反思：学得快，并不代表彻底掌握。特别是逻辑缜密的学科，一个概念不清晰，直接影响后面的学习。基础不扎实，难以跟上。我在想如果当时学会费曼技巧，查漏补缺也许会更有效率，也能更早的提前发现问题。\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003c/em>\u003c/strong>\u003c/p>\u003cp>学习了费曼技巧，下周二晚，我准备用它复习RIA便签学习法知识\u003c/p>\u003cp>我将会：\u003c/p>\u003cp>F：确立主题，找出RIA便签法的所有相关内容并整理、写下来\u003c/p>\u003cp>M：好为人师，我就不假想了，直接找我爱人讲述这个知识点\u003c/p>\u003cp>J：查漏补缺，在向我爱人讲述RIA时，看哪里卡壳了，记录下来。我爱人提问，解答疑问。\u003c/p>\u003cp>Q：巧用比喻， 竟可能多用比喻，如爱人喜欢的美食图画来讲解 让我爱人弄懂\u003c/p>\u003cp>检验标准：我爱人也能复述什么是RIA便签学习法。\u003c/p>\u003cp>奖惩：合格，晒一晒讲解图\u003c/p>\u003cp>未完成，这样拆书就够了关于RIA一章，抄写一遍。\u003c/p>\u003cp>好啦，最后我们再回顾一下本次的拆页，我们学习了费曼技巧，具体步骤F M J Q。 希望能为大家的工作学习 带去一点帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1557040267000,"updated_at":1557042153000,"ria":true},{"id":7646,"topic":"积极阅读法。","learn_goal":"熟记并应用积极阅读法步骤读书","remark":"积极阅读法能在书中高效获取知识，提升你的看书效率。\r\n","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"刘阳","city":"沈阳"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp;\u003cstrong>自我介绍\u003c/strong>\u003cstrong>:\u003c/strong>\u003c/p>\u003cp>伙伴们，大家好！我是今天的拆书人刘阳，用三个标签介绍一下自己：新手拆书家，心理咨询师，读书爱好者。很高兴和大家一起分享我的拆页。\u003c/p>\u003cp>\u003cstrong>新技能点：图书介绍（FAB）\u003c/strong>\u003c/p>\u003cp>我今天和大家分享的主题是积极阅读法，选自《如何高效学习》这本书。（实用类书）\u003c/p>\u003cp>F特征：\u003c/p>\u003cp>这本书的作者是斯科特•扬，他是一位超级学霸，讲的是整体性学习的策略和一些学习技术。\u003c/p>\u003cp>A优势：\u003c/p>\u003cp>为什么要和大家分享这本书呢？不仅仅因为这是一本学习类的畅销书。而且作者践行书中的方法，用一年的时间完成33门课程的学习。书中为我们提供一个如何更高效学习的模型—整体性学习策略和一些学习技术。我们可以根据模型，结合自己有效学习的方法建构自己的整体性学习模型，提升效率\u003c/p>\u003cp>B利益：\u003c/p>\u003cp>不知道大家在学习中有过哪些体验。您有没有读了一本书花费了很长时间，但是读完却发现什么都没有记住；你有没有很刻苦的学习，到头来考试的成绩却不理想；你有没有感觉上课听得很清楚，但是当你讲给别人听却发现自己并没有理解。你都会从这本书中找到相应的策略来解决上边的问题。\u003c/p>\u003cp>积极阅读这个主题，能快速帮助您快速找到书中有用的信息。提升你获取知识的效率。\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>\u003c/p>\u003cp>我们今天的学习目标也是这个，希望大家跟随我一起完成本次RIA现场学习后，在读书前明确自己的目标，提升阅读速度，提升获取知识的效率。\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>\u003c/p>\u003cp>在大家阅读拆页前，我们先分一下组，以我的左手边开始，两个人一组，下面给大家两分钟时间阅读这个拆页，阅读完毕举手示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":11138,"quote":"\u003cp>R积极阅读法\u003c/p>\u003cp>尽管我将积极阅读放在了快速阅读之中，实际上积极阅读与快速阅读是对立的。积极阅读强调深入地理解材料，所以自然降低了阅读速度。积极阅读不仅仅是简单地在书上画各种颜色的记号和在空白处写一写心得体会，还是将知识点真正地整合在一起。\u003c/p>\u003cp>开始积极阅读时，准备好要读的书和笔记本，在笔记本上写下每章的标题和亚标题，每读完一小部分时（指读法），在笔记本上记一些笔记。\u003c/p>\u003cp>进行积极阅读时你需要记下：\u003c/p>\u003cp>（1）这一节中主要观点是什么？\u003c/p>\u003cp>（2）我怎样才能记住主要观点？\u003c/p>\u003cp>（3）我要怎样将主要观点拓展开以及应用它。\u003c/p>\u003cp>第一个问题仅仅促使你完整地获取信息；第二个问题迫使你对信息进行联系、视觉化和比喻法；第三个问题要求你将信息应用在不同的情境中。这三个问题迫使你将每个知识点都要经过整体性学习里的理解、拓展和应用三个阶段。\u003c/p>\u003cp>比如我刚刚读完心理学中的经典条件反射，其主要的知识点是：\u003c/p>\u003cp>·经典条件反射的发现者是巴甫洛夫\u003c/p>\u003cp>·经典条件反射是刺激引起反应\u003c/p>\u003cp>我会这样记忆：\u003c/p>\u003cp>·想象一副图画，画中巴甫洛夫的狗听到铃声流出了唾液。\u003c/p>\u003cp>我会这样拓展：\u003c/p>\u003cp>·我听到电视里类似的手机铃声，会不由自主地掏出自己的手机。\u003c/p>\u003cp>如果你能对教科书里的每一个知识点都进行这样完整的积极阅读，你一定会天下无敌。一旦你熟悉了这种方式，就不必对每个知识点进行完整的积极阅读，而只针对自己需要理解和记忆困难的那些内容。\u003c/p>","explains":"\u003cp>知识点和相关理念what\u003c/p>\u003cp>这个拆页讲的是如可快速的获取书中的内容的阅读方法。高度聚焦目标，加快阅读速度，并通过做回想笔记，深刻记忆书中关键内容。\u003c/p>\u003cp>前因后果说明，强调不这么做的坏处(重点比较后果)Why\u003c/p>\u003cp>如果我们看书没有主题，没有目标，我们就犹如在大海中随波逐流，失去了前行的方向，虽然我们每天花时间看书，但是却没有掌握内容，也就无法形成知识系统，表面是看书，实质技能去没有提升，只能是满足自己的心理安慰，我是一个爱读书的人。长时间下去会耗费你的意志力，渐进失去读书，学习的兴趣。\u003c/p>\u003cp>行动建议和行动步骤how\u003c/p>\u003cp>how，那么该如何应用积极的阅读法来读一本书呢，或者是书中一个章节的内容呢？\u003c/p>\u003cp>第一步：写主题：在翻开书前，写下你在书中想明确了解的主题。\u003c/p>\u003cp>第二步：画Z字，用手指在书上画Z字，找到你想要了解主题的相关内容，可能包括概念，原理，步骤。画Z字的作用是聚焦我们的思维和目光。能加快阅读速度。\u003c/p>\u003cp>第三步：记回想笔记，读完一部分内容的时候，先试着回想设定与主题相关的内容，并记在笔记上，然后再去联想如何应用呢。\u003c/p>\u003cp>适用边界\u003c/p>\u003cp>积极阅读法是一种学习方法，比较适应于致用类书籍，理论类图书，教材用书，但不适应于读小说，故事，诗歌，人物传记，通俗历史等叙事类书籍。\u003c/p>\u003cp>分享一个我生活中的案例：（反例）\u003c/p>\u003cp>在这里和大家分享我自己低效读书的一个经历\u003c/p>\u003cp>上周四晚上临睡觉前，看了人际关系学。书中“提高反馈技巧”这一章，在我看来对咨询非常有帮助。当时主要的想法就是想多看一些内容，大概看了10分钟，翻了6.7页，看完后就睡觉了。也没有做回想笔记。现在回想只能记住“反馈”，两字，其他内容已经记不起来了。\u003c/p>\u003cp>如果按照上面的拆页内容来读书，首先应该把反馈主题相关内容（如反馈定义，那些要禁止，那些要多做）。写在纸上。然后在书中画Z字读书，找到这些内容，最后试着回想整理关于目标的笔记，并思考如何应用。\u003c/p>","interaction":"\u003cp>技能点：激活学习者经验（显像提问法）\u003c/p>\u003cp>好，现在请大家回顾自己读书时的有哪些习惯和体验？\u003c/p>\u003cp>读书时有没有给自己设立读书主题。是不是有默读，回读的习惯，读书时只求快，不能及时的做笔记。看完了一本书，书本一合，脑中空空觉得什么都没有记住。\u003c/p>\u003cp>请大家闭眼反思一下。最近一次的读书的过程是怎样的？读书的体验是怎样的。欢迎在小组内分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>我这周在读高效能人士的七个习惯，我就非常认真的看了一章又一章，看的时候只记了随笔的笔记，自己的感想和挺好的地方，但是把这个书一合，发现什么都没有记住，和别人推荐的时候，只能说这本书特别好。\u003c/p>\u003cp>A1+请学习者反思加工经验\u003c/p>\u003cp>刚刚大家也反思自己的阅读习惯和读书的感受，大家今天也了解了积极阅读法，那么该如何把这个方法，规划到自己的读书习惯中呢？制定一个具体可行的计划呢？增加我们的读书效率。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>针对上面的积极阅读法，我给自己设定了一个计划，在明天晚上睡前21：30-22:00的时候，重新阅读“高效能人士的七个习惯中”有效沟通这节内容。\u003c/p>\u003cp>写主题；有效沟通的定义，如何实现。\u003c/p>\u003cp>画Z字；在书中画Z字，找到具体的定义和具体的操作。\u003c/p>\u003cp>记回想笔记；看完本章后，回忆试着将上述两个问题写在笔记上，并思考如何应用。\u003c/p>\u003cp>结语\u003c/p>\u003cp>希望大家记住今天我们共拆的积极阅读法：写主题，用指读法快速阅读，记回想笔记，并反思我该如何记住这个主题，该怎么应用。谢谢大家。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1555394573000,"updated_at":1555394614000,"ria":true},{"id":7536,"topic":"学会运用费曼技巧","learn_goal":"运用费曼技巧达到过目不忘","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"栗子（Lisa)","city":"济南"},"club":{"name":"济南海右分舵","city":"济南"},"prologue":"\u003cp>&nbsp;\u003cstrong>自我介绍&nbsp;\u003c/strong>\u003c/p>\u003cp>&nbsp;HI,各位济南日天分舵的小伙伴们，大家好！我是栗子。&nbsp;\u003c/p>\u003cp>我的三个标签：“财务经理””瑜伽教练”“80后宝妈”。\u003c/p>\u003cp>1，我已经做了7年的财务经理了，先后从事3家不同行业的公司，外资，工业企业以及上市公司；\u003c/p>\u003cp>&nbsp;2，瑜伽是我的业余爱好，练的久了，就考了瑜伽教练证，利用周末时间代代课，既锻炼了身体，又有了一部分额外的收入；\u003c/p>\u003cp>&nbsp;3，我儿子今年初二了，即将升入初三，我教他使用RIA的方法读书，已经初见成效；\r\n之所以加入拆书帮，是因为我想用拆书法阅读更多的书，为己所用，同时锻炼自己表达能力和逻辑思维能力。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>拆书帮介绍\u003c/strong>\u003c/p>\u003cp>“拆书”并不把书拆开，它是一种学习方法论，适用于以提升能力，解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心。把书中的一部分知识关联学习者的经验，规划到具体的运用当中，不仅提升学习者的能力，更重要的是帮助学习者解决实际问题。\u003c/p>\u003cp>你不需要通读整本书，在阅读时可以使用“便签学习法”，或参加拆书帮RIA现场学习，反思经验，规划应用和现场演练，就可以把书中的知识拆为己用。\u003c/p>\u003cp>“拆书法”实用性比较强，三个小便签让我们把书本中的知识变成自己解决问题的工具，要想更好的学习“拆书法”，最好的方式就是加入“拆书帮”，拆书帮是基于拆书法的学习爱好者社群，是非营利性“青年自组织”，聚集着一群以拆书为乐的拆书家，组织”RIA现场学习“，由拆书家将一本书加工成一场培训，引导和促进一群人把知识拆为己用，同时也帮助更多的学习爱好者成为拆书家。每个城市都有分舵，日天就是拆书帮在济南的分舵。\u003c/p>\u003cp>今天是我成为拆书家的第一关，希望得到各位小伙伴的支持，谢谢！\u003c/p>\u003cp>请大家阅读发下去的拆页，时间1分钟！\u003c/p>","ratings_count":1,"texts":[{"id":11011,"quote":"\u003cp>\u003cp>\u003cstrong>拆页：《如何高效学习》133-134页&nbsp; 作者：斯科特.扬\u003c/strong>\u003c/p>\u003cp>理查德D.费曼（Richard Feynman），美国物理学家，诺贝尔奖获得者，曾经任教于普林斯顿大学物理系。费曼挑战任何一位普林斯顿大学数学系的教授，即不管这些教授告诉费曼多么复杂难懂的数学知识，只要他们使用简单的术语（不得使用费曼觉得生僻复杂的单词或术语）去描述，费曼就一定会得出同样的结果。\u003c/p>\u003cp>这则故事常常拿来证明费曼是个伟大的天才。不过，现实中，这个技巧人人都能掌握，接下来，我就告诉大家具体如何去做。\u003c/p>\u003cp>费曼技巧的具体措施:\u003c/p>\u003cp>（1）理解那些你没有真正掌握的知识点。\u003c/p>\u003cp>（2）记住那些你能理解，却可能在考试中遗忘的知识点。\u003c/p>\u003cp>（3）作为一个考前学习的高效率方法。很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只需花上20分钟就能深入理解知识点，而且记忆深刻，难以遗忘。\u003c/p>\u003cp>下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>\u003cstrong>第一步:选择要学习的概念\u003c/strong>\u003c/p>\u003cp>首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp>\u003cstrong>第二步:设想你是老师，正在试图教会一名新生这个知识点\u003c/strong>\u003c/p>\u003cp>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清。\u003c/p>\u003cp>\u003cstrong>第三步:当你感到疑惑时，返回去吧\u003c/strong>\u003c/p>\u003cp>每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>\u003cstrong>第四步:简单化和比喻\u003c/strong>\u003c/p>\u003cp>如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。例如:在学习力矩时，用简单的话解释力矩，而不是照抄书上的定义。比如，首先用俗语“扭曲”来说清楚力矩是什么意思。\u003c/p>\u003c/p>","explains":"\u003cp>\u003cp>\u003cstrong>分享 I便签\u003c/strong>\u003c/p>\u003cp>what：理查德·费曼是一个美国的物理学家，在1965年就获得诺贝尔物理学奖。费曼技巧就来自他的学习方法。本段主要阐述如果想进行高效的学习，并且达到过目不忘，可以通过使用费曼技巧的方法和步骤进行学习。\u003c/p>\u003cp>why：人类进步是随着知识在升级的，创造知识的人，往往在学习前人的知识之后，通过实践再创造成新的知识。在许多人的面前，有一个重大的问题需要解决，就是前人留给我们的知识太丰富了，怎么快速地掌握这些知识就成为一个重要的问题。那么有没有快速学习的方法，让人在最短的时间获得更多知识的积累呢？可以试试使用费曼技巧。\u003c/p>\u003cp>那么如何使用费曼技巧呢？\u003c/p>\u003cp>how：\u003c/p>\u003cp>\u003cstrong>第一步：明确需要学习和理解的目标。\u003c/strong>\u003c/p>\u003cp>假如你需要阅读一本书，先看书的要点，把书的思维结构摸清楚。然后拿一支笔和一张白纸。\u003c/p>\u003cp>\u003cstrong>第二步：设想一种场景，假想自己正在讲解给一个完全没看过的人听。\u003c/strong>\u003c/p>\u003cp>想象一下你要把这本书讲给一个没有看过这本书的人听，把要点和结构写出来，可做成一个思维导图，或可以简单做一个树形图，主要为了处理上下关系，让知识点形成逻辑关系。回想书中一些主要知识点，按照作者的写作思路，勾画出整个作者要说的知识。\u003c/p>\u003cp>\u003cstrong>第三步：当在讲的过程中卡壳了，那就从头开始，回顾一下学习资料\u003c/strong>\u003c/p>\u003cp>把一些弱点补上，直到领会顺畅，完全可以在纸上解释这个部分为止。\u003c/p>\u003cp>\u003cstrong>第四步：为了通俗易懂，简化语言表达。\u003c/strong>\u003c/p>\u003cp>用自己的语言，口语化，而不是学习资料中的语言来解释概念。\u003c/p>\u003c/p>","interaction":"\u003cp>\u003cp>\u003cstrong>分享A1便签\u003c/strong>\u003c/p>\u003cp>上学时我就喜欢读书，而且也读过很多书，我发现，虽然有时也记笔记，但是一些读过的书很快就忘了。于是就找一些如何阅读一本书的方法。自从购买了赵周老师《这样读书就够了》开始，我就试着用RIA拆书法进行读书，但是写起来挺费劲的；为了进一步的学习拆书法，从18年12月16日开始，陆续的参加了三次线下拆书的活动，听舵主千尘和贾老师的拆书课以及小伙伴的拆书升级，自我感觉已经完全理解并会使用拆书法了。于是我就参加了19年1月9日线上拆书培训，但是我发现实际操作起来还是挺难的，经千尘批改作业和辅导以后，才明白原来我虽然理解了拆书法的概念但并没有真正做到拆书法的规范运用，\u003c/p>\u003cp>所以，我给自己的\u003cstrong>A2便签的目标是\u003c/strong>使用费曼技巧学习RIA拆书法\u003c/p>\u003cp>\u003cstrong>分享A2便签\u003c/strong>\u003c/p>\u003cp>目标：使用费曼技巧学习RIA拆书法。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>第一步：\u003cstrong>明确需要学习和理解的目标；\u003c/strong> 学习RIA拆书法\u003c/p>\u003cp>第二步：\u003cstrong>设想一种场景，假想自己正在讲解给一个完全没看过的人听\u003c/strong>\u003c/p>\u003cp>而我选择的不是假想，我要把RIA拆书法讲给我儿子听，首先把要点和结构写出来，做成一个思维导图，回想书中一些主要知识点，按照赵周老师的写作思路，勾画出整个RIA拆书法的知识。\u003c/p>\u003cp>第三步：\u003cstrong>如果在讲解的过程中卡壳了或者儿子听不明白\u003c/strong>，那么我就重新再看一遍《这样读书就够了》中的RIA拆书法，或者看一遍线下小伙伴做的ppt和拆书稿，或者找几本书不停的进行练习。直到讲解清楚让儿子弄明白为止。\u003c/p>\u003cp>第四步：简化RIA拆书法的概念，用通俗的语言讲解。\u003c/p>\u003cp>好了，以上就是我今天的拆书内容，感谢大家的聆听！\u003c/p>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1554723342000,"updated_at":1554813167000,"ria":true},{"id":7483,"topic":"费曼技巧，","learn_goal":":记住费曼技巧，按费曼技巧学习","remark":"本书作者斯科特•扬12个月内自学完成4年麻省理工学院计算机科学33门课程，他将自己的学习方法写成书，向大家介绍整体性学习技术，费曼技巧就是其中之一。","level":"TF1-2","duration":30,"status":29,"type":0,"chaishujia":{"username":"刘阳","city":"沈阳"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; 大家好，我是今天的拆书家刘阳，用三个标签介绍一下自己：新手拆书家，心理咨询师，读书爱好者。很高兴能在这个夜晚和大家一起分享我的拆页。&nbsp;\u003c/p>\u003cp>今天我选择的拆页是“整体性学习技术的实际运用—费曼技巧”，拆页来自《如何高效学习》这本书。作者：斯科特･杨是一位超级学霸，在12个月内完成4年麻省理工学院计算机科学33门课程学习，他利用的就是整体性学习理论，将自己的学习方法写了这本书，向大家介绍自己的学习方法。\r\n &nbsp;\u003c/p>\u003cp>在我开始分享今天的拆页前，我们先分下组，以我的左手边开始，2人为一组，一会在小组内相互分享自己的经验，给大家一分钟时间阅读拆页，看完拆页举手示意我一下。\u003c/p>","ratings_count":2,"texts":[{"id":10952,"quote":"\u003cp>\u003cstrong>片段主题：\u003c/strong>\u003cstrong>整体性学习技术的实际运用—费曼技巧\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段来源：《\u003c/strong>\u003cstrong>如何高效学习\u003c/strong>\u003cstrong>》\u003c/strong>\u003cstrong>P133-134\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[\u003c/strong>\u003cstrong>R：阅读原文\u003c/strong>\u003cstrong>]\u003c/strong>\u003c/p>\u003cp>运用费曼技巧，你能达到过目不忘。\u003c/p>\u003cp>理查德D.费曼（Richard DFeynman），美国物理学家，诺贝尔奖获得者，曾经任教于普林斯顿大学物理系。费曼挑战任何一位普林斯顿大学数学系的教授，即不管这些教授告诉费曼多么复杂难懂的数学知识，只要他们使用简单的术语（不得使用费曼觉得生僻复杂的单词或术语）去描述，费曼就一定会得出同样的结果。\u003c/p>\u003cp>这则故事常常拿来证明费曼是个伟大的天才。不过，现实中，这个技巧人人都能掌握，接下来，我就告诉大家具体如何去做。\u003c/p>\u003cp>费曼技巧的具体措施：\u003c/p>\u003cp>（1）理解那些你没有真正掌握的知识点。\u003c/p>\u003cp>（2）记住那些你能理解，却可能在考试中遗忘的知识点。\u003c/p>\u003cp>（3）作为一个考前学习的高效率方法。很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只需花上20分钟就能深入理解知识点，而且记忆深刻，难以遗忘。\u003c/p>\u003cp>下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>\u003cstrong>第一步：选择要学习的概念\u003c/strong>\u003c/p>\u003cp>首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：设想你是老师，正在试图教会一名新生这个知识点\u003c/strong>\u003c/p>\u003cp>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清。\u003c/p>\u003cp>\u003cstrong>第三步：当你感到疑惑时，返回去吧\u003c/strong>\u003c/p>\u003cp>每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>\u003cstrong>第四步：简单化和比喻\u003c/strong>\u003c/p>\u003cp>如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003c/p>","explains":"\u003cp>大家都看完了这个拆页。\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>这个拆页讲的是高效学习的方法即费曼技巧——通过能否给别人讲解清楚要点来检验我们对知识的掌握程度。\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>为什么说费曼技巧是一种高效学习的方法呢？因为它满足了对要点有输出和自我检验的过程。要知道人们总是对自己过度自信，通常认为自己知道的比实际的要多，要明白。尤其是当我们听到一个概念或者了解一本书的时候，很容易产生这种过度自信得心理状态。而当我们真的有机会去表达时，发现我们并没有向想象中那样理解的那么透彻，清楚。费曼技巧有效的克服了这种过度自信心态倾向，并通过自我输出，及时反馈，清晰了我们对知识的理解程度。那我们该如何应用费曼技巧呢？\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003c/p>\u003cp>第一步：写概念：拿出一张纸，将你想要讲的概念理解写在上边。\u003c/p>\u003cp>第二步：讲述，评估:试着用通俗，简短的语言把你对概念的理解讲给别人听，要询问他是否听得清楚，明白。\u003c/p>\u003cp>第三步：反思，重新整理。如果您一次把概念讲清楚，说明你已经掌握了这个概念，但是您讲的模模糊糊，对方没有听清楚，这时你需要重新收集资料，整理你对概念的理解。\u003c/p>\u003cp>第四步：形象化讲述。在重新整理完对概念的理解后，再次讲述给他人听直到他人听明白，清楚。\u003c/p>\u003cp>下面我举个例子，大家可能理解起来更直观。\u003c/p>\u003cp>上周看了一本书“人际沟通关系学”，里边提到倾听技巧，于是我试着把倾听这个概念讲给我的同事。\u003c/p>\u003cp>第一步，写概念：我在纸上写下了倾听，并思考整理我对倾听的理解（包括肢体动作，心理状态。）。\u003c/p>\u003cp>第二步，讲述，评估。我是这样对同事说的。倾听是一个持续关注的过程，包括肢体语言，如要正面朝向，上身前倾，目光接触，保持开放的状态，并且自然放松和心理关注，要用心去感受对方。表述完后，同事表示不不清楚什么是用心感受。\u003c/p>\u003cp>第三步，反思，从新整理。上百度收索倾听，从新整理我对倾听概念的理解。\u003c/p>\u003cp>第四步，再次讲述：倾听是一个心理和身体都持续关注的过程。用一个形象的图像比喻：一个对你很关注的人，它肢体语言是，正面朝向你，上身前倾，目光接触，保持开放的状态，并且自然放松。脑中有个大大的问号。“对面的这个人发生了什么事情？他有什么样的情绪感受？他有哪些核心的观点？”\u003c/p>\u003cp>再次询问同事的感受，同事说按照我说的画面做了一个演示，表示理解。\u003c/p>","interaction":"\u003cp>费曼技巧和大家分享完了，大家刚刚也读过原文的片段。下面我们小组内讨论一下自己之前学习的经历和体验，给大家4分钟。我们可以从这几个方面反思。那些我们记忆深刻，讲述清晰的知识如何学会的呢？最近都用什么方法学习，效果如何？那些我们熟悉，但是却讲不清楚的知识，那个学习过程是怎样的呢？小组讨论完毕后，我们会邀请一位学员分享：\u003c/p>\u003cp>记录学员分享便签：\u003c/p>\u003cp>乐乐：\u003c/p>\u003cp>我和大家分享一个我学习的小故事，在上大学的时候，我们曾经有一个选修课程，叫做变态心理学。当时就觉得这个名字挺有意思的。我当时对变态心理学的理解，就是关于变态这些人，他的这个心理活动。然后我和我的这个室友们一起选修了这门课。正式上课的时候才发现他根本就不是我们想象的那样。他是一个很科学的概念。只是用死记硬背的方式去理解这个概念。现在我都已经大学毕业了，课程修完，拿到学分之后，我依然不记得变态心理学，它的概念到底是什么？现在我对变态心理学的理解依然停留在我自己原来的理解上。可能就是我学习的时候没有输出的过程，所以没有完全理解这个概念。我今天学了费曼技巧，要注重输出和检验。真的挺受用的。\u003c/p>\u003cp>今天和大家分享了费曼技巧，各位伙伴要学会运用费曼技巧，需要给自己设定一个应用费曼技巧目标，这个目标要遵守SMART原则，具体，可衡量，可实现，相关，有时间节点限制。我们可以参考这个目标模板。\u003c/p>\u003cp>目标：我在…（日期）给……（谁）讲清楚……\u003c/p>\u003cp>具体做法：\u003c/p>\u003cp>第一步，写概念\u003c/p>\u003cp>第二步，讲述，评估\u003c/p>\u003cp>第三步：反思，重新整理\u003c/p>\u003cp>第四步：形象化讲述\u003c/p>\u003cp>好，给大家1分钟时间，记录自己的规划应用。\u003c/p>\u003cp>学习者便签记录：\u003c/p>\u003cp>乐乐：\u003c/p>\u003cp>我打算在下次拆书时，给拆书帮的小伙伴们分享《金字塔原理》中的结论先行的逻辑写作观点。\u003c/p>\u003cp>第一步，写概念。将先结论后原因的相关概念写成逐字稿。\u003c/p>\u003cp>第二步，讲述，评估。现场分享\u003c/p>\u003cp>第三步：反思，重新整理。针对小伙伴分享与疑问进行反思，重新梳理。\u003c/p>\u003cp>第四步：形象化讲述。对概念在加工，试着用更形象化的语言简述。\u003c/p>\u003cp>希望大家把费曼技巧用在日常的学习中，提高自己的学习效率。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1553587550000,"updated_at":1553587695000,"ria":true},{"id":7242,"topic":"运用费曼技巧，你能达到过目不忘","learn_goal":"运用费曼技巧，学会高效学习，提升学习品质","remark":"在学习中我们常常会记不住信息，费曼技巧运用明确目标、给别人讲解、每个问题都理解明白、恰当运用比喻总结的四个步骤，让学习变得轻松有趣，记忆扎实，是非常高效实用的学习技巧之一。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"猴哥999","city":"鹤岗"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是来自煤城鹤岗的张继明，绰号猴哥，很高兴能在1-1拆书过级考试中能与大家相遇。\u003c/p>\u003cp>首先我将用三个便签介绍一下自己：\u003c/p>\u003cp>1、老师。我是从事20多年教育工作的高中音乐老师，一直在寻找孔孟圣人的修身齐家之道，想把更好的教育献给我的学生们。\u003c/p>\u003cp>2、学生。我当学生时候迷迷糊糊没好好学习，走上社会才发现学习的价值和乐趣，虽然天资愚钝，但后天一直勤学好问，对世界充满好奇心和激情。\u003c/p>\u003cp>3、患者。我身上有先天遗传类和社会传染类的各种毛病，比如健忘、拖延、紧张、懒散、岁数大等等，所以特别适合做拆书帮知识改变命运的试验品。\u003c/p>\u003cp>下面我介绍一下自己所认识拆书和拆书帮。\u003c/p>\u003cp>拆书是一种跟以往啃书完全不同的成人学习方式，它不要求把整本书本完全掌握，而是在书中提炼出对自己有用的部分，进行内化分解，与自己的过往经历结合反思，最终达到指导自己未来工作和生活更好的目的。\u003c/p>\u003cp>拆书又分为自学形式的便签法和现场促动的组织学习两种方式。\u003c/p>\u003cp>它的最大特点就是拆为己用、学以致用。\u003c/p>\u003cp>拆书帮是一个由拆书爱好者成立的公益性学习自组织，目前全国各地分布着正式分舵45家，筹备分舵37家。\u003c/p>\u003cp>我学习拆书就是为了能提高自己的能力，并且能够运用这种能力成为更有影响力的人，而拆书帮的使命就是让我们成为这样的拆书家。\u003c/p>\u003cp>据说拆书帮是全国最难加入的帮会，要想达到三级拆书家要经过训练营、一级、二级、三级一次次的烧脑折磨，阅读分析大量拆页，还要通过现场演讲的形式严格考核，合格者才能过级，所以拆书帮成立五年来全国正式会员才两千多人，达到三级的才二百多人，也正是这种严谨的治学态度让拆书帮成为了全国非常有影响力的学习组织之一。\u003c/p>\u003cp>今天我要分享的片段取自《如何高效学习》，作者斯科特.扬。主题是：运用费曼技巧，你能达到过目不忘。\u003c/p>","ratings_count":0,"texts":[{"id":10652,"quote":"\u003cp>原书拆页《如何高效学习》P133/134\u003cbr>&nbsp;&nbsp;理査德D．费曼（&nbsp;Richard&nbsp;D&nbsp;Feynman），美国物理学家，诺贝尔奖获得者，曾经任教于普林斯顿大学物理系。费曼挑战任何一位普林斯顿大学数学系的教授，即不管这些教授告诉费曼多么复杂难懂的数学知识，只要他们使用简单的术语（不得使用费曼觉得生僻复杂的单词或术语）去描述，费曼就定会得出同样的结果。\u003cbr>&nbsp;&nbsp;这则故事常常拿来证明费曼是个伟大的天オ。不过现实中，这个技巧人人都能掌握，接下来，我就告诉大家具体如何去做。\u003cbr>&nbsp;&nbsp;费曼技巧的具体措施\u003cbr>&nbsp;（1）理解那些你没有真正掌握的知识点。\u003cbr>&nbsp;（2）记住那些你能理解，却可能在考试中遗忘的知识点。\u003cbr>&nbsp;（3）作为一个考前学习的高效率方法。\u003c/p>\u003cp>很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只花上20分钟就能深入理解知识点，而且记忆深刻，难以遗忘。\u003cbr>&nbsp; 下面我来演示费曼技巧的操作流程，你可以用它大幅度提高各门学科的成绩。\u003cbr>&nbsp;&nbsp;第一步：选择要学习的概念&nbsp;首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003cbr>&nbsp;&nbsp;第二步：设想你是老师，正在试图教会一名新生这个知识点\u003cbr>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得好，而原先不明白的地方也得以理清。\u003cbr>&nbsp;&nbsp;第三步：当你感到疑惑时，别着急往下走，返回去吧\u003c/p>\u003cp>每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003cbr>&nbsp;&nbsp;第四步：简单化和比喻\u003cbr>如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰当的比喻以更好地理解它。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;例如：在学习力矩时，用简单的话解释力矩，而不是照抄书上的定义。比如，首先用俗语“扭曲”来说清楚力矩是什么意思。\u003c/p>","explains":"\u003cp>\u003cstrong>Why:\u003c/strong>无论在学生时代还是工作以后，我们都会在身边遇到一些学霸超人，他们精力旺盛，看似没怎么用功，却总能取得优异的成绩。而我们大部分人看似非常努力却拿不到满意的结果。这让很多人苦恼不已，到底差在哪呢？\u003c/p>\u003cp>\u003cstrong>What\u003c/strong>：在这个段落，作者告诉了我们一种非常实用高效的费曼技巧，运用它可以让你瞬间由学渣变学霸，牢牢掌握核心知识点。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>：费曼技巧分为四个步骤：\u003c/p>\u003cp>一、&nbsp;\u003cstrong>定目标。\u003c/strong>\u003cstrong>选\u003c/strong>定一个要解决的具体问题,切记贪多嚼不烂。\u003c/p>\u003cp>二、&nbsp;\u003cstrong>做讲师\u003c/strong>。根据自己的理解用自己的语言给别人把问题讲明白，把别人讲明白了说明自己真明白了。\u003c/p>\u003cp>三、&nbsp;\u003cstrong>不欠债\u003c/strong>。把一个问题弄懂再解决下一个问题，似懂非懂的实质还是不懂。\u003c/p>\u003cp>四、&nbsp;\u003cstrong>设记号\u003c/strong>。给这个知识点用简单化的语言总结或给以形象的比喻加深理解和记忆，比如教孩子学钢琴跳音的弹奏，比喻成敲门的动作要比讲解肌肉的弹性、时值的长短更容易让学生掌握要领。\u003c/p>\u003cp>\u003cstrong>Where:\u003c/strong>这个神奇的学习方法不仅可以让在校的学子们提高成绩，也能让成年人在自学的过程中大幅提高学习效率，当然前提是要有强烈的学习意愿度，被动学习的效果会大打折扣。\u003c/p>","interaction":"\u003cp>我自己就是一个好学勤学但学习效率挺低的人。\u003c/p>\u003cp>去年八月我有幸了解到拆书帮，赶紧买了一本赵周老师写的《这样读书就够了》，打算通过这本书把拆书的技巧全部掌握。正好这段时间不太忙，我就每天很认真的看一个小时，十天左右终于把这本书看完了。结果当我合上这本书回顾的时候，才发现这本书里面的内容在脑子里竟然所剩无几了！\u003c/p>\u003cp>这件事对我打击挺大，看来自己的脑子太笨了，不适合学习。\u003c/p>\u003cp>看了这个片段我才明白，原来是自己的学习方法有问题。\u003c/p>\u003cp>下面是我的反思：\u003c/p>\u003cp>一、没选定目标。所以看书就看到哪想到哪，没有重点。\u003c/p>\u003cp>二、没讲述练习。如果我每看完一个章节都找身边的朋友分享一下，给他们讲明白，我现在可能也成半拉拆书家了。而我当时只是死记硬背，结果还没记住多少东西。\u003c/p>\u003cp>三、没弄懂。整本书我哪个问题也没整明白，就着急看下个章节，就怕看不完，结果回顾看过的每个章节都是一片茫然。\u003c/p>\u003cp>四、没设记号。没有简单总结或形象比喻，自然印象很浅。\u003c/p>\u003cp>今晚我就学习掌握费曼技巧，把它讲给爱人听，半夜12点前达到熟练掌握为止。\u003c/p>\u003cp>一&nbsp;、定目标，先确定我今晚的学习目标是熟练掌握费曼技巧四步学习（S）法。\u003c/p>\u003cp>二、做讲师，我先自言自语叨咕几遍，觉得能讲明白了，就去找爱人给她讲一下这个学习法，第一目标是她说能听懂，第二目标是她也能完整复述出这个学习法的四个步骤（MA）。\u003c/p>\u003cp>三、不欠债，给自己定下规则，这个学习法不吃透，决不进行其他拆页的练习，\u003c/p>\u003cp>四、打比喻，我忽然想到我有个卖酱油的朋友最近当了一种直销膏药的讲师，天天到处讲课，现在居然被人称为教授专家了，通过讲课成专家这样的事在直销界挺多见的，所以我就把这种通过讲述达到掌握知识的技巧叫酱油教授学习法（R）。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1550758530000,"updated_at":1550759425000,"ria":true},{"id":7121,"topic":"费曼学习法","learn_goal":"1-2过级","remark":"用费曼学习法提高学习效率。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"灿阳","city":"邯郸"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 大家好，我是灿阳。我现在是一名宝妈，在基层政府部门工作。平时喜欢看电影、看话剧、阅读以及参加各类线下活动。刚刚加入拆书帮，开始了跟小伙伴们一起线下升级打怪的旅程。\r\n我今天跟大家分享的拆页来自于一本书——《如何高效学习》，作者是加拿大人斯科特.扬，2012年，他用一年的时间自学了33门计算机科学，并最终通过了考试，而这对于普通人来说需要四年的时间。本书就是对他学习方法的全面介绍，跟随作者，我们也可能成为高效学习的超级学霸。今天我们要学习的就是他常用的一个学习方法：费曼技巧。\r\n现在让我们分一下组，按今天的人数我们分为两组，按坐在桌子两边的位置分吧，组长分别是韩哥和彦晴。（发稿）\r\n请大家阅读手里的拆页，阅读完示意我一下。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10516,"quote":"\u003cp>下面我来演示费曼技巧的操作流程,你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;第一步:选择要学习的概念&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;首先选好你打算深入理解的概念,拿一张空白纸,在最上方写下概念的名称。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;第二步:设想你是老师,正在试图教会一名新生这个知识点&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂,并把你的解释记录下来。这一步至关重要,因为在自我解释那些你理解或不理解的知识过程中,你会理解得更好，而原先不明白的地方也得以理清。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;第三步:当你感到疑惑时,返回去吧&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;每当你碰到难题感到疑惑时,别急着往下走,学习不是单行道,回过头来,重新阅读参考材料、听讲座或找老师解答,直到你觉得搞懂了为止,然后把解释记到纸上。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;第四步:简单化和比喻&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;如果你的解释很啰唆或者艰涩,尽量用简单直白的语言重新表述它,或者找到一个恰当的比喻以更好地理解它。&nbsp;\u003c/p>","explains":"\u003cp>What：这段话讲的是如何运用费曼技巧来提高学习效率。\u003c/p>\u003cp>Why：有一位作家曾经说过，人与人之间的差别，大于人与猪的差别，而据研究，人与人的智力水平相差并不大，那么，究竟是什么原因导致的这种差别呢？答案是学习力。由于学习方法、学习习惯的不同，导致人与人在学习力方面有很大的差异，这种差异随着时间的延长导致人与人之间的差距越来越大。那么应该怎么提高学习力呢？其中一个方法是使用费曼技巧，费曼技巧能极大的提高学习效率，这就是我们要学习它的原因。\u003c/p>\u003cp>How：那么该如何做呢？方法如下：\u003c/p>\u003cp>\u003cstrong>第一步：挑选概念\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;首先挑出你想学的概念，把它写在一张空白纸上的最上方。\u003c/p>\u003cp>\u003cstrong>第二步：讲解概念\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;设想，你面对的是一个菜鸟，或者是一个十岁的孩童，你要试图向其解释清楚这个概念，并让对方完全听懂。将解释写到那张空白纸上。\u003c/p>\u003cp>\u003cstrong>第三步：重新返航\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;当你在记录的过程中，一旦遇到自己写不下去的情况要及时返回重新学习，弄清楚自己到底遗漏了哪些关键要点，或者被困在了哪个环节，再次理解概念，并把解释记下来。\u003c/p>\u003cp>\u003cstrong>第四步：简化类比\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;要尽量使语言简洁、明了，并且可以使用比喻的方法让讲解更加生动、更加容易理解。\u003c/p>\u003cp>Where：费曼技巧适用范围非常广泛。它不仅仅适用于学习概念，也适用于学习观点。不仅适用于理科，也适用于文科。无论是成人学习还是参加考试，都可运用此方法，它也可以用来检验我们的学习效果。\u003c/p>\u003cp>比如有一次我看了李雪老师写的一本关于亲子教育的心理学书《当我遇见一个人》，那本书给我的感触非常大，其中有一个观点说孩子不是宠坏的，应该给予他最大的爱与自由。在我们几个闺蜜聚餐的时候我本来想分享给她们，但是我发现我表达不清楚，所以到最后只能说，真的，这本书真是特别好，你们一定要看看。要知道对于不爱看书的人来说，这基本上是不可能的事情，所以我的这个建议基本没用。我很懊恼，因为这件事不止发生过一次，我一直想改变这种状况却又没有办法，直到学习了费曼技巧。对比一下我的例子可以发现，在第一步挑选概念时，我选的是一个观点，这也可以，但是没有事先把它写下来。第二步讲解概念时，我进行的是实际演练，所以发现自己讲不下去就停止了这个话题，我应该事先把解释写到纸上。第三步重新返航，我只是很懊恼却没有重新回头去看书。第四步简化类比，这步就更没有做到了。&nbsp;\u003c/p>","interaction":"\u003cp>A1：激活经验\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>我们经过拆页和讲解，已经知道了如何用费曼技巧来进行学习以及验证学习效果了。现在请大家想想自己有没有在学习的过程中感觉自己学的不太好，效率不高，或者想归纳知识点的时候做的不够好。比如明明认真读完了一本书，但是在读书会分享的时候却想不起来内容；明明对一篇文章里的观点认同的不得了，却在跟闺蜜分享的时候说不清楚你的观点。现在请每人想一个实例，并在小组内分享。&nbsp;\u003c/p>\u003cp>学习者案例分享：\u003c/p>\u003cp>大侠：我在读书会每次分享读书心得的时候，有时会用到书里面的专业术语，然后就看到大家一脸茫然的样子，但是我又不知道该如何跟大家解释这个专业术语，于是分享了之后效果并不是很好，大家的收获并不大。\u003c/p>\u003cp>A2：催化应用&nbsp;\u003c/p>\u003cp>拆书家提问设计：下面发给大家便利贴，请大家根据学到的费曼技巧对于今后要学习的新的知识规划一下未来运用，比如一个概念，一个观点，一章节的内容等等。我们不做类似下决心的表述，最好有明确的时限、目标、具体行动、以及如何衡量是否达成目标，最好呢还能有人跟你互相督促。\u003c/p>\u003cp>比如当你下次参加读书会的时候你准备分享几个观点呢？你能用费曼技巧来学习该如何分享吗？如果讲不清楚观点又该如何做呢？\u003c/p>\u003cp>学习者案例分享：\u003c/p>\u003cp>彦晴：我最近在读《认知天性》，我想明天用费曼技巧的方法来学习里面的一个新的名词或者概念，并且把这个概念讲给我的妈妈听，如果她能听懂就说明我学的不错。\u003c/p>\u003cp>总结：通过今天的费曼技巧的学习，希望能够帮助到大家在以后的学习阅读中可以更好的掌握知识，只要对大家有一点帮助，也算今天我没有白讲，感谢大家的配合，真心希望今天的小知识能够帮助到大家，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1548219327000,"updated_at":1548777483000,"ria":true},{"id":6922,"topic":"费曼技巧","learn_goal":"学习者能够运用费曼技巧学习新知识","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"张晶","city":"海口"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;小伙伴们大家好！我现在先进行分组，请坐在我左手边的两位一组，右手边两位是第二组。因为后面会有讨论环节，所以我们提前把小组分好。\r\n &nbsp; 大家好！我是张晶，张大千的张，亮晶晶的晶。目前是两个孩子的宝妈，新晋菜鸟拆书家，终生学习者。\r\n &nbsp; &nbsp; 今天我想跟大家分享的这个片段来自《如何高效的学习》。作者斯科特扬是一位学习达人，他运用自己的学习方法，12个月内自学完成4年麻省理工学院计算机科学的33门课程。今天我跟大家分享的书中一个有用的方法，叫做费曼技巧。\r\n现在请大家阅读原文。读完的请举手示意我。谢谢\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10288,"quote":"\u003cp>《如何高效得学习》P133-134&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;运用费曼技巧, 你能达到过目不忘。\u003c/p>\u003cp>理查德 D. 费曼 (Richard D Feynman), 美国物理学家,诺贝尔奖获得者, 曾经任教于普林斯顿大学物理系。费曼挑战任何一位普林斯顿大学数学系的教授, 即不管这些教授告诉费曼多么复杂难懂的数学知识, 只要他们使用简单的术语(不得使用费曼觉得生僻复杂的单词或术语)去描述, 费曼就一定会得出同样的结果。\u003c/p>\u003cp>这则故事常常拿来证明费曼是个伟大的天才。不过现实中, 这个技巧人人都能掌握,接下来,我就告诉大家具体如何去做。\u003c/p>\u003cp>费曼技巧的具体措施:\u003c/p>\u003cp>(1) 理解那些你没有真正掌握的知识点。(2)记住那些你能理解, 却可能在考试中遗忘的知识点。(3) 作为一个考前学习的高效率方法。 很多学生花了不少时间在图书馆度过, 学习效果却平平, 运用费曼技巧, 你只需花上20分钟就能深入理解知识点, 而且记忆深刻, 难以遗忘。\u003c/p>\u003cp>下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩：\u003c/p>\u003cp>第一步：选择要学习的概念——首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称；\u003c/p>\u003cp>第二步：设想你是老师，正在试图教会一名新生这个知识点——这一步你要假设自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理解。\u003c/p>\u003cp>第三步：当你感到困惑时，返回去——当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读参考资料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>第四步：简单化或比喻——如果你的解释很啰嗦或者艰涩，尽量用简单直白的语言重新表述他，或者找到一个恰当的比喻以更好地理解它。\u003c/p>","explains":"\u003cp>费曼技巧就是，把要学的知识点拆分成小知识点，写在纸上，并使用人人都懂的通俗语言讲给假想的学生听。最终目的是让自己真正掌握该知识点。多数时候我们学习知识，只是读或是看一遍，就认为掌握了。当你想跟别人分享时，才发现根本表达不出来。我们学习知识需要外部语言去描述、串联，唯有经过外部语言检验，才是真正的掌握理解！\u003c/p>\u003cp>你可以把费曼技巧应用在学习各种理论概念、操作技能、思维和工作方法中。\u003c/p>\u003cp>那么如何操作呢？我分为五个步骤：\u003c/p>\u003cp>1、明确：即明确要学习的概念是什么，写下来。\u003c/p>\u003cp>2、教授：即假想正在讲解给一个完全不懂的人听。\u003c/p>\u003cp>3、完善：即反省完善。讲解的过程中，遇到一知半解的知识点，记录下来。\u003c/p>\u003cp>4、重复：重复2-3步骤，逐步解释，梳理知识点，直到再没有难点为止。\u003c/p>\u003cp>5、包装，即包装知识，使用简化的语言和比喻。假如我给8岁的小孩或者80岁的人讲，他们能听懂吗？\u003c/p>\u003cp>举个例子，最近我在吃保健品，包装上写着胶原低聚肽。儿子就问我：什么是胶原低聚肽？\u003c/p>\u003cp>第一步我先在纸上写下胶原低聚肽，然后上网搜索了相关知识。低聚肽胶原蛋白又叫寡肽，是两个以上十个以下氨基酸组成的肽，具有一定的生物活性。问自己这样孩子能听懂吗？不能！\u003c/p>\u003cp>我于是再返回重复2-3步，抠出不懂的字眼，再次细化。最后第五步得出一个简单的表达：胶原低聚肽，就像火车的一节一节的车厢，每一节车厢就是一个氨基酸。很多节车厢连接起来，就形成了肽。这样一列一列的火车进入到我们的身体，就能给我们提供营养。\u003c/p>","interaction":"\u003cp>我想请在座小伙伴们回忆并讨论一下，你们从前都是用什么方法学习一些生涩的知识点的呢？\u003c/p>\u003cp>现在小组讨论3分钟。等会请一位小伙伴跟大家分享他的经历。\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>阿拉丁分享：\u003c/p>\u003cp>他高中时，遇到一些题目，发现有同学不会，就主动找人去讲解。当时觉得讲过就印象特别深刻。如果没讲明白就组织语言再来一次，直到对方明白为止。后来回想起来，其中收益最大的是自己。那时候，还不知道原来这个方法叫做费曼技巧。\u003c/p>\u003cp>刚才我们一起学习了费曼技巧。我现在请大家规划一项下周学习计划，可以是学习某个理论概念、操作技能、思维方法、工作方法等。要求是必须运用到费曼技巧。请注意要有明确的时限，要有可以量化或可以观测的预期结果。\u003c/p>\u003cp>例如：7天内我计划，学习《提问力》这本书的前两章，并使用费曼技巧，用自己的语言解释3个提问方法。\u003c/p>\u003cp>1分钟后邀请一位小伙伴跟大家分享以下他的计划。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>12月31日前，学习《教会你的孩子如何思考》的第三章，用费曼技巧学习里面的6个思考工具（CAF\\P.M.I/A.G.O/O.P.V/FIR/A.P.C等），并写出6个便签。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1545978368000,"updated_at":1545978485000,"ria":true},{"id":6248,"topic":"整体性学习方法的顺序---黄荣","learn_goal":"通过学习这个片段，希望大家能具体实践，将整体性学习的方法运用","remark":"整体性学习是一种学习理论，需要采取多种途径综合学习，是运用大脑里已有的丰富的神经元网络吸收、整合信息。整体学习法有5个步骤：获取、理解、拓展、纠错、应用。还有一个步骤是测试，它是需要在每一步去实行的。\r\n本次学习目标：通过学习这个片段，希望大家能具体实践，将整体性学习的方法运用到自己的学习中，提高学习效率，轻松学习，可以在短期内学习更多的知识和技能，并且取得好成绩。","level":"TF1-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"嗲嗲~","city":"葫芦岛市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; 大家好，在开始拆书之前，为了更好的促进我们的学习，方便接下来的活动，先给大家分一下小组。我们一共是4个人，就分为两个小组，每个小组两人。左面的两个同学一组。右面的两个同学一组。分组完成。 &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 在开始之前，正式自我介绍一下，我叫黄荣，现在是一名大二的学生，想要成为一名拆书家。接下来介绍今天拆页片段。今天的拆页片段来自《如何高效学习》这本书。作者是斯科特·扬，他是加拿大的大学生，就读于麻省理工，（本书出版时间是2014年）。他是一位因为快速学习而成名的神奇小子，他应用自己发明的学习方法，完成了10天搞定线性代数，1年学习4年MIT课程的“不可能任务”。本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。跟随作者，你也将成为高效学习的超级学霸。今天要讲的片段是这本书中的整体性学习的顺序。通过学习这个片段，希望大家能具体实践，将整体性学习的方法运用到自己的学习中，提高学习效率，轻松学习，可以在短期内学习更多的知识和技能，并且取得好成绩。接下来请大家阅读一下这个片段。&nbsp;&nbsp;&nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9532,"quote":"\u003cp>整体性学习的顺序\u003c/p>\u003cp>到目前为止，我已经描述了信息在头脑中是如何储存的。但是，首要的问题是：信息是怎么来的？\u003c/p>\u003cp>任何学习都可以分成几个独立的步骤。如果只是为了通过一次考试，你并不需要完成所有步骤，也不需要理解得非常深入。完成步骤的顺序也不需要固定不变，你完全可以完成第二步后再跳回第一步继续学习。\u003c/p>\u003cp>每一个步骤对学习都很重要。如果你总是缺少某一步骤，或者某个步骤完成得不好。信息就不会得到很好的存储，这种学习就是失败的，因为信息不能整合到你的整体性认识中去。为了看一看每一步是如何纳入到整体性学习理论中的，我们可以采取一些学习策略，通过这些策略，你可以弥补自己现有技术的不足。当然，你也可以自己发展出些新的方法来替代不合适的环节。\u003c/p>\u003cp>整体性学习的顺序：\u003c/p>\u003cp>（1）获取\u003c/p>\u003cp>（2）理解\u003c/p>\u003cp>（3）拓展\u003c/p>\u003cp>（4）纠错\u003c/p>\u003cp>（5）应用\u003c/p>\u003cp>还有一个测试步骤是伴随上述每一步的。测试就是观察以上五个步骤做得好不好，严格的测试能发现问题出在哪里。\u003c/p>\u003cp>以下是这六个步骤的简单介绍\u003c/p>\u003cp>（1）获取\u003c/p>\u003cp>获取就是信息进入你的眼睛和耳朵，阅读、课堂上记笔记以及个人的种种经历都是获取。获取阶段的目标是获取的信息要准确，信息量要尽量压缩。\u003c/p>\u003cp>（2）理解\u003c/p>\u003cp>理解就是了解信息的基本意思，并放在上下文中联系，这是学习的最基本联系。\u003c/p>\u003cp>（3）拓展\u003c/p>\u003cp>拓展阶段是整体性学习中最花力气的地方，这一步将形成模型、高速公路和广泛的联系，从而获得良好的结构。\u003c/p>\u003cp>（4）纠错\u003c/p>\u003cp>纠错阶段是在模型和高速公路中寻找错误，这个阶段。要删除那些无效的联系。\u003c/p>\u003cp>（5）应用\u003c/p>\u003cp>应用把纠错带入最后的水平，通过比较（知识）信息是如何在现实中运行的来进行调整，如果理解不符合现实世界，那么再多也无用。在这一步中失败的典型例子就是书呆子，即那些读书读得很好但是出了学校大门却茫然不知所措的家伙。\u003c/p>\u003cp>（6）测试\u003c/p>\u003cp>上述阶段的每一步都需要测试，测试有助于你迅速找到学习中的问题所在，帮助你改进学习技术，克服缺点。\u003c/p>","explains":"\u003cp>现在大家已经阅读完了片段，这个片段清晰的写出了整体性学习的顺序。大家可能还不太理解整体性学习，下面我简单的介绍下整体性学习方法。整体性学习与机械记忆正好相反。机械记忆就是反复记忆信息，希望以此牢记信息。整体性学习是一种学习理论，它更精确、全面地描述了我们大脑是如何工作的。大脑并不像计算机一样用二进制来进行存储，大脑是通过神经元相互联系来存储信息的。整体性学习需要采取多种途径综合学习，是运用你大脑里已有的丰富的神经元网络吸收、整合信息。整体性学习在于创造信息的网络，一个知识与另一个知识相互关联，那些相互关联的知识网络使你真正做到对知识的完全理解，从而轻松地驾驭知识。整体性学习是关于如何有效学习的假说。之所以说它是假说，是因为目前整体性学习还缺少科学证据，更多的是实践总结。整体性学习是通过观察聪明的人是如何学习而得到的总结。这就是整体性学习法。整体学习法有5个步骤：获取、理解、拓展、纠错、应用。\u003c/p>\u003cp>第一步：获取信息而不理解是没有任何价值的，这就是所谓的填鸭式学习。假如你不理解一本书、一章节、一段话说的是什么意思，要想牢牢记住它或者在实际生活中应用它几乎是不可能的\u003c/p>\u003cp>第二步：在理解阶段，你只是理解了信息的表面意思。举个例子，比如你正在学习一个新的数学公式，你要知道公式里每个符号代表的是什么。\u003c/p>\u003cp>第三步：在拓展阶段要应用模型来简化和扩展你的结构，同时也要拓展对信息的理解，包括信息的由来（问为什么？）以及与其他信息是怎么联系在一起的。比如：公式是怎么来的？公式中的每个成分代表的真实含义是什么？公式中的什么成分可以做些改变？这种改变会导致结果发生什么样的变化？其他公式与这个公式有什么相同之处，又有什么不同之处？\u003c/p>\u003cp>第四步：纠错可以采取多种方法，包括阅读那些与你观点相反的书籍，以及把结论放入现实世界中看看等方法。\u003c/p>\u003cp>第五步：应用是学习的最终目的，能做到学以致用方能更好地适应现实世界。如果你学习税法并用到自己的企业管理中，那肯定比纸上谈兵学得好。如果你学习统计学，又把学到的知识用在实验设计上，那你对统计学的理解一定更深刻。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 还有一个测试是需要在每一步去实行的。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ·获取阶段的测试——我以前看过或听过这个知识吗？\u003c/p>\u003cp>·理解阶段的测试——我理解知识的含义吗？（至少是字面上的意思。）\u003c/p>\u003cp>·拓展阶段的测试——我知道知识从何而来，与哪些知识有关系吗？\u003c/p>\u003cp>·纠错阶段的测试——我删除了那些不恰当的联系吗？我删除了那些错误结论吗？\u003c/p>\u003cp>·应用阶段的测试——我将知识用到实际生活中了吗？ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 这就是整体性学习的顺序。\u003c/p>","interaction":"\u003cp>A1:听了以上的讲解，相信大家都学习到了这个片段，那么想一想，我们之前有哪些相关的经历或者经验呢？ 我来举个例子：比如说学习高数中的格林公式。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (1) 获取：我们通过老师讲课、记笔记、自己看书、看视频、询问同学来获取知识。(测试：我以前学过吗？)\u003c/p>\u003cp>(2) 理解：高数中的格林公式是用来求平面闭区域上二重积分的，并且有限定条件。(测试：我理解他们的含义吗？)\u003c/p>\u003cp>(3) 拓展：格林公式的计算需要用到积分的知识。(测试：这些知识之间是不是有什么关联？他们到底是怎么得出的？)\u003c/p>\u003cp>(4) 纠错：格林公式不能求所有的曲线积分。（测试：联系生活实际，用这个公式算，最后是正确的吗？）\u003c/p>\u003cp>(5) 应用：利用格林公式计算构件的质量，合理使用材料。(测试：我真的用到生活中了吗？运用的是否正确呢？)\u003c/p>\u003cp>A2:拆书家提问设计（逐字稿）：大家刚刚已经讲了自己过去的经历，我们学习这个片段并不只是希望回顾过去，现在请大家在便签上写出自己以后运用时的行动或者结合自己以前的经历，写出如果再遇到类似事件要如何利用整体性学习方法的顺序解决。 例子：在学习计算机语言Java时 ： &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>(1)获取：要学习计算机语言Java，老师课堂上会讲基础知识，记笔记，课后复习书上知识点。\u003c/p>\u003cp>(2)理解：Java要学哪些方面的知识，有多少内容需要掌握，有多少只需要理解意思即可\u003c/p>\u003cp>(3)拓展：学习C语言的时候有哪些类似的地方；Java语言的优点是什么，缺点在哪里；学习Java比学习C语言好在哪里；Java以后得发现怎么样；以后哪些学科会用到Java的知识呢。\u003c/p>\u003cp>(4)纠错：Java语言和C语言都是一种编程语言，两者有很大不同。Java更加注重实际操作，而不是理论知识\u003c/p>\u003cp>(5)应用：运用Java语言编写程序，解决同学个人信息统计问题。\u003c/p>\u003cp>学习者案例记录：利用整体性学习的方法掌握工数。行动1.上课认真听课（理解和认知新理念）2.联系高数、线代、大物、寻找共同点（拓展）3.做练习，询问老师，获得反馈（纠错）&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1539731613000,"updated_at":1539773160000,"ria":true},{"id":6240,"topic":"绝不拖延——黄荣","learn_goal":"通过学习这个拆页希望能帮助大家解决遇事拖延的习惯，运用周/日","remark":"大多数人或多或少都有遇事拖延的习惯，这个片段给出了解决拖延问题的解决方法——周/日目标系统，通过做周计划和日计划以及总结来摆脱拖延。","level":"TF1-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"嗲嗲~","city":"葫芦岛市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，很高兴这次能见到帮外的伙伴们来到我们的拆书现场，希望我们的活动能让你们收获满满。我是这次的分享者之一，我叫黄荣。和大家一样是一名大学生，想要成为三级拆书家，现在正在晋级当中。希望大家能多多给出建议。\r\n为了方便大家接下来的学习，现在给大家分一下组。我们一共是5个人，所以让我们分为两组，我左手边的两个伙伴一组，右手边的三个同学一组。好，分组已经完成了。\u003c/p>\u003cp>FAB法介绍图书：下面我介绍一下，这次我选择的拆页片段的来源。它来自《如何高效学习这本书》，作者是斯科特·扬。这本书向我们介绍了整体性学习的方法。有了这套方法呢，我们可以避免上课随便听，考前疯狂记，半年忘光光的学习状态。通过学习这套方法，你可以花费更少的时间，学到更多，有效地提高学习效率。像作者一样一年完成 MIT 4年三十三门课程。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9539,"quote":"\u003cp>高效率秘籍3 绝不拖延\u003c/p>\u003cp>如果一项作业完成的日期是下周四,你属于下列哪种人?\u003c/p>\u003cp>A.尽快完成\u003c/p>\u003cp>B.在今天至截止日期之间的某个时间,一次完成作业\u003c/p>\u003cp>C.星期三晚上\u003c/p>\u003cp>D.星期四早上,上课前10分钟\u003c/p>\u003cp>很不幸,我知道大多数学生会选择C答案或D答案,哪一个答案是最佳选择?不过我也并不认为A是最理想的选择,如我所解释,不延迟并不意味着尽量早地完成工作。 \u003c/p>\u003cp>最佳答案(在多数情况下)应该是B,一次性完成作业比分次完成更节省时间。 此外,如果你采用周/日目标方法来完成作业,效果会更好。\u003c/p>\u003cp>周/日目标体系\u003c/p>\u003cp>周/日目标体系是我知道的最好的对抗延迟的方法,办法很简单: \u003c/p>\u003cp>&nbsp;1.每周周末,列一个清单,包括所有的任务,作业以及你想在下周完成的读书和学习活动。 \u003c/p>\u003cp>&nbsp;除非在一周内出现意想不到的事情,否则你就有责任完成这个清单,不过也不必超过清单所规定的任务。这样做就把无限的工作分割成在一周内可以完成的子任务。如果这一周特别忙碌,你可能会推迟完成任务。如果这一周很清闲,\u003c/p>\u003cp>你可能会提前完成任务。\u003c/p>\u003cp>2.每天晚上,检查周计划,列出每日目标清单。\u003c/p>\u003cp>下一步是将每周的工作分配到每一天,你要确保完成每日的工作清单,但是不必超过它。\u003c/p>\u003cp>周/日目标系统有什么好处? \u003c/p>\u003cp>(1)可以缓解你作决策的应激。 你只需检查清单,就明白是否完成。\u003c/p>\u003cp>(2)防止你做一项大任务时耽搁不前,依赖每周和每日目标清单,而不是截止日期,你会有时间紧迫感。\u003c/p>\u003cp>(3)帮助分配你的工作量。通过制订计划,你可以将工作适当分配到周和日,不需要考试前熬通宵而前三周一个字不看，你可以细分工作\u003c/p>","explains":"\u003cp>这个片段针对拖延，给出了解决的方法。那就是周/日目标系统。很简单，第一，每周周末列出自己下周要完成的所有事情，学习方面的，生活方面的，个人成长方面的等等。这些事情可以是长期目标的分解，可以是短期重要需要完成的事情。按照这个清单，一项一项的去完成。如果这周的事情比较少，那你可以早些完成，而且也不必多做，如果这周比较忙，那可能会晚些完成，但也不会出现一直延迟的现象甚至是不做。第二，每天晚上检查周计划，列出每天的目标清单。意思就是把一周内要完成的所有事情细分到每一天，确保你可以完成它。\u003c/p>\u003cp>不这么行动的坏处：为什么一定要这么做呢？想像一下你没有做这个计划(或许你现在就是没有)如果突然出现了紧急的情况，需要一定时间去解决，你是不是会放弃一件事情，而利用这个时间去做其他的事情呢？就像组织，班级或者老师突然有事情交给你去做，而你已经打算好了要写作业或者做其他事情，这个时候你只能放弃。这样我们每天就好像一直在“救火”，忙的不可开交，结果就是将一些不紧急的事情一拖再拖，最后慌忙的去完成，质量大打折扣，自己都不满意，身心疲惫。再想一下，如果还有60天你就要参加英语六级的考试，你是选择现在就开始备考，还是考试一周前备考呢？我们\u003c/p>\u003cp>都知道考六级需要提前备考，单词，听力等等需要长时间的记忆，训练。一周内背2000个单词，你会累成什么样子？大家心里或多或少会有感触。\u003c/p>\u003cp>目标：通过学习这个拆页希望能帮助大家解决遇事拖延的习惯，不断地完成自己设立的目标，摆脱拖延的困扰。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>\u003cstrong>(\u003c/strong>\u003cstrong>逐字稿\u003c/strong>\u003cstrong>)\u003c/strong>:\u003c/p>\u003cp>显像提问法：现在请大家和我一起想像一下：在过去，你有没有出现过作者说的情况呢？你的专业老师现在给你留了2个小时才能完成的作业，你要选择什么时候去完成呢？平时这种情况你是什么时候完成的呢？在写作业的时候你又是什么心情呢？焦虑不安，抵触，无奈？\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>:\u003c/p>\u003cp>老师留了HTML的小组作业，由于老师没有明确日期，学习者觉得时间还充裕，一直拖延没有去做，最后不得不急忙完成作业，导致作业的质量无法保证。\u003c/p>\u003cp>A2:\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>\u003cstrong>(\u003c/strong>\u003cstrong>逐字稿\u003c/strong>\u003cstrong>):\u003c/strong>\u003c/p>\u003cp>反思加工经验：那么，你之前有过哪些拖延的经历呢？写作业？准备比赛？他们让你感受到了什么？如果再出现那样的情况，你会怎么去做呢？运用拆页中的方法，你能更好的处理吗？下面请大家组内讨论并在便签上写下自己过去的经历以及如何去克服拖延。(这是我们周计划和日计划表，大家可以参考)。\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>\u003cstrong>:\u003c/strong>\u003c/p>\u003cp>有一篇写过的文章需要去修改，但是与自己的其他计划有冲突，所以一直搁置了。现在修改也忘了好多老师指导的地方。通过片段的学习，会把事情任务分解到一周一天，及时修改文章，避免拖延。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1539685179000,"updated_at":1539767560000,"ria":true},{"id":6033,"topic":"联想法","learn_goal":"学完后，能够使用联想法帮助学习者记忆随意信息。","remark":"你是否遇到过记忆随意性信息时感觉困难，比如说你要超市购物，经常是买了西瓜忘记了买牛奶。怎样才能帮助我们比较容易地记住这些随意性信息，怎样才能帮助我们提高记忆能力？只要四个步骤，你将了解联想法来高效记忆。请你来到9月9日上午的东莞分舵分场，让拆书家带你学习联想法！","level":"TF3-1","duration":50,"status":29,"type":0,"chaishujia":{"username":"曾金泉","city":"东莞"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"开场：\r\n 大家好，欢迎来到TF3-1的拆书现场。\r\n我是拆书家曾金泉，用3个标签来介绍一下我自己：国家二级人力资源管理师，高级培训师，二级拆书家。\r\n今天人有点多，我们分成三组：前面左边为一组，右边为一组。后面一组。\r\n【学习目标】\r\n学完后，能够使用（行动）联想法四连环（澄清）帮助学习者记忆随意信息（界定）。\r\n【图书介绍】（学习者场景介绍法）\r\n【事件场景】你是否遇到过记忆随意性信息时感觉困难，比如说你要超市购物，经常是买了西瓜忘记了买牛奶。\r\n【提问】怎样才能帮助我们比较容易地记住这些随意性信息，怎样才能帮助我们提高记忆能力？\r\n【影响】随意信息是整体性学习中的一个难点，死记硬背，我们总是记了就忘了，而且还浪费时间，造成学习效率低下。\r\n【解决】以上的现象和疑惑，都可以在这本斯科特•扬所写《如何高效学习》一书中找到答案，联想法是整体性学习的一个重要方法，运用联想法将会帮助你记忆随意性信息。","ratings_count":1,"texts":[{"id":9274,"quote":"\u003cp>【原文片段】联想法\u003c/p>\u003cp>《如何高效学》P104-106页：联想法\u003c/p>\u003cp>随意信息是整体性学习中的一个难点。针对随意信息，如何联系、比喻以及内在化呢？\u003c/p>\u003cp>例如：\u003c/p>\u003cp>l&nbsp; 一系列日期\u003c/p>\u003cp>l&nbsp; 解剖学术语\u003c/p>\u003cp>l&nbsp; 系列步骤\u003c/p>\u003cp>l&nbsp; 各种各样的规章、条例\u003c/p>\u003cp>l&nbsp; 科学公式\u003c/p>\u003cp>一般情况下，这些信息只能靠机械记忆了，整体性学习则要尽可能地避免死记硬背。取而代之，用比喻、内在化和图表法，创建模型和最终的结构是应用大脑的最好、最快的方法。不过，在有些情况下，这些办法效果并不好。随意信息，或者内容太多、太复杂的信息，都不容易被理解，它们需要不同的技术。假如你发现联想法不能帮助你理解材料，或者需要花费的时间太长，这时候处理随意信息。这些处理随意信息的方法介于机械记忆和整体性学习之间。\u003cstrong>联想法、挂钩法就是处理随意信息的方法，它们能加速记忆，而且也符合大脑的学习方式。\u003c/strong>（这么做的好处）机械记忆好比钝刀切菜,整体性学习就是寒光闪闪的解剖刀，而联想法、挂钩法则算是切牛排的餐刀。（前因后果，适用边界）\u003c/p>\u003cp>处理随意信息的方法需要不断地练习，理由如下。\u003c/p>\u003cp>(1)不经常使用它们。我平时很少使用联想和挂钩法正因为不常用，所以练习非常重要。\u003c/p>\u003cp>(2)这些方法比较复杂。联想法、挂钩法和信息压缩技术很少依靠直觉，需要多加练习才能很好地掌握\u003c/p>\u003cp>小贴士一\u003c/p>\u003cp>随意信息的结构很弱，总是需要某种转化后才学习\u003c/p>\u003cp>弱—重复学习。\u003c/p>\u003cp>好—通过联想法、挂钩法以及信压缩技术学习。\u003c/p>\u003cp>最好—通过比法、内在化法及图表学习。\u003c/p>\u003cp>联想法\u003c/p>\u003cp>联想法并不是我首创的，作为一种记忆技巧，它已经存在很多年了。之所以称为联想法是因为它的目的是将一系列观点串在一起，就像链条旦进入链条中的一环，就可以轻易地到达链条中的其他环节。\u003cstrong>联想法在处理一系列随意信息时效果很好，（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>）包含步骤的过程信息、（2\u003c/strong>\u003cstrong>）按顺序写下的名字或公式，（3\u003c/strong>\u003cstrong>）都可以应用联想法随着不断地练习，（4\u003c/strong>\u003cstrong>）你可以迅速地将数十个知识点连在一起。\u003c/strong>\u003c/p>\u003cp>【拆书家指令】请大家快速阅读完片段。阅读完的小伙伴举手示意一下我。\u003c/p>","explains":"\u003cp>【概念与匹配案例】\u003c/p>\u003cp>[WHAT]联想法就是运用想像把需要记忆的信息进行联结记忆的学习方法。\u003c/p>\u003cp>[WHY]我们学习联想法的“联想四环”：找顺序——定清单——列编号——强记忆。对随意性信息的记忆采用联想法的好处就是强化记忆，建立逻辑关系，并运用强烈的想像，夸张的想像，让自己印象深刻，从而顺记倒记，都能倒背如流。今天我们将用几个小案例，都是非常夸张的，所以，就是看起来毫无联系的词也能在讲完故事后就马上记住了。测试的结果，也是非常有效的。比如说我之前发给小星星看，问他能不能理解，他说很难，但是看完以后就记住了，而且还哇啦哇啦地跟他的师父姐姐说，故事里少了烤豆。一看，果然如此。联想法和作者提到的比喻法也不相同，它们之间最大的区别在，联想法是事物之间本无联系，通过记忆者自已找到对应想像，建立关系。比喻法是指某物和某物之间本来就是有联系，比如说，某人胖的就象一座山，那么肯定是外观上给人感觉就是很胖很胖，而且上面小下面大，象一座山的形状。\u003c/p>\u003cp>联想法是本体就是记忆的重点。只是通过把本无联系的事物通过夸张的故事创建联系进行整体性记忆。联想法并不适用于简单记忆，逻辑性本来就很强的，非机械性记忆的信息，是不适用本法的。如果死记硬背速度快过本法，也不适用联想法。\u003c/p>\u003cp>死记硬背大家都懂，但是如果我们需要找到一种比单纯的死记硬背更快速的方法来记忆那些随意性的信息，这个时候大家就需要来学习联想法了。在这个拆页中，我们看到了联想法的定义和优点，到底怎么样才叫联想法？我给几个例子，大家来判断一下。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 【互动-判断题1】根据一个东西想象出另外一个东西？比如说你要记苹果，你想到一个大大的红色的苹果的图片。这个是联想法吗？\u003c/p>\u003cp>学习爱好者回答：是的。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 【互动-判断题2】根据一个东西想象出另外一个东西？比如说我的身材胖的象个大苹果。这个是联想法吗？ \u003c/p>\u003cp>学习爱好者回答：不是。是比喻法。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 【互动-判断题3】我们根据这束花想象到春天，这个是联想法吗？\u003c/p>\u003cp>学习爱好者回答：这个，有点象联想法。应该是的。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 【互动-判断题4】我们在记忆本片段知识点的时候，想到了电脑品牌“联想”，这叫不叫联想法？\u003c/p>\u003cp>学习爱好者回答：是的。是联想。\u003c/p>\u003cp>我们回看原文片段中的这个概念，之所以称为联想法是因为它的目的串在一起，就像链条，一旦进入链条中的一环，就可以轻易地到达链条中的其他环节。大家认真看看，现在理解它的意思了吗？接下来我们还要从原文中找出联想法的执行步骤。\u003c/p>\u003cp>大家能从原文中找到几个步骤？\u003c/p>\u003cp>学习爱好者们找步骤。并讨论。有人说三，有人说四。拆书家引导：好，我们可以先划一下（参见上面的原文片段中拆书家给了的引导数字。）有四个步骤：\u003c/p>\u003cp>[HOW]：联想四环\u003cbr>\u003c/p>\u003cp>•&nbsp;&nbsp;&nbsp; 1、明确顺序 \u003c/p>\u003cp>•&nbsp;&nbsp;&nbsp; 2、罗列清单 \u003c/p>\u003cp>•&nbsp;&nbsp;&nbsp; 3、给清单中的每一项设符号 \u003c/p>\u003cp>•&nbsp;&nbsp;&nbsp; 4、创建联想 \u003c/p>\u003cp>所以，我们从这里可以看出，联想法是一个针对整体性学习的工具，是要解开全部链条的学习方法，是目的和目的的串联，也是一个系统的串联，我们从中可以归纳出联想法的四边环步骤：\u003c/p>\u003cp>1、&nbsp; 明确顺序。\u003c/p>\u003cp>（预防异议）可能有的学习者会说，怎么明确顺序？我们来看这个词：“链条”。既然是链条就一定会有第一个，接着第二个，这就是顺序的隐喻。\u003c/p>\u003cp>2、&nbsp; 罗列清单。\u003c/p>\u003cp>这个步骤难不难？\u003c/p>\u003cp>比如我现在要记这条信息，怎样创建顺序？\u003c/p>\u003cp>先列清单：怎么列？123456。\u003c/p>\u003cp>3、&nbsp; 给清单中的每一项设一个符号。\u003c/p>\u003cp>拆书家问：这一步难不难？\u003c/p>\u003cp>学习爱好者们一脸茫然。\u003c/p>\u003cp>拆书家继续问：大家来看一下，这四步中最难的是哪一步？是不是就是这一步？\u003c/p>\u003cp>学习爱好者们点头。\u003c/p>\u003cp>拆书家继续问：那我们来看一下，是不是可以这么来想呢？每一个词对应一个画面。比如说：\u003c/p>\u003cp>1，民间借贷——联想一个老头愁眉苦脸拿着借条\u003c/p>\u003cp>2，旁边儿子叼着根烟，手持非法集资的牌\u003c/p>\u003cp>3，儿子旁边一高瘦丑老婆，拿把钱递给儿子身旁的一大汉，钱上面写着洗字\u003c/p>\u003cp>4，大汉的背心衣服上写着诈骗二字\u003c/p>\u003cp>5，远处一个西装男端着电脑玩鼠标，脑袋上方画股票曲线，西装男奸笑吐泡泡:内幕交易\u003c/p>\u003cp>6，再把12345用线连向操纵市场四个字\u003c/p>\u003cp>7，一付手铐加二条铁窗，写违法\u003c/p>\u003cp>拆书家问：大家觉得这么联想可不可以？\u003c/p>\u003cp>学习爱好者们：哇，太有趣了。还可以这么想？但是真的好深刻。\u003c/p>\u003cp>拆书家继续：好，那我们把联想串起来。\u003c/p>\u003cp>4、&nbsp; 创建联想。\u003c/p>\u003cp>老子民间借贷，儿子非法集资，老婆洗钱，小舅子诈骗这一家人，小舅子的上线用骗来的钱进行内幕交易，这里有一只黑手在操纵市场，但最终还是被木大侠发现，违法就会被查。\u003c/p>\u003cp>学习爱好者们瞪大眼睛，很兴奋，脸上露出了跃跃欲试的表情。有些学习爱好者还发出了赞叹的声音：“啊，原来可以这么记啊，真的太有用了！”\u003c/p>\u003cp>【好处】联想法能帮助我们把任何二个以上的随意性信息紧紧地联结在一起，我们能非常快速而且牢靠地记住这些信息。\u003c/p>\u003cp>【不这么做的坏处】我们也可以继续采用死记硬背，因为这种方法简单，但是耗费时间多，而且效果不好。\u003c/p>\u003cp>【预防异议】有的人会说，我用死记硬背挺好的，是的，如果是逻辑关系本身就很强的信息、很容易记住的信息就没有必要使用联想法了。\u003c/p>\u003cp>【适用边界】联想法更多的是针对机械记忆、那些相互之间没有逻辑关系的信息、随意性的信息，联想法会让你感觉事半功倍，而且记忆深刻。简单的内容就不适用这个方法了。\u003c/p>\u003cp>【成功的A1】\u003c/p>\u003cp>我们再来看一个拆书家本人的例子：泉水的宝贝女儿读高三了，一个月才回来一次，她给她妈提出要求说要吃水果和零食，昨天，拆书家泉水就去超市采购，在去之前，她把纸制清单丢掉，采用联想法进行记忆：香蕉、牛奶、烤豆、面包、黄油、果酱。具体怎么做呢？\u003c/p>\u003cp>1、&nbsp; 明确顺序：1香蕉——2牛奶——3烤豆——4面包——5黄油——6果酱\u003c/p>\u003cp>2、&nbsp; 罗列清单：1香蕉——2牛奶——3烤豆——4面包——5黄油——6果酱\u003c/p>\u003cp>从1开始，从1-6进行罗列，每一项都对应一个顺序的编号来把它列出清单。\u003c/p>\u003cp>3、&nbsp; 给清单中的每一项设符号：\u003c/p>\u003cp>1香蕉：一根巨大的香蕉\u003c/p>\u003cp>2牛奶：一群奶牛\u003c/p>\u003cp>3烤豆：奶牛嘴里在嚼着烤豆\u003c/p>\u003cp>4面包：挤奶工手里拿着面包，一手拿着挤奶的桶子\u003c/p>\u003cp>5黄油：远处放着黄油要抹在面包上的\u003c/p>\u003cp>6果酱：黄油旁边放着果酱\u003c/p>\u003cp>4、&nbsp; 创建联想：\u003c/p>\u003cp>首先，我们要想象一幅图画来联系香蕉和牛奶，我想象到的图画是一只巨大的香蕉上面，有一群奶牛在散步；旁边有一个挤奶工拎着桶子准备挤牛奶，挤奶工嘴巴里嚼着烤豆，他一手拿着面包象是在招呼奶牛们来吃，旁边还准备了好吃的黄油，黄油旁边有果酱，奶牛们可以根据自己的喜好去挑选，这样奶牛们就能挤出很愉快的奶了。\u003c/p>\u003cp>学习爱好者们纷纷点头。张思英非常感叹地说：太实用了，太有用了，我完全记住了。\u003cbr>\u003c/p>","interaction":"\u003cp>【拆书家指令】\u003c/p>\u003cp>在大脑中过一遍，就近似于实际中应用一遍，今天请每一位学习者来设计一个剧本，几百字即可，其中部分要运用今天学习的“联想法四环”的技巧，摘要写在一张纸上，时间五分钟。五分钟后我们请人分享。按下面的模版写一个剧本，\u003c/p>\u003cp>\u003cstrong>要求：\u003c/strong>在对话中要针对联想法，剧情的结果能完整呈现联想四环的步骤。\u003c/p>\u003cp>具体格式如下：\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;\u003c/strong>\u003cstrong>主题：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; 时间：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;\u003c/strong>\u003cstrong>地点：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;\u003c/strong>\u003cstrong>人物：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;\u003c/strong>\u003cstrong>内容：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; 事件\u003c/strong>\u003cstrong>：\u003c/strong>（事件具体内容，能完整呈现联想四环的步骤的。）\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;\u003c/strong>\u003cstrong>旁白：\u003c/strong>（可选）（用来介绍背景、人物关系、人物的内心想法等）\u003c/p>\u003cp>三个小组展开了热烈的讨论。\u003c/p>\u003cp>第一组讨论如何在学医的过程应有联想法记忆那些枯燥的知识点。并写小剧本。\u003c/p>\u003cp>第三组讨论如何记六个毫无关系的名词。\u003c/p>\u003cp>第二组讨论的最为热烈，而且主动要求分享。他们的剧本模板如下：\u003c/p>\u003cp>时间：2018年9月9日上午10：30\u003c/p>\u003cp>地点：东莞卡斯书吧\u003c/p>\u003cp>人物：木门、张思英、小星、娟子、秋芬\u003c/p>\u003cp>事件：如何在最短时间内运用联想法记住六样随意信息\u003c/p>\u003cp>角色A:木门，本次小剧本的总编剧。由他来全程指挥和安排事项。并首先由他挑选六样随意物品，木门随意指定杯子、花瓶、雪梨、笔、笔记本、奶茶。刚好这些物品就在他身边。\u003c/p>\u003cp>角色B：小星，找顺序。杯子——花瓶——雪梨——笔——笔记本——奶茶。\u003c/p>\u003cp>角色C：娟子，列清单。1、杯子——2、花瓶——3、雪梨——4、笔——5、笔记本——6、奶茶。\u003c/p>\u003cp>角色D：秋芬，观察者。\u003c/p>\u003cp>角色E：张思英，记忆者。负责给清单中的每一项设符号和创建联想。\u003c/p>\u003cp>剧情：木门挑选六样物品并组织大家一起共同协助张思英运用联想四环来完成记忆。张思英顺利完成任务。\u003c/p>\u003cp>拆书家引导：我们来看一下张思英他们小组是如何来完成联想法的记忆的。我们来看一下他们的剧本。\u003c/p>\u003cp>之后，张思英迫不及待地兴奋地讲解他们的剧本和运用联想四环的记忆过程。\u003c/p>\u003cp>回应与反馈：哇，你们真的是太棒了！大家对知识点的应用和迁移能力真的很强！\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>从刚才的学习结果来看，运用联想法的四连环，我们就能有效地提高我们的记忆力，特别是对随意性信息的学习和记忆很有帮助。我的3-1就到这里，谢谢大家的积极参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1536592857000,"updated_at":1536592857000,"ria":true},{"id":6007,"topic":"设置学习目标","learn_goal":"学习后，学习者能够设置一个可应用的学习目标。","remark":"么我们会觉得有些课程枯燥乏味，有的课程却令人着迷？你的学习都能应用吗？你的学习有目标吗？如何设置目标并将之变成有组织、有系统、有计划和目的的学习？只要五个步骤，你将掌握设定学习的目标的技巧。请你来到9月2日上午的东莞分舵分场，让拆书家带你学习设置学习目标的技巧！","level":"TF3-3","duration":50,"status":30,"type":0,"chaishujia":{"username":"曾金泉","city":"东莞"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>开场： 大家好，我是今天的拆书家曾金泉，我的三个标签：国家二级人力师，高级培训师，二级拆书家。今天我将带大家一起拆《如何高效学习》这本书。&nbsp;\u003c/p>\u003cp>分组：我们沿用前一位拆书家的分组，根据大家坐的位置，分成两组，左边一桌为一组，右边一桌为一组。\r\n &nbsp;\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>&nbsp;\u003c/p>\u003cp>大家有没有碰到过这样的场景：\u003c/p>\u003cp>【事件场景】你在自学中因为没有目标、缺少计划和方向而陷入自由散漫的状态的情况？比如说，你参加完线上训练营进入线下过级，但因为没有学习目标而一直拖延？\u003c/p>\u003cp>【提问】遇到这类事情，你之前是怎么做的？\u003c/p>\u003cp>【影响】不管是何种情况，没有学习的目标，我们发现，自学过程总是难以坚持长久，经常发生力不从心或者半途而废的情况。\u003c/p>\u003cp>【解决】那正确的方法应该怎么做呢？斯科特·扬在《如何高效学习》这本书中告诉我们学习目标的实用性，通过“思考+学习+应用”的模型找寻学习的目标，并设定学习目标，推进学习。\u003c/p>","ratings_count":1,"texts":[{"id":9245,"quote":"\u003cp>片段一：主题：学习的目标\u003c/p>\u003cp>拆解的书籍《如何高效学习》第三部分“整体性学习策略”P63\u003c/p>\u003cp>学习的目标\u003c/p>\u003cp>到目前为止，我已经确定你的目标是完整地学习知识以通过各种考试，但是仅仅是通过考试，有好分数是不够的。你学习眼前这个知识的目的是什么?你为什么要学习它?它对你的生活、人生有什么用处？\u003c/p>\u003cp>毋庸置疑，如此这般思考的人肯定比那些仅仅想通过考试获得好分数的人学得更为深刻、效果更好。因为他们学习的动机更加强烈，学习的意义更加深远，学习的目的更为远\u003c/p>\u003cp>大，所以他们对知识的理解必将更加深刻。\u003c/p>\u003cp>在开始学习编程时，我为之着迷，不满足于上课教得那些内容，我试着用学到的知识自己写一些程序，由于对编程的兴趣，最终完成了好几个有点规模的游戏编程。\u003c/p>\u003cp>我在学习会计学时，立即就看出了学习它的门道，我一边学习一边将知识用在管理我的小公司上，尽管很多知识并不是我这个小公司需要的，但是在试图应用知识的过程中，\u003c/p>\u003cp>我的会计学也学得很棒。\u003c/p>","explains":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>学习者能够使用【行动】“思考+学习+应用”的模型来找寻学习的目标【澄清】，更深刻地理解知识【界定】。\u003c/p>\u003cp>\u003cstrong>【I拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>我们为什么要学习？要怎样学习？学习了怎么用？在这个拆页中，我们看到了“学习目标”的定义和重要性。\u003c/p>\u003cp>\u003cstrong>【对比概念】\u003c/strong>\u003c/p>\u003cp>提问：什么是学习的目标？\u003c/p>\u003cp>学习爱好者回答：学习的目的和标准。\u003c/p>\u003cp>提问：没有学习目标会怎样？\u003c/p>\u003cp>学习爱好者回答：学不好，没兴趣。\u003c/p>\u003cp>提问：有了学习目标，对我们的生活和人生有什么好处？\u003c/p>\u003cp>学习爱好者回答：有了学习目标，就有了学习的动力。\u003c/p>\u003cp>学习的目标就是指学习的目的。“你学习眼前这个知识的目的是什么？”作者给出了答案，思考为什么要学习它，怎么学它，它将对你的生活、人生有什么用处？\u003c/p>\u003cp>\u003cstrong>【互动提问】\u003c/strong>\u003c/p>\u003cp>我们回看原文拆页的内容，大家想一想：\u003c/p>\u003cp>1、 作者认为学习目标不明确会怎样？\u003c/p>\u003cp>学习爱好者回答：没兴趣学习。\u003c/p>\u003cp>学习爱好者回答：只学习而没有实际的应用，就是在浪费生命。\u003c/p>\u003cp>2、 为了学习更为深刻、效果更好，我们究竟应该怎么做呢？\u003c/p>\u003cp>学习爱好者们摇头，表示不清楚。\u003c/p>\u003cp>拆书家引导：拆页中作者用了几个自己的案例，大家找找看？\u003c/p>\u003cp>学习爱好者亚兰：学习编程的案例。\u003c/p>\u003cp>学习爱好者龙珠：学习会计的案例。\u003c/p>\u003cp>学习爱好者小华：我在学习会计学时，立即就看出了学习它的门道\u003cstrong>（思考）\u003c/strong>，我一边学习\u003cstrong>（学习）\u003c/strong>一边将知识用在管理我的小公司上\u003cstrong>（应用）\u003c/strong>，尽管很多知识并不是我这个小公司需要的，但是在试图应用知识的过程中，我的会计学也学得很棒\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>拆书家回答：是的。作者本人就是先思考自己的学习目的，然后，一边学习，一边应用。&nbsp;\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;\u003c/strong>我先来讲一个拆书家本人的案例。\u003c/p>\u003cp>拆书家泉水一直非常迷恋线上拆书训练营。为什么呢？因为在线上训练营，泉水一边思考自己为什么要学习\u003cstrong>（思考）\u003c/strong>，一边每天接受拆书学习、听大媛媛的课\u003cstrong>（学习）\u003c/strong>，同时还把拆书技能放到写作中，并应用拆书技能完成了《绩效管理》的14万字的写作并已经提交出版社\u003cstrong>（应用）\u003c/strong>。\u003c/p>\u003cp>但是线下过级的时候，拆书家泉水感觉自己提不起兴趣。思考中没想明白自己线下过级的目的是什么，我为什么要学习它？它对我的工作和生活能如何应用？\u003c/p>\u003cp>\u003cstrong>【清晰的how】\u003c/strong>\u003c/p>\u003cp>那么，究竟如何才能通过“思考+学习+应用”的模型来寻找学习目标？\u003c/p>\u003cp>以我刚才的例子为模板，我来说说我的看法：\u003c/p>\u003cp>1、&nbsp;第一步，思考：——想想我要学什么？\u003c/p>\u003cp>——线下过级的技能点。\u003c/p>\u003cp>2、&nbsp;第二步：学习——想想我要怎么学？\u003c/p>\u003cp>——抄写线下过级的技能点，并把它写到简书，在会员群朗读技能点。\u003c/p>\u003cp>3、&nbsp; 第三步：应用——想想我要怎么用？\u003c/p>\u003cp>——在给公司员工培训的时候把技能点应用进去，提高培训的影响力。&nbsp;\u003c/p>\u003cp>我们用一个模型表示：\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>我们为什么要学习？要怎样学习？学习了怎么用？\u003c/p>\u003cp>[不这么做的坏处]因为学习目标不明确，所以学习效果明显不好，这种情况我们常常碰到。\u003c/p>\u003cp>[这么做的好处]所以我想强调，要想超出知识的本身，光有热情还是不够的，只有当你找到应用知识的途径，并将所学的知识运用到实际中间去，知识才能变成你自己的知识体系中的重要成分。所以，我们在学习中，要尝试将学习与我们感兴趣的东西联系在一起，挖掘出它实际的用处，特别是对自身改进的帮助，学习就会大不相同了。\u003c/p>\u003cp>\u003cstrong>这个方法特别适合于你不得不学习的知识或者你想提高自己能力学习新知识的情况。当然，如果本身就已经明白这个道理，并能学以致用的人，再温习这个概念也会对你起到激励作用。\u003c/strong>\u003c/p>","interaction":"\u003cp>A&nbsp;学习者拆为己用\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>现在到了我们练一练的时候。\u003c/p>\u003cp>请大家根据自己的情况，来编辑一段小故事，几百字即可，小故事的需要是发生在\u003cstrong>未来，\u003c/strong>有时间、地点、人物和事件（包括事情的起因、经过和结果）和当时的双方的对话、动作等，其中部分对话要使用到今天学习到的找寻学习目标的“思考+学习+应用”的模型的的技巧。\u003c/p>\u003cp>请将故事摘要写在一张纸上，时间五分钟。五分钟后，我们请一位代表来讲述他们小组编出的故事。\u003c/p>\u003cp>\u003cstrong>【剧本模板】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>故事背景：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>人物角色：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>故事内容：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>对话设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【伙伴剧本展示】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>2018年9月2日上午13：00\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>卡斯书吧\u003c/p>\u003cp>\u003cstrong>故事背景：\u003c/strong>第七期训练营马上结束了，秋芬等二人获得了优秀学员，小星星班长跟她讨论拆书的学习目标。\u003c/p>\u003cp>\u003cstrong>人物角色：\u003c/strong>小星星、秋芬\u003c/p>\u003cp>\u003cstrong>故事内容：\u003c/strong>第七期线上训练营小伙伴讨论拆书的学习目标。\u003c/p>\u003cp>\u003cstrong>对话设计：\u003c/strong>\u003c/p>\u003cp>小星星：秋芬，是什么支持你每天写作业到凌晨二点的？\u003c/p>\u003cp>秋芬：我是听了泉水姐姐的课，觉得太实用了，我想拆书是不是能帮到我\u003cstrong>（思考）？\u003c/strong>然后，我就报名了，一边听敏君教练讲课，一边写作业\u003cstrong>（学习）\u003c/strong>，而且我学的都可以用到我的工作中间，特别是A1和A2。对我帮助很大\u003cstrong>（应用）。\u003c/strong>\u003c/p>\u003cp>小星星：你是先想明白了为什么要学习，然后，就一边学一边用，然后，你就觉得自己目标很明确了，所以才能取的好成绩。是吗？\u003c/p>\u003cp>秋芬：是的。\u003c/p>\u003cp>小星星：哦，我明白了。那我也要好好想想我为什么要拆书\u003cstrong>（思考）？\u003c/strong>然后，线上我们学完了，我们线下要拜师来学习，参加线下的过级\u003cstrong>（学习）\u003c/strong>。然后，我还要把我学到的东西用到我的工作中间去，还要跟我的妹妹讲一遍\u003cstrong>（应用）。\u003c/strong>这样的话，我就能想明白我为什么要拆书了。（找到学习的目标）\u003c/p>\u003cp>秋芬：我觉得可以的。\u003c/p>\u003cp>\u003cstrong>故事的结果：小星星决定继续拆书，同时9月9日，小星星勇敢地挑战线下训练营TF1-1。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【给出反馈】\u003c/strong>&nbsp;\u003c/p>\u003cp>谢谢小伙伴的分享，我们看到大家在小剧场中都运用了刚才所学的方法，可以说充分地练习了知识点，看来大家的吸收和迁移的能力都不一般哦，真棒！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":9246,"quote":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>学完后，能够使用五个技巧（澄清）的方法设计（行为）自学者自学中的学习目标（界定）。\u003c/p>\u003cp>\u003cstrong>【A1 自测题】\u003c/strong>\u003c/p>\u003cp>刚才我们重新理解了学习目标对我们的意义，明确了找寻学习的目标的方法，接下来我们就具体学习一下如何设定学习的目标。\u003c/p>\u003cp>如果说拆页一的内容是个目的地，那么即将学习的拆页二内容，就是在给我们铺一条通往这个目的地的路。\u003c/p>\u003cp>在阅读拆页之前，先请大家花1分钟时间完成一个量表自测题。注意：量表的测试结果无关好坏，只是帮助大家更加了解自己的情况。\u003c/p>\u003cp>你是如何设定学习目标的呢？自测题：以下6个题目，请按照1-5的标准给自己打分，1代表完全不符合，5代表非常符合，请仔细阅读下面的每句话，根据自己的实际情况为自己打分。\u003c/p>\u003cp>\u003cstrong>【测试讲解】\u003c/strong>\u003c/p>\u003cp>【拆书家】&nbsp;\u003cstrong>请问20分以上的有吗？请举手示意一下\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>拆书家\u003cstrong>】\u003c/strong>我看到有几个小伙伴在20分及以上这个区间，非常好，这说明你对学习目标的设定非常重视。\u003c/p>\u003cp>【拆书家】10-20分的也请举手示意一下\u003c/p>\u003cp>【拆书家】大部分小伙伴在10-20分这个区间，这说明我们来参加拆书的都是一个有学习目标的人；\u003c/p>\u003cp>【拆书家】10分以下有吗？也请举手示意一下。哦，也有个别学员。10分以下这说明你对学习目标的设定不太重视；\u003c/p>\u003cp>如果得分偏低，您也不用太担心，相信参加过今天的学习，你一定会有一些不一样的处理方法。\u003c/p>\u003cp>下面给大家二分钟的时间阅读一下原文片段。阅读完成的小伙伴可以举手示意我。\u003c/p>\u003cp>R&nbsp;原文片段\u003c/p>\u003cp>\u003cstrong>原文片段\u003c/strong>：\u003c/p>\u003cp>片段二：主题：设置学习目标\u003c/p>\u003cp>拆解的书籍《如何高效学习》第三部分“超越整体性学习”P161-162页内容\u003c/p>\u003cp>没有学校有计划的教学安排，自学需要学习者强大的内在自我约束机制，方能保证自己跨\u003c/p>\u003cp>过一个又一个的障碍。\u003c/p>\u003cp>我发现设置一个吸引人的学习目标会给学习者带来强大的学习动力。下面是一些学习目标的例子。\u003c/p>\u003cp>l&nbsp; 每年阅读一定量的书。\u003c/p>\u003cp>l&nbsp; 为一个项目工作，工作的过程也就是学习的过程。\u003c/p>\u003cp>l&nbsp; 在一定的期限之前，必须学会做某件事。比如：学会作曲，完成你的财务报表，或者在6月3日之前学会说拉丁文，等等。\u003c/p>\u003cp>给自己设定完成期限看起来有点不通人情，但是要不然目标会自动完成吗?\u003c/p>\u003cp>不过太多的安排也会限制人的自由，让人喘不过气来(我相信这是大多数人对传统教育的感觉)。太少的安排则可能使学习令人生厌和目标性不强，这样的学习容易陷入自由散漫的状态之中。设定学习目标可以给你恰当的安排，你可以在这之下拓展、探究新的知识，这样的自我教育就不是随意的，而是有组织、有系统、有计划和目的的学习了。\u003c/p>\u003cp>设定学习目标的一些技巧：\u003c/p>\u003cp>(1)所有的目标都要写下来。目标没有写下来，就等于没有目标。用一两个句子写下目标，并给它一个截止期限。\u003c/p>\u003cp>(2)让目标客观化。学习过程中，你要能很容易判断出是否已经达到了目标。所谓的“学得更多”不是学习目标，因为它不客观，你不知道怎样才算是完成了目标，所以它只\u003c/p>\u003cp>能是一种幻想。\u003c/p>\u003cp>(3)设定有些困难，但是努把力也可以达到的截止期限。给自己达成目标设定一个期限会迫使你不断地采取行动，而不是拖延不前。假如期限定得太松，就起不到促使你行动的作用；如果期限定得太紧，会让你丧失信心，垂头丧气。\u003c/p>\u003cp>(4)将目标的完成转化为每日和每周的具体行动。你的目标应该分解为每日和每周的具体小目标。一个今天就需要立即完成的小目标远比几个月后的大目标更让人坐立不安，焦急万分。\u003c/p>\u003cp>(5)经常看看你的目标。至少一周检查一次目标完成的情况。\u003c/p>","explains":"\u003cp>\u003cstrong>【I拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【概念讲解】\u003c/strong>\u003c/p>\u003cp>好了，我们回到原文当中，其实这个片段非常的简单，就是帮助我们区分：\u003c/p>\u003cp>一、设定学习目标的好处。\u003c/p>\u003cp>二、没有学习目标的坏处。\u003c/p>\u003cp>没有学习目标，我们的学习就容易陷入自由散漫的状态；如何才能有效地设定目标呢？本节片段正是教你解决这个问题。通过五有技巧设定学习目标，就可以给我们恰当的安排，让自我教育变成有组织、有系统、有计划和目的的学习。\u003c/p>\u003cp>\u003cstrong>【类似概念】\u003c/strong>\u003c/p>\u003cp>我们生活中有没有这样类似的例子呢？有的。\u003c/p>\u003cp>\u003cstrong>【对比概念】\u003c/strong>\u003c/p>\u003cp>比如说目标设定的SMART原则，它的五个方面和这个五有技巧有相似之处，但又不完全相同。目标设定的SMART原则更具体更详细，适用范围更广，设定学习目标的五有技巧主要是针对学习特别是自学过程。\u003c/p>\u003cp>又比如说学校的学习计划的设定也是一个类似的概念。但是学校的学习计划的设定也和这五有技巧并不完全相同。学校是有计划的，有老师的教学安排，对学生的自我管理要求没有这么高。本节片段的五有技巧更侧重自学者的自我管理、和应用五有技巧来执行自我管理。\u003c/p>\u003cp>\u003cstrong>【提问和互动】\u003c/strong>\u003c/p>\u003cp>请问一下大家在这个片段当中看到的关键词是什么？\u003c/p>\u003cp>【学习者】有计划、有组织、系统的、目的。\u003c/p>\u003cp>【拆书家】对的。\u003c/p>\u003cp>\u003cstrong>【回应和反馈】\u003c/strong>\u003c/p>\u003cp>【互动—判断题1】那请问一下大家，我们的线上训练营是有学习目标的吗？\u003c/p>\u003cp>【学习者】是的。\u003c/p>\u003cp>【互动—判断题2】那我们的线下训练营，拆书帮对线下过级的规定，它是有明确的学习目标的吗？\u003c/p>\u003cp>【学习者】不知道。\u003c/p>\u003cp>【互动—判断题3】再问一下大家，线下训练营有规定什么时候一定要完成过级？\u003c/p>\u003cp>【学习者】没有。\u003c/p>\u003cp>【互动—判断题4】好了，你可能要说，我有给自己定线下训练营的目标啊，那么，请问一下，你有针对线下训练营制订每天、每周的计划吗？有进行复盘吗？（预防异议）\u003c/p>\u003cp>【学习者】有计划，但是好象没有复盘。\u003c/p>\u003cp>【拆书家】对了，木门说线下训练营他还是有制订计划的，只是没有复盘。效果也没有线上营明显。木门，你的意思是不是这样的？\u003c/p>\u003cp>【学习者】点头表示认同。\u003c/p>\u003cp>【拆书家】好的，谢谢木门。他的例子非常符合我们今天学习的这个片段提到的没有目标的情况。我们知道，线上训练营是有明确的学习的目标的，每天、每周都有学习方案，还有每周的复盘。但是为什么大家线下这么难过级呢？因为线下训练营没有明确的学习目标，过也可以，不过也可以，反正没有人看着，完全靠自己。（回应和反馈）\u003cbr>\u003c/p>\u003cp>\u003cstrong>【强化概念】\u003c/strong>\u003c/p>\u003cp>我们先来介绍一下两个概念，按五有技巧设定学习目标和没有学习目标，举个例子类比一下。\u003c/p>\u003cp>像我们线上训练营这种，是有学习目标吗？是的。因为有计划、有教练、有明确的期限，还有每天、每周的任务和每周的复盘。\u003c/p>\u003cp>像我们线下过级这种学习，是没有学习目标吗？是的。因为它相对线上训练营这种，没有设定完成期限，也没有每天每周的任务规定，也没有每周的检查，所以很多人半途而废。\u003c/p>\u003cp>\u003cstrong>【概念重点讲解】\u003c/strong>\u003c/p>\u003cp>那么，可能有人会说，线下训练营还是有学习目标的。\u003c/p>\u003cp>好，那我来问你：\u003c/p>\u003cp>线下训练营有没有把这个目标写下来了吗\u003cstrong>（一有）\u003c/strong>？（学习者摇头）\u003c/p>\u003cp>我们来看看拆书帮对线下过级的规定，它有明确要求在什么时间必须要完成过级吗\u003cstrong>（二有）\u003c/strong>？\u003c/p>\u003cp>线下训练营有针对线下过级的自我学习的评价吗\u003cstrong>（三有）\u003c/strong>？\u003c/p>\u003cp>线下训练营有明确规定到每天要做什么、每周要做什么吗\u003cstrong>（四有）\u003c/strong>？\u003c/p>\u003cp>线下训练营有要求大家对自己的自学要做复盘或者检查吗\u003cstrong>（五有）\u003c/strong>？\u003c/p>\u003cp>学习者摇头中。\u003c/p>\u003cp>\u003cstrong>【概念难点讲解】\u003c/strong>\u003c/p>\u003cp>好了，说到这，有的小伙伴可能又要说了，我自己个人有对线下过级设定学习目标啊！\u003c/p>\u003cp>那么我们来看看，你的线下过级的学习目标是不是也包括了这五个方面呢？\u003c/p>\u003cp>1、你有写下来的明确目标吗？如：我要在一年内通过全部三级的线下拆书任务。\u003c/p>\u003cp>学习者摇头。\u003c/p>\u003cp>2、你有看的见的可评价的目标？如：我将拆书技能点的学习至少写成一篇简书，做一次分享，应用在工作中间一次及以上。\u003c/p>\u003cp>学习者摇头。\u003c/p>\u003cp>3、你的目标的期限设定是否合理呢？如：一年的期限，让我很有紧张感，我会不断地采取行动以争取达成目标；或者是：一年的期限，让我没有紧张感，我完全没有要马上采取行动的动力。\u003c/p>\u003cp>学习者摇头。\u003c/p>\u003cp>4、你有把目标分解到每日每周的具体行动吗？如：拆书的一至三级总共有若干个技能点，我已经把技能点的学习安排到每天，每周，每月的小目标。\u003c/p>\u003cp>一部分学习者摇头，一部分学习者点头。\u003c/p>\u003cp>5、你有目标的完成情况检查表吗？如：我有每周检查一次我的拆书技能掌握情况和应用情况。\u003c/p>\u003cp>学习者摇头。\u003c/p>\u003cp>\u003cstrong>【概念步骤&nbsp;how】\u003c/strong>\u003c/p>\u003cp>究竟我们要如何设定我们的学习目标，才能让这个学习目标给我们自己赋能呢？作者在本节片段给出了一个法宝，我们称之为“自我学习的五有技巧”。\u003c/p>\u003cp>1、有明确期限的写下来的可以看到的目标。我要在多长时间内完成XX学习；\u003c/p>\u003cp>2、有目标达成的评价。XX学习完成的评价是：通过考试或者通过定级等；\u003c/p>\u003cp>3、有明确的目标期限。XX学习在多长时间内要完成；\u003c/p>\u003cp>4、有目标行动方案。XX学习时间表；\u003c/p>\u003cp>5、有复盘。有针对目标的反省和复查的安排；\u003c/p>\u003cp>现在，大家明白了学习目标设定的五有技巧了吗？不如我们来看一个例子更好的理解。\u003c/p>\u003cp>\u003cstrong>【举出案例】\u003c/strong>\u003c/p>\u003cp>还以刚才线下拆书过级的事件为例子，我们参加线下拆书过级，我们其实并不要先忙着过级，而是先要思考我为什么要线下过级，我要如何学习，我要如何应用，并应用五有技巧，来帮助自己设定线下过级的学习目标。\u003c/p>\u003cp>具体怎么做呢？\u003c/p>\u003cp>我们先把自己线下过级的目标写下来：我要在一年内通过三级拆书家的线下过级任务。你可以会说：这个容易，好，那么，现在请你拿笔写下来，写在你的笔记本上。\u003c/p>\u003cp>然后，我们来思考：有目标达成的评价：如何来评价我们的是否已经达到了目标？现在请大家拿笔在自己的笔记本上写下来。你认为这个评价是什么。但请注意，不要把它当成幻想。\u003c/p>\u003cp>有明确的目标期限。\u003c/p>\u003cp>有目标行动方案。请大家为你的目标写一个每日和每周的行动计划。\u003c/p>\u003cp>有复盘：至少一周检查一下自己的目标完成情况。有没有困难，是不是努把力就可以达到。\u003c/p>\u003cp>\u003cstrong>【预防异议+讲解】\u003c/strong>&nbsp;\u003c/p>\u003cp>有的小伙伴可能会说，这样做真的有效吗？\u003c/p>\u003cp>说实话，我开始也是这么觉得的，所以我在线下过级的时候，我跟师父说我的目标是用N年过完三级。\u003c/p>\u003cp>但是后来当我给自己设定一个一个月挑战九级的学习目标后，我就鼓起勇气开始这么去做了，而且这个目标的执行也让我收到了令我意外的收获。\u003c/p>\u003cp>可以说，在有明确的学习目标的情况下，我发现自我学习真的并不象我开始想的这么难。当然，这还是要感谢东莞乐享分舵线下小伙伴们的鼓励与师父的指导，然后，现在我也慢慢养成了自己的良好习惯，在学习一项新知识的时候我就会下意识地这么来设定学习目标。所以说，难的不是如何去做，而是一定要做!学习一定要有目标。（这么做的好处）。\u003c/p>\u003cp>其实，如果我没有应用“自我学习五有技巧”来设定过级的目标，我想我可能真的是用N年才能完成过级了，甚至有可能象很多半途而废的拆书小伙伴一样，因为漫无目标而放弃了，去当逃兵了。这样也就没有办法实现自我改进了。（不这么做的坏处）\u003c/p>\u003cp>\u003cstrong>【明确适用边界】\u003c/strong>\u003c/p>\u003cp>上面的例子里我们说的是在线下拆书过级中的学习目标的设定中如何应用“自我学习五有技巧”。同样，我们也可以将它应用在我们在工作和生活中学习新的知识、或者进行自我学习时。当然，它主要适用于各类学习，特别适用于自我学习。\u003c/p>","interaction":"\u003cp>A&nbsp;学习者拆为己用\u003c/p>\u003cp>\u003cstrong>【A3 指令清晰，主持微行动学习，讨论解决方案】\u003c/strong>\u003c/p>\u003cp>伙伴们，我今天的这个片段分享内容到这里，想请问下大家，在今天的学习过程中，我们学习了设定学习目标的五有技巧，现在，我们来回顾一下，这五有技巧中，大家都理解了吗？还有没有觉得哪个知识点还有盲点、不太能理解的？（明确问题）\u003c/p>\u003cp>\u003cstrong>【学习者确认】\u003c/strong>嗯，我觉得基本理解了。（有一部分还是露出茫然的神情。）\u003c/p>\u003cp>\u003cstrong>【提问式反馈与回应】\u003c/strong>好，那下面我们来分组讨论一下，我们今天学习的内容，我们从第一个技巧开始进行讨论。大家可以结合自己的学习经验来进行思考，可以针对全部技巧，也可以针对你认为很重要的技巧。请注意，一定要找到问题的本质。\u003c/p>\u003cp>学习者们分组热烈讨论中。\u003c/p>\u003cp>\u003cstrong>【学习者提问】老师，其实\u003c/strong>一个学习目标我知道按这个五有技巧来设定了，但是如果多个呢？比如说我，我有三个目标，考试PMP、学习精时力、努力成为时间管理讲师，我要怎么按照这五有技巧来设定学习的目标，最终帮助到我自己？\u003c/p>\u003cp>\u003cstrong>【提问式反馈与回应】嗯，挺好的。好，我们来征求一下大家的意见，\u003c/strong>大家觉得这个问题有没有普遍性？有没有必要我们一起开展讨论找出解决的方法？\u003c/p>\u003cp>\u003cstrong>【学习者确认】\u003c/strong>嗯，有必要。（有一部分认为没有必要）\u003c/p>\u003cp>在征求意见后，基本同意就这个问题来进行讨论。其中，拆书家有适当地引导，确认多个目标同时应用五有技巧，也是可行的。\u003c/p>\u003cp>\u003cstrong>【引导分组讨论问题本质】\u003c/strong>既然大家都觉得这个问题很重要，那我们现在就停下来，一起看看这个问题到底怎么来解决，那为了让大家更充分发酵和思考这个问题，首先呢想请大家先来分组讨论下，这个问题的本质是什么？\u003c/p>\u003cp>(学习者们开始热烈讨论)\u003c/p>\u003cp>小星星：我觉得应该是一样的吧。就是要把全部目标写下来。\u003c/p>\u003cp>秋芬：对啊。有几个目标就写几个五有。\u003c/p>\u003cp>张思英：可以看看能不能综合起来。\u003c/p>\u003cp>楚瑜：其实我是很好奇泉水你当时第二期四个目标并行并且实现了是怎么做到的。特别是你还能同时写完14万字的专业书稿，同时还出了二本电子书，还进行你的公众号的每日更新，还有保证完成每天的作业，这是怎么做到的？我一直很好奇。你是用这五有技巧做到的吗？\u003c/p>\u003cp>龙珠：对的，我们也好奇。你是用这个五有技巧来进行设定的吗？\u003c/p>\u003cp>\u003cstrong>【明确问题本质】\u003c/strong>我想知道，大家为什么特别在乎这个问题？\u003c/p>\u003cp>\u003cstrong>【学习者确认】\u003c/strong>是的呀，我们想知道你是不是用这个五有技巧来实现的呀？\u003c/p>\u003cp>\u003cstrong>【明确问题本质】\u003c/strong>大家的意思我明白了，大家的意思其实是说对设定一个学习目标的步骤非常认同，但是，如果是多个目标并行时，如何应用五有技巧？是这样的吗？\u003c/p>\u003cp>\u003cstrong>【学习者确认】\u003c/strong>是的呀。\u003c/p>\u003cp>\u003cstrong>【引导分组讨论解决方案】&nbsp;\u003c/strong>好啦，这是一组由反思而来的问题本质，大家认同吗？有补充吗？（大家基本表示认同）。哈哈，我确实是运用五有技巧来帮助自己达成学习的目标的。我们来看龙珠的这个案例，和书上给出的有什么相同的，有哪些不同的？同时，我们来进行下一步，深入来探讨一下这个问题的本质问题，我们继续刚才的分组，讨论有什么解决方案，大家可以把讨论结果写下来，写在白纸上。等下我们请一组人员出来给我们分享他们的解决方案。\u003c/p>\u003cp>学习者们热烈的讨论中。张思英组认为直接运用五有技巧来对每个目标进行规划。龙珠组讨论的比较热烈，对三个目标的逻辑联系方面开始没有想明白，后来经过拆书家引导：如何把精时力和时间管理讲师结合在一起，并应用PMP技巧来规划设计。三个目标并串行。龙珠组才恍然大悟，才发现五有技巧确实是很有用。\u003c/p>\u003cp>\u003cstrong>【角色扮演/小组讨论，给出解决方案】\u003c/strong>\u003c/p>\u003cp>分组讨论：大家针对龙珠的考试PMP、学习精时力、努力成为时间管理讲师三个目标并行来确定学习目标给出了以下的“五有”解决方案，由张思英和楚瑜作为代表分享和建议：\u003c/p>\u003cp>学习爱好者张思英、楚瑜讲解他们的解决方案：\u003c/p>\u003cp>1、 把三个目标写下来：90天通过PMP考试，100天学习精时力，90天掌握时间管理课程。\u003c/p>\u003cp>2、 有目标达成的评价：完成PMP考试（国家统考成绩评价），完成精时力学习（崔律评价），上台讲课一次（公司领导评价）。\u003c/p>\u003cp>3、 有明确的目标期限：100天内完成这三个目标。\u003c/p>\u003cp>4、&nbsp; 有目标行动方案。应用高效TODO、爱今天这二个软件来设计《龙珠学习时间表》，安排每天、每周的学习计划，并当天检查完成情况。\u003c/p>\u003cp>5、&nbsp; 有复盘的安排。每月复盘检查完成情况并向泉水报告和交流，请教泉水。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>&nbsp;谢谢伙伴们的精彩分享，看来设定学习目标的五有技巧大家已经基本理解了。而且大家在刚才所想的解决方法中，我看到大家已经用到了今天新学的知识和方法，好的，那么，让我们一起应用设定学习目标的五有技巧来找寻学习的目标，学以致用，找到学习的动力。有了好的学习目标，这就是一个良好的开端，从这里开始，大家都将成为自我学习的专家呢！\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>特定任务\u003c/strong>&nbsp;\u003c/p>\u003cp>\u003cstrong>【特定任务的A2】\u003c/strong>\u003c/p>\u003cp>今天的观点对你有什么样的启发和感触？今天就找机会跟人表达“设定学习的目标”，要强调设定学习的目标的五有技巧并让她（他）跟着学习。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>刘星（小星星）：我回家以后把今天学到的知识讲给我妹妹听。让她跟着学习一下。我觉得泉水讲的片段对我特别实用。我就是听了泉水姐姐的课才爱上拆书的。而且我感觉泉水姐姐的每个片段都很好，是我在工作中能用的上的。\u003c/p>\u003cp>1、 我把我的目标写下来给我妹妹看：我的目标9.16——10.21 ，每个周日，报名参加下线拆书表达一次。\u003c/p>\u003cp>2、 有目标达成的评价。参加每周日的线下训练营，过一个级。完成上台呈现，请观察家点评。\u003c/p>\u003cp>3、 有明确的目标期限：在10月30日前要完成TF1-1至TF2-4的线下拆书过级的表达活动。\u003c/p>\u003cp>4、 行动： 第一，每天线上学习师父教授的拆书手册讲解 10分钟左右；第二，每周，参加线下拆书过级一次；第三，每个周日拆完书后48小时内提交实录（共六篇）。第四，每周三前完成预备表交给师父检查。\u003c/p>\u003cp>5、 下载高效TODO进行检查。同时复盘，每周写一遍简书，就拆书的技能点之类的进行复盘总结\u003c/p>\u003cp>小星星补充：我个人觉得非常有用。我在拆书中就要用上的。而且我妹也觉得很有道理。\u003c/p>\u003cp>\u003cstrong>【强有力的结语】\u003c/strong>\u003c/p>\u003cp>自我学习并不难，难的是我们没有学习目标，更难的是我们明白自己要有目标的学习，但却不知道如何来设定学习目标推我们的学习，希望今天的TF3-3能帮助您解决这些问题，运用思考+学习+应用模型找寻学习目标，并运用五有技巧设定学习目标，实现自我改进和提升！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1536153743000,"updated_at":1536155773000,"ria":true},{"id":5584,"topic":"整体性学习技术的实际运用——费曼技巧","learn_goal":"学习者能够通过学习，掌握整体性学习技术的实际运用费曼技巧。","remark":"如何高效学习？如何在有限的时间内掌握更多的信息，掌握大幅度提高各门学科成绩的方法？。本节拆书家将带你学习费曼技巧，教你掌握整体学习技术的实际运用。","level":"TF2-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"曾金泉","city":"东莞"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"【学习目标】希望在跟随我完成本场RIA现场学习之后，各位学习者能够：在拆书学习中，按照费曼技巧给出的方法和步骤，帮助理解拆书中提到的技能观察点要求，也可以把很多事实放在里面，在联系中理解他们，至少能顺利完成一个技能观察点的学习要求。\r\n（技能观察点4：学习目标包含学习者可能被观察到/被观测到的行为或动作，现场学习者涉及清晰体现了该学习目标。）\r\n【图书介绍】（技能观察点2：所选图书是实用类或理论类图书）\r\n我先简单的介绍一下今天要拆的书：\r\n【F特征】《如何高效学习》的作者是斯科特•扬，他经营着世界上最大的学习博客之一，是麻省理工大学历史上最快毕业的人，不折不扣的学霸。本书正是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。\r\n【A优势】这本书讲的是“巧读书”，我们以前听更多的是苦读书。而且特别是本书介绍的整体性学习策略非常具有操作性，可以避免学生在学习中陷入只见树木不见森林的误区。同时，这本书也得到诸多教育界人士的大力推崇，这本书的清晰的逻辑和流畅的思路，使成年人产生共鸣，青少年获得更多启迪。\r\n【B利益】B1:你是否希望自己在有限的时间内掌握更多的信息？是否曾经迷惑不知如何考到高分，还是想真正学习一门技术却苦于学习无功，或者想自学知识达到应用水平却苦于读书效率太低？在这本书中你将找到帮助你解决这些问题的答案。B2:通过学习今天的拆页片段，你将学会整体性学习技术的实际运用技巧，掌握费曼技巧，能有效地提高学习效率，让你在有限的时间内掌握更多的信息，掌握大幅度提高各门学科成绩的方法，并运用于学习中。\r\n（技能观察点5：在FAB介绍法中，能够清晰辨别出F、A、B）","ratings_count":1,"texts":[{"id":8803,"quote":"\u003cp>【原文片段】附件\u003c/p>\u003cp>【拆书家指令】请大家先用2分钟时间快速阅读完片段。（最后30秒时）阅读完的小伙伴举手示意一下。\u003c/p>\u003cp>整体性学习技术的实际运用一一费曼技巧。\u003c/p>\u003cp>运用费曼技巧，你能达到过目不忘。\u003c/p>\u003cp>理查D。费曼( Richard inan，美国物理学家，诺贝尔奖获得者，曾经任教于普林斯顿大学物理系，费曼挑战任何一位普林斯顿大学数学系的教授，即不管这些教授告诉费曼多么复杂难懂的数学知识，只要他们使用简单的术语（不得使用费曼觉得生僻复杂的单词或术语)去描述，费曼一定会得出同样的结果\u003c/p>\u003cp>这则故事常常拿来证明费曼是个伟大的天才。不过，现实中，这个技巧人人都能掌握，接下来，我就告诉大家具体如何去做。\u003c/p>\u003cp>费曼技巧的具体措施\u003c/p>\u003cp>(1)理解那些你没有真正掌\u003c/p>\u003cp>(2)记住那些你能理解，却可能在考试中遗忘的知识点。\u003c/p>\u003cp>(3)作为一个考前学习的高效率方法。很多学生花了不少时间在图书馆度过，学习效果却平平，运用费曼技巧，你只需花上20分钟就能深入理解知识点，而且记忆深刻，难以遗忘。\u003c/p>","explains":"\u003cp>【逐字稿】\u003c/p>\u003cp>&nbsp;整体性学习技术的实际运用其实就是费曼的学习技巧，我们称它为费曼技巧，它是指费曼用来理解知识点并达到深刻记忆的方法。\u003c/p>\u003cp>今天我们要拆解的就是第133页内容“整体性学习技术的实际运用——费曼技巧”。\u003c/p>\u003cp>只要我们掌握了费曼技巧，我们就可以用它来大幅度地提高自己的学习效率，提高学科成绩。\u003c/p>\u003cp>从原文拆页中大家可以看到三个具体措施，我总结为技巧应用的四大步骤，大家可以运用这四个步骤来体验费曼技巧并加以操作：\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、选择一个你要学习的概念，并用一张白纸记录下来。\u003c/strong>\u003c/p>\u003cp>以上周我们学习的TF2-2知识技能点来说，敏君给我们讲解了一个知识点中的二个概念：情景、情境。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、现在假设你是敏君，你要来当这二个概念讲解的老师讲给我们这些新学生听，并试图让我们掌握和了解这个知识点。\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>情景指什么？\u003c/p>\u003cp>情境又是指什么？\u003c/p>\u003cp>这二个字词的区别是什么，分别用在哪些方面？\u003c/p>\u003cp>你先假想自己是一位老师，假想自己正准备费尽口舌地来教对这二个知识点一无所知的人，并把你的解释记录下来，在这一步里面，你有哪些不会的，你要如何搞懂它，并真地去搞懂它。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、当你觉得困惑时，就从头开始，找寻答案。\u003c/strong>\u003c/p>\u003cp>例如：如果你不懂，或者你没有办法搞懂它，那么，就继续通过百度百科、说文解字、字典这一类的工具，去学习，并把知识点的理解和解释记录在刚才那张白纸上。这个步骤可以重复至你自己完全明白为止。或者说你对自己给出的解释满意为止。\u003c/p>\u003cp>\u003cstrong>4、 \u003c/strong>\u003cstrong>对知识点的解释进行优化，采用简单或者比喻让它变得容易理解。\u003c/strong>\u003c/p>\u003cp>比如说，你的解释可能是一百字，也可能是晦涩的难懂的，那么你要提炼简化它到二十字甚至一行字可以解释说明清楚，或者采用一个比喻的方法更方便让人理解。\u003c/p>\u003cp>我们下面来看从原文中提取出来的一个案例：\u003c/p>\u003cp>例如：在学习力矩时，用简单的话解释力矩，而不是照抄书上的定义。比如，首先用俗语“扭曲”来说清楚力矩是什么意思。\u003c/p>\u003cp>其次，给力矩找个恰当的比喻，这就是它原文片段的内容，我把力矩向量比喻为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>\u003cp>这个案例告诉我们，\u003c/p>\u003cp>假定你要记住\u003cstrong>力矩\u003c/strong>这个知识点，你可以这么做：\u003c/p>\u003cp>\u003cstrong>1、 \u003c/strong>\u003cstrong>拿出一张白纸，在白纸上写下“力矩”这二个字。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、 \u003c/strong>\u003cstrong>现在假设你是老师，你要讲“力矩”这个知识点讲给我们这些新学生听，并试图让我们掌握和了解这个知识点。\u003c/strong>\u003c/p>\u003cp>费曼是这么干的：\u003c/p>\u003cp>先用俗语来解释——力矩就是扭曲。\u003c/p>\u003cp>\u003cstrong>3、 \u003c/strong>\u003cstrong>“\u003c/strong>\u003cstrong>当你觉得困惑时，就从头开始，找寻答案。\u003c/strong>\u003c/p>\u003cp>用扭曲还不够明白是吧。好的，重新来设计讲解方案。\u003c/p>\u003cp>4、\u003cstrong>对知识点的解释进行优化，采用简单或者比喻让它变得容易理解。\u003c/strong>\u003c/p>\u003cp>因为费曼已经掌握了这个方法，给力矩找个恰当的比喻，费曼把力矩向量比喻为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>\u003cp>（技能观察点6：I环节，给出了比原文拆页更加细化的行动步骤，或者将书中的案例进行了意译）\u003c/p>","interaction":"\u003cp>【拆书家指令】\u003c/p>\u003cp>接下来我们要设定二个场景，下面为了强化对这四个步骤的应用，大家来想象一个这样的场景。这个场景分为两个片段，一个片段是拆书爱好者泉水教拆书爱好者小烦如何提炼I便签，结果交流未果，小烦还是没有搞懂还是不会写。所以我们需要三个人来配合。第二个片段是三级拆书家敏君成功辅导拆书爱好者小烦完成TF1-1的预备表中I便签的撰写。\u003c/p>\u003cp>下面是场景描述：\u003c/p>\u003cp>小烦加入东莞乐享分舵，准备在7月20日来提起TF1-1的拆书过级任务。三级拆书家敏君将这个任务交给拆书爱好者泉水，泉水采用传统的教学方法，给小烦讲解知识点，但是泉水跟小烦沟通，小烦还是不理解，最后敏君出马，通过应用费曼技巧的四个步骤，成功辅导小烦完成TF1-1的预备表中I便签的撰写。\u003c/p>\u003cp>请问你要如何运用刚才学到的知识，拆书爱好者小烦为什么没有办法理解拆书爱好者泉水的讲解，泉水可能是怎么讲解的？而三级拆书家敏君为什么又能成功地辅导小烦完成TF1-1的预备表中I便签的撰写？\u003c/p>\u003cp>因为我们今天人少，我们现在就四个人一起来进行讨论，讨论之后，分别由三人来分别演绎三级拆书家敏君、拆书爱好者泉水、拆书爱好者小烦。请大家认领一下自己的角色。现在开始。\u003c/p>\u003cp>8分钟之后，我们请一组成员来为大家做个角色扮演。\u003c/p>\u003cp>（技能观察点7： A3环节，给出了非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能）\u003c/p>\u003cp>（技能观察点8：使用A3技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论，应用知识点并形成解决方案，或是应用知识点进行组内角色扮演。）\u003c/p>\u003cp>【学习者案例记录：】\u003c/p>\u003cp>认领角色：敏君、泉水、小烦。\u003c/p>\u003cp>拆书爱好者小烦：师姐，I怎么写？\u003c/p>\u003cp>拆书爱好者泉水：I吧，就是，准确来讲，我就给你一个结果。我要说给你，你能听懂。比如说今天，我给你介绍，这就是泉水，你现在认识泉水了吧。\u003c/p>\u003cp>拆书爱好者小烦：（笑）我知道她叫泉水，但我对她的性格，爱好啊不了解。\u003c/p>\u003cp>拆书爱好者泉水：所以说，这个I，I在我们的拆书手册里不同的层级，有不同的写法，深度不一样的，1-1里面的，你只要大胆地说出来，比如你告诉大家，这是一个杯子，在1-1的时候，我可以说这就是一个杯子，在1-2的时候，也许你可会说这个杯子呢，它是什么材质的、经过了哪一些步骤，经过哪一些烧制的一个程序，你可以把这个I讲的更为精彩。\u003c/p>\u003cp>拆书爱好者小烦：把原文片段里的内容选出来吗？找出最重要的字、最重要的词。\u003c/p>\u003cp>拆书爱好者泉水：这是一种方法，在1-1里面，我们支持你这样，你可以把I回去跟你的孩子讲一遍，他听的懂，就可以了。\u003c/p>\u003cp>拆书爱好者小烦：我还没有孩子。（笑）\u003c/p>\u003cp>培训师引导：敏君，到你了。\u003c/p>\u003cp>拆书爱好者小烦：师父，我还是不懂写I。我跟师姐请教了I，师姐告诉我，把那个知识点是什么东西说出来就行了，但是我还是不知道。\u003c/p>\u003cp>三级拆书家敏君：嗯，现在呢，我就给你一张便签纸，请你在上面写上那个概念：I。这个I在英文中是什么概念？对，就是我，对，这代表着你。I就是你自己。你先联上你，先介绍你。\u003c/p>\u003cp>拆书爱好者小烦：介绍我的，首先我先介绍我的名字，可能有一些场景需要介绍到我的职业，兴趣爱好，擅长的领域。\u003c/p>\u003cp>三级拆书家敏君：我里面包括了很多的元素。在我们拆书家里面也包括了很多元素，I包括了WHAT、WHY、HOW\u003c/p>\u003cp>（培训师引导，回到原文片段中的步骤）\u003c/p>\u003cp>三级拆书家敏君：现在你讲给我听，I包括了哪些。\u003c/p>\u003cp>拆书爱好者小烦：我读了这本书，I包括了对原文的讲解和对学习者的引导，也讲了一些写I的要点，也讲了I的几个元素，为什么我们要采取这样的一个行为，解释清楚了为什么之后，接下来是要怎么做HOW，怎么做就有步骤，第一步，第二步，第三步，写I的模式吧。\u003c/p>\u003cp>三级拆书家敏君：理解的很详细了，对于I部分你还有什么不了解的地方呢？\u003c/p>\u003cp>拆书爱好者小烦：HOW我还是不理解怎么做？\u003c/p>\u003cp>三级拆书家敏君：那现在你再翻到这本书中，找一找，HOW怎么写。……原来它是包括这几个方面，用一个简单的比喻来说，I它包括几个方面。\u003c/p>\u003cp>拆书爱好者小烦：三个要素，2个W一个H。\u003c/p>\u003cp>三级拆书家敏君：哦，2个W一个H。\u003c/p>\u003cp>拆书爱好者小烦：哦，我明白了，I就是包括了2W1H。\u003c/p>\u003cp>好的，谢谢三位学习者的分享。\u003cbr>\u003c/p>\u003cp>大家可以看到，拆书爱好者泉水在讲解TF1-1中I便签的撰写时，是用的传统的方法，直接讲解概念，太过于片面、学术化，完全就是生搬硬套，而小烦作为接受者，对这个技能点也是没有办法理解。而三级拆书家敏君是运用费曼技巧，让小烦自己去学习和理解来探索和学习理解知识点，并应用在知识点的使用上，首先让他写下来，让小烦在白纸上写下“I便签”的三个要点，然后，让他自己思考怎么写，怎么讲，给出答案，同时引导小烦用简单的、还有比喻的方法来完成，当小烦对知识点的思考不够透彻的时候，三级拆书家敏君也是引导小烦重新回到我们的成长手册，并查阅《成长手册》中的讲解，重新反思I便签的解释，直到小烦搞懂搞明白并能讲解出这个知识点并做好备课。我们可以采访一下小烦，小烦，你觉得在刚才的学习中，二种讲解方法，哪些印象更深刻。（小烦回应说：师父的，高明！）谢谢。如果小烦能将这种技巧变成自己的习惯，她将会学的更好。\u003c/p>\u003cp>（注：拆书家楚瑜告诉我们，她在课后运用费曼技巧和儿子沟通，让儿子掌握一个汉字来进行学习，效果很好。）\u003c/p>\u003cp>非常感谢小伙伴的分享。\u003cstrong>看来大家已经能够使用“费曼技巧”的方法了，\u003c/strong>希望大家能主动应用今天学到的内容用来指导自己的学习。我今天的拆书到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1532446577000,"updated_at":1532446577000,"ria":true},{"id":4139,"topic":"终极学习法—费曼技巧。","learn_goal":"学习费曼技巧，让你能达到过目不忘。","remark":"学习过程中面对知识点，你是否有理解不了、记不住的情况呢？哪应该怎么解决，从而实现高效学习呢？拆书家带你一起通过对费曼技巧的学习，达到过目不忘的学习效果。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"宝仲","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好，我是拆书家宝仲。我今天拆解的级别是TF1-2.\r\n拆书的图书是《如何高效学习》。本书的作者是斯科特·扬。他自己发明了一套学习方法，使用他的学习方法，他完成了10天搞定线性代数，1年学习4年MIT课程的“不可能任务”。本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化、费曼技巧等方法，并为高效学习提供了从生活到时间管理的整体解决方案。\r\n在介绍完图书后，我想问大家一个问题，大家在日常学习中是否遇到过，自己学习了一个知识点，感觉自己学会了，理解了。但是具体应用时，或分享给别人听的时候，却发现自己讲不清楚,也记忆不全.也就是说没有真正的弄懂全部知识细节？存在知识缺口的情况。\r\n今天分享给大家的图书的片段,讲的是费曼技巧的学习方法，就可以帮助大家解决这个问题，强化我们对知识点的理解和记忆。\r\n好，请大家用1分钟的时间,带着我们的问题阅读拆页中的原文片段，阅读完的伙伴请抬头示意我。","ratings_count":1,"texts":[{"id":7116,"quote":"\u003cp>运用费曼技巧，你能达到过目不忘。\u003c/p>\u003cp>理查德D. 费曼（Richard D Feynman），美国物理学家，诺贝尔奖获得者，曾经任教\u003c/p>\u003cp>于普林斯顿大学物理系。费曼挑战任何一位普林斯顿大学数学系的教授，即不管这些教授告诉费曼多么复杂难懂的数学知识，只要他们使用简单的术语（不得使用费曼觉得生僻复杂的单词或术语）去描述，费曼就一定会得出同样的结果。\u003c/p>\u003cp>这则故事常常拿来证明费曼是个伟大的天才。不过，现实中，这个技巧人人都能掌\u003c/p>\u003cp>握，接下来，我就告诉大家具体如何去做。\u003c/p>\u003cp>费曼技巧的具体措施：\u003c/p>\u003cp>（1）理解那些你没有真正掌握的知识点。\u003c/p>\u003cp>（2）记住那些你能理解，却可能在考试中遗忘的知识点。\u003c/p>\u003cp>（3）作为一个考前学习的高效率方法。很多学生花了不少时间在图书馆度过，学习\u003c/p>\u003cp>效果却平平，运用费曼技巧，你只需花上20分钟就能深入理解知识点，而且记忆深刻，难以遗忘。\u003c/p>\u003cp>下面我来演示费曼技巧的操作流程，你可以用它大幅度地提高各门学科的成绩。\u003c/p>\u003cp>第一步：选择要学习的概念\u003c/p>\u003cp>首先选好你打算深入理解的概念，拿一张空白纸，在最上方写下概念的名称。\u003c/p>\u003cp>第二步：设想你是老师，正在试图教会一名新生这个知识点\u003c/p>\u003cp>这一步你要假想自己费尽口舌让一名毫无这方面知识的学生听懂，并把你的解释记录\u003c/p>\u003cp>下来。这一步至关重要，因为在自我解释那些你理解或不理解的知识过程中，你会理解得更好，而原先不明白的地方也得以理清。\u003c/p>\u003cp>第三步：当你感到疑惑时，返回去吧\u003c/p>\u003cp>每当你碰到难题感到疑惑时，别急着往下走，学习不是单行道，回过头来，重新阅读\u003c/p>\u003cp>参考材料、听讲座或找老师解答，直到你觉得搞懂了为止，然后把解释记到纸上。\u003c/p>\u003cp>第四步：简单化和比喻\u003c/p>\u003cp>如果你的解释很啰唆或者艰涩，尽量用简单直白的语言重新表述它，或者找到一个恰\u003c/p>\u003cp>当的比喻以更好地理解它。\u003c/p>","explains":"\u003cp>相信大家都已经看完了原文的片段，我们来进一步聊一下费曼技巧。\u003c/p>\u003cp>首先费曼技巧是一种学习方法。\u003c/p>\u003cp>它可以帮助我们 理解那些没有真正掌握的知识点，记住那些我们理解了但是容易遗忘的知识点，并且可以提高我们考试前复习的效率。\u003c/p>\u003cp>在具体应用费曼技巧时，要通过四个步骤。大家可以看到我白板上画的这个图。\u003c/p>\u003cp>第一步，选择你要学习的知识点。把这个知识点的名字写在，一张白纸的最上面。\u003c/p>\u003cp>第二步，是假设你是一个老师，正试图把这个知识点讲给一个学生。把你解释和讲解的过程记录在白纸上。\u003c/p>\u003cp>第三步，当你发现自己在讲解过程中卡壳了，有讲解不清楚、记不住的地方时，回过头，重新阅读书本的章节、听讲座的视频或者找他人解答你卡壳的部分。直到自己感觉弄懂了，然后在把解释记录在白纸上。直到讲解完毕。\u003c/p>\u003cp>这个步骤是这个循环的步骤，当发现自己还是有卡壳的情况，重复第三步。就算自己讲清楚了，但是自己对自己的讲解还是不满意，还是不流畅，那么说明你对这个知识点还是没有理解的很透彻，继续重复第三步。\u003c/p>\u003cp>直到自己满意后，进行第四步。\u003c/p>\u003cp>第四步，是如果你的解释还是应用书面语，给你自己感觉晦涩或啰嗦。那么试着寻找更简单化，更直白的语言去重新讲解，或者找到一个恰当的比喻来描述，更好的使自己和他人来理解知识点。\u003c/p>\u003cp>在比喻的时候呢，我们是指寻找生活、工作或学习中熟悉的场景、经历或知识点，跟原有知识点放到一起对比理解。通过比喻可以凸显两个事情之间的共性，从而方便了我们理解和解释复杂问题。\u003c/p>\u003cp>好了，费曼技巧的四个步骤，我们聊完了，我来举个例子来具体运用下。\u003c/p>\u003cp>比如，我刚接触到拆书法。怎么运用费曼技巧来学习拆书法呢。\u003c/p>\u003cp>第一步，我把拆书法，这三个字写到白板的上边。\u003c/p>\u003cp>第二步，我假设要讲给一个没有接触过拆书法的人，我开始记录我的讲述，拆书法是一个读书方法，又叫RIA阅读法，R是阅读原文片段，I是使用自己的话复述原文，A分为A1和A2，A1是根据读书片段关联自己的经验，A2 是根据原文片段的指导定义自己的应用计划，根据RIA读书法阅读可以让我们，将所学的知识内化吸收，并且可以付诸行动，真正达到个人能力的提升。\u003c/p>\u003cp>第三步，我要看下自己是否有卡壳，或写的不流畅，或不满意的地方。如果卡壳了，我要去找找帮主的书去看看，学习卡壳的地方。如果感觉没有卡壳，还比较满意，就继续第四步。\u003c/p>\u003cp>第四步，要用简单化或比喻的方式解释拆书法。\u003c/p>\u003cp>简单的讲，拆书法就是关联思想、关联身体、最后达到能力提升的学习发。\u003c/p>\u003cp>好了，以上就是我运用费曼技巧来进行学习拆书法的过程。\u003c/p>","interaction":"\u003cp>【A1】联系具体经验\u003c/p>\u003cp>下面呢，请大家分组讨论一下，自己以前感觉理解或学会了一个知识点，但是呢具体应用或与他人分享时，却发现自己没有真正的弄懂的经历。时间是3分钟。\u003c/p>\u003cp>下面呢，哪一个小组可以给大家分享一下。\u003c/p>\u003cp>学习者杨硕分享：\u003cbr>\u003c/p>\u003cp>我之前拆书的时候，就是根据自己拆的片段已经懂了，可是准备拆书预备提示表时，发现自己总写不明白，才发现自己其实没有真正的弄懂片段中的知识。\u003c/p>\u003cp>【A2】具体应用\u003c/p>\u003cp>下面呢，请大家对自己讨论过程中想到的知识点，使用一下费曼技巧来进行复习。如果没有合适的知识点，可以使用费曼技巧这个知识点。时间是5分钟。\u003c/p>\u003cp>那一小组的伙伴可以跟大家分享一下，具体应该的应用结果。\u003c/p>\u003cp>学习者朱琳分享：\u003c/p>\u003cp>第一步，把费曼技巧这四个字，写到便签的上方。\u003c/p>\u003cp>第二步，假设给学生讲解，费曼技巧实际上就是一教为学，通过把知识点的讲述过程记录在纸上的方式来学习。\u003c/p>\u003cp>第三步，如果有不清楚的地方看下书本，回来继续书写。\u003c/p>\u003cp>第四步，费曼技巧就像高中复习时，看书的目录来回忆知识点，有不懂得就在回到书中进行内容的复习。\u003c/p>\u003cp>好，感谢朱琳的分享，基本用到了费曼技巧的四个步骤。\u003c/p>\u003cp>好了，以上就是我对费曼技巧的分享，希望对大家有帮助。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1512097364000,"updated_at":1512097364000,"ria":true},{"id":3514,"topic":"终极学习法—费曼技巧","learn_goal":"学习费曼技巧，让你能达到过目不忘。","remark":"《如何高效学习》的作者是斯科特·扬。他自己发明了一套学习方法，使用他的学习方法，他完成了10天搞定线性代数，1年学习4年MIT课程的“不可能任务”。本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化、费曼技巧等方法，并为高效学习提供了从生活到时间管理的整体解决方案。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"宝仲","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好，我是拆书家宝仲。我今天拆解的级别是TF1-2.\r\n拆书的图书是《如何高效学习》。本书的作者是斯科特·扬。他自己发明了一套学习方法，使用他的学习方法，他完成了10天搞定线性代数，1年学习4年MIT课程的“不可能任务”。本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化、费曼技巧等方法，并为高效学习提供了从生活到时间管理的整体解决方案。","ratings_count":0,"texts":[{"id":6392,"quote":"\u003cp>在介绍完图书后，我想问大家一个问题，大家在日常学习中是否遇到过，自己学习了一个知识点，感觉自己学会了，理解了。但是具体应用时，或分享给别人听的时候，却发现自己讲不清楚,也记忆不全.也就是说没有真正的弄懂全部知识细节？存在知识缺口的情况。\u003c/p>\u003cp>今天分享给大家的图书的片段,讲的是费曼技巧的学习方法，就可以帮助大家解决这个问题，强化我们对知识点的理解和记忆。\u003c/p>\u003cp>好，请大家用1分钟的时间,带着我们的问题阅读拆页中的原文片段，阅读完的伙伴请抬头示意我。\u003c/p>","explains":"\u003cp>相信大家都已经看完了原文的片段，我们来进一步聊一下费曼技巧。\u003c/p>\u003cp>首先费曼技巧是一种学习方法。\u003c/p>\u003cp>它可以帮助我们 理解那些没有真正掌握的知识点，记住那些我们理解了但是容易遗忘的知识点，并且可以提高我们考试前复习的效率。\u003c/p>\u003cp>在具体应用费曼技巧时，要通过四个步骤。\u003c/p>\u003cp>第一步，选择你要学习的知识点。把这个知识点的名字写在，一张白纸的最上面。\u003c/p>\u003cp>第二步，是假设你是一个老师，正试图把这个知识点讲给一个学生。把你解释和讲解的过程记录在白纸上。\u003c/p>\u003cp>第三步，当你发现自己在讲解过程中卡壳了，有讲解不清楚、记不住的地方时，回过头，重新阅读书本的章节、听讲座的视频或者找他人解答你卡壳的部分。直到自己感觉弄懂了，然后在把解释记录在白纸上。直到讲解完毕。\u003c/p>\u003cp>这个步骤是这个循环的步骤，当发现自己还是有卡壳的情况，重复第三步。就算自己讲清楚了，但是自己对自己的讲解还是不满意，还是不流畅，那么说明你对这个知识点还是没有理解的很透彻，继续重复第三步。\u003c/p>\u003cp>直到自己满意后，进行第四步。\u003c/p>\u003cp>第四步，是如果你的解释还是应用书面语，给你自己感觉晦涩或啰嗦。那么试着寻找更简单化，更直白的语言去重新讲解，或者找到一个恰当的比喻来描述，更好的使自己和他人来理解知识点。\u003c/p>\u003cp>在比喻的时候呢，我们是指寻找生活、工作或学习中熟悉的场景、经历或知识点，跟原有知识点放到一起对比理解。通过比喻可以凸显两个事情之间的共性，从而方便了我们理解和解释复杂问题。\u003c/p>\u003cp>比如在物理学中有一个力矩的知识点，是指\u003ca href=\"https://baike.baidu.com/item/%E4%BD%9C%E7%94%A8%E5%8A%9B\">作用力使物体绕着\u003ca href=\"https://baike.baidu.com/item/%E8%BD%AC%E5%8A%A8%E8%BD%B4\">转动轴或\u003ca href=\"https://baike.baidu.com/item/%E6%94%AF%E7%82%B9\">支点转动的趋向。我们先有简单化的解释，大家可以理解为“扭曲”的意思，如果用比喻的方式，大家可以把力矩向量理解为一个开瓶器的运动，向右旋转是拧紧，向左旋转为松动。\u003c/p>\u003cp>好了，费曼技巧的四个步骤，我们聊完了，我来举个例子来具体运用下。\u003c/p>\u003cp>比如，我刚接触到拆书法。怎么运用费曼技巧来学习拆书法呢。\u003c/p>\u003cp>第一步，我把拆书法，这三个字写到白板的上边。\u003c/p>\u003cp>第二步，我假设要讲给一个没有接触过拆书法的人，我开始记录我的讲述，拆书法是一个读书方法，又叫RIA阅读法，R是阅读原文片段，I是使用自己的话复述原文，A分为A1和A2，A1是根据读书片段关联自己的经验，A2 是根据原文片段的指导定义自己的应用计划，根据RIA读书法阅读可以让我们，将所学的知识内化吸收，并且可以付诸行动，真正达到个人能力的提升。\u003c/p>\u003cp>第三步，我要看下自己是否有卡壳，或写的不流畅，或不满意的地方。如果卡壳了，我要去找找帮主的书去看看，学习卡壳的地方。如果感觉没有卡壳，还比较满意，就继续第四步。\u003c/p>\u003cp>第四步，要用简单化或比喻的方式解释拆书法。\u003c/p>\u003cp>我想通过简化的方式来解释拆书法，我想拆书法就是一个阅读-复述-关联自己思想-关联自己身体-促进自我成长的学习过程。\u003c/p>\u003cp>好了，以上就是我运用费曼技巧来进行学习拆书法的过程。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>下面呢，请大家分组讨论一下，自己以前感觉理解或学会了一个知识点，但是呢具体应用或与他人分享时，却发现自己没有真正的弄懂的经历。时间是3分钟。\u003c/p>\u003cp>下面，哪一个小组的伙伴可以给大家分享一下呢？\u003c/p>\u003cp>分享记录：\u003c/p>\u003cp>小洪分享的是他离开校园，参加工作之后，原来学校学习的一些知识点，需要在工作中来使用，确发现自己并没有完全的掌握，需要进一步的回顾，这让他感觉很羞愧。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>下面呢，请大家对自己讨论过程中想到的知识点，使用一下费曼技巧来进行复习。如果没有合适的知识点，可以使用费曼技巧这个知识点。时间是5分钟。\u003c/p>\u003cp>相信大家已经写的差不多了，由于时间关系就不请小伙伴来分享了。\u003c/p>\u003cp>好了，以上就是我对费曼技巧的分享，希望对大家有帮助。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1503906546000,"updated_at":1503906546000,"ria":true},{"id":3239,"topic":"高效学习工具之一：联想法","learn_goal":"如何利用联想法来快速建立新旧知识的关系，从旧知识理解新的知识","remark":"这本书是斯科特.杨写的一本关于学习策略的书。本书讲的是整体性学习策略的核心思想和具体技术。其核心思想是通过寻求知识之间的联系，理解新知识，构建知识模型，从而形成知识之间的快速通道，更好地理解新知识的特点。整体学习策略一共分5个阶段，每个阶段都有对应的技术，那么今天拆书的片段主要是在第二阶段，理解阶段的6大技术之一，即学习如何运用比喻法来建立新旧知识的联系。","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"素颜","city":"沈阳"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天带大家拆书的拆书家。我叫王蕾，在群里叫素颜。还是按拆书的老规矩分三个标签来介绍一下自己。\r\n1、首先，我比较喜欢解决问题；喜欢思考，帮助大家找到解决问题的方法\r\n2、其次，拆书帮的共性，比较爱学习，比较爱看书。\r\n3、第三，我比较擅长观察。一般喜欢处于旁观者的状态，不太喜欢积极参与活动，和积极参与发言。一般会关注讨论中大家的表现，然后会形成自己的一些观点和看法。\r\n\"1、拆书首先是一种学习方法论，主要是用于以提升能力，解决问题为目标的成人学习，是以学习者为中心并不是以知识点为中心，和以前上课一个老师在上面讲的填鸭式的教学是不一样的，主要是通过拆书的活动，让大家互动起来，把知识点与学习者过去的经验关联起来，并帮助学习者找到具体规划运用的学习方式。一般来讲，拆书帮的拆书法是分为两种，一种是个人学习的拆书法，一个是组织学习的拆书法。个人学习的拆书法就是便签读书法，就是我们今天一会儿拆书中要运用到的RIAA的拆书方法，通过个人学习的拆书法就是让大家可以通过读一本而达到参加主题培训的效果；组织学习的应用是一位拆书家通过阅读一本书之后提炼出知识点而加工出一场现场学习，从而引导和促进","ratings_count":0,"texts":[{"id":6072,"quote":null,"explains":"\u003cp>1、比喻法很简单，通常在学习中遇到一个不好理解、记忆的抽象概念时，通常在日常生活中你已经拥有的知识，通过找到已有知识和要学习抽象概念之间的共性，从而让二者关联起来，用已经有的东西来帮助你理解和学习的这个抽象概念。整个片段中最核心的地方在于比喻的概念，即比喻是在熟悉和不熟悉的概念之间架起一座沟通的桥梁。比喻法不是一个简单的外在形象的比喻，比如说这条狗长得象什么，而是在不熟悉的知识点找到它的特点，并关联到熟悉知识点与之相似的共性上去，在二者之间建立起桥梁，从而帮助对不熟悉的知识的学习和记忆。\u003c/p>","interaction":"\u003cp>A1：我的经验是，在前一段时间我学习心理咨询的培训课程，其中有大量的医学名词，很难理解。比如在讲视觉的时候，就有锥体细胞和杆体细胞的两种细胞。视网膜上这两种细胞是有不同功用的。那什么叫锥体细胞，什么叫杆体细胞，我总是弄混。锥体细胞实际上是对明视觉有感觉的，在视神经上的主要功能是用来区分事物的细节和色彩的。而杆体细胞则是对暗视觉有感觉的细胞。当时我这两种细胞我记了好久也没记住，考试的时候也没答对。后来有一次和我一朋友聊天，她说这个很好理解啊，你想啊锥体细胞的特点是什么啊，C15就是一个锥子，锥子的特点就是聚焦啊，就是一个点儿一个劲儿的往下扎，所以它一定会把细节看得很清楚啊。我一想对啊，我就通过这么一句话就把这事儿记住了。我细一想，其实她就是通过锥子的特性跟锥休细胞对细节把控的特点建立起联系。这是我现实生活中的一个经验，我感觉比喻法对于那种特别不好理解的抽象名词特别有帮助。\u003c/p>\u003cp>A2：接下来呢，我今年年底要英语听说过关，所以，我就想如何把这个比喻法运用到我的英语学习中呢?我就想英语听说要过关，涉及到这么几个阶段，首先要创造一个场景，然后你要对这个场景去描述，然后呢，去使用这个英语知识。那么，现在在学习英语的时候，一般都是一段小对话，那么我现在要做的就是根据这个小段子去构建一个画面，通过这个画面把这个小段子和我已有的中文知识建立起桥梁，经过充分设想之后，我再去反复听这个小段子，加强这个小段子和我这个图片之间的联系，然后摆脱需要中文翻译的过程，达到在头脑中想到这个图片，我就能说出来这个图片对应的英语表达。每一天都要做一个这样的小小训练，每天5分钟的训练，争取年底英语过关。这是我下一步具体对这个片段知识点的一个应用。\u003c/p>\u003cp>&nbsp; &nbsp; 以上就是我今天分享的内容，希望大家在未来的生活中能够有意识的运用该项工具。感谢大家的参与。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500356974000,"updated_at":1500357246000},{"id":2816,"topic":"如何掌握高效的学习方法","learn_goal":"如何掌握高效的学习方法","remark":"一位因为快速学习而成名的神奇小子，他应用自己发明的学习方法，完成了10天搞定线性代数，1年学习4年MIT课程的“不可能任务”。本书就是对他学习方法的全面介绍，其中包括整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。跟随作者，你也将成为高效学习的超级学霸。","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"小清蜓","city":"上饶"},"club":{"name":"上饶三清山分舵","city":"上饶"},"prologue":"大 家好，我叫李清。今天我用三个标签来介绍下自己。\r\n我的第一标签是我来自湖南，今年22岁。第二个标签是我平时的爱好是看看书、写点东西\r\n我的第三个标签是我希望在未来三年内成为一名自由作家。\r\n接下来我要训练的是TF1—2\r\n接下来为了方便我们的讨论，我们分成俩个组，为了不移动位置，靠我这边的一组，另外一边一组。\r\n今天给大家拆解的片段是选自《书都不会读，你还想成功》作者是郑会一，韩国著名畅销书作家，韩国国民导师\r\n这本书讲的是郑会一的徒弟洪镇洙的故事，洪镇洙在没有认识郑会一之前是一位时装公司职员，从企划部调到市场销售部，工作中不被领导重视，业绩不好、受尽了夹板气，连女朋友也和自己分手了，后来通过朋友介绍认识了郑会一，洪镇洙在郑会一的引导下开始制定读书计划，通过疯狂读书，实现了人生3级跳，不仅升职加薪，还找到了一位很优秀的女孩结了婚，开始了崭新的人生，书中还有一些读书的技巧和方法，是一本非常很能激发一个人去读书的一本书，推荐大家可以去看看。","ratings_count":0,"texts":[{"id":5591,"quote":"\u003cp>今天给大家拆解的片段是选自《书都不会读，你还想成功》作者是郑会一，韩国著名畅销书作家，韩国国民导师\u003c/p>\u003cp>这本书讲的是郑会一的徒弟洪镇洙的故事，洪镇洙在没有认识郑会一之前是一位时装公司职员，从企划部调到市场销售部，工作中不被领导重视，业绩不好、受尽了夹板气，连女朋友也和自己分手了，后来通过朋友介绍认识了郑会一，洪镇洙在郑会一的引导下开始制定读书计划，通过疯狂读书，实现了人生3级跳，不仅升职加薪，还找到了一位很优秀的女孩结了婚，开始了崭新的人生，书中还有一些读书的技巧和方法，是一本非常很能激发一个人去读书的一本书，推荐大家可以去看看。\u003c/p>","explains":"\u003cp>你想培养某一习惯或者必须完成一些重要事情的时候，你必须让自己清晰让自己知道什么是重要的事情，把重要的事情和必做的事情放在优先位置。\u003c/p>\u003cp>例如培养读书的习惯，在没有养成读书习惯的情况下，总会把读书的位置往后放。喜欢看电视的人读完书再去看，喜爱运动的人读完书再去运动，将读书放在优先位置就更容易的培养读书的习惯，其他事情也是一样，每天把必做的事情放在第一位，能更容易是完成自己的目标。\u003c/p>\u003cp>比如说我在读书会有一个连续15天每日阅读半小时在群里打卡，月底我们就会送一本送书的活动，我每天都要统计打卡的人的姓名，然后公布到群里，我这个人本身自带有一种情况就是没有养成习惯的事情就不会主动性去做，就算别人跟我说了我也会时常会忘记，然后一月份刚接手这个工作，这个阅读打卡的我就统计了第一天，到一月底有很多人跑来跟我说她满了15天有本书领，当时脑袋都炸掉了，然后翻群记录从这个月翻到上个月，折腾了一上午也没有弄好。\u003c/p>\u003cp>2月份开始吸取教训每天早上打开电脑的第一件事就是统计每天打卡人的姓名，公布到群里，统计一下大概5分钟以内。几十个人的阅读打卡天数都了一目了然，以结果导向的思维去做这件事情会感觉很轻松，到现在这件事情每天做已经坚持一个多月了，发现现在基本上已经不用脑袋思考，每天上班打开电脑第一件事就是统计这个，基本是在每天同样的时间去做这件事情。已经潜移默化的养成了统计的习惯，这件事情也执行得很到位了，所以想养成某一习惯的时候，可以用30天的时间去坚持做这一件事情，30天内每天必须坚持，不能俩天打渔、三天晒网，然后选取一个对你来说完成这件事情有利的时间，可以选取每天同一个时间点，还有一点很重要在做这件事情的时候不要带着痛苦的情绪和想法去完成，假使这样过了30天你也不一定能养成这个习惯\u003c/p>\u003cp>现在请大家在小组内分享你在生活中有没有想做的事情，想培养的习惯，但是很多次都没有坚持，忘记做了的。等下我会请每个小组的一位来分享她的案例。\u003c/p>","interaction":"\u003cp>\u003cstrong>今年我想把我的普通话练标准，\u003c/strong>\u003cstrong>所以昨天开始定了今年的\u003c/strong>第三期21天计划，从这期开始，我把练习普通话这一项坚持30天\u003c/p>\u003cp>并在30天内坚持每天去完成，六项内容中每天先完成普通话的练习\u003c/p>\u003cp>并且每天在同一个时间点完成练习普通话，这样每天就不会忘记更容易养成习惯\u003c/p>\u003cp>练习的时候享受这个让自己普通话越来越标准的过程。因为每练习一次我的标准就会提高一点，我很开心现在信息时代很方便，手机上下载一个app就有人每天免费带我练习普通话\u003c/p>\u003cp>练习一次我的标准就会提高一点，这是一个能让我变得越来越好和实现目标的练习，我会全然接受并去享受整个过程。\u003c/p>\u003cp>练习时间除特殊情况外会选择早上，我觉得早上精神面貌会比较好，练习完可以在新的一天用上去并加以练习。效果会更好。这是我练习普通话的计划。\u003c/p>\u003cp>所以请大家现在写下将来你如何去运用这四点成你自己想养成的每日习惯的例子。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496541752000,"updated_at":1496541841000,"ria":true},{"id":1183,"topic":"如何学的少会的多？","learn_goal":"如何学的少会的多？","remark":"如何高效学习？","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"Emma","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"【学习目标】在跟随我完成本次现场学习后，学习者能够①在使用笔记流时，首先写下最主要的观点，②找到观点之间的的联系。\r\n【学习者场景法介绍图书】大家好，我是Emma。\r\n不知道大家念书时班上有没有学霸，他看起来学得很省劲，问啥啥都会，你自己却苦哈哈每天写卷子晚睡。到了考试，人家轻轻松松就考第一，自己却只会泡图书馆突击。\r\n除了天赋，方法也很重要，他们到底有什么秘密武器能够会的多学的少？\r\n也许你总被拿来和“别人家的孩子”作比较，苦不堪言，甚至开始怀疑自己的能力。\r\nScott Young就是这样一个典型的学霸，他用1年的时间全A的学分完成了麻省理工4年的33门课程，成为史上最快毕业的人。他在这本书《Learn More Study Less》中分享了“整体性学习法”的思维方式和学习技巧，能帮助我们有效地提高自己的学习效率，从而像他一样学的少会的多。","ratings_count":0,"texts":[{"id":3422,"quote":"\u003cp>说明：因为网站没有上传自测题的窗口，所以我先上传了出自测题，然后新增了一个片段上传实录。\u003c/p>","explains":null,"interaction":null,"flags":{"r":true,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":3423,"quote":"\u003cp>如果你希望掌握整体性学习法中做笔记的方法，在阅读拆页之前，先来做一个简单的测试，看看这种技术是否符合你当前的记录习惯。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>请仔细阅读以下5个题目中的每句话，根据自己当前的实际情况按照1~5的程度打分，1表示完全不符合，5表示非常符合。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>听课时，我花在记笔记上的时间多于跟随老师听课的思考时间。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>我按照老师讲课的顺序而非我自己理解的逻辑顺序来做笔记。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>我的笔记只记老师说的内容，不记我联想到的内容。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>尽管笔记精确复制了课堂内容，课下复习时我还是不能很好的理解知识点。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>我难以判断哪些知识是重点，哪些是老师教的核心内容。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cp>我尽可能详尽地记录下老师讲的每一句话。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>我们通过自测来了解自己的学习方式与整体性学习法的差距。\u003c/p>\u003cp>如果得分低于12分，说明你已经具备了进行整体性学习的关键条件；\u003cbr>\u003c/p>\u003cp>如果得分在12~24分之间，可能你做笔记的目标与整体性学习法的思维方式存在一定差异；\u003c/p>\u003cp>如果得分高于24分，说明你当前的笔记习惯可能不太符合整体性学习法的思维方式。\u003c/p>","interaction":null,"flags":{"r":true,"i":true,"a":false,"a1":false,"a2":false,"a3":false}},{"id":3654,"quote":null,"explains":"\u003cp>请大家看一下自己刚才在拆书过程中做的笔记，谁是一句话一句话往下记的？【大家回答：有，我】这种记笔记的方式我们称作线性笔记。谁还有不同的方式？【大家回答：思维导图】刚刚读完的原文拆页中作者介绍的这种做笔记的方法是什么？【大家回答：笔记流】\u003c/p>\u003cp>好，这就是我们今天要讨论的主要内容。\u003c/p>\u003cp>请看一下我手中的三张笔记，都记录了同样的内容：蛋炒饭的制作，大家觉得视觉上哪个最好看？【大家回答：思维导图】那个最完整？【大家回答：线性笔记】\u003c/p>\u003cp>第一张是线性笔记，笔记细致，看上去整齐，把老师讲的步骤一字不落地记下来了，但是文字太多，观点不够突出，观点之间的联系基本没有体现。\u003c/p>\u003cp>第二张是思维导图，特点是：视觉上漂亮，信息分类也直观，观点之间有联系，但是仅限于记在这张思维导图上的观点之间的联系，这种联系的扩展和衍生受一定的限制，而且联系并不是笔记的主要内容。\u003c/p>\u003cp>第三张是笔记流，特点是：看着就很low，杂乱、粗糙、可读性差。但是它有一个最大的优点：观点之间的联系很明显，既有老师讲的知识点之间的联系，又有新知识点与自己已有的知识之间的联系，并且可以无限的扩展。箭头的关联就是大脑思维流向的呈现，你记录的这些观点和你本身的知识关联性很大。\u003c/p>\u003cp>笔记流技术的做法是：写下最主要的观点，也就是老师讲的重点。在这些观点和其他观点（可以是书上的，也可以是自己已有的观点）之间画上箭头，发现相互关联的关系。\u003c/p>\u003cp>我们来对比着说一下他们的区别。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>线性笔记和思维导图\u003c/p>\u003c/td>\u003ctd>\u003cp>笔记流\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>以老师讲的内容为核心\u003c/p>\u003c/td>\u003ctd>\u003cp>以自己的知识结构为核心\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>最大限度地还原老师讲的内容，是老师备课的呈现\u003c/p>\u003c/td>\u003ctd>\u003cp>最大限度地理解老师讲的内容，把它融入到自己现有的知识结构里\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>分析老师讲的知识之间的逻辑关系\u003c/p>\u003c/td>\u003ctd>\u003cp>分析课堂知识与自己已有的知识之间的逻辑关系\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>尽可能完整地记录，课下再去理解\u003c/p>\u003c/td>\u003ctd>\u003cp>记录主要观点和联系，争取当堂理解并吸收\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>重点在于：记录\u003c/p>\u003c/td>\u003ctd>\u003cp>重点在于：思考\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>我知道老师讲隔夜饭并不是因为隔夜饭好吃，而是因为重点是隔夜饭软硬适中，我联系到自己吃过的馒头丁也符合这个特点，是不是也可以拿来炒？或者讲蛋液搅成碎鸡蛋的时候，就是为了获取更香更碎的颗粒，那我鸡蛋用完了，是不是也可以用老干妈代替？这样在老师讲知识点的时候，我已有的知识瞬间就浮现出来，给我理解这个出锅的节点提供了帮助。最后，我已有的知识告诉我光吃蛋炒饭有点干并且营养不均衡，这时搭配一瓶酸奶更赞。所以这堂课结束后，我不只学会了蛋炒饭，还举一反三地想到了蛋炒一切，老干妈炒一切，甚至还搭配出一个营养套餐。在课堂上，我跟着老师讲课在思考，理解并会应用了知识，比起课上记笔记+课下复习应用的学习方式来说更高效，会的更多。\u003c/p>\u003cp>现在大家觉得这三张笔记哪个能让我们最有效地理解老师讲的内容？【大家回答：笔记流啊】\u003c/p>\u003cp>记好笔记流的一个关键能力是知道哪些知识是重点，哪些是那老师教的核心内容。假如你平均记录老师讲的每一句话，那你所做的工作就是实录而非思考。作者在他的笔记流中删减掉很多信息，重点记录了联系和按照自己理解的方式给信息分类。我们在练习时也要注意重点和删减。\u003c/p>\u003cp>对于有讲义的情况，笔记流的方式就不太适合了，这是我们会转而使用评注流的方式，感兴趣的同学可以课下再讨论。\u003c/p>","interaction":"\u003cp>【A3】\u003c/p>\u003cp>请阅读以下有关“什么是整体性学习”的内容，和你的搭档进行小组讨论，找出最主要的观点，在这些观点和其他观点之间画上箭头，发现相互关联的关系，请练习使用笔记流技术，你们需要共同合作来完成一份笔记流笔记，最后给大家看一下这份笔记，讲讲你们如何建立起的联系。时间5分钟。\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>倩倩和二毛组的分享：先给大家展示一下我们组完成的笔记流，再来讲一下怎么想到的这些联系。\u003c/p>\u003cp>首先，最主要的观点是：整体性学习法的主要内容是吸收整合信息、知识之间相互关联、创造信息网络、轻松的驾驭知识。我们是通过战争的对比来理解这段内容的。他们之间的联系是这样的：首先，吸收整合信息我想到的是——&gt;哪儿打仗了，创造信息网络就是——&gt;为什么会打仗？好像凡是能源通道上的国家都在打，然后就想到伊拉克阿富汗都在打仗这样就是相当于——&gt;联通了一个网络，最后归结起来——&gt;美国的利益，但是涉及到美国利益的地方，美国都要去打。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>最后给大家布置一个小的作业，我知道大家已经习惯了用传统的方式记笔记，所以在决定是否用笔记流取代传统笔记之前，请在今天回去之后，练习一次笔记流技术：把今晚做的传统笔记拿出来，按照笔记流的方式重新记录，记下知识点并在知识点之间画上联系。\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>二毛的笔记流分享\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1477291992000,"updated_at":1478853339000},{"id":971,"topic":"运用联想法记忆","learn_goal":"让学习了解到什么是联想法，还会知道联想法的步骤，更好的记忆。","remark":"斯科特·扬是因为快速学习而成名的神奇小子，他应用自己发明的学习方法，完成了10天搞定线性代数，1年学习4年MIT课程的不可能。全书就是对他学习方法的全面介绍，其中包括 “整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。”","level":"TF2-4","duration":50,"status":0,"type":0,"chaishujia":{"username":"七月上","city":"兰州"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"大家好：我是一级拆书家七月上。很高兴能与小伙伴们一起打怪升级，我今天所拆的书籍是《如何高效学习》【特征】：作者：斯科特•扬（Scott Young）他是因为快速学习而成名的神奇小子，他应用自己发明的学习方法，完成了10天搞定线性代数，1年学习4年MIT课程的不可能。【优势】：这本书的作者给我们总结出一套学习方法，叫做“整体学习法”，包括2个方面，一方面是整体学习法的理论框架，另一方面是整体性学习法的技术要点。【利益】：全书详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决案。”我今天拆解的主题是：“联想法”学习者跟随我的本次拆解，不仅仅会了解到什么是联想法，还会知道联想法的步骤，更好的记忆。","ratings_count":0,"texts":[{"id":3015,"quote":"\u003cp>片段选自《如何高效学习》P106页\u003c/p>\u003cp>联想法\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;联想法并不是我首创的，作为一种记忆技巧，它已经存在很多年了。之所以称为联想法是因为它的目的是将一系列观点串在一起，就像链条，一旦进入链条中的一环，就可以轻易地到达链条中的其他环节。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;联想法在处理一系列随意信息时效果很好，包含步骤的过程信息、按顺序写下的名字或公式，都可以应用联想法。随着不断地练习，你可以迅速地将数十个知识点连在一起。\u003c/p>","explains":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;大家有过用联想法的方式来做记忆吗？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我记忆东西的时候就是跨界记忆，像一些概念性的东西记忆起来是比较枯燥和难记的，上一次我做过整体性学习的分享，就说到过我是如何记忆的，在我学习医学文献检索的时候我就将文献的特点结合女孩子衣服的特点完全的记下来，在答题时就不会记不起来。例1：数量庞大，类型复杂，重复交叉，分布分散，周期短，传播快，信息化，电子化，网络化。例2：文献类型联想我们记录生活的照片，纸介型（画像）缩微型（胶片）视听型（录像带or MP3）电子型（视频，电子期刊）。\u003cbr>\u003c/p>\u003cp>【不这么做的坏处】如果我们是一味地死记硬背，那么既浪费时间，又显得的别枯燥即使你当时记下了，可是过段时间还是会忘记。\u003c/p>","interaction":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 回想大家过去有没有联想记忆的实例？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 联想会不会对你的记忆有帮助？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 有没有发现这一现象并且刻意练习过呢？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者一:在学习英语单词的时候会，记忆电话号码的时候比如27668记忆为我去顺顺发；历史用故事记忆。\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者二:历史用看了电视剧的方法联想\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我的例子对您有没有启发?\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 您觉得这样学习有什么好处？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 您会将它应用到您的生活或者工作中吗?\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如果会，您会怎么做？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者一：会有启发，在学习一些小知识，如:知识点难以消化，用运场景和故事去消化。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":3016,"quote":"\u003cp>片段选自《如何高效学习》P107-110\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 使用联想法的步骤\u003c/p>\u003cp>第一步 &nbsp;创造顺序\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 先在纸上写下你打算记住的很多信息，在你能理解的前提下，迅速地将信息分成几类。把要处理的信息罗列成一个线性的清单非常重要，因为这是用联想法保存数据的唯一方法。 &nbsp; &nbsp;简单例子:联想法记忆杂货清单。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （1）香蕉\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （2）牛奶\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （3）铐豆\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （4）黄油\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;（5）果酱\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我相信没有什么课程会让你记忆杂货清单，不过其中的原理是相同的。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;要记住一个公式，可以将公式先转化成一个序列，即将公式变为可以输入到计算器的形式。公式V=1＋X/b可以写成V=1加上X除以b,V、=、1、加上、X、除以、b就是这个序列中的元素。如果你不习惯这种方法，碰到复杂的公式可能会花些时间，但是如果你很担心自己忘记，使用这种方法还是很有效果的。\u003c/p>\u003cp>第二步 &nbsp;给清单中的每一项设一个符号\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如果清单中是抽象信息的话，你可以给每个抽象信息设计一个容易识别的符号。学习管理学时，我需要记住亨利•法约尔(Henry Fayol)的管理十原则，我运用联想法给每一条原则设计一个助记符，劳动分配变成了一把锋利的刀，个人薪水则成了大棒上的胡萝卜。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 设计的符号要能迅速让你联想到原始的知识，因为联想法记住的是视觉符号，而不是抽象信息本身(记住的是胡萝而不是个人薪水)，所以如果符号和知识之间没有什么相关性，那联想法就不起作用了、除非你确信能从视觉符号想到原始知识，否则不要使用联想法。要记忆公式，可以将公式中的字母用一个相关的有实际意义的物体来替代，比如变量a的自替代符号是红红的苹果( apple ).开始时写下序列中每个项目的替代符号，一旦你联想得很熟练，成为习惯，就不必每一步都写下来了。\u003c/p>\u003cp>第三步 &nbsp;创建属于自己的联想\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 这一步是联想法的基础，你要做的就是创造生动夸张的图像，能将序列中的两个符号联系在一起，这表示你需要创造出图像联系1和2，2和3以及3和4，等等。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 以上面杂货清单的例子来说，首先我要想象一幅图画来联系香蕉和牛奶，我想象的图画是一只巨大的香蕉上面，有一群奶牛在散步；或者我也可以想象一名挤奶工在给个巨大的香蕉挤奶，注意是巨大的香蕉而不是奶牛，是不是很疯狂？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;这种疯狂、古怪、滑稽、荒诞的想象正是联想法的精髓，假如这种联系平淡无奇，只不过是普通的农场工人在给奶牛挤奶，一边挤奶一边吃香蕉，这样的想象不够夸张，不够生动，不能让自己兴奋，回忆起来也就很困难。这样的联系称为弱联系，而前面那种称为强联系。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在1和2建立联系之后，接下来就要想象2和3的联系了，想象一幅什么样的图画来建立牛奶和烤豆之间的联系呢&#39;?想象巨大的豆子在和一盒牛奶摔跤是不是生动有趣？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 接下来大家自己试试分别想象烤豆和黄油，黄油和果酱之间的联系。做完所有的联系后，再回忆一下是否能很容易地从1联想到2,3,4直至最后，如果中间有困难，说明你想象的图画不够生动，不够夸张、荒诞，重新想个好点的吧!\u003cbr>\u003c/p>","explains":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;看完拆页会不会觉得不可思议，怎么可以这样联想？挤奶工给巨大的香蕉挤奶？\u003c/p>\u003cp>换个角度你在记忆一些事物的时候如果都用我们平时都可以联想到的事物，那么当大量信息涌入时要想一下子就找到我们所要的信息就显得比较困难了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 比如：片段中的讲到的杂物清单\u003c/p>\u003cp>（1）香蕉\u003c/p>\u003cp>（2）牛奶\u003c/p>\u003cp>（3）铐豆\u003c/p>\u003cp>（4）黄油\u003c/p>\u003cp>（5）果酱。\u003c/p>\u003cp>想象早晨你出门坐着香蕉一样的滑板向前滑行，你相信自己有能力掌握平衡，就在经过一个游泳池时你太过兴奋被烤豆滑到掉进了池子里，你懊恼一头扎进深处，才发现自己掉进的不是一般的池子，这个池子里全是牛奶，你感觉到自己饿了，出了泳池去找吃的，到了面包店被奇特的香味所吸引，你顺着香味发现了一瓶被黄油浸泡的果酱，此时的你激动坏了，从来没见过果酱是浸泡在黄油里的，你立马买了它迫不及待的尝了口，啊！天那一点都不好吃。\u003c/p>\u003cp>【不这么做的坏处】如果我们不用联想法，刚才提到的清单都是我们生活中经常会用到的，但是因为经常用且多，所以往往我们就会忽略甚至想不起来。\u003cbr>\u003c/p>","interaction":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 同样是购物清单，我将它多加了几个进去，你将它们如何记忆？\u003c/p>\u003cp>分组讨论\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 1.一把勺子，2.洗衣粉，3.6只酒杯，4.天然皂，5.鸡蛋，6烤豆，7.黄油，8.香蕉，9.黄油，10.果酱。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者一:早晨出门坐着香蕉一样的雪橇，走在洒满牛奶路上，被烤豆绊了一跤掉进了泳池，里边是果酱和黄油，之后我想做一道黑暗料理:拿出勺子，舀一勺洗衣服放进六个杯子，打上鸡蛋，然后放在天然皂里蒸看看会是什么样。\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者二:我用洗衣服洗干净衣服，用天然皂洗澡打扮漂亮，摆好桌子，放上六个杯子，做好了香蕉牛奶放上，还做了鸡蛋夹黄油和牛奶的汉堡，还是双夹哦！还放了一碟烤豆，等待着我的情人回来享受浪漫的烛光晚餐。&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如何将联想法用到生活中？\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 列自己的购物清单，用联想法将它下下来。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;内容：十三香、衣架、果冻、大虾、酸奶、笼屉、麻辣香锅、薯片、苹果\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者一：我让孩子去买东西，你可以嘴里叼一个酸奶，背上背一个薯片，然后左手提着衣架，衣架上挂一个苹果，苹果下面吊一个果冻，右手拿一个笼屉，笼屉上面放大虾大虾上面是十三香和麻辣香料。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者二：果冻乘着衣架飞到十三香，碰着了邻居薯片邻居薯片从笼屉里拿出酸奶和苹果，请他吃麻辣香锅油焖大虾。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;学习者三：衣架和笼屉不对付打架请来了帮手，一个用果冻砸对方，一个用薯片作飞镖，笼屉更加阴险用十三香和麻辣香锅料来迷眼睛，这时候出来了江湖上的大侠（大虾）。说了一句不要打了下雨天苹果和酸奶更配哦！\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者四：洗了衣服在晾衣服结果孩子就匆忙回来，“我们要春游去”将果冻薯片酸奶就挂衣架上了，然后他发现有东西没买就又出去了，做饭时间到，泡好了大虾，就做油焖大虾吧。然后放了香锅料，结果料放少了就又加了十三香，味道不错呦，一个菜好像不好，就再用笼屉做一个蒸苹果吧。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者五：十三香和大虾的孩子薯片掉进了酸奶和果冻的泥潭里，特别脏，然后十三香将他挂在衣架上。后来大虾吃了麻辣香锅料，一下特别火，然后去锻炼身体，将笼屉做为轮胎去翻，然后特别累就吃了一个苹果。\u003c/p>\u003cp>【总结】通过联想法，伙伴们对学习枯燥内容有了不一样的认识；学会联想法，我们对于多且复杂的问题就会很好的记忆，并且在提到这样的问题时立马能从脑子里提炼出来。那么我希望大家去刻意练习，创造属于自己的联想。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1474773615000,"updated_at":1478413098000,"ria":true},{"id":908,"topic":"整体性学习将使你的课程不再枯燥乏味","learn_goal":"学会联想经验方法，解决整体性学习课程枯燥乏味问题","remark":"他是因为快速学习而成名的神奇小子，他应用自己发明的学习方法，完成了10天搞定线性代数，1年学习4年MIT课程的不可能。全书就是对他学习方法的全面介绍，其中包括 “整体性学习策略的核心思想和具体技术，详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决方案。”","level":"TF2-2","duration":16,"status":0,"type":0,"chaishujia":{"username":"七月上","city":"兰州"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"大家好：我是一级拆书家七月上。很高兴能与小伙伴们一起打怪升级，请允许我介绍我今天所拆的书籍。《如何高效学习》作者:【加】斯科特•扬（scott young），【特征】：他是因为快速学习而成名的神奇小子，他应用自己发明的学习方法，完成了10天搞定线性代数，1年学习4年MIT课程的不可能。【优势】：这本书的作者给我们总结出一套学习方法，叫做“整体学习法”，包括2个方面，一方面是整体学习法的理论框架，另一方面是整体性学习法的技术要点。【利益】：全书详细介绍了快速阅读法、流笔记法、比喻法、内在化等七大方法，并为高效学习提供了从生活到时间管理的整体解决案。”我今天拆解的主题是“整体性学习将使你的课程不再枯燥乏味”。","ratings_count":0,"texts":[{"id":2778,"quote":"\u003cp>《如何高效学习》第61-62页为什么你会觉得有的课枯燥乏味，有的课却令人着迷？你可能会说我对某些学科感兴趣，而对某些学科兴趣索然，不过你知道其中的缘由吗？喜欢文学而不是物理，喜欢编程而不是会计学，其中的原因有很多:或许你天生喜欢某门学科而不是另一种；也许你在日常生活中经常用到某门学科，所以才喜欢它；也许是因为某门学科的老师讲课生动有趣，他能将抽象的概念与你感兴趣的东西精密联系在一起。问题是：你能否掌控自己喜欢或是讨厌某门学科？你能让一门枯燥的课变得有趣吗？假如你能掌控自己的学习，那么，我相信你会发现学习任何学科都会变得生动有趣。整体性学习和对课程的兴趣密切相关。你对一门课程的兴趣越大，学习就越容易整体性。你有没有发现自己可以很容易的联系到喜欢的学科上，却很难联系到乏味的学科上。反过来，学习越是整体性，课程就越生动有趣。你可以通过整体性学习，来让你感觉乏味的课程变得有趣。我们在开始学习一门学科时，都会觉得枯燥，也许是因为要拿学位而不得不学习统计学；也许是因为开公司需要学习税收法。如果你能使这些枯燥的学科变得生动有趣，你就会学的容，效果更好。下一次当碰到“乏味”的课程时，不要马上抱怨。问题可能在于老师教你时没有和你的经验联系，而使用整体性学习方法，你可以将内容与你感兴趣的东西相连。学习计算机科学时，你是思考课本上那些文字，还是在想宇宙的神秘符号？学习医学时，你是在背诵那些文字，还是在想着活生生的病人？学习历史时，你看到的难道仅仅是数字和日期，难道没有看见那么多历史人物的鲜活故事。整体性学习的一个附加的好处是它强迫你以不同的视角看待学科、课程和问题。任何知识都可以以抽象的原理转化为生动的图像、有趣的故事。\u003cbr>\u003c/p>","explains":"\u003cp>你可能会觉得这样做很麻烦，学习就学习呗，我能将它记住就好了，干嘛还要去联想经验，那岂不是很浪费时间？可是当我们花一点时间去与我们的经验联系起来会记得更牢固。比如：学医的，可能要记一些专业名词像是“癫痫”别说这个名词了，就是这两个字都不好写，但联系老百姓的叫法叫“羊角风”这样是不是很容易记住，而且还能知道他发病时的症状。\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cp>【A2】你可以怎样将我刚才讲的法子，使你所学的课程不再枯燥乏味？\u003c/p>\u003cp>心里学，逻辑思维，时间管理，医学，在哪个领域你会联系你的经验，让你的学习不枯燥？\u003c/p>学习者一:喜欢心理学，与生活中的实例，与人的思想联系起来。\u003cbr>学习者二:心理学三级考试，确实也好好看书了，在考试中的几个量表也复习过，但是混淆了，只是死记硬背，没有做联想。\u003cbr>学习者三:对数学，数字图表有障碍，不好联想，难联想。\u003cbr>&nbsp; &nbsp; 在接下来的学习中，你是不是可以具体实施我的方法，联系你的经验将枯燥的学科变得不枯燥。&nbsp; &nbsp; 比如你学医的，那单纯的记忆解剖学术语是不是很难？比如角膜，虹膜。此时的你会不会停下来想想哪一部分是角膜，那一部分是虹膜？又或者像文献检索，你要知道文献的特点，可能要记住以下几点，1数量庞大，2类型复杂3，分布分散4传播速度快5网络化数字化。这样记忆就很枯燥，换个思路将文献联系为女孩子的衣服，会不会好记很多而且也没有那么枯燥呢？请在小组内分享你的应用。学习者一:在学习《社区帮扶解答》时有5个领域，25块内容，不好记忆，希望用画图的方式联想记忆。\u003cbr>学习者二:将这种联想更多的用于心理学中，有点到面，全面应用。\u003cbr>\u003cbr>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1473855441000,"updated_at":1478411420000,"ria":true}]};